/* Amiyo Studio - 09-pro-davinci.js */
/* DaVinci pages, loudness radar and speed zones */
/* Scripts 1100 to 1399 */


;
/* ==================== Script 1100 id="amiyo-speed-zones" ==================== */
/* ===== Speed Zones =====
   Speed up / slow down chosen parts of the timeline in one go, e.g.  2s-10s at 2x,  40s-45s at 2.5x.
   Times are the CURRENT timeline times (seconds or m:ss). Every track is cut at the zone edges with the Cut Suite engine,
   clips inside a zone get speed x factor (video AND its audio), and everything after is moved to close/open the gap
   (text, images, music, markers too) so the edit stays in sync. One undo step. */
(function(){
"use strict";
var MIN=.05, MAX=8;
function say(m){ try{ (window.notify||window.toast)(m); }catch(e){} }
function esc(s){ return String(s).replace(/[&<>"]/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c];}); }
function parseTime(s){
  s=String(s==null?"":s).trim().toLowerCase().replace(/s$/,"");
  if(!s) return NaN;
  if(s.indexOf(":")>=0){ var p=s.split(":").map(Number); if(p.some(isNaN)) return NaN; return p.reduce(function(a,x){return a*60+x;},0); }
  var v=Number(s); return isFinite(v)?v:NaN;
}
function parseSpeed(s){ s=String(s==null?"":s).trim().toLowerCase().replace(/[x×]$/,""); var v=Number(s); return isFinite(v)?v:NaN; }
function fmtT(t){ var m=Math.floor(t/60); return m?m+":"+(t-m*60<10?"0":"")+(t-m*60).toFixed(2).replace(/\.?0+$/,""):(+t.toFixed(2))+"s"; }
function projEnd(){ var e=0; project.tracks.forEach(function(t){ t.clips.forEach(function(c){ e=Math.max(e,c.start+c.duration); }); }); return e; }

/* validate + sort rows -> {zones:[{a,b,v}]} or {error} */
function selTracks(){
  var ids={}, links={};
  project.tracks.forEach(function(t){ t.clips.forEach(function(c){ if(c.id===selectedClipId||c.selected){ ids[t.id]=1; if(c.linkId) links[c.linkId]=1; } }); });
  project.tracks.forEach(function(t){ t.clips.forEach(function(c){ if(c.linkId&&links[c.linkId]) ids[t.id]=1; }); });
  return ids;
}
function inc(t,scope,sel){ if(scope==="media") return t.kind==="video"||t.kind==="audio"; if(scope==="selected") return !!(sel||selTracks())[t.id]; return true; }
function expand(z,ease){
  if(!(ease>0)||z.cur>0) return [z];
  var r=Math.min(ease,(z.b-z.a)/2-.02), N=6, out=[], i;
  if(r<.12||Math.abs(z.k-1)<.05) return [z];
  function seg(a,b,k){ out.push({a:a,b:b,v:z.v,k:k,n:z.n}); }
  for(i=0;i<N;i++) seg(z.a+r*i/N,z.a+r*(i+1)/N,1+(z.k-1)*(i+.5)/N);
  seg(z.a+r,z.b-r,z.k);
  for(i=0;i<N;i++) seg(z.b-r+r*i/N,z.b-r+r*(i+1)/N,1+(z.k-1)*(N-i-.5)/N);
  return out;
}
function check(rows,ease,scope){
  var z=[], end=projEnd();
  for(var i=0;i<rows.length;i++){
    var r=rows[i], a=parseTime(r.a), b=parseTime(r.b), v=parseSpeed(r.v), n=i+1;
    if(isNaN(a)&&isNaN(b)&&isNaN(v)&&!String(r.a).trim()&&!String(r.b).trim()) continue;
    if(isNaN(a)||isNaN(b)) return {error:"Row "+n+": type the From and To times (like 2 and 10, or 0:40 and 0:45)"};
    if(isNaN(v)) return {error:"Row "+n+": type a speed like 2 or 2.5"};
    if(a<0) return {error:"Row "+n+": From can't be below 0"};
    if(b<=a+.05) return {error:"Row "+n+": To must be after From"};
    if(a>=end-.05) return {error:"Row "+n+": From is after the end of the edit ("+fmtT(end)+")"};
    if(v<MIN||v>MAX) return {error:"Row "+n+": speed must be between "+MIN+"x and "+MAX+"x"};
    var cur=r.cur>0?+r.cur:1; z.push({a:a,b:Math.min(b,end),v:v,k:v/cur,n:n,cur:r.cur>0?cur:0});
  }
  if(!z.length) return {error:"Add at least one zone"};
  z=z.filter(function(q){ return Math.abs(q.k-1)>.0005; });
  if(!z.length) return {error:"Nothing changed yet — change a speed or add a zone"};
  z.sort(function(x,y){return x.a-y.a;});
  for(var j=1;j<z.length;j++) if(z[j].a<z[j-1].b-1e-6) return {error:"Rows "+z[j-1].n+" and "+z[j].n+" overlap ("+fmtT(z[j].a)+" is inside "+fmtT(z[j-1].a)+"–"+fmtT(z[j-1].b)+")"};
  if(ease>0){ var ex=[]; z.forEach(function(q){ ex=ex.concat(expand(q,ease)); }); z=ex; }
  if(scope==="selected"&&!Object.keys(selTracks()).length) return {error:"Select a clip on the timeline first (scope: selected clip's tracks)"};
  var sel=scope==="selected"?selTracks():null;
  var lock=project.tracks.filter(function(t){ return inc(t,scope,sel)&&t.locked&&t.clips.length; });
  if(lock.length) return {error:"Unlock "+lock.map(function(t){return t.name||t.kind;}).join(", ")+" first, so every track stays in sync"};
  return {zones:z};
}
function mapper(zones){
  return function(t){ var r=t; zones.forEach(function(z){ var o=Math.min(Math.max(t,z.a),z.b)-z.a; r-=o*(1-1/z.k); }); return r; };
}
function scaleKeys(list,k){ (list||[]).forEach(function(p){ p.t=p.t*k; }); }

/* the real edit. Returns {zones,before,after} */
function applyZones(zones,scope){
  var cut=window.amiyoCut;
  if(!cut||!cut.run||!cut.cutOne){ say("The cut engine isn't available"); return 0; }
  var sel=scope==="selected"?selTracks():null, f=mapper(zones), oldEnd=projEnd(), newEnd=f(oldEnd), done=0;
  var n=cut.run("Speed zones",function(){
    var ctx=cut.newCtx(), pts=[];
    zones.forEach(function(z){ pts.push(z.a,z.b); });
    pts.forEach(function(t){ project.tracks.forEach(function(tr){ if(!inc(tr,scope,sel)) return; tr.clips.slice().forEach(function(c){ cut.cutOne(tr,c,t,ctx); }); }); });
    cut.finish(ctx);
    project.tracks.forEach(function(tr){
      if(!inc(tr,scope,sel)) return;
      tr.clips.forEach(function(c){
        var s=c.start, e=s+c.duration, m=(s+e)/2, z=null;
        for(var i=0;i<zones.length;i++) if(m>zones[i].a&&m<zones[i].b){ z=zones[i]; break; }
        c.start=Math.max(0,f(s)); c.duration=Math.max(.02,f(e)-f(s));
        if(!z) return;
        var k=1/z.k, a=project.assets&&project.assets[c.assetId], media=a&&a.type!=="image"&&!c.freeze;
        if(media) c.speed=(c.speed||1)*z.k;
        scaleKeys(c.keyframes,k); scaleKeys(c.volumeKeyframes,k);
        if(c.speedKeyframes&&c.speedKeyframes.length){ c.speedKeyframes.forEach(function(p){ p.t*=k; p.speed*=z.k; }); }
        if(c.fadeIn) c.fadeIn*=k; if(c.fadeOut) c.fadeOut*=k;
        done++;
      });
      tr.clips.sort(function(x,y){return x.start-y.start;});
    });
    if(!scope||scope==="all") (project.markers||[]).forEach(function(m){ if(isFinite(m.time)) m.time=f(m.time); });
    return Math.max(1,done);
  });
  if(n) say("Speed zones applied: "+zones.length+" zone"+(zones.length>1?"s":"")+" · edit "+fmtT(oldEnd)+" → "+fmtT(newEnd));
  return n?{zones:zones,before:oldEnd,after:newEnd}:0;
}

/* ---------- freeze hold + reverse part ---------- */
function srcAtEnd(c){ try{ return window.__amiyoComputeSeek(c,c.duration); }catch(e){ return c.outPoint; } }
function freezeAt(t,D){
  var cut=window.amiyoCut; t=+t; D=+D;
  if(!cut||!cut.run) return say("The cut engine isn't available"),0;
  if(!(t>=0)||!(D>=.1&&D<=60)) return say("Freeze: type a time and a hold length between 0.1 and 60 s"),0;
  if(project.tracks.some(function(x){ return x.locked&&x.clips.length; })) return say("Unlock all tracks first so everything stays in sync"),0;
  var ok=false;
  var n=cut.run("Freeze frame hold",function(){
    var ctx=cut.newCtx(), fz=[];
    project.tracks.forEach(function(tr){
      tr.clips.slice().forEach(function(c){
        if(tr.kind==="video"||tr.kind==="audio"){
          var r=cut.cutOne(tr,c,t,ctx);
          if(r&&tr.kind==="video"&&media(c)&&!c.freeze){
            var f=JSON.parse(JSON.stringify(c)), a=srcAtEnd(c);
            f.id=uid("clip"); f.name=(c.name||"Clip")+" — Freeze"; f.start=t; f.duration=D; f.inPoint=a; f.outPoint=a; f.freeze=true; f.freezeAt=a; f.speed=1;
            f.keyframes=[]; f.transitionIn=null; f.transitionOut=null; f.linkId=null; f.audioDetached=null; f.detachedFrom=null; f.selected=false; f.fadeIn=0; f.fadeOut=0; f.speedKeyframes=[];
            fz.push({tr:tr,c:f});
          }
        }else if(c.start<t-.02&&c.start+c.duration>t+.02) c.duration+=D;
      });
    });
    cut.finish(ctx);
    if(!fz.length){ return 0; }
    project.tracks.forEach(function(tr){ tr.clips.forEach(function(c){ if(c.start>=t-.001) c.start+=D; }); });
    fz.forEach(function(x){ x.tr.clips.push(x.c); });
    project.tracks.forEach(function(tr){ tr.clips.sort(function(p,q){return p.start-q.start;}); });
    (project.markers||[]).forEach(function(m){ if(isFinite(m.time)&&m.time>=t) m.time+=D; });
    ok=true; return fz.length;
  });
  if(!n){ say("Put the freeze point inside a video clip (0–"+fmtT(projEnd())+")"); return 0; }
  say("Froze the picture at "+fmtT(t)+" for "+D+" s · edit now "+fmtT(projEnd())); return n;
}
async function reversePart(a,b){
  var cut=window.amiyoCut, X=window.amiyoX; a=+a; b=+b;
  if(!cut||!X||!X.reverseClip) return say("Reverse isn't available"),0;
  if(!(a>=0&&b>a+.2)) return say("Reverse: type From and To (To after From)"),0;
  var n=cut.run("Cut for reverse",function(){
    var ctx=cut.newCtx(), c0=0; [a,b].forEach(function(t){ project.tracks.forEach(function(tr){ if(tr.kind!=="video"&&tr.kind!=="audio"||tr.locked) return; tr.clips.slice().forEach(function(c){ if(cut.cutOne(tr,c,t,ctx)) c0++; }); }); });
    cut.finish(ctx); return Math.max(1,c0);
  });
  var inz=[]; project.tracks.forEach(function(tr){ if(tr.kind==="video") tr.clips.forEach(function(c){ if(media(c)&&c.start>=a-.03&&c.start+c.duration<=b+.03&&!c.reverse) inz.push(c.id); }); });
  if(!inz.length) return say("No video in that range"),0;
  for(var i=0;i<inz.length;i++){ var id=inz[i], tid=null; project.tracks.forEach(function(tr){ tr.clips.forEach(function(c){ if(c.id===id) tid=tr.id; }); }); selectedClipId=id; selectedTrackId=tid; try{ await X.reverseClip(); }catch(e){ window.__swl&&window.__swl(e); } }
  say("Reversed "+fmtT(a)+" – "+fmtT(b)+" ("+inz.length+" clip"+(inz.length>1?"s":"")+")"); return inz.length;
}

/* ---------- dialog ---------- */
var css=document.createElement("style");
css.textContent=".szb{position:fixed;inset:0;z-index:99999;background:rgba(0,0,0,.55);display:grid;place-items:center}"
+".szc{width:min(480px,94vw);max-height:92vh;overflow:auto;background:#17140f;color:#e8e2d4;border:1px solid #3a342a;border-radius:12px;padding:16px;font:13px system-ui,sans-serif}"
+".szc h3{margin:0 0 4px;font-size:15px}.szc p{margin:0 0 10px;color:#9a9486;font-size:11.5px;line-height:1.45}"
+".szr{display:grid;grid-template-columns:1fr 1fr 1fr 28px;gap:6px;margin-bottom:6px;align-items:center}"
+".szr.h{font-size:10px;text-transform:uppercase;letter-spacing:.05em;color:#9a9486;margin-bottom:2px}"
+".szi{padding:5px;border-radius:6px;border:1px solid #3a342a;background:#0f0d0a;color:inherit}.szr input:disabled{opacity:.6}.szr input{width:100%;box-sizing:border-box;padding:7px;border-radius:7px;border:1px solid #3a342a;background:#0f0d0a;color:inherit}"
+".szr button.x{border:0;background:none;color:#9a9486;font-size:16px;cursor:pointer}"
+".szm{min-height:32px;margin:8px 0;font-size:12px;color:#ffb27a}.szm.ok{color:#9be3a8}"
+".szf{display:flex;gap:8px;justify-content:flex-end;flex-wrap:wrap}"
+".szf button,.szchip{padding:8px 12px;border-radius:7px;border:1px solid #3a342a;background:#141310;color:#e8e2d4;cursor:pointer;font-size:12.5px}"
+".szf button.p{background:linear-gradient(155deg,#ff7a2f,#e8622a);color:#1a0c03;border-color:transparent;font-weight:600}";
document.head.appendChild(css);

function open(){
  if(document.getElementById("szBack")) return;
  function loaded(){ return (window.amiyoSpeedZones.current?window.amiyoSpeedZones.current():[]).map(function(q){ return {a:String(+q.a.toFixed(3)),b:String(+q.b.toFixed(3)),v:String(+q.v.toFixed(3)),cur:q.v}; }); }
  var rows=loaded(); if(!rows.length) rows=[{a:"2",b:"10",v:"2"},{a:"40",b:"45",v:"2.5"}];
  var b=document.createElement("div"); b.className="szb"; b.id="szBack";
  b.innerHTML='<div class="szc" role="dialog" aria-label="Speed zones"><h3>⏩ Speed zones</h3>'
   +'<p>Existing sped-up parts load automatically — change their speed (1 = normal) or add new zones. Pick parts of the timeline and give each its own speed. Times are on the timeline now (seconds or m:ss). Video, its audio, text and music all stay in sync. Zones can\'t overlap. Speed 0.05×–8×.</p>'
   +'<div class="szr h"><span>From</span><span>To</span><span>Speed ×</span><span></span></div><div id="szRows"></div>'
   +'<div id="szPre" style="margin:0 0 8px;display:flex;flex-wrap:wrap;gap:5px;align-items:center"></div><div style="margin:6px 0"><button class="szchip" id="szAdd">+ Add zone</button> <button class="szchip" id="szLoad">↻ Load from timeline</button> <button class="szchip" id="szPh">Use In/Out or playhead…</button></div>'
   +'<div style="margin:6px 0;font-size:12px;color:#c4bcac">Smooth ramp: <input id="szEase" value="0" inputmode="decimal" style="width:54px;padding:5px;border-radius:6px;border:1px solid #3a342a;background:#0f0d0a;color:inherit"> s ease in &amp; out (0 = instant). Applies to new zones.</div><div style="margin:6px 0;font-size:12px;color:#c4bcac">Apply to: <select id="szScope" style="padding:5px;border-radius:6px;border:1px solid #3a342a;background:#0f0d0a;color:inherit"><option value="all">Whole edit (all tracks stay in sync)</option><option value="media">Video &amp; audio only (text/graphics stay put)</option><option value="selected">Only the selected clip’s tracks</option></select></div><details style="margin:6px 0;font-size:12px;color:#c4bcac"><summary style="cursor:pointer">Freeze &amp; reverse</summary><div style="margin-top:6px">Freeze the picture at <input id="szFa" value="" placeholder="10" style="width:52px" class="szi"> s for <input id="szFd" value="3" style="width:44px" class="szi"> s <button class="szchip" id="szFz">Freeze</button></div><div style="margin-top:6px">Play backwards from <input id="szRa" value="" placeholder="5" style="width:52px" class="szi"> to <input id="szRb" value="" placeholder="8" style="width:52px" class="szi"> s <button class="szchip" id="szRv">Reverse</button></div></details><div class="szm" id="szMsg"></div><div class="szf"><button id="szX">Close</button><button class="p" id="szGo">Apply (undo = Ctrl+Z)</button></div></div>';
  document.body.appendChild(b);
  var host=b.querySelector("#szRows"), msg=b.querySelector("#szMsg");
  function draw(){
    host.innerHTML=rows.map(function(r,i){ return '<div class="szr"><input data-i="'+i+'" data-k="a" value="'+esc(r.a)+'" inputmode="decimal" placeholder="2"'+(r.cur?' disabled title="Existing zone: change its speed (1 = back to normal)"':'')+'><input data-i="'+i+'" data-k="b" value="'+esc(r.b)+'" inputmode="decimal" placeholder="10"'+(r.cur?' disabled':'')+'><input data-i="'+i+'" data-k="v" value="'+esc(r.v)+'" inputmode="decimal" placeholder="2"><button class="x" data-del="'+i+'" title="Remove">×</button></div>'; }).join("");
  }
  function scopeVal(){ return (b.querySelector("#szScope")||{}).value||"all"; }
  function easeVal(){ var e=parseFloat((b.querySelector("#szEase")||{}).value); return isFinite(e)&&e>0?e:0; }
  function preview(){
    var c=check(rows,easeVal(),scopeVal()); msg.className="szm";
    if(c.error){ msg.textContent=c.error; return null; }
    var f=mapper(c.zones), o=projEnd(); msg.className="szm ok";
    msg.textContent=c.zones.length+" zone"+(c.zones.length>1?"s":"")+" · edit "+fmtT(o)+" → "+fmtT(f(o));
    return c.zones;
  }
  var PK="amiyo.sz.presets.v1", BUILT=[["Slow-mo",.5,0],["Super slow",.25,0],["Normal",1,0],["Fast",2,0],["Timelapse",8,0],["Smooth 2×",2,1]], sel=-1;
  function mine(){ try{ var v=JSON.parse(localStorage.getItem(PK)||"[]"); return Array.isArray(v)?v.filter(function(x){return x&&x.n&&x.v>0;}):[]; }catch(e){ return []; } }
  function saveMine(l){ try{ localStorage.setItem(PK,JSON.stringify(l.slice(0,12))); }catch(e){} }
  function drawPre(){
    var h='<span style="font-size:10px;color:#9a9486;text-transform:uppercase;letter-spacing:.05em">Presets</span>';
    BUILT.forEach(function(p,i){ h+='<button class="szchip" data-pre="b'+i+'">'+p[0]+' '+p[1]+'×</button>'; });
    mine().forEach(function(p,i){ h+='<button class="szchip" data-pre="m'+i+'" title="Shift+click to delete">★ '+esc(p.n)+' '+p.v+'×</button>'; });
    h+='<button class="szchip" id="szSavePre">+ Save speed as preset</button>';
    b.querySelector("#szPre").innerHTML=h;
  }
  function target(){ var i=sel>=0&&sel<rows.length?sel:rows.length-1; if(i<0){ rows.push({a:"0",b:"5",v:"1"}); i=0; } return i; }
  b.querySelector("#szPre").addEventListener("click",function(e){
    var t=e.target.closest("button"); if(!t) return;
    if(t.id==="szSavePre"){ var r=rows[target()]; var v=parseSpeed(r.v); if(!(v>0)){ msg.className="szm"; msg.textContent="Type a speed first"; return; }
      var nm=window.prompt("Preset name",v+"× speed"); if(!nm) return; var l=mine(); l.push({n:nm.slice(0,16),v:v,e:easeVal()}); saveMine(l); drawPre(); return; }
    var k=t.dataset.pre; if(!k) return; var idx=+k.slice(1), p;
    if(k[0]==="m"){ if(e.shiftKey){ var l2=mine(); l2.splice(idx,1); saveMine(l2); drawPre(); return; } var m=mine()[idx]; p=[m.n,m.v,m.e||0]; } else p=BUILT[idx];
    var i=target(); rows[i].v=String(p[1]); if(p[2]) b.querySelector("#szEase").value=String(p[2]); else if(k[0]==="b") b.querySelector("#szEase").value="0";
    draw(); preview();
  });
  host.addEventListener("focusin",function(e){ if(e.target.dataset&&e.target.dataset.i!=null) sel=+e.target.dataset.i; });
  drawPre(); draw(); preview();
  host.addEventListener("input",function(e){ var t=e.target; if(t.dataset.i==null) return; rows[+t.dataset.i][t.dataset.k]=t.value; preview(); });
  host.addEventListener("click",function(e){ var d=e.target.dataset.del; if(d==null) return; rows.splice(+d,1); draw(); preview(); });
  b.querySelector("#szFz").onclick=function(){ var t=parseTime(b.querySelector("#szFa").value); if(isNaN(t)) t=window.currentTime||0; if(freezeAt(t,parseTime(b.querySelector("#szFd").value))) close(); };
  b.querySelector("#szRv").onclick=async function(){ var x=parseTime(b.querySelector("#szRa").value), y=parseTime(b.querySelector("#szRb").value); if(isNaN(x)||isNaN(y)){ msg.className="szm"; msg.textContent="Type the From and To times to reverse"; return; } close(); await reversePart(x,y); };
  b.querySelector("#szEase").addEventListener("input",preview); b.querySelector("#szScope").addEventListener("change",preview);
  b.querySelector("#szAdd").onclick=function(){ var last=rows[rows.length-1], s=last?(parseTime(last.b)||0):0; rows.push({a:String(+s.toFixed(2)),b:String(+(s+5).toFixed(2)),v:"2"}); draw(); preview(); };
  b.querySelector("#szLoad").onclick=function(){ var l=loaded(); if(!l.length){ msg.className="szm"; msg.textContent="No sped-up or slowed parts on the timeline yet"; return; } rows=l; draw(); preview(); };
  b.querySelector("#szPh").onclick=function(){
    var io=window.amiyoGetIO?window.amiyoGetIO():{i:null,o:null}, t=window.currentTime||0;
    var a=io.i!=null&&io.o!=null&&io.o>io.i?io.i:t, e=io.i!=null&&io.o!=null&&io.o>io.i?io.o:t+5;
    rows.push({a:String(+a.toFixed(2)),b:String(+e.toFixed(2)),v:"2"}); draw(); preview();
  };
  function close(){ b.remove(); }
  b.querySelector("#szX").onclick=close;
  b.addEventListener("pointerdown",function(e){ if(e.target===b) close(); });
  b.addEventListener("keydown",function(e){ e.stopPropagation(); if(e.key==="Escape") close(); if(e.key==="Enter") b.querySelector("#szGo").click(); },true);
  b.querySelector("#szGo").onclick=function(){
    var z=preview(); if(!z) return;
    var r=applyZones(z,scopeVal()); if(r) close();
  };
}

/* ---------- entry points: Speed bar chip + timeline toolbar button ---------- */
function mount(){
  var bar=document.getElementById("proSpeedBar");
  if(bar&&!bar.querySelector(".szentry")){
    var top=bar.querySelector(".spbar-top");
    if(top){ var btn=document.createElement("button"); btn.type="button"; btn.className="chip szentry"; btn.textContent="Zones…"; btn.title="Speed up or slow down parts of the timeline (e.g. 2s–10s at 2×)"; btn.onclick=open; top.appendChild(btn); }
  }
}
try{ new MutationObserver(function(){ mount(); }).observe(document.body,{childList:true,subtree:true}); }catch(e){}
document.addEventListener("DOMContentLoaded",mount); mount();
window.amiyoSpeedZones={open:open,apply:function(list,opt){ var c=check(list.map(function(r){ return {a:r.from!=null?r.from:r.a,b:r.to!=null?r.to:r.b,v:r.speed!=null?r.speed:r.v}; }),opt&&opt.ease,opt&&opt.scope); if(c.error){ say(c.error); return 0; } return applyZones(c.zones,opt&&opt.scope); },check:check,freeze:freezeAt,reverse:reversePart};
})();

;
/* ==================== Script 1101 id="amiyo-template-text-edit" ==================== */
/* ===== Edit template text =====
   Every template (built-in and "Mine") gets an "Edit text" button: one box per text line / label with a live preview.
   Add it to the timeline with your words, or save the edited version to My templates. Turn on "Edit text before adding"
   to be asked every time you tap a template. Text layers already on the timeline stay editable as before. */
(function(){
"use strict";
var PREF="amiyo.tpl.edittext.v1";
function say(m){ try{ (window.notify||window.toast)(m); }catch(e){} }
function esc(s){ return String(s==null?"":s).replace(/[&<>"]/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c];}); }
function api(){ return window.AMIYO_TEMPLATES; }
function find(id){ var l=api().list(); for(var i=0;i<l.length;i++) if(l[i].id===id) return l[i]; return null; }
function pref(){ try{ return localStorage.getItem(PREF)==="1"; }catch(e){ return false; } }
function setPref(v){ try{ localStorage.setItem(PREF,v?"1":"0"); }catch(e){} }

/* every editable string in a template: {get,set,label,kind} */
function fields(tpl){
  var out=[];
  tpl.items.forEach(function(it,i){
    if(it.t==="t") out.push({kind:"Text",get:function(){return it.text;},set:function(v){it.text=v;}});
    else if(it.t==="g"&&it.label) out.push({kind:"Label",get:function(){return it.label;},set:function(v){it.label=v;}});
    else if(it.t==="raw"&&it.clip){
      if(it.kind==="text"&&typeof it.clip.text==="string") out.push({kind:"Text",get:function(){return it.clip.text;},set:function(v){it.clip.text=v; if(it.clip.name) it.clip.name=String(v).split("\n")[0].slice(0,24);}});
      else if(it.kind==="graphic"&&it.clip.label) out.push({kind:"Label",get:function(){return it.clip.label;},set:function(v){it.clip.label=v;}});
    }
  });
  return out;
}
function clone(o){ return JSON.parse(JSON.stringify(o)); }

var css=document.createElement("style");
css.textContent=".teb{position:fixed;inset:0;z-index:99999;background:rgba(0,0,0,.55);display:grid;place-items:center}"
+".tec{width:min(520px,94vw);max-height:92vh;overflow:auto;background:#17140f;color:#e8e2d4;border:1px solid #3a342a;border-radius:12px;padding:16px;font:13px system-ui,sans-serif}"
+".tec h3{margin:0 0 4px;font-size:15px}.tec p{margin:0 0 10px;color:#9a9486;font-size:11.5px}"
+".tec canvas{width:100%;aspect-ratio:16/9;border:1px solid #3a342a;border-radius:8px;background:#000;display:block;margin-bottom:10px}"
+".tef{margin-bottom:8px}.tef label{display:block;font-size:10px;text-transform:uppercase;letter-spacing:.05em;color:#9a9486;margin-bottom:3px}"
+".tef textarea{width:100%;box-sizing:border-box;padding:7px;border-radius:7px;border:1px solid #3a342a;background:#0f0d0a;color:inherit;font:inherit;resize:vertical}"
+".tebtn{display:flex;gap:8px;justify-content:flex-end;flex-wrap:wrap;margin-top:12px}"
+".tebtn button,.szTxtBtn{padding:8px 12px;border-radius:7px;border:1px solid #3a342a;background:#141310;color:#e8e2d4;cursor:pointer;font-size:12.5px}"
+".tebtn button.p{background:linear-gradient(155deg,#ff7a2f,#e8622a);color:#1a0c03;border-color:transparent;font-weight:600}"
+".szTxtBtn{display:block;width:calc(100% - 8px);margin:4px 4px 6px;padding:5px 8px;font-size:11px}";
document.head.appendChild(css);

function open(id){
  if(document.getElementById("teBack")) return;
  var src=find(id); if(!src) return say("Template not found");
  var tpl=clone(src), F=fields(tpl), orig=F.map(function(f){return f.get();});
  var b=document.createElement("div"); b.className="teb"; b.id="teBack";
  var rows=F.length?F.map(function(f,i){ return '<div class="tef"><label for="teF'+i+'">'+f.kind+' '+(i+1)+'</label><textarea id="teF'+i+'" data-i="'+i+'" rows="'+Math.min(4,String(orig[i]).split("\n").length)+'">'+esc(orig[i])+'</textarea></div>'; }).join(""):'<p>This template has no text to edit.</p>';
  b.innerHTML='<div class="tec" role="dialog" aria-label="Edit template text"><h3>Aa Edit text — '+esc(src.name)+'</h3><p>Change the words, then add it to the timeline. New lines work (Enter).</p>'
   +'<canvas id="teCv" width="480" height="270"></canvas>'+rows
   +'<div class="tebtn"><button id="teReset">Reset text</button><button id="teSave">'+(src.user?'Save changes':'Save as my template')+'</button><button id="teCopy" '+(src.user?'':'style="display:none"')+'>Save copy</button><button id="teX">Cancel</button><button class="p" id="teGo" '+(F.length?'':'disabled')+'>Add to timeline</button></div></div>';
  document.body.appendChild(b);
  function paint(){ try{ if(api().paint) api().paint(b.querySelector("#teCv"),tpl); }catch(e){ window.__swl&&window.__swl(e); } }
  paint();
  function close(){ b.remove(); }
  b.addEventListener("input",function(e){ var t=e.target; if(t.dataset.i==null) return; F[+t.dataset.i].set(t.value); paint(); });
  b.addEventListener("keydown",function(e){ e.stopPropagation(); if(e.key==="Escape") close(); },true);
  b.addEventListener("pointerdown",function(e){ if(e.target===b) close(); });
  b.querySelector("#teX").onclick=close;
  b.querySelector("#teReset").onclick=function(){ F.forEach(function(f,i){ f.set(orig[i]); b.querySelector("#teF"+i).value=orig[i]; }); paint(); };
  b.querySelector("#teGo").onclick=function(){ api().apply(tpl); close(); };
  function persist(asCopy){
    var L=api().userTpls(), n=clone(tpl);
    if(src.user&&!asCopy){ var i=L.findIndex(function(u){return u.id===src.id;}); if(i<0) return say("Could not find that saved template"); n.id=src.id; delete n.cat; delete n.user; L[i]=n; }
    else{ n.id="u_"+Date.now().toString(36)+"e"; n.name=(src.name+(src.user?" copy":" (edited)")).slice(0,40); delete n.cat; delete n.user; L.unshift(n); }
    if(!api().saveUser(L.slice(0,60))) return say("Could not save — browser storage is full or blocked");
    say("Saved “"+n.name+"” to My templates"); close();
    try{ if(typeof activePanel!=="undefined"&&activePanel==="templates") renderLeftPanel(); }catch(e){}
  }
  b.querySelector("#teSave").onclick=function(){ persist(false); };
  b.querySelector("#teCopy").onclick=function(){ persist(true); };
  var first=b.querySelector("textarea"); if(first) first.focus();
}

/* ---------- decorate the template gallery ---------- */
function decorate(){
  var g=document.getElementById("tpGrid"); if(!g||g.dataset.teDone||!api()||!api().paint) return;
  g.dataset.teDone="1";
  g.querySelectorAll(".el-tile").forEach(function(t){
    if(t.querySelector(".szTxtBtn")) return;
    var b=document.createElement("button"); b.type="button"; b.className="szTxtBtn"; b.dataset.teEdit=t.dataset.id; b.textContent="Aa Edit text"; b.setAttribute("aria-label","Edit text of template "+(t.getAttribute("aria-label")||"").replace(/^Apply template /,""));
    t.appendChild(b);
  });
  var card=g.parentNode&&g.parentNode.querySelector(".panel-card");
  if(card&&!card.querySelector("#teAsk")){
    var l=document.createElement("label"); l.style.cssText="display:flex;gap:6px;align-items:center;margin-top:8px;font-size:11px;color:#c4bcac;cursor:pointer";
    l.innerHTML='<input type="checkbox" id="teAsk"> Edit text before adding'; card.appendChild(l);
    var c=l.querySelector("input"); c.checked=pref(); c.onchange=function(){ setPref(c.checked); };
  }
  var BTN="[data-pin],[data-upd],[data-ren],[data-dup],[data-del]";
  g.addEventListener("click",function(e){
    var eb=e.target.closest("[data-te-edit]");
    if(eb){ e.stopPropagation(); e.preventDefault(); open(eb.dataset.teEdit); return; }
    var t=e.target.closest(".el-tile");
    if(t&&pref()&&!e.target.closest(BTN)){ e.stopPropagation(); e.preventDefault(); open(t.dataset.id); }
  },true);
  g.addEventListener("keydown",function(e){
    if((e.key==="Enter"||e.key===" ")&&e.target.classList&&e.target.classList.contains("el-tile")&&pref()){ e.stopPropagation(); e.preventDefault(); open(e.target.dataset.id); }
  },true);
}
try{ new MutationObserver(decorate).observe(document.body,{childList:true,subtree:true}); }catch(e){}
document.addEventListener("DOMContentLoaded",decorate); decorate();
window.amiyoTemplateText={open:open,fields:function(id){ var t=find(id); return t?fields(clone(t)).map(function(f){return f.get();}):null; }};
})();

;
/* ==================== Script 1102 id="amiyo-sz-step01" ==================== */
/* Step 1 — speed is visible on the timeline: a coloured band along the top for every stretch that is faster (orange) or slower (blue)
   than normal, and a small "2×" badge on each clip that has its own speed. Display only; the project is never changed. */
(function(){
"use strict";
function fx(v){ return (Math.round(v*100)/100)+"×"; }
function media(c){ var a=project.assets&&project.assets[c.assetId]; return a&&a.type!=="image"&&!c.freeze; }
function zonesNow(){
  var iv=[];
  var vt=project.tracks.filter(function(t){return t.kind==="video";}), at=project.tracks.filter(function(t){return t.kind==="audio";});
  [vt,at].forEach(function(list){ if(iv.length) return;
    list.forEach(function(t){ t.clips.forEach(function(c){ if(media(c)&&Math.abs((c.speed||1)-1)>.001) iv.push({a:c.start,b:c.start+c.duration,v:c.speed}); }); }); });
  iv.sort(function(x,y){return x.a-y.a;});
  var out=[]; iv.forEach(function(z){ var l=out[out.length-1]; if(l&&Math.abs(l.b-z.a)<.03&&Math.abs(l.v-z.v)<.001) l.b=z.b; else out.push({a:z.a,b:z.b,v:z.v}); });
  return out;
}
var css=document.createElement("style");
css.textContent="#amiyoZoneStrip{position:absolute;left:0;top:0;height:0;width:100%;pointer-events:none;z-index:7}"
+"#amiyoZoneStrip i{position:absolute;top:0;height:7px;border-radius:0 0 3px 3px;font:700 8px/7px system-ui;color:#1a0c03;text-align:center;overflow:hidden;white-space:nowrap;pointer-events:auto;cursor:pointer}"
+"#amiyoZoneStrip i.f{background:#ff9a3d}#amiyoZoneStrip i.s{background:#ff915a}"
+".szBadge{position:absolute;right:3px;bottom:2px;padding:0 4px;border-radius:4px;background:rgba(255,154,61,.92);color:#1a0c03;font:700 9px/14px system-ui;pointer-events:none;z-index:3}"
+".szBadge.s{background:rgba(255,145,90,.92)}";
document.head.appendChild(css);
function draw(){
  try{
    var host=document.getElementById("timelineInner"); if(!host) return;
    var strip=document.getElementById("amiyoZoneStrip");
    if(!strip||!strip.isConnected){ strip=document.createElement("div"); strip.id="amiyoZoneStrip"; host.appendChild(strip); }
    var L=labelW(), z=zonesNow();
    strip.innerHTML=z.map(function(q){ var w=Math.max(3,timeToPx(q.b-q.a)); return '<i class="'+(q.v>1?"f":"s")+'" title="Speed '+fx(q.v)+' · '+q.a.toFixed(2)+'s – '+q.b.toFixed(2)+'s (click to edit)" data-a="'+q.a+'" data-b="'+q.b+'" style="left:'+(L+timeToPx(q.a))+'px;width:'+w+'px">'+(w>26?fx(q.v):"")+'</i>'; }).join("");
    document.querySelectorAll("#tracks .clip").forEach(function(el){
      if(el.querySelector(".szBadge")) return;
      var f=null; project.tracks.forEach(function(t){ t.clips.forEach(function(c){ if(c.id===el.dataset.clip) f=c; }); });
      if(f&&media(f)&&Math.abs((f.speed||1)-1)>.001){ var b=document.createElement("span"); b.className="szBadge"+(f.speed<1?" s":""); b.textContent=fx(f.speed); el.appendChild(b); }
    });
  }catch(e){ window.__swl&&window.__swl(e); }
}
var prev=window.renderTimeline; window.renderTimeline=function(){ var r=prev.apply(this,arguments); draw(); return r; };
document.addEventListener("click",function(e){ var i=e.target.closest&&e.target.closest("#amiyoZoneStrip i"); if(i&&window.amiyoSpeedZones) window.amiyoSpeedZones.open(); },true);
window.amiyoSpeedZones=window.amiyoSpeedZones||{}; window.amiyoSpeedZones.current=zonesNow;
setTimeout(draw,300);
})();

;
/* ==================== Script 1103 id="amiyo-pr2-s01-speed-duration" ==================== */
/* Premiere step 1: Speed / Duration dialog (Ctrl+R, like Premiere Pro). Select clips, press Ctrl+R or the "Speed" button above the timeline.
   Set Speed % or Duration (they follow each other), Reverse, and Ripple Edit (clips after it move so no gap or overlap). Linked picture/sound partners change together. One Undo undoes it all. */
(function(){"use strict";
if(window.AMIYO_PR2_S01) return;
function $(i){return document.getElementById(i)}
function num(v,d){v=parseFloat(v);return isFinite(v)?v:d}
function targets(){
  var out=[],seen={},sel=[];
  try{sel=selectedClips()||[]}catch(e){}
  sel.forEach(function(f){ if(f&&f.clip&&f.clip.assetId&&!seen[f.clip.id]){seen[f.clip.id]=1;out.push(f)} });
  var ids={}; out.forEach(function(f){ if(f.clip.linkId) ids[f.clip.linkId]=1 });
  if(Object.keys(ids).length) project.tracks.forEach(function(t){ (t.clips||[]).forEach(function(c){ if(c.linkId&&ids[c.linkId]&&c.assetId&&!seen[c.id]){seen[c.id]=1;out.push({track:t,clip:c})} }) });
  return out.filter(function(f){return !f.track.locked});
}
function span(c){var s=(c.outPoint||0)-(c.inPoint||0); if(!(s>0)) s=(c.duration||0)*(c.speed||1); return Math.max(.01,s)}
function fmt(x){return (Math.round(x*100)/100).toString()}
function open(){
  var T=targets();
  if(!T.length){ try{toast("Select a video or sound clip first, then press Ctrl+R")}catch(e){} return; }
  var c0=T[0].clip, one=T.length===1, sp0=Math.round((c0.speed||1)*10000)/100;
  var h='<div style="display:grid;gap:10px;min-width:260px;max-width:420px">'+
   '<div class="note" style="font-size:12px;opacity:.85">'+T.length+' clip'+(T.length>1?'s':'')+' (picture and sound that belong together change together).</div>'+
   '<label class="field">Speed (%)</label><input id="pr2sSp" type="number" min="10" max="1000" step="1" value="'+sp0+'">'+
   '<label class="field">Duration (seconds)</label><input id="pr2sDu" type="number" min="0.05" step="0.01" value="'+(one?fmt(c0.duration):"")+'" '+(one?"":"disabled placeholder=\"one clip only\"")+'>'+
   '<label style="display:flex;gap:8px;align-items:center"><input id="pr2sRev" type="checkbox"'+(c0.reverse?" checked":"")+'> Reverse speed (play backwards)</label>'+
   '<label style="display:flex;gap:8px;align-items:center"><input id="pr2sRip" type="checkbox" checked> Ripple edit: move the clips after it</label>'+
   '<div id="pr2sInfo" class="note" style="font-size:12px"></div>'+
   '<div style="display:flex;gap:8px;justify-content:flex-end"><button class="toolbtn" id="pr2sReset" type="button">100%</button><button class="toolbtn" id="pr2sCancel" type="button">Cancel</button><button class="toolbtn tool-active" id="pr2sOk" type="button">OK</button></div></div>';
  openModal("Clip Speed / Duration",h);
  var sp=$("pr2sSp"),du=$("pr2sDu"),info=$("pr2sInfo");
  function sv(){return Math.min(1000,Math.max(10,num(sp.value,100)))}
  function upd(){ var tot=0; T.forEach(function(f){tot+=span(f.clip)/(sv()/100)}); info.textContent="New length: "+fmt(tot)+" s"+(T.length>1?" (all clips together)":"")+" at "+fmt(sv())+"% speed." }
  sp.addEventListener("input",function(){ if(one){ du.value=fmt(span(c0)/(sv()/100)) } upd() });
  du.addEventListener("input",function(){ var d=num(du.value,0); if(d>0){ sp.value=fmt(Math.min(1000,Math.max(10,span(c0)/d*100))) } upd() });
  $("pr2sReset").onclick=function(){ sp.value=100; sp.dispatchEvent(new Event("input")) };
  $("pr2sCancel").onclick=close;
  $("pr2sOk").onclick=function(){ apply(T,sv()/100,$("pr2sRev").checked,$("pr2sRip").checked); close() };
  upd(); setTimeout(function(){try{sp.focus();sp.select()}catch(e){}},30);
}
function close(){ try{ $("modalBackdrop").style.display="none" }catch(e){} }
function apply(T,speed,rev,ripple){
  var bf=deepClone(serializableProject()), moved=0, clamped=0, ids={};
  T.forEach(function(f){ ids[f.clip.id]=1 });
  var plan=T.map(function(f){ var c=f.clip,old=c.duration||0,nd=span(c)/speed; return {f:f,c:c,old:old,nd:nd,oldEnd:(c.start||0)+old}; });
  plan.forEach(function(p){
    if(!ripple){ /* do not run over the next clip on the same track */
      var nxt=Infinity; (p.f.track.clips||[]).forEach(function(o){ if(!ids[o.id]&&(o.start||0)>=p.oldEnd-1e-6&&o.start<nxt) nxt=o.start });
      var room=nxt-(p.c.start||0); if(p.nd>room+1e-6&&room>.05){ p.nd=room; clamped++ }
    }
  });
  plan.forEach(function(p){
    var c=p.c; c.speed=Math.round(span(c)/p.nd*1e6)/1e6; c.reverse=!!rev; c.duration=p.nd;
    if(c.transitionIn&&c.transitionIn.duration>p.nd/2) c.transitionIn.duration=Math.max(.05,p.nd/2);
    if(c.transitionOut&&c.transitionOut.duration>p.nd/2) c.transitionOut.duration=Math.max(.05,p.nd/2);
    if(ripple){ var d=p.nd-p.old;
      if(Math.abs(d)>1e-9) (p.f.track.clips||[]).forEach(function(o){ if(!ids[o.id]&&(o.start||0)>=p.oldEnd-1e-6){ o.start=Math.max(0,(o.start||0)+d); moved++ } });
    }
  });
  recordHistory("Clip speed / duration",bf,serializableProject()); scheduleAutosave(); renderAll();
  try{ toast("Speed set to "+fmt(speed*100)+"%"+(rev?" (reversed)":"")+(moved?" · "+moved+" clip"+(moved>1?"s":"")+" moved":"")+(clamped?" · limited so it does not cover the next clip":"")) }catch(e){}
}
window.addEventListener("keydown",function(e){
  if((e.ctrlKey||e.metaKey)&&!e.shiftKey&&!e.altKey&&(e.key==="r"||e.key==="R")){
    var t=e.target,tag=t&&t.tagName; if(tag==="INPUT"||tag==="TEXTAREA"||tag==="SELECT"||(t&&t.isContentEditable)) return;
    e.preventDefault(); e.stopPropagation(); open();
  }
},true);
function addBtn(){
  var b=$("fitTimelineBtn"); if(!b||$("pr2sBtn")) return;
  var n=document.createElement("button"); n.className="toolbtn"; n.id="pr2sBtn"; n.type="button"; n.textContent="⏱ Speed"; n.title="Speed / Duration (Ctrl+R)";
  n.addEventListener("click",open); b.parentNode.insertBefore(n,b.nextSibling);
}
addBtn(); document.addEventListener("DOMContentLoaded",addBtn); setTimeout(addBtn,800);
window.AMIYO_PR2_S01={open:open,apply:apply};
try{window.AMIYO_EDITOR_BUILD="pr2-step01-speed-duration"}catch(e){}
})();

;
/* ==================== Script 1104 id="amiyo-pr2-s02-frame-size" ==================== */
/* Premiere step 2: Frame size. Select picture clips, press Shift+F or the "⛶ Frame" button: Set to Frame Size (whole picture visible), Fill Frame (no black bars),
   Stretch to Frame, or Reset position/scale/rotation. Works on all selected clips, one Undo. */
(function(){"use strict";
if(window.AMIYO_PR2_S02) return;
function $(i){return document.getElementById(i)}
function vis(){ var o=[],s={}; try{(selectedClips()||[]).forEach(function(f){ var c=f.clip; if(!s[c.id]&&!f.track.locked&&(c.assetId||c.kind==="text"||c.kind==="adjustment")){s[c.id]=1;o.push(c)} })}catch(e){} return o; }
function H(label,fn){ var bf=deepClone(serializableProject()); fn(); recordHistory(label,bf,serializableProject()); scheduleAutosave(); renderAll(); }
function apply(mode){
  var L=vis(); if(!L.length){ try{toast("Select a picture clip first")}catch(e){} return false; }
  H("Frame size",function(){ L.forEach(function(c){
    if(mode==="reset"){ c.x=.5;c.y=.5;c.scale=1;c.rotation=0; return; }
    c.fit=mode; c.x=.5; c.y=.5; c.scale=1; });
  });
  try{toast(({contain:"Set to frame size",cover:"Filled the frame",stretch:"Stretched to frame",reset:"Position reset"})[mode]+" · "+L.length+" clip"+(L.length>1?"s":""))}catch(e){}
  return true;
}
function open(){
  var L=vis(); if(!L.length){ try{toast("Select a picture clip first")}catch(e){} return; }
  var b=function(m,t,d){return '<button class="toolbtn" type="button" data-pr2f="'+m+'" style="text-align:left;padding:10px"><b>'+t+'</b><br><span style="font-size:11px;opacity:.75">'+d+'</span></button>'};
  openModal("Frame size",'<div style="display:grid;gap:8px;min-width:260px;max-width:380px">'+
   b("contain","Set to Frame Size","The whole picture fits inside the frame (black bars if shapes differ).")+
   b("cover","Fill Frame","The picture fills the frame. Edges may be cut off.")+
   b("stretch","Stretch to Frame","Squeezes the picture to match the frame exactly.")+
   b("reset","Reset position","Back to the centre, 100% size, no turn.")+'</div>');
  Array.prototype.forEach.call(document.querySelectorAll("[data-pr2f]"),function(e){ e.onclick=function(){ if(apply(e.getAttribute("data-pr2f"))) $("modalBackdrop").style.display="none" } });
}
window.addEventListener("keydown",function(e){
  if(e.shiftKey&&!e.ctrlKey&&!e.metaKey&&!e.altKey&&(e.key==="F"||e.key==="f")){
    var t=e.target,g=t&&t.tagName; if(g==="INPUT"||g==="TEXTAREA"||g==="SELECT"||(t&&t.isContentEditable)) return;
    e.preventDefault(); open(); }
},true);
function addBtn(){ var b=$("pr2sBtn")||$("fitTimelineBtn"); if(!b||$("pr2fBtn")) return;
  var n=document.createElement("button"); n.className="toolbtn"; n.id="pr2fBtn"; n.type="button"; n.textContent="⛶ Frame"; n.title="Frame size (Shift+F)"; n.onclick=open; b.parentNode.insertBefore(n,b.nextSibling); }
addBtn(); document.addEventListener("DOMContentLoaded",addBtn); setTimeout(addBtn,900);
window.AMIYO_PR2_S02={open:open,apply:apply};
try{window.AMIYO_EDITOR_BUILD="pr2-step02-frame-size"}catch(e){}
})();

;
/* ==================== Script 1105 id="amiyo-pr2-s03-shortcuts" ==================== */
/* Premiere step 3: Premiere keyboard edits. Ctrl+K = Add Edit (cut selected clips, or every clip under the playhead if none selected).
   Ctrl+Shift+K = Add Edit to all tracks. Q = Ripple Trim Previous Edit to Playhead (removes the start up to the playhead and closes the gap).
   W = Ripple Trim Next Edit to Playhead (removes the end after the playhead and closes the gap). Playhead must be over the clip. */
(function(){"use strict";
if(window.AMIYO_PR2_S03) return;
var EPS=.001;
function under(all){
  var out=[],t=currentTime,sel={};
  try{(selectedClips()||[]).forEach(function(f){sel[f.clip.id]=1})}catch(e){}
  var hasSel=Object.keys(sel).length>0;
  project.tracks.forEach(function(tr){ if(tr.locked) return; (tr.clips||[]).forEach(function(c){
    if(t>c.start+.03&&t<c.start+c.duration-.03&&(all||!hasSel||sel[c.id])) out.push({track:tr,clip:c}); }); });
  return out;
}
function addEdit(all){
  var L=under(all); if(!L.length){ try{toast("Move the playhead over a clip first")}catch(e){} return 0; }
  var t=currentTime; L.forEach(function(f){ try{splitClipAt(f.track.id,f.clip.id,t)}catch(e){} });
  try{toast("Edit added"+(L.length>1?" on "+L.length+" clips":""))}catch(e){} return L.length;
}
function rippleTrim(which){
  var t=currentTime,sel={},hasSel=false;
  try{(selectedClips()||[]).forEach(function(f){sel[f.clip.id]=1;hasSel=true})}catch(e){}
  var L=[]; project.tracks.forEach(function(tr){ if(tr.locked) return; (tr.clips||[]).forEach(function(c){
    if(t>c.start+EPS&&t<c.start+c.duration-EPS&&(!hasSel||sel[c.id])) L.push({track:tr,clip:c}); }); });
  if(!L.length){ try{toast("Move the playhead over a clip first")}catch(e){} return 0; }
  var bf=deepClone(serializableProject());
  L.forEach(function(f){ var c=f.clip,sp=c.speed||1,oldEnd=c.start+c.duration,removed;
    if(which==="prev"){ removed=t-c.start; c.inPoint=(c.inPoint||0)+removed*sp; c.duration-=removed; c.start=t-removed; /* keeps its place on the timeline */
      project.tracks.forEach(function(tr){ if(tr.locked) return; (tr.clips||[]).forEach(function(o){ if(o!==c&&o.start>=oldEnd-EPS) o.start=Math.max(0,o.start-removed); }); });
    } else { removed=oldEnd-t; c.outPoint=(c.outPoint!=null?c.outPoint:(c.inPoint||0)+c.duration*sp)-removed*sp; c.duration-=removed;
      project.tracks.forEach(function(tr){ if(tr.locked) return; (tr.clips||[]).forEach(function(o){ if(o!==c&&o.start>=oldEnd-EPS) o.start=Math.max(0,o.start-removed); }); });
    }
    if(c.transitionIn&&c.transitionIn.duration>c.duration/2) c.transitionIn.duration=Math.max(.05,c.duration/2);
    if(c.transitionOut&&c.transitionOut.duration>c.duration/2) c.transitionOut.duration=Math.max(.05,c.duration/2);
  });
  recordHistory(which==="prev"?"Ripple trim previous edit":"Ripple trim next edit",bf,serializableProject()); scheduleAutosave(); renderAll();
  try{toast((which==="prev"?"Trimmed start to playhead":"Trimmed end to playhead")+" · gap closed")}catch(e){} return L.length;
}
window.addEventListener("keydown",function(e){
  var t=e.target,g=t&&t.tagName; if(g==="INPUT"||g==="TEXTAREA"||g==="SELECT"||(t&&t.isContentEditable)) return;
  var k=(e.key||"").toLowerCase();
  if((e.ctrlKey||e.metaKey)&&!e.altKey&&k==="k"){ e.preventDefault(); e.stopPropagation(); addEdit(e.shiftKey); return; }
  if(!e.ctrlKey&&!e.metaKey&&!e.altKey&&!e.shiftKey&&(k==="q"||k==="w")){ e.preventDefault(); e.stopPropagation(); rippleTrim(k==="q"?"prev":"next"); }
},true);
window.AMIYO_PR2_S03={addEdit:addEdit,rippleTrim:rippleTrim};
try{window.AMIYO_EDITOR_BUILD="pr2-step03-shortcuts"}catch(e){}
})();

