/* ==================== Script 1106 id="amiyo-pr2-s04-ripple-gaps" ==================== */
/* Premiere step 4: Ripple delete and gaps. Shift+Delete removes every selected clip (and its linked picture/sound partner) and slides everything later on all
   unlocked tracks left by the removed time. Alt+Shift+Delete or the "Close gaps" button closes the empty gap under the playhead. One Undo. */
(function(){"use strict";
if(window.AMIYO_PR2_S04) return;
function $(i){return document.getElementById(i)}
function rippleDelete(){
  var sel=[],ids={},links={};
  try{(selectedClips()||[]).forEach(function(f){ if(!f.track.locked){ sel.push(f); ids[f.clip.id]=1; if(f.clip.linkId) links[f.clip.linkId]=1 } })}catch(e){}
  if(!sel.length){ try{toast("Select a clip first")}catch(e){} return 0; }
  project.tracks.forEach(function(t){ if(t.locked) return; (t.clips||[]).forEach(function(c){ if(c.linkId&&links[c.linkId]&&!ids[c.id]){ids[c.id]=1; sel.push({track:t,clip:c})} }) });
  var bf=deepClone(serializableProject()), rng=sel.map(function(f){return [f.clip.start,f.clip.start+f.clip.duration]}).sort(function(a,b){return a[0]-b[0]});
  var m=[]; rng.forEach(function(r){ var l=m[m.length-1]; if(l&&r[0]<=l[1]+1e-6) l[1]=Math.max(l[1],r[1]); else m.push(r.slice()) });
  project.tracks.forEach(function(t){ if(t.locked) return; t.clips=(t.clips||[]).filter(function(c){return !ids[c.id]}); });
  project.tracks.forEach(function(t){ if(t.locked) return; (t.clips||[]).forEach(function(c){ var sh=0; m.forEach(function(r){ if(c.start>=r[1]-1e-6) sh+=r[1]-r[0] }); if(sh) c.start=Math.max(0,c.start-sh); }); });
  try{selectedClipId=null}catch(e){}
  recordHistory("Ripple delete",bf,serializableProject()); scheduleAutosave(); renderAll();
  try{toast("Ripple deleted "+sel.length+" clip"+(sel.length>1?"s":""))}catch(e){} return sel.length;
}
function closeGapAtPlayhead(){
  var t=currentTime,bf=deepClone(serializableProject()),best=null;
  project.tracks.forEach(function(tr){ if(tr.locked) return; var cs=(tr.clips||[]).slice().sort(function(a,b){return a.start-b.start}),prevEnd=0;
    cs.forEach(function(c){ if(c.start>prevEnd+.01&&t>=prevEnd-1e-6&&t<=c.start+1e-6){ var g=c.start-prevEnd; if(!best||g<best.g) best={s:prevEnd,e:c.start,g:g}; } prevEnd=Math.max(prevEnd,c.start+c.duration); }); });
  if(!best){ try{toast("Put the playhead inside an empty gap first")}catch(e){} return 0; }
  project.tracks.forEach(function(tr){ if(tr.locked) return; (tr.clips||[]).forEach(function(c){ if(c.start>=best.e-1e-6) c.start=Math.max(0,c.start-best.g); }); });
  recordHistory("Close gap",bf,serializableProject()); scheduleAutosave(); renderAll();
  try{toast("Gap of "+(Math.round(best.g*100)/100)+" s closed")}catch(e){} return 1;
}
window.addEventListener("keydown",function(e){
  var t=e.target,g=t&&t.tagName; if(g==="INPUT"||g==="TEXTAREA"||g==="SELECT"||(t&&t.isContentEditable)) return;
  if(e.shiftKey&&!e.ctrlKey&&!e.metaKey&&(e.key==="Delete"||e.key==="Backspace")){ e.preventDefault(); e.stopPropagation(); if(e.altKey) closeGapAtPlayhead(); else rippleDelete(); }
},true);
function addBtn(){ var b=$("pr2fBtn")||$("pr2sBtn")||$("fitTimelineBtn"); if(!b||$("pr2gBtn")) return;
  var n=document.createElement("button"); n.className="toolbtn"; n.id="pr2gBtn"; n.type="button"; n.textContent="⇤ Close gap"; n.title="Close the empty gap under the playhead (Alt+Shift+Delete)"; n.onclick=closeGapAtPlayhead; b.parentNode.insertBefore(n,b.nextSibling); }
addBtn(); document.addEventListener("DOMContentLoaded",addBtn); setTimeout(addBtn,1000);
window.AMIYO_PR2_S04={rippleDelete:rippleDelete,closeGap:closeGapAtPlayhead};
try{window.AMIYO_EDITOR_BUILD="pr2-step04-ripple-gaps"}catch(e){}
})();

