function addBtn(){ var b=$("pr2gBtn")||$("fitTimelineBtn"); if(!b||$("pr2tBtn")) return;
  var n=document.createElement("button"); n.className="toolbtn"; n.id="pr2tBtn"; n.type="button"; n.textContent="✂ Trim"; n.title="Trim mode (T)"; n.onclick=open; b.parentNode.insertBefore(n,b.nextSibling); }
addBtn(); document.addEventListener("DOMContentLoaded",addBtn); setTimeout(addBtn,1100);
