/* ==================== Script 1108 id="amiyo-pr2-s06-track-targets" ==================== */
/* Premiere step 6: Track target buttons on the track headers. Each track label gets a ◎ button, like Premiere's V1/A1 patch buttons: click it to make
   that track the target for Insert/Overwrite (video and audio each have one). The lit button shows the current target. */
(function(){"use strict";
if(window.AMIYO_PR2_S06) return;
function tgt(){ project.targets=project.targets||{}; return project.targets; }
function kindOf(t){ return (t.kind||t.type)==="audio"?"audio":"video"; }
function current(k){ var id=tgt()[k]; var l=project.tracks.filter(function(t){return kindOf(t)===k}); var f=l.filter(function(t){return t.id===id})[0]; return f?f.id:(l[0]&&l[0].id); }
function setTarget(id){ var t=project.tracks.filter(function(x){return x.id===id})[0]; if(!t) return false; var k=kindOf(t);
  var bf=deepClone(serializableProject()); tgt()[k]=t.id; recordHistory("Track target",bf,serializableProject()); scheduleAutosave(); decorate();
  try{toast((t.name||t.kind||"Track")+" is now the "+k+" target")}catch(e){} return true; }
function labels(){ return Array.prototype.slice.call(document.querySelectorAll("#tracks .track-label")); }
function trackOf(lab,i){ var row=lab.closest(".track,.track-row")||lab.parentNode; var id=row&&(row.getAttribute("data-track")||row.getAttribute("data-track-id")||row.dataset&&row.dataset.id);
  var t=project.tracks.filter(function(x){return x.id===id})[0]; return t||project.tracks[i]; }
function decorate(){
  try{ labels().forEach(function(lab,i){ var t=trackOf(lab,i); if(!t) return; var b=lab.querySelector(".pr2-tgt");
    if(!b){ b=document.createElement("button"); b.type="button"; b.className="pr2-tgt"; b.style.cssText="border:1px solid #666;background:transparent;color:#aaa;border-radius:4px;font-size:11px;margin-left:4px;padding:0 5px;cursor:pointer";
      b.addEventListener("click",function(e){ e.stopPropagation(); e.preventDefault(); var id=this.getAttribute("data-tid"); if(id) setTarget(id); }); lab.appendChild(b); }
    b.setAttribute("data-tid",t.id); var on=current(kindOf(t))===t.id; b.textContent=(kindOf(t)==="audio"?"A":"V")+(on?" ◉":" ◎"); b.style.color=on?"#ffb454":"#aaa"; b.style.borderColor=on?"#ffb454":"#666"; b.title="Make this the "+kindOf(t)+" target for Insert / Overwrite"; }); }catch(e){}
}
var ra=window.renderAll; if(typeof ra==="function"&&!ra.__pr2s06){ window.renderAll=function(){ var r=ra.apply(this,arguments); decorate(); return r; }; window.renderAll.__pr2s06=true; }
try{ var tr=document.getElementById("tracks"); if(tr&&window.MutationObserver) new MutationObserver(function(){ if(!decorate.busy){ decorate.busy=1; setTimeout(function(){decorate.busy=0;decorate()},60) } }).observe(tr,{childList:true}); }catch(e){}
setTimeout(decorate,600); setTimeout(decorate,1500);
window.AMIYO_PR2_S06={setTarget:setTarget,current:current,decorate:decorate};
try{window.AMIYO_EDITOR_BUILD="pr2-step06-track-targets"}catch(e){}
})();

