/* ==================== Script 1109 id="amiyo-pr2-s07-program-monitor" ==================== */
/* Premiere step 7: Program monitor. A strip under the picture: big timecode (hours:minutes:seconds:frames), picture zoom (Fit 25% 50% 100% 200%),
   Go to In / Go to Out, Previous / Next edit, and a Lift / Extract pair that cuts the In-to-Out range (Extract closes the gap, Lift leaves it). */
(function(){"use strict";
if(window.AMIYO_PR2_S07) return;
function $(i){return document.getElementById(i)}
function fps(){ try{return +project.settings.fps||30}catch(e){return 30} }
function p2(n){return (n<10?"0":"")+n}
function tc(t){ var f=fps(),tf=Math.round(t*f),fr=tf%Math.round(f),s=Math.floor(tf/Math.round(f)); return p2(Math.floor(s/3600))+":"+p2(Math.floor(s%3600/60))+":"+p2(s%60)+":"+p2(fr); }
function range(){ var i=null,o=null; try{ i=ioIn; o=ioOut }catch(e){} return (i!=null&&o!=null&&o>i)?{i:i,o:o}:null; }
function edits(){ var a={}; project.tracks.forEach(function(t){ (t.clips||[]).forEach(function(c){ a[Math.round(c.start*1000)/1000]=1; a[Math.round((c.start+c.duration)*1000)/1000]=1; }) }); return Object.keys(a).map(Number).sort(function(x,y){return x-y}); }
function go(dir){ var e=edits(),t=currentTime,r=null; if(dir>0){ for(var i=0;i<e.length;i++) if(e[i]>t+.02){r=e[i];break} } else { for(var j=e.length-1;j>=0;j--) if(e[j]<t-.02){r=e[j];break} }
  if(r==null){ try{toast("No more edits")}catch(x){} return; } setCurrentTime(r); }
function cutRange(close){
  var r=range(); if(!r){ try{toast("Set an In and an Out point first (I and O)")}catch(e){} return 0; }
  var bf=deepClone(serializableProject()),len=r.o-r.i;
  project.tracks.forEach(function(t){ if(t.locked) return; var out=[];
    (t.clips||[]).forEach(function(c){ var s=c.start,e=c.start+c.duration,sp=c.speed||1;
      if(e<=r.i+1e-6||s>=r.o-1e-6){ out.push(c); return; }
      if(s<r.i-1e-6&&e>r.o+1e-6){ var right=deepClone(c); right.id=uid("clip"); right.start=r.o; right.duration=e-r.o; right.inPoint=(c.inPoint||0)+(r.o-s)*sp; c.duration=r.i-s; c.outPoint=(c.inPoint||0)+c.duration*sp; out.push(c,right); return; }
      if(s<r.i-1e-6){ c.duration=r.i-s; c.outPoint=(c.inPoint||0)+c.duration*sp; out.push(c); return; }
      if(e>r.o+1e-6){ var cut=r.o-s; c.inPoint=(c.inPoint||0)+cut*sp; c.start=r.o; c.duration=e-r.o; out.push(c); return; }
    }); t.clips=out; });
  if(close) project.tracks.forEach(function(t){ if(t.locked) return; (t.clips||[]).forEach(function(c){ if(c.start>=r.o-1e-6) c.start=Math.max(0,c.start-len); }); });
  recordHistory(close?"Extract":"Lift",bf,serializableProject()); scheduleAutosave(); renderAll();
  try{toast((close?"Extracted ":"Lifted ")+(Math.round(len*100)/100)+" s")}catch(e){} return 1;
}
function build(){
  var shell=$("canvasShell"); if(!shell||$("pr2Prog")) return; var host=shell.closest(".preview-wrap")||shell.parentNode;
  var d=document.createElement("div"); d.id="pr2Prog"; d.style.cssText="display:flex;gap:6px;align-items:center;flex-wrap:wrap;padding:4px 8px;font-size:12px";
  d.innerHTML='<b style="font-size:11px;opacity:.7">PROGRAM</b><span id="pr2Tc" style="font:700 16px ui-monospace,monospace;color:#ffb454">00:00:00:00</span>'+
   '<select id="pr2Zoom" class="toolbtn" title="Picture zoom"><option value="0">Fit</option><option value=".25">25%</option><option value=".5">50%</option><option value="1">100%</option><option value="2">200%</option></select>'+
   '<button class="toolbtn" id="pr2PE" type="button" title="Previous edit">⏮</button><button class="toolbtn" id="pr2NE" type="button" title="Next edit">⏭</button>'+
   '<button class="toolbtn" id="pr2GI" type="button">→In</button><button class="toolbtn" id="pr2GO" type="button">→Out</button>'+
   '<button class="toolbtn" id="pr2Lift" type="button" title="Remove the In–Out range, leave a gap">Lift</button><button class="toolbtn" id="pr2Ext" type="button" title="Remove the In–Out range and close the gap">Extract</button>';
  host.appendChild(d);
  $("pr2PE").onclick=function(){go(-1)}; $("pr2NE").onclick=function(){go(1)};
  $("pr2GI").onclick=function(){ var r=range(); if(r) setCurrentTime(r.i); else try{toast("No In point")}catch(e){} };
  $("pr2GO").onclick=function(){ var r=range(); if(r) setCurrentTime(r.o); else try{toast("No Out point")}catch(e){} };
  $("pr2Lift").onclick=function(){cutRange(false)}; $("pr2Ext").onclick=function(){cutRange(true)};
  $("pr2Zoom").onchange=function(){ var z=+this.value; shell.style.transformOrigin="center center"; shell.style.transform=z?"scale("+z+")":""; };
}
var ut=window.updateTimeUI; function tick(){ var e=$("pr2Tc"); if(e) try{ var _t=tc(currentTime); if(e.textContent!==_t) e.textContent=_t }catch(x){} }
if(typeof ut==="function"&&!ut.__pr2s07){ window.updateTimeUI=function(){ var r=ut.apply(this,arguments); tick(); return r; }; window.updateTimeUI.__pr2s07=true; }
build(); document.addEventListener("DOMContentLoaded",build); setTimeout(function(){build();tick()},800); setInterval(tick,400);
window.AMIYO_PR2_S07={tc:tc,cutRange:cutRange,go:go,setRange:function(i,o){ ioIn=i; ioOut=o }};
try{window.AMIYO_EDITOR_BUILD="pr2-step07-program-monitor"}catch(e){}
})();

