/* ==================== Script 1110 id="amiyo-pr2-s08-workspaces" ==================== */
/* Premiere step 8: Workspaces. A "Workspace" menu in the top bar: Editing, Assembly, Color, Audio, Effects, Graphics, plus "Save current as…" for your own.
   Each one opens the matching tool panel on the left and sets the size of the timeline and the inspector. Your own workspaces are remembered while the page is open (and saved if the browser allows it). */
(function(){"use strict";
if(window.AMIYO_PR2_S08) return;
function $(i){return document.getElementById(i)}
var BUILT={editing:{n:"Editing",panel:"media",tl:0,insp:1},assembly:{n:"Assembly",panel:"media",tl:-1,insp:0},color:{n:"Color",panel:"color",tl:-1,insp:1},audio:{n:"Audio",panel:"audio",tl:1,insp:1},effects:{n:"Effects",panel:"effects",tl:0,insp:1},graphics:{n:"Graphics",panel:"text",tl:-1,insp:1}};
var mine={};
try{ var raw=localStorage.getItem("amiyo_pr2_ws"); if(raw) mine=JSON.parse(raw)||{}; }catch(e){}
function persist(){ try{ localStorage.setItem("amiyo_pr2_ws",JSON.stringify(mine)); }catch(e){} }
function tl(){ return document.querySelector(".timeline"); }
function insp(){ return $("inspectorCol"); }
function apply(ws){
  var b=document.querySelector('.navbtn[data-panel="'+ws.panel+'"]'); if(b) b.click();
  var t=tl(); if(t){ t.style.height=ws.tl>0?"52vh":ws.tl<0?"26vh":""; t.style.flex=ws.tl?"none":""; }
  var i=insp(); if(i) i.style.display=ws.insp?"":"none";
  try{ window.dispatchEvent(new Event("resize")); }catch(e){}
}
function cur(){ var a=document.querySelector(".navbtn.active"); var t=tl(),i=insp(); return {n:"",panel:a?a.getAttribute("data-panel"):"media",tl:t&&t.style.height?(parseFloat(t.style.height)>40?1:-1):0,insp:i&&i.style.display==="none"?0:1}; }
function names(){ return Object.keys(BUILT).concat(Object.keys(mine).map(function(k){return "my:"+k})); }
function pick(k){ var ws=k.indexOf("my:")===0?mine[k.slice(3)]:BUILT[k]; if(!ws) return false; apply(ws); try{toast("Workspace: "+(ws.n||k.replace("my:","")))}catch(e){} try{ $("pr2Ws").value=k }catch(e){} return true; }
function save(){ var n=prompt("Name this workspace","My layout"); if(!n) return; n=String(n).slice(0,24); mine[n]=cur(); mine[n].n=n; persist(); rebuild(); pick("my:"+n); }
function rebuild(){ var s=$("pr2Ws"); if(!s) return; var v=s.value; s.innerHTML="";
  names().forEach(function(k){ var o=document.createElement("option"); o.value=k; o.textContent=k.indexOf("my:")===0?"★ "+k.slice(3):BUILT[k].n; s.appendChild(o); });
  var o=document.createElement("option"); o.value="__save"; o.textContent="＋ Save current as…"; s.appendChild(o); if(v&&v!=="__save") s.value=v; }
function build(){ var top=document.querySelector(".top-spacer"); if(!top||$("pr2Ws")) return; var s=document.createElement("select"); s.id="pr2Ws"; s.className="topbtn"; s.title="Workspace"; s.style.maxWidth="130px";
  s.onchange=function(){ if(this.value==="__save"){ this.value="editing"; save(); } else pick(this.value); }; top.parentNode.insertBefore(s,top.nextSibling); rebuild(); }
build(); document.addEventListener("DOMContentLoaded",build); setTimeout(build,700);
window.AMIYO_PR2_S08={pick:pick,save:save,names:names};
try{window.AMIYO_EDITOR_BUILD="pr2-step08-workspaces"}catch(e){}
})();

