/* ==================== Script 1111 id="amiyo-pr2-s09-effect-controls" ==================== */
/* Premiere step 9: Effect Controls. Press Shift+5 or the "Fx Controls" button. A floating panel for the selected clip: Position X/Y, Scale, Rotation, Opacity, Speed.
   If the clip has keyframes, changing a value at the playhead sets a keyframe there (like Premiere's stopwatch). ◆ adds a keyframe now, ◀ ▶ jump between keyframes, Clear removes all. */
(function(){"use strict";
if(window.AMIYO_PR2_S09) return;
function $(i){return document.getElementById(i)}
var P=[["x","Position X %",100,0.5,0,100,0.1],["y","Position Y %",100,0.5,0,100,0.1],["scale","Scale %",100,1,1,1000,1],["rotation","Rotation °",1,0,-3600,3600,1],["opacity","Opacity %",100,1,0,100,1]];
function sel(){ try{return getClip()}catch(e){return null} }
function fmt(v){ return Math.round(v*100)/100 }
function valuesAt(c,t){ var k=(c.keyframes||[]).slice().sort(function(a,b){return a.t-b.t}),o={};
  P.forEach(function(p){ var key=p[0],base=c[key]!=null?c[key]:p[3];
    if(!k.length){ o[key]=base; return; }
    var a=null,b=null; k.forEach(function(q){ if(q.t<=t) a=q; else if(!b) b=q; });
    var va=function(q){ return q[key]!=null?q[key]:base };
    if(!a) o[key]=va(k[0]); else if(!b) o[key]=va(a); else { var r=(t-a.t)/Math.max(1e-6,b.t-a.t); o[key]=va(a)+(va(b)-va(a))*r; } });
  return o; }
function upsert(c,t,vals){ c.keyframes=c.keyframes||[]; var k=null; c.keyframes.forEach(function(q){ if(Math.abs(q.t-t)<.02) k=q });
  if(!k){ k={t:t,easing:"linear"}; c.keyframes.push(k); } P.forEach(function(p){ k[p[0]]=vals[p[0]]; }); c.keyframes.sort(function(a,b){return a.t-b.t}); return k; }
function H(label,fn){ var bf=deepClone(serializableProject()); fn(); recordHistory(label,bf,serializableProject()); scheduleAutosave(); renderAll(); }
function setProp(key,disp){
  var f=sel(); if(!f||f.track.locked) return false; var c=f.clip,p=P.filter(function(q){return q[0]===key})[0]; if(!p) return false; var v=+disp/p[2]; if(!isFinite(v)) return false;
  H("Effect controls: "+p[1],function(){ var t=Math.max(0,currentTime-c.start);
    if(c.keyframes&&c.keyframes.length){ var vals=valuesAt(c,t); vals[key]=v; upsert(c,t,vals); } else c[key]=v; }); return true; }
function setSpeed(pct){ var f=sel(); if(!f) return false; var c=f.clip,sp=Math.min(10,Math.max(.1,pct/100)); H("Effect controls: Speed",function(){ var span=Math.max(.01,(c.outPoint||0)-(c.inPoint||0)); c.speed=sp; c.duration=span/sp; }); return true; }
function addKey(){ var f=sel(); if(!f) return false; var c=f.clip,t=Math.max(0,Math.min(c.duration,currentTime-c.start)); H("Add keyframe",function(){ upsert(c,t,valuesAt(c,t)); }); return true; }
function nav(dir){ var f=sel(); if(!f) return; var c=f.clip,t=currentTime-c.start,ks=(c.keyframes||[]).map(function(k){return k.t}).sort(function(a,b){return a-b}),r=null;
  if(dir>0){ for(var i=0;i<ks.length;i++) if(ks[i]>t+.02){r=ks[i];break} } else { for(var j=ks.length-1;j>=0;j--) if(ks[j]<t-.02){r=ks[j];break} }
  if(r!=null) setCurrentTime(c.start+r); }
function clearKeys(){ var f=sel(); if(!f||!(f.clip.keyframes||[]).length) return; H("Clear keyframes",function(){ var v=valuesAt(f.clip,Math.max(0,currentTime-f.clip.start)); f.clip.keyframes=[]; P.forEach(function(p){ f.clip[p[0]]=v[p[0]]; }); }); }
var last="";
function paint(force){
  var box=$("pr2Ec"); if(!box||box.style.display==="none") return; var f=sel(),body=$("pr2EcBody");
  if(!f||!f.clip){ if(last!=="none"||force){ body.innerHTML='<div class="note" style="padding:8px;font-size:12px">Select a clip on the timeline.</div>'; last="none"; } return; }
  var c=f.clip,v=valuesAt(c,Math.max(0,currentTime-c.start)),sig=c.id+"|"+(c.keyframes||[]).length+"|"+Math.round(currentTime*30)+"|"+P.map(function(p){return fmt(v[p[0]])}).join(",")+"|"+(c.speed||1);
  if(sig===last&&!force) return; if(document.activeElement&&document.activeElement.className==="pr2ec-in") return; last=sig;
  var h='<div style="font-size:11px;opacity:.7;padding:2px 8px">'+(c.name||c.kind||"Clip")+" · "+((c.keyframes||[]).length)+' keyframe'+((c.keyframes||[]).length===1?"":"s")+'</div>';
  P.forEach(function(p){ h+='<label style="display:flex;justify-content:space-between;align-items:center;padding:3px 8px;font-size:12px">'+p[1]+'<input class="pr2ec-in" data-k="'+p[0]+'" type="number" min="'+p[4]+'" max="'+p[5]+'" step="'+p[6]+'" value="'+fmt(v[p[0]]*p[2])+'" style="width:80px"></label>'; });
  if(c.assetId) h+='<label style="display:flex;justify-content:space-between;align-items:center;padding:3px 8px;font-size:12px">Speed %<input class="pr2ec-in" data-k="__speed" type="number" min="10" max="1000" step="1" value="'+fmt((c.speed||1)*100)+'" style="width:80px"></label>';
  h+='<div style="display:flex;gap:6px;padding:6px 8px"><button class="toolbtn" id="pr2EcP" type="button" title="Previous keyframe">◀</button><button class="toolbtn" id="pr2EcA" type="button" title="Add keyframe at playhead">◆ Key</button><button class="toolbtn" id="pr2EcN" type="button" title="Next keyframe">▶</button><button class="toolbtn" id="pr2EcC" type="button">Clear</button><button class="toolbtn" id="pr2EcG" type="button" title="Keyframe graph">📈</button></div>';
  body.innerHTML=h;
  Array.prototype.forEach.call(body.querySelectorAll(".pr2ec-in"),function(i){ i.onchange=function(){ var k=i.getAttribute("data-k"); if(k==="__speed") setSpeed(+i.value); else setProp(k,+i.value); last=""; paint(true); }; });
  $("pr2EcP").onclick=function(){nav(-1)}; $("pr2EcN").onclick=function(){nav(1)}; $("pr2EcA").onclick=function(){addKey();last="";paint(true)}; $("pr2EcC").onclick=function(){clearKeys();last="";paint(true)};
  $("pr2EcG").onclick=function(){ if(window.AMIYO_PR2_S10) window.AMIYO_PR2_S10.open(); else try{toast("Graph editor is added in step 10")}catch(e){} };
}
function toggle(show){ var b=$("pr2Ec"); if(!b) build(); b=$("pr2Ec"); b.style.display=(show===undefined?(b.style.display==="none"):show)?"block":"none"; last=""; paint(true); }
function build(){ if($("pr2Ec")||!document.body) return; var d=document.createElement("div"); d.id="pr2Ec"; d.style.cssText="position:fixed;right:10px;bottom:70px;width:250px;max-height:70vh;overflow:auto;background:var(--panel,#29201b);color:var(--text,#fce5d9);border:1px solid var(--line,#394150);border-radius:10px;z-index:9000;display:none;box-shadow:0 8px 28px rgba(0,0,0,.45)";
  d.innerHTML='<div style="display:flex;justify-content:space-between;align-items:center;padding:6px 8px;border-bottom:1px solid var(--line,#394150)"><b style="font-size:12px">Effect Controls</b><button class="toolbtn" id="pr2EcX" type="button" aria-label="Close">✕</button></div><div id="pr2EcBody"></div>'; document.body.appendChild(d); $("pr2EcX").onclick=function(){toggle(false)}; }
window.addEventListener("keydown",function(e){ var t=e.target,g=t&&t.tagName; if(g==="INPUT"||g==="TEXTAREA"||g==="SELECT"||(t&&t.isContentEditable)) return;
  if(e.shiftKey&&!e.ctrlKey&&!e.metaKey&&!e.altKey&&(e.key==="%"||e.code==="Digit5")){ e.preventDefault(); toggle(); } },true);
function addBtn(){ var b=$("pr2tBtn")||$("pr2gBtn")||$("fitTimelineBtn"); if(!b||$("pr2EcBtn")) return; var n=document.createElement("button"); n.className="toolbtn"; n.id="pr2EcBtn"; n.type="button"; n.textContent="Fx Controls"; n.title="Effect Controls (Shift+5)"; n.onclick=function(){toggle()}; b.parentNode.insertBefore(n,b.nextSibling); }
build(); addBtn(); document.addEventListener("DOMContentLoaded",function(){build();addBtn()}); setTimeout(addBtn,1200); setInterval(function(){paint(false)},300);
window.AMIYO_PR2_S09={toggle:toggle,setProp:setProp,addKey:addKey,valuesAt:valuesAt,upsert:upsert,paint:paint};
try{window.AMIYO_EDITOR_BUILD="pr2-step09-effect-controls"}catch(e){}
})();

