/* ==================== Script 1114 id="amiyo-pr2-s12-colour" ==================== */
/* Premiere step 12: Colour (Lumetri-style) panel. Shift+L or Pr Tools > Colour. Exposure, Contrast, Saturation, Blur sliders for the selected clips, with presets
   (Warm film, Cool, Black & white, Punchy) and Reset. Works with the editor's own brightness, contrast, saturation and blur effects, so the preview and export match. */
(function(){"use strict";
if(window.AMIYO_PR2_S12) return;
function $(i){return document.getElementById(i)}
var F=[["brightness","Exposure",-.5,.5,.01,0],["contrast","Contrast",.5,1.6,.01,1],["saturation","Saturation",0,2,.01,1],["blur","Blur",0,20,.5,0]];
function L(){ var o=[],s={}; try{(selectedClips()||[]).forEach(function(f){ if(!f.track.locked&&!s[f.clip.id]&&(f.clip.assetId||f.clip.kind==="adjustment")){s[f.clip.id]=1;o.push(f.clip)} })}catch(e){} return o; }
function fx(c,name){ c.effects=c.effects||[]; var e=c.effects.filter(function(x){return x.name===name})[0]; return e; }
function get(c,k){ var e=fx(c,k[0]); return e&&e.enabled!==false&&e.value!=null?e.value:k[5]; }
function set(c,name,v){ var def=F.filter(function(k){return k[0]===name})[0][5],e=fx(c,name);
  if(Math.abs(v-def)<1e-6){ if(e) c.effects=c.effects.filter(function(x){return x!==e}); return; }
  if(!e){ e={id:uid("fx"),name:name,enabled:true,value:v}; c.effects.push(e); } else { e.enabled=true; e.value=v; } }
function apply(vals){ var l=L(); if(!l.length){ try{toast("Select a clip first")}catch(e){} return 0; }
  pr2H("Colour",function(){ l.forEach(function(c){ Object.keys(vals).forEach(function(k){ set(c,k,vals[k]); }); }); }); return l.length; }
var PRE={"Warm film":{brightness:.04,contrast:1.12,saturation:1.15},"Cool":{brightness:0,contrast:1.08,saturation:.9},"Black & white":{saturation:0,contrast:1.15},"Punchy":{contrast:1.25,saturation:1.4}};
function open(){ var l=L(); if(!l.length){ try{toast("Select a clip first")}catch(e){} return; } var c=l[0];
  var h='<div style="display:grid;gap:8px;min-width:270px;max-width:390px"><div class="note" style="font-size:12px">'+l.length+' clip'+(l.length>1?'s':'')+'. Sliders apply when you let go.</div>'+
   F.map(function(k){ return '<label style="display:flex;justify-content:space-between;font-size:12px">'+k[1]+'<output id="pr2c_o_'+k[0]+'">'+get(c,k)+'</output></label><input type="range" id="pr2c_'+k[0]+'" min="'+k[2]+'" max="'+k[3]+'" step="'+k[4]+'" value="'+get(c,k)+'">'; }).join("")+
   '<div style="display:flex;gap:6px;flex-wrap:wrap">'+Object.keys(PRE).map(function(n){return '<button class="toolbtn" type="button" data-pr2p="'+n+'">'+n+'</button>'}).join("")+'<button class="toolbtn" id="pr2cR" type="button">Reset</button></div></div>';
  openModal("Colour",h);
  F.forEach(function(k){ var r=$("pr2c_"+k[0]); r.oninput=function(){ $("pr2c_o_"+k[0]).textContent=r.value; }; r.onchange=function(){ var v={}; v[k[0]]=+r.value; apply(v); }; });
  Array.prototype.forEach.call(document.querySelectorAll("[data-pr2p]"),function(b){ b.onclick=function(){ var p=PRE[b.getAttribute("data-pr2p")],v={}; F.forEach(function(k){ v[k[0]]=p[k[0]]!=null?p[k[0]]:k[5]; }); apply(v); open(); }; });
  $("pr2cR").onclick=function(){ var v={}; F.forEach(function(k){ v[k[0]]=k[5]; }); apply(v); open(); };
}
pr2Register("Colour (Lumetri)","Shift+L",open); pr2Key(function(e){return e.shiftKey&&!e.ctrlKey&&!e.metaKey&&!e.altKey&&(e.key==="L"||e.key==="l")},open);
window.AMIYO_PR2_S12={open:open,apply:apply,get:function(c,n){return get(c,F.filter(function(k){return k[0]===n})[0])}};
try{window.AMIYO_EDITOR_BUILD="pr2-step12-colour"}catch(e){}
})();

