/* ==================== Script 1115 id="amiyo-pr2-s13-sound" ==================== */
/* Premiere step 13: Essential Sound. Shift+V or Pr Tools > Sound. For the selected clips (and their linked partners): volume %, fade in, fade out, mute,
   and one-tap roles: Dialogue (100%), Music (40%), Effects (80%), Ambience (25%). One Undo. */
(function(){"use strict";
if(window.AMIYO_PR2_S13) return;
function $(i){return document.getElementById(i)}
function L(){ var o=[],s={},links={}; try{(selectedClips()||[]).forEach(function(f){ if(!f.track.locked&&f.clip.assetId&&!s[f.clip.id]){s[f.clip.id]=1;o.push(f.clip);if(f.clip.linkId)links[f.clip.linkId]=1} })}catch(e){}
  if(Object.keys(links).length) project.tracks.forEach(function(t){ if(t.locked) return; (t.clips||[]).forEach(function(c){ if(c.linkId&&links[c.linkId]&&c.assetId&&!s[c.id]){s[c.id]=1;o.push(c)} }); }); return o; }
var ROLE={Dialogue:1,Music:.4,Effects:.8,Ambience:.25};
function apply(o){ var l=L(); if(!l.length){ try{toast("Select a clip with sound first")}catch(e){} return 0; }
  pr2H("Essential Sound",function(){ l.forEach(function(c){ if(o.volume!=null) c.volume=Math.max(0,Math.min(3,o.volume)); if(o.fadeIn!=null) c.fadeIn=Math.max(0,Math.min(c.duration/2,o.fadeIn)); if(o.fadeOut!=null) c.fadeOut=Math.max(0,Math.min(c.duration/2,o.fadeOut)); if(o.muted!=null){ if(o.muted){ c.__vol=c.volume!=null?c.volume:1; c.volume=0; } else { c.volume=c.__vol||1; } } }); }); return l.length; }
function open(){ var l=L(); if(!l.length){ try{toast("Select a clip with sound first")}catch(e){} return; } var c=l[0];
  var h='<div style="display:grid;gap:8px;min-width:260px;max-width:380px"><div style="display:flex;gap:6px;flex-wrap:wrap">'+Object.keys(ROLE).map(function(r){return '<button class="toolbtn" type="button" data-pr2r="'+r+'">'+r+'</button>'}).join("")+'</div>'+
   '<label class="field">Volume %</label><input id="pr2aV" type="number" min="0" max="300" value="'+Math.round((c.volume!=null?c.volume:1)*100)+'">'+
   '<label class="field">Fade in (seconds)</label><input id="pr2aI" type="number" min="0" step="0.1" value="'+(c.fadeIn||0)+'">'+
   '<label class="field">Fade out (seconds)</label><input id="pr2aO" type="number" min="0" step="0.1" value="'+(c.fadeOut||0)+'">'+
   '<div style="display:flex;gap:6px"><button class="toolbtn tool-active" id="pr2aOk" type="button">Apply</button><button class="toolbtn" id="pr2aM" type="button">Mute</button></div></div>';
  openModal("Essential Sound",h);
  Array.prototype.forEach.call(document.querySelectorAll("[data-pr2r]"),function(b){ b.onclick=function(){ apply({volume:ROLE[b.getAttribute("data-pr2r")]}); $("modalBackdrop").style.display="none"; }; });
  $("pr2aOk").onclick=function(){ apply({volume:(+$("pr2aV").value||0)/100,fadeIn:+$("pr2aI").value||0,fadeOut:+$("pr2aO").value||0}); $("modalBackdrop").style.display="none"; };
  $("pr2aM").onclick=function(){ apply({muted:true}); $("modalBackdrop").style.display="none"; };
}
pr2Register("Sound (Essential Sound)","Shift+V",open); pr2Key(function(e){return e.shiftKey&&!e.ctrlKey&&!e.metaKey&&!e.altKey&&(e.key==="V"||e.key==="v")},open);
window.AMIYO_PR2_S13={open:open,apply:apply};
try{window.AMIYO_EDITOR_BUILD="pr2-step13-sound"}catch(e){}
})();

