/* ==================== Script 1116 id="amiyo-pr2-s14-select-forward" ==================== */
/* Premiere step 14: Track select forward. Shift+A selects every clip from the playhead to the end on the selected clip's track (or all unlocked tracks if nothing is
   selected). Alt+Shift+A selects forward on ALL tracks. Then move, delete or ripple them together. */
(function(){"use strict";
if(window.AMIYO_PR2_S14) return;
function run(all){
  var t=currentTime,rows=[],trk=null;
  try{ var f=getClip(); if(f) trk=f.track; }catch(e){}
  project.tracks.forEach(function(tr){ if(tr.locked) return; if(!all&&trk&&tr!==trk) return; (tr.clips||[]).forEach(function(c){ c.selected=false; if(c.start+c.duration>t+1e-6) rows.push(c); }); });
  if(!rows.length){ try{toast("No clips after the playhead")}catch(e){} return 0; }
  project.tracks.forEach(function(tr){ (tr.clips||[]).forEach(function(c){ c.selected=false; }); });
  rows.forEach(function(c){ c.selected=true; }); try{selectedClipId=rows[0].id}catch(e){}
  try{renderAll()}catch(e){} try{toast(rows.length+" clip"+(rows.length>1?"s":"")+" selected forward")}catch(e){} return rows.length; }
pr2Register("Select forward","Shift+A",function(){run(false)}); pr2Register("Select forward (all tracks)","Alt+Shift+A",function(){run(true)});
pr2Key(function(e){return e.shiftKey&&!e.ctrlKey&&!e.metaKey&&(e.key==="A"||e.key==="a")},function(e){run(!!e.altKey)});
window.AMIYO_PR2_S14={run:run};
try{window.AMIYO_EDITOR_BUILD="pr2-step14-select-forward"}catch(e){}
})();

