/* ==================== Script 1117 id="amiyo-pr2-s15-go-to-time" ==================== */
/* Premiere step 15: Go to timecode. Click the big program timecode (or Pr Tools > Go to time, or Ctrl+G) and type a time: 00:01:30:12, 1:30, 90 (seconds), or +30 / -15 frames to move from here. */
(function(){"use strict";
if(window.AMIYO_PR2_S15) return;
function fps(){ try{return +project.settings.fps||30}catch(e){return 30} }
function parse(s){ s=String(s||"").trim(); if(!s) return null; var f=fps(),m;
  if((m=s.match(/^([+-])\s*(\d+)$/))) return currentTime+(m[1]==="-"?-1:1)*(+m[2])/f;
  if(s.indexOf(":")>=0||s.indexOf(";")>=0){ var p=s.split(/[:;]/).map(function(x){return parseFloat(x)||0}); var fr=0,sec=0; if(p.length>=4){ fr=p.pop(); sec=p[0]*3600+p[1]*60+p[2]; } else if(p.length===3){ sec=p[0]*3600+p[1]*60+p[2]; } else if(p.length===2){ sec=p[0]*60+p[1]; } else sec=p[0]; return sec+fr/f; }
  var n=parseFloat(s); return isFinite(n)?n:null; }
function go(s){ var t=parse(s); if(t==null||!isFinite(t)){ try{toast("Type a time like 1:30 or 00:00:10:15")}catch(e){} return false; } setCurrentTime(t); return true; }
function ask(){ var v=prompt("Go to time (e.g. 1:30, 00:00:10:15, 90 seconds, +30 frames)",""); if(v!=null) go(v); }
document.addEventListener("click",function(e){ if(e.target&&e.target.id==="pr2Tc") ask(); },true);
pr2Register("Go to time","Ctrl+G",ask); pr2Key(function(e){return (e.ctrlKey||e.metaKey)&&!e.shiftKey&&!e.altKey&&(e.key==="g"||e.key==="G")},ask);
window.AMIYO_PR2_S15={parse:parse,go:go};
try{window.AMIYO_EDITOR_BUILD="pr2-step15-go-to-time"}catch(e){}
})();

