/* ==================== Script 1118 id="amiyo-pr2-s16-markers" ==================== */
/* Premiere step 16: Markers panel. Shift+M or Pr Tools > Markers. Lists every marker with its time; add one at the playhead, rename, delete, jump to it,
   or copy a ready YouTube chapter list (needs a marker at 0:00 — added for you if missing). */
(function(){"use strict";
if(window.AMIYO_PR2_S16) return;
function $(i){return document.getElementById(i)}
function list(){ project.markers=project.markers||[]; return project.markers.filter(function(m){return isFinite(m.time)}).sort(function(a,b){return a.time-b.time}); }
function mm(t){ t=Math.max(0,Math.round(t)); var h=Math.floor(t/3600),m=Math.floor(t%3600/60),s=t%60; return (h?h+":"+(m<10?"0":""):"")+m+":"+(s<10?"0":"")+s; }
function esc(s){ return String(s==null?"":s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/"/g,"&quot;"); }
function add(label,time){ pr2H("Add marker",function(){ project.markers=project.markers||[]; project.markers.push({id:uid("marker"),time:time!=null?time:currentTime,label:label||"Marker",color:"#ffb454"}); }); }
function chapters(){ var l=list().slice(); if(!l.length||l[0].time>.5) l.unshift({time:0,label:"Intro"}); return l.map(function(m){return mm(m.time)+" "+(m.label||"Chapter")}).join("\n"); }
function open(){ var l=list();
  var h='<div style="display:grid;gap:8px;min-width:280px;max-width:420px"><div style="display:flex;gap:6px"><button class="toolbtn tool-active" id="pr2kA" type="button">＋ Marker at playhead</button><button class="toolbtn" id="pr2kY" type="button">Copy YouTube chapters</button></div>'+
   (l.length?l.map(function(m){ return '<div style="display:flex;gap:6px;align-items:center"><button class="toolbtn" type="button" data-pr2kg="'+m.id+'">'+mm(m.time)+'</button><input data-pr2kn="'+m.id+'" value="'+esc(m.label)+'" style="flex:1;min-width:0"><button class="toolbtn" type="button" data-pr2kd="'+m.id+'" aria-label="Delete marker">🗑</button></div>'; }).join(""):'<div class="note" style="font-size:12px;opacity:.8">No markers yet.</div>')+'</div>';
  openModal("Markers",h);
  $("pr2kA").onclick=function(){ add("Marker "+(list().length+1)); open(); };
  $("pr2kY").onclick=function(){ var t=chapters(); try{ navigator.clipboard.writeText(t).then(function(){toast("Chapter list copied")},function(){prompt("Copy this:",t)}); }catch(e){ prompt("Copy this:",t); } };
  Array.prototype.forEach.call(document.querySelectorAll("[data-pr2kg]"),function(b){ b.onclick=function(){ var m=project.markers.filter(function(x){return x.id===b.getAttribute("data-pr2kg")})[0]; if(m) setCurrentTime(m.time); }; });
  Array.prototype.forEach.call(document.querySelectorAll("[data-pr2kd]"),function(b){ b.onclick=function(){ var id=b.getAttribute("data-pr2kd"); pr2H("Delete marker",function(){ project.markers=project.markers.filter(function(x){return x.id!==id}); }); open(); }; });
  Array.prototype.forEach.call(document.querySelectorAll("[data-pr2kn]"),function(i){ i.onchange=function(){ var id=i.getAttribute("data-pr2kn"),v=i.value; pr2H("Rename marker",function(){ project.markers.forEach(function(x){ if(x.id===id) x.label=v; }); }); }; });
}
pr2Register("Markers","Shift+M",open); pr2Key(function(e){return e.shiftKey&&!e.ctrlKey&&!e.metaKey&&!e.altKey&&(e.key==="M"||e.key==="m")},open);
window.AMIYO_PR2_S16={open:open,add:add,chapters:chapters};
try{window.AMIYO_EDITOR_BUILD="pr2-step16-markers"}catch(e){}
})();

