/* ==================== Script 1119 id="amiyo-pr2-s17-zoom-keys" ==================== */
/* Premiere step 17: Timeline zoom keys. = zoom in, - zoom out, \ zoom to fit the whole edit, Shift+\ zoom to the selected clip(s). The view scrolls to keep your place. */
(function(){"use strict";
if(window.AMIYO_PR2_S17) return;
function $(i){return document.getElementById(i)}
function z(){ return $("timelineZoom"); }
function setZ(v){ var r=z(); if(!r) return false; v=Math.min(+r.max,Math.max(+r.min,v)); r.value=v; r.dispatchEvent(new Event("input",{bubbles:true})); r.dispatchEvent(new Event("change",{bubbles:true})); return v; }
function scrollTo(sec,z0){ var sc=$("timelineScroll"); if(sc) sc.scrollLeft=Math.max(0,sec*(z0||+z().value)-sc.clientWidth*.15); }
function zin(f){ var r=z(); if(!r) return; var keep=currentTime,v=setZ(+r.value*(f||1.4)); if(v) scrollTo(keep-0,v); }
function fitAll(){ var b=$("fitTimelineBtn"); if(b) b.click(); try{toast("Zoomed to fit")}catch(e){} }
function toSel(){ var s=[]; try{s=selectedClips()||[]}catch(e){} if(!s.length){ try{toast("Select a clip first")}catch(e){} return false; }
  var a=Infinity,b=0; s.forEach(function(f){ a=Math.min(a,f.clip.start); b=Math.max(b,f.clip.start+f.clip.duration); }); var sc=$("timelineScroll"); if(!sc) return false;
  var v=setZ(sc.clientWidth*.8/Math.max(.2,b-a)); scrollTo(a,v); return true; }
pr2Register("Zoom to selection","Shift+\\",toSel); pr2Register("Zoom to fit","\\",fitAll);
pr2Key(function(e){return !e.ctrlKey&&!e.metaKey&&!e.altKey&&(e.key==="="||e.key==="+")},function(){zin(1.4)});
pr2Key(function(e){return !e.ctrlKey&&!e.metaKey&&!e.altKey&&(e.key==="-"||e.key==="_")},function(){zin(1/1.4)});
pr2Key(function(e){return !e.ctrlKey&&!e.metaKey&&!e.altKey&&e.key==="\\"},fitAll);
pr2Key(function(e){return !e.ctrlKey&&!e.metaKey&&!e.altKey&&e.key==="|"},toSel);
window.AMIYO_PR2_S17={zin:zin,fitAll:fitAll,toSel:toSel,setZ:setZ};
try{window.AMIYO_EDITOR_BUILD="pr2-step17-zoom-keys"}catch(e){}
})();

