/* ==================== Script 1120 id="amiyo-pr2-s18-reframe" ==================== */
/* Premiere step 18: Auto reframe. Shift+R or Pr Tools > Reframe. Change the whole project's shape (16:9 wide, 9:16 tall for Reels/Shorts, 1:1 square, 4:5 portrait, 21:9 cinema)
   and, if you like, fill the new frame with every picture clip so there are no black bars. Text and clip positions stay where they are in the frame. */
(function(){"use strict";
if(window.AMIYO_PR2_S18) return;
function $(i){return document.getElementById(i)}
var A={"16:9 wide":[1920,1080],"9:16 tall":[1080,1920],"1:1 square":[1080,1080],"4:5 portrait":[1080,1350],"21:9 cinema":[2560,1096]};
function apply(name,fill){ var d=A[name]; if(!d) return false;
  pr2H("Reframe "+name,function(){ project.settings=project.settings||{}; project.settings.width=d[0]; project.settings.height=d[1]; project.settings.aspect=name.split(" ")[0];
    if(fill) project.tracks.forEach(function(t){ if(t.locked) return; (t.clips||[]).forEach(function(c){ if(c.assetId&&(t.kind||t.type)!=="audio"){ c.fit="cover"; c.x=.5; c.y=.5; c.scale=1; } }); }); });
  try{ renderPreviewFrame() }catch(e){} try{toast("Frame is now "+name+" ("+d[0]+"×"+d[1]+")"+(fill?" · pictures fill it":""))}catch(e){} return true; }
function open(){ var s=project.settings||{};
  openModal("Reframe",'<div style="display:grid;gap:8px;min-width:260px;max-width:380px"><div class="note" style="font-size:12px">Now: '+(s.width||1280)+'×'+(s.height||720)+'</div>'+
   Object.keys(A).map(function(n){return '<button class="toolbtn" type="button" data-pr2a="'+n+'" style="text-align:left">'+n+' <span style="opacity:.6">'+A[n][0]+'×'+A[n][1]+'</span></button>'}).join("")+
   '<label style="display:flex;gap:8px;align-items:center"><input id="pr2aF" type="checkbox" checked> Fill the new frame with the pictures</label></div>');
  Array.prototype.forEach.call(document.querySelectorAll("[data-pr2a]"),function(b){ b.onclick=function(){ apply(b.getAttribute("data-pr2a"),$("pr2aF").checked); $("modalBackdrop").style.display="none"; }; }); }
pr2Register("Reframe (aspect ratio)","Shift+R",open); pr2Key(function(e){return e.shiftKey&&!e.ctrlKey&&!e.metaKey&&!e.altKey&&(e.key==="R"||e.key==="r")},open);
window.AMIYO_PR2_S18={open:open,apply:apply,presets:A};
try{window.AMIYO_EDITOR_BUILD="pr2-step18-reframe"}catch(e){}
})();

