    c.globalCompositeOperation="lighter"; var col=["rgba(255,70,60,.8)","rgba(70,230,90,.8)","rgba(255,138,80,.8)"];
    for(ch=0;ch<3;ch++){ c.fillStyle=col[ch]; for(b=0;b<256;b++){ var bh=Math.min(1,h[ch][b]/mx)*(SH-4); c.fillRect(b/256*SW,SH-bh,Math.ceil(SW/256)+.5,bh); } }
