    for(y=0;y<H;y+=sy) for(x=0;x<W;x+=sx){ i=(y*W+x)*4; var r=d[i]/255,g=d[i+1]/255,bl=d[i+2]/255; var cb=-.1146*r-.3854*g+.5*bl, cr=.5*r-.4542*g-.0458*bl; var px=Math.round(SH/2+cb*2*R), py=Math.round(SH/2-cr*2*R); if(px>=0&&px<SH&&py>=0&&py<SH){ var v=++acc[py*SH+px]; if(v>mxv) mxv=v; } total++; if(d[i]>=254||d[i+1]>=254||d[i+2]>=254) hi++; if(d[i]<=1&&d[i+1]<=1&&d[i+2]<=1) lo++; }
    c.strokeStyle="rgba(255,255,255,.18)"; c.beginPath(); c.arc(cx,cy,R,0,7); c.stroke(); c.beginPath(); c.arc(cx,cy,R/2,0,7); c.stroke(); c.beginPath(); c.moveTo(cx-R,cy); c.lineTo(cx+R,cy); c.moveTo(cx,cy-R); c.lineTo(cx,cy+R); c.stroke();
    c.strokeStyle="rgba(255,190,120,.7)"; c.beginPath(); c.moveTo(cx,cy); var sa=-123*Math.PI/180; /* skin tone line */ c.lineTo(cx+Math.cos(sa)*-R*.0+Math.cos(Math.PI*.6)*0, cy); c.stroke();
    var ox=cx-SH/2; var id=c.getImageData(0,0,SW,SH), o=id.data;
    for(py=0;py<SH;py++) for(px=0;px<SH;px++){ var a=acc[py*SH+px]; if(!a) continue; var t=Math.min(1,Math.sqrt(a/mxv)*1.4), k=((py)*SW+(px+Math.round(ox)))*4; o[k]=Math.min(255,o[k]+60+t*195); o[k+1]=Math.min(255,o[k+1]+80+t*175); o[k+2]=Math.min(255,o[k+2]+70+t*185); }
    c.putImageData(id,0,0);
