/* ==================== Script 1129 id="amiyo-pro-s01-zoom" ==================== */
/* Pro step 1 of 20: faster timeline zoom. A zoom tap used to animate for 150 ms and rebuild the whole timeline on every frame (about 9 rebuilds). It now measures how long a rebuild takes and jumps straight to the target when rebuilds are slow, so zooming stays quick on long edits and still glides on short ones. */
(function(){ try{ window.AMIYO_PRO_STEP=1; window.AMIYO_EDITOR_BUILD="pro-step01-zoom"; }catch(e){} })();

;
/* ==================== Script 1130 id="amiyo-fix-s02-log-slider" ==================== */
/* Fix step 2 of 20: the zoom slider is now logarithmic. It used to be linear (10 to 1500), so the first half of the line did almost nothing visible to
   the "seconds on screen" and the last bit jumped a lot. Now every equal move along the line zooms by the same factor.
   The slider still reports plain zoom numbers through .value / .min / .max, so every other script (buttons, Shift+Z, saved zoom, pinch, presets) works unchanged. */
(function(){ try{
  var z=document.getElementById("timelineZoom"); if(!z||z.__log) return;
  var P=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,"value"), LO=(typeof AZ_MIN==="number"?AZ_MIN:(+z.getAttribute("min")||1)), HI=(typeof AZ_MAX==="number"?AZ_MAX:(+z.getAttribute("max")||6000)), N=100000, K=Math.log(HI/LO);
  function toPos(v){ v=+v; if(!isFinite(v)||v<LO) v=LO; if(v>HI) v=HI; return Math.round(N*Math.log(v/LO)/K); }
  function toZoom(p){ p=+p; if(!isFinite(p)) p=0; var v=LO*Math.exp(K*Math.max(0,Math.min(N,p))/N); return v<10?Math.round(v*10)/10:Math.round(v); }
  var cur=timelineZoom;
  z.setAttribute("min","0"); z.setAttribute("max",String(N)); z.setAttribute("step","1");
  Object.defineProperty(z,"value",{configurable:true,get:function(){ return String(toZoom(P.get.call(z))); },set:function(v){ P.set.call(z,String(toPos(v))); }});
  Object.defineProperty(z,"min",{configurable:true,get:function(){ return String(LO); },set:function(){}});
  Object.defineProperty(z,"max",{configurable:true,get:function(){ return String(HI); },set:function(){}});
  Object.defineProperty(z,"valueAsNumber",{configurable:true,get:function(){ return +z.value; },set:function(v){ z.value=v; }});
  /* keyboard: one arrow press zooms by 10% (Page Up/Down 40%, Home/End = min/max); the raw position step is far too fine to notice */
  z.addEventListener("keydown",function(e){
    if(e.ctrlKey||e.metaKey||e.altKey) return;
    var k=e.key, f=k==="ArrowRight"||k==="ArrowUp"?1.1:k==="ArrowLeft"||k==="ArrowDown"?1/1.1:k==="PageUp"?1.4:k==="PageDown"?1/1.4:0, v=+z.value;
    if(k==="Home") v=LO; else if(k==="End") v=HI; else if(f) v=Math.max(LO,Math.min(HI,Math.round(v*f)===v?v+(f>1?1:-1):Math.round(v*f))); else return;
    e.preventDefault(); e.stopPropagation(); z.value=v;
    z.dispatchEvent(new Event("input",{bubbles:true})); z.dispatchEvent(new Event("change",{bubbles:true}));
  },true);
  z.__log=1; z.value=cur;
  z.title="Timeline zoom (log scale: each step along the line zooms by the same factor)";
  window.AMIYO_FIX_S02={toPos:toPos,toZoom:toZoom};
  try{ window.AMIYO_EDITOR_BUILD="fix-step02-log-slider"; }catch(e){}
}catch(e){ try{console.warn("fix-s02",e)}catch(_){} } })();

