    if(gest&&Math.abs(e.clientX-last.x)>MOVE_PX){ if(raf){ cancelAnimationFrame(raf); flush(); } gest=null; }   /* the mouse moved: aim at the new spot */
    if(!gest){ gest={vx:vx,t:(ts.scrollLeft+vx-lw())/getTimelinePx()}; last.x=e.clientX; }
