/* ==================== Script 1135 id="amiyo-ag-s01-audio-gain" ==================== */
/* Professional Audio step 1: AUDIO GAIN (Premiere's G). Select clips, press G or Pr Tools > Audio gain. Set gain to a dB value, adjust by a dB amount, or Normalize the loudest peak to a target.
   Unlike the Volume slider (stops at 100%) this can BOOST quiet recordings up to +24 dB. Heard in preview on audio-track clips and baked into export for every clip. One undo step. */
(function(){"use strict";
if(window.AMIYO_AG_S01) return;
function $(i){return document.getElementById(i)}
var MAXDB=24, MINDB=-60;
function lin(db){ return Math.pow(10,db/20); }
function gainDb(c){ var g=+c.gainDb; return isFinite(g)?Math.max(MINDB,Math.min(MAXDB,g)):0; }
window.amiyoGainLin=function(c){ try{ return lin(gainDb(c)); }catch(e){ return 1; } };
function clipById(id){ for(var i=0;i<project.tracks.length;i++){ var cs=project.tracks[i].clips||[]; for(var j=0;j<cs.length;j++) if(cs[j].id===id) return cs[j]; } return null; }
/* preview: the gain node sits right after the clip's sound, so every effect after it hears the boosted sound */
function applyPreview(){ try{ if(typeof audioNodes==="undefined") return;
  audioNodes.forEach(function(n,id){ if(!n||!n.gain) return; var c=clipById(id); if(!c) return; var v=window.__agBypass?1:lin(gainDb(c)); if(Math.abs(n.gain.value-v)>.001){ try{ n.gain.value=v; }catch(e){} } }); }catch(e){} }
setInterval(applyPreview,150);
function targets(){ var s=[]; try{ s=selectedClips()||[]; }catch(e){} return s.map(function(f){return f.clip}).filter(function(c){return c&&c.assetId}); }
var ctxCache=new Map();
async function peakOf(c){ /* loudest sample of the part of the file this clip plays, 0..1 (null = no sound found) */
  var a=getAsset(c.assetId); if(!a) return null; var key=a.id||c.assetId, buf=ctxCache.get(key);
  if(!buf){ try{ var blob=ASSET_BLOBS.get(a.id), ab; if(blob) ab=await blob.arrayBuffer(); else{ var u=await ensureUrl(a); if(!u) return null; ab=await (await fetch(u)).arrayBuffer(); }
      buf=await new OfflineAudioContext(1,1,44100).decodeAudioData(ab); ctxCache.set(key,buf); }catch(e){ return null; } }
  var sr=buf.sampleRate, i0=Math.max(0,Math.floor((c.inPoint||0)*sr)), i1=Math.min(buf.length,Math.floor(((c.inPoint||0)+c.duration*(c.speed||1))*sr)), pk=0;
  for(var ch=0;ch<buf.numberOfChannels;ch++){ var d=buf.getChannelData(ch); for(var i=i0;i<i1;i++){ var v=d[i]<0?-d[i]:d[i]; if(v>pk) pk=v; } }
  return pk; }
function fmt(db){ return (db>0?"+":"")+db.toFixed(1)+" dB"; }
function open(){ var cl=targets(); if(!cl.length){ try{toast("Select one or more clips first, then press G")}catch(e){} return; }
  var cur=cl.length===1?gainDb(cl[0]):0;
  var h='<div style="display:grid;gap:10px;min-width:270px;max-width:380px"><div style="opacity:.8;font-size:12px">'+cl.length+' clip'+(cl.length>1?'s':'')+' selected'+(cl.length===1?' · now '+fmt(cur):'')+'</div>'+
  '<label><input type="radio" name="agm" value="set" checked> Set gain to <input id="agV" type="number" step="0.5" min="-60" max="24" value="'+cur.toFixed(1)+'" style="width:70px"> dB</label>'+
  '<label><input type="radio" name="agm" value="adj"> Adjust gain by <input id="agA" type="number" step="0.5" value="3" style="width:70px"> dB</label>'+
  '<label><input type="radio" name="agm" value="norm"> Normalize loudest peak to <input id="agN" type="number" step="0.5" max="0" value="-1" style="width:70px"> dB</label>'+
  '<label><input type="radio" name="agm" value="reset"> Reset to 0 dB</label>'+
  '<div id="agMsg" style="min-height:16px;font-size:12px;opacity:.85">Range −60 to +24 dB. Boosting loud clips can distort; use Normalize for a safe level.</div>'+
  '<div style="display:flex;gap:8px;justify-content:flex-end"><button class="toolbtn" id="agX" type="button">Cancel</button><button class="toolbtn tool-active" id="agOK" type="button">Apply</button></div></div>';
  openModal("Audio gain",h);
  $("agX").onclick=function(){ $("modalBackdrop").style.display="none"; };
  ["agV","agA","agN"].forEach(function(id,i){ $(id).onfocus=function(){ document.querySelectorAll('input[name=agm]')[i].checked=true; }; });
  $("agOK").onclick=async function(){ var mode=document.querySelector('input[name=agm]:checked').value, msg=$("agMsg"), out=[];
    try{ if(mode==="norm"){ var tgt=Math.min(0,parseFloat($("agN").value)); if(!isFinite(tgt)) tgt=-1; msg.textContent="Measuring…"; var low=0;
        for(var i=0;i<cl.length;i++){ var pk=await peakOf(cl[i]); if(pk==null||pk<.0005){ out.push(null); low++; } else out.push(tgt-20*Math.log10(pk)); }
        if(low===cl.length){ msg.textContent="No sound found in the selected clip"+(cl.length>1?"s":"")+"."; return; }
        if(low) try{toast(low+" clip"+(low>1?"s":"")+" had no sound and were skipped")}catch(e){} }
      else if(mode==="set"){ var v=parseFloat($("agV").value); if(!isFinite(v)){ msg.textContent="Type a number of dB."; return; } out=cl.map(function(){return v}); }
      else if(mode==="adj"){ var a=parseFloat($("agA").value); if(!isFinite(a)){ msg.textContent="Type a number of dB."; return; } out=cl.map(function(c){return gainDb(c)+a}); }
      else out=cl.map(function(){return 0});
      pr2H("Audio gain",function(){ cl.forEach(function(c,i){ if(out[i]==null) return; var g=Math.max(MINDB,Math.min(MAXDB,out[i])); if(Math.abs(g)<.05) delete c.gainDb; else c.gainDb=Math.round(g*10)/10; }); });
      applyPreview(); $("modalBackdrop").style.display="none";
      try{ toast("Audio gain: "+(cl.length===1?fmt(gainDb(cl[0])):cl.length+" clips updated")); }catch(e){}
    }catch(e){ msg.textContent="Could not change the gain: "+(e&&e.message||e); } };
}
pr2Register("Audio gain","G",open);
pr2Key(function(e){ return !e.ctrlKey&&!e.metaKey&&!e.altKey&&!e.shiftKey&&(e.key==="g"||e.key==="G"); },open);
window.AMIYO_AG_S01={open:open,peakOf:peakOf,gainDb:gainDb,apply:applyPreview};
try{window.AMIYO_EDITOR_BUILD="ag-step01-audio-gain"}catch(e){}
})();

