function clipById(id){ for(var i=0;i<project.tracks.length;i++){ var cs=project.tracks[i].clips||[]; for(var j=0;j<cs.length;j++) if(cs[j].id===id) return cs[j]; } return null; }
function apply(){ try{ var m=window.__amiyoVGain; if(!m) return; m.forEach(function(n,id){ if(!n||!n.gain) return; var c=clipById(id); if(!c) return; var v=window.__agBypass?1:lin(c); if(Math.abs(n.gain.value-v)>.001){ try{ n.gain.value=v; }catch(e){} } }); }catch(e){} }
