/* ==================== Script 1137 id="amiyo-ag-s03-select-at-playhead" ==================== */
/* Professional Editing step 3: SELECT AT PLAYHEAD. Alt+P (or Pr Tools > Select clips at playhead) selects every clip the playhead is touching, on every unlocked track, so you can gain, delete, move or copy a whole stack at once.
   Pr Tools > Invert selection inverts the selection (everything that was not selected, on unlocked tracks). Both are shown in a toast with the count. */
(function(){"use strict";
if(window.AMIYO_AG_S03) return;
function pick(test,label){ var n=0,first=null;
  try{ clearMultiSelection(); }catch(e){}
  project.tracks.forEach(function(t){ if(t.locked) return; (t.clips||[]).forEach(function(c){ if(test(c,t)){ c.selected=true; n++; if(!first) first=c.id; } }); });
  try{ selectedClipId=first; }catch(e){}
  try{ renderAll(); }catch(e){}
  try{ toast(n?(label+": "+n+" clip"+(n>1?"s":"")):"No clips there"); }catch(e){}
  return n; }
function atPlayhead(){ var t=currentTime; return pick(function(c){ return c.start<=t+1e-6&&t<c.start+c.duration-1e-6; },"Selected at playhead"); }
function invert(){ var was={}; selectedClips().forEach(function(f){ was[f.clip.id]=1; }); return pick(function(c){ return !was[c.id]; },"Inverted selection"); }
pr2Register("Select clips at playhead","Alt+P",atPlayhead); pr2Register("Invert selection","menu",invert);
pr2Key(function(e){ return e.altKey&&!e.ctrlKey&&!e.metaKey&&!e.shiftKey&&e.code==="KeyP"; },atPlayhead);
window.AMIYO_AG_S03={atPlayhead:atPlayhead,invert:invert};
try{window.AMIYO_EDITOR_BUILD="ag-step03-select-at-playhead"}catch(e){}
})();

