/* ==================== Script 1138 id="amiyo-ag-s04-offset-clips" ==================== */
/* Professional Editing step 4: OFFSET CLIPS. Alt+O is taken, so use Alt+Shift+O or Pr Tools > Offset clips. Type an exact move for the selected clips: 2.5 (seconds), +12f / -12f (frames), or 0:01:05 style. Positive moves later, negative earlier.
   Clips keep their gaps between each other. If the move would push a clip onto another clip, or before 0:00, nothing changes and you are told why. One undo step. */
(function(){"use strict";
if(window.AMIYO_AG_S04) return;
function fps(){ try{ return +project.settings.fps||30; }catch(e){ return 30; } }
function parse(s){ s=String(s||"").trim().toLowerCase(); if(!s) return null; var m, sign=1;
  if(s[0]==="+"||s[0]==="-"){ sign=s[0]==="-"?-1:1; s=s.slice(1).trim(); }
  if((m=s.match(/^(\d+(?:\.\d+)?)\s*f(?:rames?)?$/))) return sign*(+m[1])/fps();
  if((m=s.match(/^(\d+(?:\.\d+)?)\s*(?:s|sec|secs|seconds?)?$/))) return sign*(+m[1]);
  if(s.indexOf(":")>=0){ var p=s.split(":").map(function(x){return parseFloat(x)}); if(p.some(function(x){return !isFinite(x)})) return null; var sec=0; p.forEach(function(x){ sec=sec*60+x; }); return sign*sec; }
  return null; }
function offset(dt){ var sel=selectedClips(); if(!sel.length) return {ok:false,why:"Select one or more clips first"};
  if(!isFinite(dt)||Math.abs(dt)<1e-6) return {ok:false,why:"Type an amount like 2.5, +12f or -0:01"};
  var ids={}; sel.forEach(function(f){ ids[f.clip.id]=1; });
  var minStart=Math.min.apply(null,sel.map(function(f){return f.clip.start;}));
  if(minStart+dt<-1e-6) return {ok:false,why:"That would move a clip before 0:00 (you can move it at most "+minStart.toFixed(2)+"s earlier)"};
  for(var i=0;i<sel.length;i++){ var f=sel[i]; if(f.track.locked) return {ok:false,why:"Track "+(f.track.name||"")+" is locked"};
    var a=f.clip.start+dt, b=a+f.clip.duration;
    for(var j=0;j<f.track.clips.length;j++){ var o=f.track.clips[j]; if(ids[o.id]) continue; if(a<o.start+o.duration-1e-6&&b>o.start+1e-6) return {ok:false,why:"That would land on another clip on "+(f.track.name||"the track")}; } }
  pr2H("Offset clips",function(){ sel.forEach(function(f){ f.clip.start=Math.round((f.clip.start+dt)*1000)/1000; f.track.clips.sort(function(x,y){return x.start-y.start;}); }); });
  return {ok:true,n:sel.length}; }
function open(){ if(!selectedClips().length){ try{toast("Select one or more clips first")}catch(e){} return; }
  var h='<div style="display:grid;gap:10px;min-width:260px"><div style="font-size:12px;opacity:.8">Move '+selectedClips().length+' selected clip(s) by:</div><input id="ofV" value="+1" style="font-size:16px" autocomplete="off"><div style="font-size:12px;opacity:.75">Examples: 2.5 &nbsp; +12f &nbsp; -30f &nbsp; -0:01</div><div id="ofM" style="min-height:16px;font-size:12px;color:#ff9b9b"></div><div style="display:flex;gap:8px;justify-content:flex-end"><button class="toolbtn" id="ofX" type="button">Cancel</button><button class="toolbtn tool-active" id="ofOK" type="button">Move</button></div></div>';
  openModal("Offset clips",h); var inp=document.getElementById("ofV"); setTimeout(function(){ inp.focus(); inp.select(); },30);
  function go(){ var dt=parse(inp.value); if(dt==null){ document.getElementById("ofM").textContent="Type a number like 2.5, +12f or -0:01"; return; } var r=offset(dt); if(!r.ok){ document.getElementById("ofM").textContent=r.why; return; } document.getElementById("modalBackdrop").style.display="none"; try{ toast("Moved "+r.n+" clip"+(r.n>1?"s":"")+" by "+inp.value.trim()); }catch(e){} }
  document.getElementById("ofOK").onclick=go; document.getElementById("ofX").onclick=function(){ document.getElementById("modalBackdrop").style.display="none"; };
  inp.addEventListener("keydown",function(e){ if(e.key==="Enter"){ e.preventDefault(); go(); } e.stopPropagation(); }); }
pr2Register("Offset clips","Alt+Shift+O",open);
pr2Key(function(e){ return e.altKey&&e.shiftKey&&!e.ctrlKey&&!e.metaKey&&e.code==="KeyO"; },open);
window.AMIYO_AG_S04={parse:parse,offset:offset,open:open};
try{window.AMIYO_EDITOR_BUILD="ag-step04-offset-clips"}catch(e){}
})();

