/* ==================== Script 1139 id="amiyo-ag-s05-select-matching" ==================== */
/* Professional Editing step 5: SELECT MATCHING. Pr Tools > "Select same source": with a clip selected, selects every other clip on the timeline that plays the same media file (on unlocked tracks), e.g. to colour-grade, gain or delete all the shots of one interview.
   Pr Tools > "Select whole track" selects every clip on the track of the selected clip. Shown with a count. */
(function(){"use strict";
if(window.AMIYO_AG_S05) return;
function run(test,label){ var n=0,first=null; try{ clearMultiSelection(); }catch(e){}
  project.tracks.forEach(function(t){ if(t.locked) return; (t.clips||[]).forEach(function(c){ if(test(c,t)){ c.selected=true; n++; if(!first) first=c.id; } }); });
  try{ selectedClipId=first; }catch(e){} try{ renderAll(); }catch(e){}
  try{ toast(label+": "+n+" clip"+(n===1?"":"s")); }catch(e){} return n; }
function sameSource(){ var s=selectedClips(); if(!s.length){ try{toast("Select a clip first")}catch(e){} return 0; }
  var ids={}; s.forEach(function(f){ if(f.clip.assetId) ids[f.clip.assetId]=1; });
  if(!Object.keys(ids).length){ try{toast("That clip has no media file (text or shape)")}catch(e){} return 0; }
  return run(function(c){ return c.assetId&&ids[c.assetId]; },"Same source"); }
function wholeTrack(){ var s=selectedClips(); if(!s.length){ try{toast("Select a clip first")}catch(e){} return 0; }
  var ids={}; s.forEach(function(f){ ids[f.track.id]=1; });
  return run(function(c,t){ return ids[t.id]; },"Whole track"); }
pr2Register("Select same source","menu",sameSource); pr2Register("Select whole track","menu",wholeTrack);
window.AMIYO_AG_S05={sameSource:sameSource,wholeTrack:wholeTrack};
try{window.AMIYO_EDITOR_BUILD="ag-step05-select-matching"}catch(e){}
})();

