/* ==================== Script 1140 id="amiyo-ag-s06-match-loudness" ==================== */
/* Professional Audio step 6: MATCH LOUDNESS. Pr Tools > "Match loudness": select several clips (e.g. interview shots recorded at different levels) and give them all the same average loudness (RMS dB).
   Pick a target, or use "Average of the selected clips". With "Keep peaks under -1 dB" ticked a clip is not boosted past clipping. Uses the Audio Gain value from step 1, so it is one undo step and can be tweaked with G. */
(function(){"use strict";
if(window.AMIYO_AG_S06) return;
function $(i){return document.getElementById(i)}
var cache=new Map();
async function stats(c){ var a=getAsset(c.assetId); if(!a) return null; var key=a.id||c.assetId, buf=cache.get(key);
  if(!buf){ try{ var blob=ASSET_BLOBS.get(a.id), ab; if(blob) ab=await blob.arrayBuffer(); else{ var u=await ensureUrl(a); if(!u) return null; ab=await (await fetch(u)).arrayBuffer(); }
      buf=await new OfflineAudioContext(1,1,44100).decodeAudioData(ab); cache.set(key,buf); }catch(e){ return null; } }
  var sr=buf.sampleRate, i0=Math.max(0,Math.floor((c.inPoint||0)*sr)), i1=Math.min(buf.length,Math.floor(((c.inPoint||0)+c.duration*(c.speed||1))*sr)), pk=0, sum=0, n=0;
  for(var ch=0;ch<buf.numberOfChannels;ch++){ var d=buf.getChannelData(ch); for(var i=i0;i<i1;i++){ var v=d[i]; sum+=v*v; n++; var av=v<0?-v:v; if(av>pk) pk=av; } }
  if(!n||pk<.0005) return null; var rms=Math.sqrt(sum/n); return {rms:20*Math.log10(rms),peak:20*Math.log10(pk)}; }
function g0(c){ var g=+c.gainDb; return isFinite(g)?g:0; }
async function match(target,keepPeaks,msg){ var cl=selectedClips().map(function(f){return f.clip}).filter(function(c){return c.assetId});
  if(cl.length<1) return {ok:false,why:"Select the clips to match first"};
  var st=[]; for(var i=0;i<cl.length;i++) st.push(await stats(cl[i])); var ok=st.filter(Boolean);
  if(!ok.length) return {ok:false,why:"No sound found in the selected clips"};
  if(target==null) target=ok.reduce(function(s,x){return s+x.rms;},0)/ok.length;
  var out=[],capped=0;
  cl.forEach(function(c,i){ var s=st[i]; if(!s){ out.push(null); return; } var want=target-s.rms; if(keepPeaks&&s.peak+want>-1){ want=-1-s.peak; capped++; } out.push(Math.max(-60,Math.min(24,want))); });
  pr2H("Match loudness",function(){ cl.forEach(function(c,i){ if(out[i]==null) return; var g=Math.round(out[i]*10)/10; if(Math.abs(g)<.05) delete c.gainDb; else c.gainDb=g; }); });
  return {ok:true,n:ok.length,skipped:cl.length-ok.length,capped:capped,target:Math.round(target*10)/10,gains:out.map(function(x){return x==null?null:Math.round(x*10)/10})}; }
function open(){ var n=selectedClips().length; if(n<1){ try{toast("Select the clips to match first")}catch(e){} return; }
  var h='<div style="display:grid;gap:10px;min-width:270px;max-width:380px"><div style="font-size:12px;opacity:.8">'+n+' clip(s) selected. Make them all the same average loudness:</div>'+
  '<label><input type="radio" name="mlm" value="avg" checked> Average of the selected clips</label>'+
  '<label><input type="radio" name="mlm" value="num"> Target <input id="mlT" type="number" step="1" max="0" min="-60" value="-20" style="width:64px"> dB (RMS) · speech is usually −20 to −16</label>'+
  '<label><input id="mlP" type="checkbox" checked> Keep peaks under −1 dB (avoids distortion)</label><div id="mlM" style="min-height:16px;font-size:12px;opacity:.85"></div>'+
  '<div style="display:flex;gap:8px;justify-content:flex-end"><button class="toolbtn" id="mlX" type="button">Cancel</button><button class="toolbtn tool-active" id="mlOK" type="button">Match</button></div></div>';
  openModal("Match loudness",h); $("mlX").onclick=function(){ $("modalBackdrop").style.display="none"; }; $("mlT").onfocus=function(){ document.querySelector('input[name=mlm][value=num]').checked=true; };
  $("mlOK").onclick=async function(){ var m=$("mlM"); m.textContent="Measuring…"; var t=document.querySelector('input[name=mlm]:checked').value==="num"?parseFloat($("mlT").value):null; if(t!=null&&!isFinite(t)){ m.textContent="Type a number of dB."; return; }
    var r=await match(t,$("mlP").checked,m); if(!r.ok){ m.textContent=r.why; return; } $("modalBackdrop").style.display="none";
    try{ toast("Matched "+r.n+" clip"+(r.n>1?"s":"")+" to "+r.target+" dB"+(r.capped?" · "+r.capped+" held back to avoid clipping":"")+(r.skipped?" · "+r.skipped+" had no sound":"")); }catch(e){} }; }
pr2Register("Match loudness","menu",open);
window.AMIYO_AG_S06={match:match,stats:stats,open:open};
try{window.AMIYO_EDITOR_BUILD="ag-step06-match-loudness"}catch(e){}
})();

;
/* ==================== Script 1141 id="amiyo-ag-s07-gain-badge" ==================== */
/* Professional Audio step 7: GAIN BADGE. Every timeline clip that has an Audio Gain (step 1 or Match loudness) shows a small "+12 dB" chip in its top-right corner (red when boosted more than +12 dB, because that can distort).
   Click the chip to open the Audio Gain window for that clip. Clips with no gain show nothing. */
(function(){"use strict";
if(window.AMIYO_AG_S07) return;
var css=document.createElement("style"); css.textContent=".agBadge{position:absolute;right:3px;top:2px;z-index:6;font:600 10px/1 system-ui,sans-serif;padding:2px 4px;border-radius:4px;background:rgba(32,24,20,.82);color:#ffbf9f;cursor:pointer;pointer-events:auto}.agBadge.hot{background:#8f1d1d;color:#fff}.agBadge.cut{color:#ffd78a}";
document.head.appendChild(css);
function find(id){ for(var i=0;i<project.tracks.length;i++){ var cs=project.tracks[i].clips||[]; for(var j=0;j<cs.length;j++) if(cs[j].id===id) return cs[j]; } return null; }
function sweep(){ try{ var els=document.querySelectorAll(".clip[data-clip]");
  for(var i=0;i<els.length;i++){ var el=els[i], c=find(el.getAttribute("data-clip")), b=el.querySelector(":scope > .agBadge"), g=c&&+c.gainDb;
    if(!c||!isFinite(g)||Math.abs(g)<.05){ if(b) b.remove(); continue; }
    var txt=(g>0?"+":"")+g.toFixed(1)+" dB";
    if(!b){ b=document.createElement("span"); b.className="agBadge"; b.title="Audio gain · click to change"; b.setAttribute("data-agclip",c.id);
      if(getComputedStyle(el).position==="static") el.style.position="relative"; el.appendChild(b); }
    if(b.textContent!==txt) b.textContent=txt; b.className="agBadge"+(g>12?" hot":g<0?" cut":""); } }catch(e){} }
function onBadge(e){ var t=e.target&&e.target.closest?e.target.closest(".agBadge"):null; if(!t) return null; e.stopPropagation(); e.preventDefault(); return t; }
document.addEventListener("pointerdown",onBadge,true);
document.addEventListener("click",function(e){ var t=onBadge(e); if(!t) return; try{ var id=t.getAttribute("data-agclip"), cl=find(id); clearMultiSelection(); if(cl) cl.selected=true; selectedClipId=id; }catch(x){} try{ window.AMIYO_AG_S01.open(); }catch(x){} },true);
setInterval(sweep,400);
window.AMIYO_AG_S07={sweep:sweep};
try{window.AMIYO_EDITOR_BUILD="ag-step07-gain-badge"}catch(e){}
})();

