/* ==================== Script 1142 id="amiyo-ag-s08-gain-check" ==================== */
/* Professional Audio step 8: GAIN CHECK. Pr Tools > "Gain check" scans every clip that has an Audio Gain and works out its loudest peak AFTER the boost. Clips that would go over 0 dB (distortion) are listed in red, near-limit ones in amber.
   "Fix all" lowers each too-loud clip's gain so its peak sits at -1 dB. Click a clip name to jump the playhead to it. One undo step. */
(function(){"use strict";
if(window.AMIYO_AG_S08) return;
function $(i){return document.getElementById(i)}
function esc(s){ return String(s==null?"":s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/"/g,"&quot;"); }
function gainClips(){ var out=[]; project.tracks.forEach(function(t){ (t.clips||[]).forEach(function(c){ if(c.assetId&&isFinite(+c.gainDb)&&Math.abs(+c.gainDb)>=.05) out.push({c:c,t:t}); }); }); return out; }
function nm(c){ var a=getAsset(c.assetId); return (c.name||(a&&a.name)||"Clip"); }
async function scan(){ var list=gainClips(), res=[];
  for(var i=0;i<list.length;i++){ var c=list[i].c, st=null; try{ st=await window.AMIYO_AG_S06.stats(c); }catch(e){}
    if(!st){ res.push({c:c,name:nm(c),peak:null,state:"nosound"}); continue; }
    var after=st.peak+(+c.gainDb); res.push({c:c,name:nm(c),track:list[i].t.name||"",peak:after,state:after>0?"over":after>-0.9?"near":"ok"}); }
  return res; }
async function fixAll(res){ var bad=res.filter(function(r){return r.state==="over"||r.state==="near"&&false;}); if(!bad.length) return 0;
  pr2H("Fix gain clipping",function(){ bad.forEach(function(r){ var g=(+r.c.gainDb)-(r.peak+1); g=Math.round(g*10)/10; if(Math.abs(g)<.05) delete r.c.gainDb; else r.c.gainDb=Math.max(-60,g); }); });
  return bad.length; }
async function open(){ openModal("Gain check",'<div style="min-width:280px;font-size:13px">Checking…</div>'); var res=await scan();
  var over=res.filter(function(r){return r.state==="over"}).length, near=res.filter(function(r){return r.state==="near"}).length;
  var h='<div style="display:grid;gap:8px;min-width:290px;max-width:420px">'+
   (!res.length?'<div>No clips have an Audio Gain yet. Select clips and press G.</div>':'<div style="font-size:12px;opacity:.85">'+res.length+' clip(s) with gain · <b style="color:'+(over?'#ff8a8a':'#8fe3a5')+'">'+over+' would distort</b> · '+near+' close to the limit</div>'+
   '<div style="display:grid;gap:4px;max-height:260px;overflow:auto">'+res.map(function(r,i){ var col=r.state==="over"?"#ff8a8a":r.state==="near"?"#ffd78a":r.state==="nosound"?"#aaa":"#8fe3a5"; var tx=r.peak==null?"no sound":(r.peak>0?"+":"")+r.peak.toFixed(1)+" dB peak";
     return '<div style="display:flex;gap:8px;align-items:center"><button class="toolbtn" type="button" data-agj="'+i+'" style="flex:1;text-align:left;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+esc(r.name)+' · '+(+r.c.gainDb>0?"+":"")+r.c.gainDb+' dB</button><span style="color:'+col+';font-size:12px;min-width:96px;text-align:right">'+tx+'</span></div>'; }).join("")+'</div>')+
   '<div style="display:flex;gap:8px;justify-content:flex-end"><button class="toolbtn" id="gcX" type="button">Close</button>'+(over?'<button class="toolbtn tool-active" id="gcFix" type="button">Fix '+over+' clip'+(over>1?'s':'')+'</button>':'')+'</div></div>';
  openModal("Gain check",h); $("gcX").onclick=function(){ $("modalBackdrop").style.display="none"; };
  Array.prototype.forEach.call(document.querySelectorAll("[data-agj]"),function(b){ b.onclick=function(){ var r=res[+b.getAttribute("data-agj")]; try{ setCurrentTime(r.c.start); }catch(e){} }; });
  if($("gcFix")) $("gcFix").onclick=async function(){ var n=await fixAll(res); $("modalBackdrop").style.display="none"; try{ toast("Lowered gain on "+n+" clip"+(n>1?"s":"")+" to stop distortion"); }catch(e){} }; }
pr2Register("Gain check","menu",open);
window.AMIYO_AG_S08={scan:scan,fixAll:fixAll,open:open};
try{window.AMIYO_EDITOR_BUILD="ag-step08-gain-check"}catch(e){}
})();

