/* ==================== Script 1143 id="amiyo-ag-s09-copy-gain" ==================== */
/* Professional Audio step 9: COPY / PASTE / RESET GAIN. Pr Tools > "Copy gain" remembers the Audio Gain of the selected clip (the first one if several). "Paste gain" applies it to every selected clip, "Reset gain" puts the selected clips back to 0 dB.
   Handy after you have balanced one interview shot: copy its gain, select the other shots from the same camera (Select same source helps), paste. Each is one undo step. */
(function(){"use strict";
if(window.AMIYO_AG_S09) return;
var copied=null;
function sel(){ return selectedClips().map(function(f){return f.clip}).filter(function(c){return c&&c.assetId}); }
function say(m){ try{toast(m)}catch(e){} }
function copy(){ var s=sel(); if(!s.length){ say("Select a clip first"); return null; } var g=+s[0].gainDb; copied=isFinite(g)?g:0; say("Copied gain "+(copied>0?"+":"")+copied+" dB"); return copied; }
function paste(){ if(copied==null){ say("Copy a gain first (Pr Tools > Copy gain)"); return 0; } var s=sel(); if(!s.length){ say("Select the clips to paste onto"); return 0; }
  pr2H("Paste gain",function(){ s.forEach(function(c){ if(Math.abs(copied)<.05) delete c.gainDb; else c.gainDb=copied; }); }); say("Pasted "+(copied>0?"+":"")+copied+" dB onto "+s.length+" clip"+(s.length>1?"s":"")); return s.length; }
function reset(){ var s=sel().filter(function(c){return c.gainDb!=null}); if(!s.length){ say("No gain to reset on the selected clips"); return 0; }
  pr2H("Reset gain",function(){ s.forEach(function(c){ delete c.gainDb; }); }); say("Gain reset on "+s.length+" clip"+(s.length>1?"s":"")); return s.length; }
pr2Register("Copy gain","menu",copy); pr2Register("Paste gain","menu",paste); pr2Register("Reset gain","menu",reset);
window.AMIYO_AG_S09={copy:copy,paste:paste,reset:reset,get copied(){return copied}};
try{window.AMIYO_EDITOR_BUILD="ag-step09-copy-gain"}catch(e){}
})();

