/* ==================== Script 1144 id="amiyo-ag-s10-help-selftest" ==================== */
/* Professional Editing step 10: GUIDE + SELF-TEST. Pr Tools > "Gain and selection guide" explains steps 1-9 in plain words with their keys, and "Run self-test" checks that every one of those tools is loaded and working (reports PASS/FAIL per line; changes nothing in your project). */
(function(){"use strict";
if(window.AMIYO_AG_S10) return;
function $(i){return document.getElementById(i)}
var GUIDE=[
 ["Audio gain","G","Select clips, press G. Set, adjust or normalize loudness from −60 to +24 dB. Boosts quiet recordings (the Volume slider cannot go past 100%)."],
 ["Video-clip sound","","Gain also changes the sound of clips on the video track while you play, and in export."],
 ["Select at playhead","Alt+P","Selects every clip the playhead touches on unlocked tracks. Pr Tools has Invert selection."],
 ["Offset clips","Alt+Shift+O","Move selected clips by exact time: 2.5, +12f, -0:01. Blocked with a reason if it would overlap or go before 0:00."],
 ["Select same source / whole track","Pr Tools","Selects every clip using the same media file, or every clip on that track."],
 ["Match loudness","Pr Tools","Gives several clips the same average loudness (RMS). Keeps peaks under −1 dB if ticked."],
 ["Gain badge","","Clips with gain show a chip such as +12.0 dB. Red above +12 dB. Click it to edit."],
 ["Gain check","Pr Tools","Lists boosted clips that would distort and fixes them to −1 dB peak."],
 ["Copy / Paste / Reset gain","Pr Tools","Copy one clip's gain and paste it onto the selected clips, or reset to 0 dB."]];
function guide(){ var h='<div style="display:grid;gap:8px;min-width:290px;max-width:440px;max-height:62vh;overflow:auto">'+GUIDE.map(function(g){ return '<div><b>'+g[0]+'</b>'+(g[1]?' <span style="opacity:.65;font-size:12px">· '+g[1]+'</span>':'')+'<div style="font-size:12.5px;opacity:.85">'+g[2]+'</div></div>'; }).join("")+
  '<div style="display:flex;gap:8px;justify-content:flex-end;position:sticky;bottom:0"><button class="toolbtn" id="ghX" type="button">Close</button><button class="toolbtn tool-active" id="ghT" type="button">Run self-test</button></div></div>';
  openModal("Gain and selection guide",h); $("ghX").onclick=function(){ $("modalBackdrop").style.display="none"; }; $("ghT").onclick=async function(){ var r=await selfTest(); show(r); }; }
async function selfTest(){ var out=[]; function t(n,f){ try{ var v=f(); out.push([n,v===true||v===undefined?true:!!v]); }catch(e){ out.push([n,false,String(e&&e.message||e)]); } }
  for(var i=1;i<=9;i++) (function(k){ t("Step "+k+" loaded",function(){ return !!window["AMIYO_AG_S0"+k]; }); })(i);
  t("Gain maths: +6 dB ≈ 2×",function(){ return Math.abs(window.amiyoGainLin({gainDb:6})-1.9953)<.01; });
  t("Gain maths: limits to +24 dB",function(){ return Math.abs(window.amiyoGainLin({gainDb:99})-Math.pow(10,24/20))<.01; });
  t("Offset parser: 12f / 2.5 / -0:01",function(){ var P=window.AMIYO_AG_S04.parse; return Math.abs(P("+12f")-12/(+project.settings.fps||30))<1e-6&&P("2.5")===2.5&&P("-0:01")===-1&&P("zz")===null; });
  t("Pr Tools list has the new tools",function(){ var n=(window.AMIYO_PR2_TOOLS||[]).map(function(x){return x[0]}); return ["Audio gain","Offset clips","Match loudness","Gain check","Copy gain","Select clips at playhead"].every(function(x){return n.indexOf(x)>=0}); });
  t("Selection at playhead works",function(){ var tr=project.tracks.find(function(x){return x.kind==="video"}); if(!tr) return true; var keep=tr.clips.slice(), sv=currentTime, c={id:"__st",assetId:"x",start:0,duration:1,inPoint:0,outPoint:1,volume:1}; tr.clips=[c]; currentTime=.5; var n=window.AMIYO_AG_S03.atPlayhead(); tr.clips=keep; currentTime=sv; clearMultiSelection(); selectedClipId=null; try{renderAll()}catch(e){} return n===1; });
  return out; }
function show(res){ var pass=res.filter(function(r){return r[1]}).length; var h='<div style="display:grid;gap:6px;min-width:280px;max-width:420px"><div style="font-weight:600;color:'+(pass===res.length?"#8fe3a5":"#ff8a8a")+'">'+pass+" of "+res.length+' checks passed</div>'+res.map(function(r){ return '<div style="font-size:12.5px"><span style="color:'+(r[1]?"#8fe3a5":"#ff8a8a")+'">'+(r[1]?"PASS":"FAIL")+'</span> · '+r[0]+(r[2]?' <span style="opacity:.7">('+r[2]+')</span>':'')+'</div>'; }).join("")+'<div style="display:flex;justify-content:flex-end"><button class="toolbtn" id="stX" type="button">Close</button></div></div>';
  openModal("Self-test",h); $("stX").onclick=function(){ $("modalBackdrop").style.display="none"; }; }
pr2Register("Gain and selection guide","menu",guide); pr2Register("Run self-test (gain tools)","menu",async function(){ show(await selfTest()); });
window.AMIYO_AG_S10={guide:guide,selfTest:selfTest};
try{window.AMIYO_EDITOR_BUILD="ag-step10-help-selftest"}catch(e){}
})();

