/* ==================== Script 1145 id="amiyo-ag-s11-gain-bypass" ==================== */
/* Professional Audio step 11: GAIN BYPASS (A/B). Pr Tools > "Bypass gain (A/B)" switches every Audio Gain off in PREVIEW so you can hear the original recording against your boosted version, then switches them back on. While bypassed the clip chips turn grey and a "GAIN OFF" tag shows in the top bar.
   It only affects what you hear while editing: Export always includes the gain, and bypass resets itself when you start an export. */
(function(){"use strict";
if(window.AMIYO_AG_S11) return;
var css=document.createElement("style"); css.textContent=".agBadge.off{background:#444!important;color:#aaa!important;text-decoration:line-through}#agOffTag{position:fixed;left:50%;transform:translateX(-50%);top:6px;z-index:99999;background:#8a5a00;color:#fff;font:700 11px/1 system-ui,sans-serif;padding:5px 9px;border-radius:999px;display:none;cursor:pointer}";
document.head.appendChild(css);
var tag=document.createElement("div"); tag.id="agOffTag"; tag.textContent="GAIN OFF (tap to turn on)"; tag.setAttribute("role","button"); document.body.appendChild(tag);
function set(on){ window.__agBypass=!!on; tag.style.display=on?"block":"none";
  try{ window.AMIYO_AG_S01.apply(); window.AMIYO_AG_S02.apply(); }catch(e){}
  var bs=document.querySelectorAll(".agBadge"); for(var i=0;i<bs.length;i++) bs[i].classList.toggle("off",!!on); }
function toggle(){ set(!window.__agBypass); try{ toast(window.__agBypass?"Gain bypassed (preview only)":"Gain on"); }catch(e){} return window.__agBypass; }
tag.addEventListener("click",function(){ toggle(); });
setInterval(function(){ try{ if(window.__agBypass){ var bs=document.querySelectorAll(".agBadge:not(.off)"); for(var i=0;i<bs.length;i++) bs[i].classList.add("off"); if(window.__amiyoExporting) set(false); } }catch(e){} },400);
pr2Register("Bypass gain (A/B)","menu",toggle);
window.AMIYO_AG_S11={toggle:toggle,set:set};
try{window.AMIYO_EDITOR_BUILD="ag-step11-gain-bypass"}catch(e){}
})();

