        var dx=Math.abs(e.clientX-ox), dy=Math.abs(e.clientY-oy), vertOnly=lockX||(e.shiftKey&&dy>dx), horOnly=e.shiftKey&&dx>dy;
        if(!vertOnly) key.t=Math.max(lo,Math.min(hi,horOnly?p.t:p.t)); else key.t=base[ki].t;
