/* ==================== Script 1169 id="amiyo-export-s01" ==================== */
/* Export step 1 (baseline): when the browser cannot make AAC sound, Auto really saves a WebM if sound is on.
   The size estimate ("as MP4") and the Format note ("Auto makes MP4") used to say the opposite of the warning under them
   and of the saved file. They now follow the warning, which is the one computed from what the browser can actually do. */
(function(){
"use strict";
if(window.__amiyoS01) return; window.__amiyoS01=1;
function $(i){ return document.getElementById(i); }
var busy=false;
function fix(){
  if(busy) return; busy=true;
  try{
    var tr=$("expFmtTruth"), est=$("expEstimate"), note=$("expFmtNote");
    var webmNow=!!(tr&&tr.textContent&&/WebM/.test(tr.textContent));
    if(est){
      [].forEach.call(est.querySelectorAll("div"),function(d){
        if(!/^File size:/.test(d.textContent||"")) return;
        var s=d.innerHTML;
        if(webmNow&&/as MP4/.test(s)) d.innerHTML=s.replace(/as MP4/,"as WebM");
      });
    }
    if(note&&webmNow&&/Auto makes MP4/.test(note.textContent||"")){
      note.textContent="Auto makes WebM · VP9 here, because this browser cannot make AAC sound for MP4. Choose No sound for a real MP4.";
    }
  }catch(e){ try{ window.__swl&&window.__swl(e); }catch(x){} }
  busy=false;
}
var t=null; function soon(){ clearTimeout(t); t=setTimeout(fix,60); }
new MutationObserver(soon).observe(document.documentElement,{childList:true,subtree:true,characterData:true});
document.addEventListener("click",function(){ setTimeout(fix,200); },true);
})();

