/* ==================== Script 1170 id="amiyo-export-s07" ==================== */
/* Export step 7: a video file with no sound track (screen recording, b-roll, a silent WebM) was still counted as "has sound".
   Result: the size estimate promised sound, a no-AAC browser showed a needless "will save a WebM" warning, and after the export the
   sound check said "the file has no readable sound track" and the app exported a SECOND time with the slow method.
   Now each video's sound track is looked up (MP4/MOV by the import reader, WebM/MKV here) and a silent video is treated as silent. */
(function(){
"use strict";
if(window.__amiyoS07) return; window.__amiyoS07=1;
window.amiyoNoAudio=function(a){ try{ return !!(a&&((a.fc&&a.fc.noAudio)||a.__noAud)); }catch(e){ return false; } };
function find(b,pat,from,to){ for(var i=from;i<=to-pat.length;i++){ var ok=true; for(var j=0;j<pat.length;j++){ if(b[i+j]!==pat[j]){ ok=false; break; } } if(ok) return i; } return -1; }
async function scan(a){
  if(a.__audTried||a.type!=="video") return; a.__audTried=1;
  var I=window.amiyoImp2; if(!I||!I.file) { a.__audTried=0; return; }
  var f=I.file(a); if(!f||!f.slice) { a.__audTried=0; return; }
  if(!/\.(webm|mkv)$/i.test(f.name||"")&&!/^video\/(webm|x-matroska)/.test(f.type||"")) return;
  var b=new Uint8Array(await f.slice(0,Math.min(f.size,524288)).arrayBuffer());
  if(!(b[0]===0x1A&&b[1]===0x45&&b[2]===0xDF&&b[3]===0xA3)) return;
  var t=find(b,[0x16,0x54,0xAE,0x6B],0,b.length); if(t<0) return;                /* Tracks not in the first 512 KB: unknown, leave as is */
  var l=1,m=128,x=b[t+4]; while(l<=8&&!(x&m)){ l++; m>>=1; } var sz=x&(m-1); for(var i=1;i<l;i++) sz=sz*256+b[t+4+i];
  var from=t+4+l, to=Math.min(b.length,from+sz); if(to-from<8) return;
  var hasA=find(b,[0x83,0x81,0x02],from,to)>=0, hasV=find(b,[0x83,0x81,0x01],from,to)>=0;
  if(hasV&&!hasA) a.__noAud=true;
}
async function all(){ try{ var A=(window.project&&project.assets)||{}; for(var k in A){ try{ await scan(A[k]); }catch(e){ try{ window.__swl&&window.__swl(e); }catch(x){} } } }catch(e){} }
var po=window.openModal;
window.openModal=function(title){ var r=po.apply(this,arguments); if(title==="Export video"){ all().then(function(){ try{ document.getElementById("expGo")&&document.getElementById("expSizes")&&document.getElementById("expSizes").dispatchEvent(new Event("input",{bubbles:true})); }catch(e){} }); } return r; };
var ii=window.importFiles; if(typeof ii==="function") window.importFiles=async function(){ var r=await ii.apply(this,arguments); all(); return r; };
setTimeout(all,2500);
})();

;
/* ==================== Script 1171 id="amiyo-export-s15-verified" ==================== */
/* Export step 15 checked (colour and effects, preview versus export): 21 single effects (blur, brightness, contrast, saturation, grayscale, sepia, hue, invert, vignette, sharpen, mirror, posterize, pixelate, grain, white balance, tint, hue, fade tools), 6 looks, 18 of the 75 filter presets (plus half-strength), colour wheels, a .cube LUT, a blend mode and a 5-effect stack were drawn for an image clip and for a video clip, in preview mode and with the export flags on (full quality, no draft): the frames matched (image vs video within codec noise, preview vs export flags 0 levels apart; film grain is random by design). A real fast export (MP4) of a clip with brightness + saturation + contrast was decoded and compared with the preview: mean difference about 3 levels, from the chroma subsampling at hard colour edges.
   Two real differences found and fixed. 1) Mirror, Sharpen and Film grain on an ADJUSTMENT LAYER were applied twice (the top-track adjustment layer also counted as the active clip): Mirror cancelled itself so nothing flipped, Sharpen and Grain ran at double strength. They now run once, exactly like the same effect on a clip. 2) Blur on a picture that fills the frame made the edges of the picture dark (a 3 px border at Blur 6, about 30 px at Blur 30) in the preview and in the file, because the blur mixed in transparent black from outside the frame. The picture now blends with itself at the edges; faded, blended, rotated, shadowed and partly-covering clips are unchanged.
   Not changed: Blur on an Adjustment Layer still blurs the whole frame including the edges (no dark border there). Pixel effects (sharpen, mirror, posterize, pixelate, grain) on a clip that sits under another video layer are only drawn for the top clip; this belongs to the multi-layer step. */window.AMIYO_EXPORT_STEP=15; try{ window.AMIYO_EDITOR_BUILD="export-step15-parity"; }catch(e){}

;
/* ==================== Script 1172 id="amiyo-export7-step01" ==================== */
/* Export round 7, step 1 of 20: baseline + a real "Will make" SIZE estimate.
   Before: "Will make" showed picture size, parts and fps, but no file size, so you could not tell if the export would fit your phone or an upload limit.
   Now: a line under it shows "About 38 MB (one file)" worked out from the same bitrate the exporter really uses (video + sound x length x parts).
   After an export the real size is compared: toast and the line show "Estimated 38 MB, real 35 MB (-8%)". If the guess is more than 35% off, say so plainly.
   Nothing about how files are made changes; this only reads settings. */
(function(){
  "use strict";
  var KEY="amiyo_editor_size_est", est=null;
  function $(i){ return document.getElementById(i); }
  function mb(n){ return n>=1048576?(n/1048576).toFixed(n>=104857600?0:1)+" MB":Math.max(1,Math.round(n/1024))+" KB"; }   /* export step 10: one decimal up to 100 MB, like the other size lines */
  function secs(){
    try{ var end=window.amiyoContentEnd?window.amiyoContentEnd():0, r=window.__amiyoExportRange;
      return r?Math.max(0,Math.min(r.t1,end)-r.t0):end; }catch(e){ return 0; }
  }
  function dims(){
    var m=((($("expSummary")||{}).textContent)||"").match(/Will make:\s*(\d{3,5})\s*[×x]\s*(\d{3,5})/);
    return m?[+m[1],+m[2]]:[project.settings.width,project.settings.height];
  }
  function partsLen(){ var m=((($("expSummary")||{}).textContent)||"").match(/(\d+) files of up to ([\d.]+) min/); return m?{n:+m[1],min:+m[2]}:null; }
  /* the exporter's own rule (see the MediaRecorder setup): preset/option bitrate, else 5 or 1.5 Mbps floor vs pixels*fps*0.14, capped at 20 Mbps, times quality */
  function vbps(w,h,fps){
    var o=window.__amiyoExportOpts, b=(o&&o.bps)||window.__amiyoPresetBps||0, q=window.__amiyoXQ||1;
    if(q!==1||!b){ b=Math.round((b||Math.min(20e6,Math.max(w*h>=921600?5e6:1.5e6,w*h*fps*.14)))*q); }
    if(window.__amiyoXBps>0) b=Math.round(window.__amiyoXBps);
    return b;
  }
  function compute(){
    var d=dims(), fps=window.__amiyoXFps||project.settings.fps||30, len=secs(); if(len<=0) return null;
    var N=window.amiyoExportNow&&window.amiyoExportNow();   /* export step 10: the one shared calculation (sound on/off, sound rate, preset, quality, manual bitrate, parts) */
    if(N&&N.perFile>0) return {total:N.all,per:N.perFile,n:N.parts||1,len:len,bps:N.vb+N.ab};
    var v=vbps(d[0],d[1],fps), a=window.__amiyoXAbps||128000, p=partsLen();
    var total=(v+a)*len/8, n=p?p.n:1, per=total/n;
    return {total:total,per:per,n:n,len:len,bps:v+a};
  }
  function paint(){
    var sum=$("expSummary"); if(!sum||!sum.parentNode) return;
    var el=$("x7Est");
    if(!el){ el=document.createElement("div"); el.id="x7Est"; el.setAttribute("aria-live","polite"); el.style.cssText="font-size:12px;line-height:1.5;margin-top:2px;color:var(--muted)"; sum.parentNode.insertBefore(el,sum.nextSibling); }
    var c=compute(), txt;
    if(!c) txt="File size: add something to the timeline to see an estimate.";
    else txt="Up to about "+mb(c.per)+(c.n>1?" per file ("+c.n+" files, up to "+mb(c.total)+" in total)":" (one file)")+".";
    var last=null; try{ last=JSON.parse(localStorage.getItem(KEY)||"null"); }catch(e){}
    if(last&&last.real) txt+=" Last time: the window said up to "+mb(last.est)+", the real file was "+mb(last.real)+" ("+(last.pct>0?"+":"")+last.pct+"%).";
    if(el.textContent!==txt) el.textContent=txt;
  }
  /* remember the estimate at the moment Start is pressed */
  document.addEventListener("click",function(e){
    if(!(e.target&&e.target.id==="expGo")) return;
    try{ est=compute(); hook(); }catch(x){ window.__swl&&window.__swl(x); }
  },true);
  function hook(){
    var o=window.amiyoOnExport; if(typeof o!=="function"||o.__x7) return;
    var n=function(blob,fname){
      try{
        if(est&&blob&&blob.size&&!(window.__amiyoCancelled)){
          var pct=Math.round((blob.size-est.per)/est.per*100), rec={est:Math.round(est.per),real:blob.size,pct:pct,t:Date.now()};
          localStorage.setItem(KEY,JSON.stringify(rec));
          var msg="Real file "+mb(blob.size)+"; the window said up to "+mb(est.per)+" ("+(pct>0?"+":"")+pct+"%)."+(pct>0?" It came out bigger than that: a very busy picture can make the encoder go over its bitrate. A smaller size, a lower frame rate or WebM keeps closer.":(pct<-60?" Simple pictures come out much smaller than the ceiling.":""));
          setTimeout(function(){ try{ toast(msg,6000); }catch(e){} },4200);
          paint();
        }
      }catch(x){ window.__swl&&window.__swl(x); }
      return o.apply(this,arguments);
    };
    Object.keys(o).forEach(function(k){ try{ n[k]=o[k]; }catch(e){} });   /* keep other steps' flags so they do not wrap it again */
    n.__x7=1; window.amiyoOnExport=n;
  }
  /* keep the line fresh while the Export dialog is open (sizes, presets, ranges change it) */
  setInterval(function(){ try{ if($("expSummary")) paint(); }catch(e){} },600);
  /* export step 10: also right after a tap or a slider move, so the line never shows the previous setting for a moment */
  ["click","input","change"].forEach(function(ev){ document.addEventListener(ev,function(){ setTimeout(function(){ try{ if($("expSummary")) paint(); }catch(e){} },90); },true); });
  window.amiyoExportSizeEstimate=compute;
  window.AMIYO_EXPORT7_STEP=1;
})();

