/* ==================== Script 1173 id="amiyo-export7-step02" ==================== */
/* Export round 7, step 2 of 20: cancel, pause, close the dialog, and a second export straight after.
   Found: the "export is already running" check only looked at a running export, not one still being set up, so a double tap on Export (or the shortcut plus the button)
   could open two dialogs and start two exports at once. A tab switch also dropped the screen-awake lock, so long exports could dim and stall.
   Now: only one export can be set up or running at a time (plain message otherwise); after a finished, cancelled or failed export the pause/cancel flags are cleared,
   so the next export never starts "paused" or "cancelled"; the screen-awake lock is asked for again when you come back to the tab. */
(function(){
  "use strict";
  var busy=false, lock=null;
  function say(m){ try{ toast(m,3500); }catch(e){} }
  function relock(){
    try{ if(!navigator.wakeLock||!window.__amiyoExporting||(lock&&!lock.released)) return;
      navigator.wakeLock.request("screen").then(function(l){ lock=l; }).catch(function(){}); }catch(e){}
  }
  document.addEventListener("visibilitychange",function(){ if(!document.hidden) relock(); });
  function clean(){
    if(window.__amiyoExporting) return;   /* never touch flags of a run that is still going */
    window.__amiyoExportPaused=false; window.__amiyoCancel=false; window.__amiyoCancelled=false; window.__amiyoExportPart=null;
    try{ var p=document.getElementById("expPause"); if(p) p.textContent="Pause"; }catch(e){}
    try{ if(lock&&!lock.released) lock.release(); }catch(e){} lock=null;
  }
  function install(){
    var orig=window.exportProject; if(typeof orig!=="function"||orig.__x7s2) return;
    var g=function(){
      if(busy||window.__amiyoExporting){ say(window.__amiyoExporting?"An export is already running. Cancel it first, or wait until it finishes.":"The export window is already open."); return Promise.resolve(); }
      busy=true; var self=this, args=arguments, r;
      try{ r=orig.apply(self,args); }catch(e){ busy=false; clean(); throw e; }
      return Promise.resolve(r).then(function(v){ return v; },function(e){ window.__swl&&window.__swl(e); }).then(function(v){ busy=false; setTimeout(clean,400); return v; });
    };
    Object.keys(orig).forEach(function(k){ try{ g[k]=orig[k]; }catch(e){} });
    g.__x7s2=1; window.exportProject=g;
  }
  /* install last, after every other step has wrapped exportProject */
  if(document.readyState==="complete") setTimeout(install,0); else window.addEventListener("load",function(){ setTimeout(install,0); });
  window.amiyoExportBusy=function(){ return busy||!!window.__amiyoExporting; };
  window.AMIYO_EXPORT7_STEP=2;
})();

