/* ==================== Script 1174 id="amiyo-export7-step03" ==================== */
/* Export round 7, step 3 of 20: progress bar, time left, Recent exports.
   Checked in the code: the percent, the bar and "Paused" already behave (paused time is not counted, the ETA is smoothed, finished exports are listed with size, fps and folder).
   Found: when an export is split into parts, the time left was only "content length left" (as if every part ran in real time), so a slow phone or a long Fast-export
   run showed a time that was too short or too long, and it never learned from how fast the earlier parts really were.
   Now: with parts, the time left is worked out from how long the whole job has taken so far (pauses excluded) and the share done in total, then smoothed.
   Single-file exports keep their existing estimate. It only changes the "about … left" words. */
(function(){
  "use strict";
  var job={t0:0,pz:0,last:0,ema:0,key:""};
  function human(s){ try{ return window.amiyoHumanDur?window.amiyoHumanDur(Math.max(1,s)):Math.round(s)+" s"; }catch(e){ return Math.round(s)+" s"; } }
  function wrap(){
    var o=window.amiyoExportProgress; if(typeof o!=="function"||o.__x7s3) return;
    var w=function(){
      var r=o.apply(this,arguments);
      try{
        var info=window.__amiyoExportPart, paused=!!window.__amiyoExportPaused, now=performance.now();
        if(!window.__amiyoExporting||!info||info.n<2){ job.t0=0; return r; }
        var key=String(window.__amiyoExportName||"").replace(/-part\d+of\d+$/,"")+"|"+info.n;
        if(!job.t0||job.key!==key){ job={t0:now,pz:0,last:now,ema:0,key:key}; }
        if(paused) job.pz+=now-job.last; job.last=now;
        var el=(now-job.t0-job.pz)/1000, t=document.getElementById("expTxt"); if(!t||paused) return r;
        var m=(t.textContent||"").match(/\((\d+)%\)/), part=m?+m[1]/100:0;
        var f=((info.i-1)+part)/info.n;          /* share of the whole job done (parts are about equal) */
        if(f>=0.04&&el>=3){
          var rem=el*(1-f)/f; job.ema=job.ema?job.ema*0.7+rem*0.3:rem;
          t.textContent=t.textContent.replace(/about .+? left/,"about "+human(job.ema)+" left");
        }
      }catch(e){ window.__swl&&window.__swl(e); }
      return r;
    };
    Object.keys(o).forEach(function(k){ try{ w[k]=o[k]; }catch(e){} });
    w.__x7s3=1; window.amiyoExportProgress=w;
  }
  function go(){ setTimeout(wrap,0); }
  if(document.readyState==="complete") go(); else window.addEventListener("load",go);
  window.AMIYO_EXPORT7_STEP=3;
})();

