/* ==================== Script 1175 id="amiyo-export7-step04" ==================== */
/* Export round 7, step 4 of 20: My presets.
   Checked in the code: save, rename (inline), delete (asks twice), export/import (.json, size and shape checked, names cleaned, 30 max) and reload all work.
   Found 3 gaps:
   1) Saving under a name you already have replaced that preset at once, with only a note afterwards. Now the first tap says so and the second tap (within 6 s) replaces it.
   2) Enter in the name box did nothing. Now Enter saves.
   3) If the saved list in this browser was damaged (storage glitch, half-written data), the next Save wrote a fresh list over it and every preset was lost.
      Now a spare copy is kept; if the main list is missing or unreadable when the Export dialog opens, the spare is put back first. */
(function(){
  "use strict";
  var KEY="amiyo_editor_user_presets", BAK=KEY+"_spare", armed=null;
  function $(i){ return document.getElementById(i); }
  function parse(raw){ try{ var a=JSON.parse(raw); return Array.isArray(a)?a:null; }catch(e){ return null; } }
  function get(k){ try{ return localStorage.getItem(k); }catch(e){ return null; } }
  function set(k,v){ try{ localStorage.setItem(k,v); return true; }catch(e){ return false; } }
  function restoreIfBroken(){
    var main=get(KEY); if(main!==null&&parse(main)) return false;
    var b=get(BAK), a=b&&parse(b); if(!a||!a.length) return false;
    return set(KEY,b);
  }
  function mirror(){ var m=get(KEY), a=m!==null&&parse(m); if(a&&get(BAK)!==m) set(BAK,m); }
  function cleanName(n){ return String(n==null?"":n).replace(/<[^>]*>/g,"").replace(/[\u0000-\u001f<>]/g,"").replace(/\s{2,}/g," ").trim().slice(0,40); }
  function exists(n){ var a=parse(get(KEY))||[]; return a.some(function(p){ return p&&String(p.name).toLowerCase()===n.toLowerCase(); }); }
  /* 1) overwrite needs a second tap (capture phase: runs before the Save handler) */
  document.addEventListener("click",function(e){
    var b=e.target&&e.target.closest&&e.target.closest("#expMineSave"); if(!b) return;
    var inp=$("expMineName"), n=cleanName(inp&&inp.value), note=$("expMineNote"); if(!n||!exists(n)){ armed=null; return; }
    var now=Date.now();
    if(armed&&armed.n===n.toLowerCase()&&now-armed.t<6000){ armed=null; return; }   /* second tap: let it through */
    armed={n:n.toLowerCase(),t:now}; e.stopImmediatePropagation(); e.preventDefault();
    if(note) note.textContent="You already have a preset called “"+n+"”. Tap Save again to replace its settings, or type another name.";
  },true);
  /* 2) Enter saves */
  document.addEventListener("keydown",function(e){
    if(e.key==="Enter"&&e.target&&e.target.id==="expMineName"){ e.preventDefault(); var s=$("expMineSave"); if(s) s.click(); }
  });
  /* 3) spare copy */
  var prev=window.openModal;
  window.openModal=function(title){
    if(title==="Export video"){ try{ if(restoreIfBroken()) setTimeout(function(){ try{ var n=$("expMineNote"); if(n) n.textContent="Your saved presets were damaged, so the spare copy was put back."; }catch(e){} },0); }catch(e){ window.__swl&&window.__swl(e); } }
    return prev.apply(this,arguments);
  };
  setInterval(function(){ try{ if($("expMine")) mirror(); }catch(e){} },2000);
  window.addEventListener("pagehide",function(){ try{ mirror(); }catch(e){} });
  try{ mirror(); }catch(e){}
  window.AMIYO_EXPORT7_STEP=4;
})();

