/* ==================== Script 1176 id="amiyo-matte-video" ==================== */
/* TRACK MATTE with a VIDEO as the matte: before each frame is drawn, the matte video is loaded and moved to the same moment as the matte clip, so the clip above it is cut by the moving video (luma or alpha, invert works). Pictures and text mattes work as before. */
(function(){
  var vids={};
  function load(a){ var o=vids[a.id]; if(o) return o.p||Promise.resolve(o);
    o=vids[a.id]={el:null,fail:false};
    o.p=Promise.resolve(ensureUrl(a)).then(function(u){ if(!u) return null;
      return new Promise(function(res){ var v=document.createElement("video"); v.muted=true; v.defaultMuted=true; v.playsInline=true; v.setAttribute("playsinline",""); v.preload="auto"; v.loop=false; v.crossOrigin="anonymous";
        var done=false, fin=function(ok){ if(done) return; done=true; res(ok?v:null); }; v.addEventListener("loadeddata",function(){ fin(true); }); v.addEventListener("error",function(){ fin(false); }); setTimeout(function(){ fin(v.readyState>=2); },8000); v.src=u; try{ v.load(); }catch(e){} }); })
      .then(function(el){ if(el) o.el=el; else o.fail=true; delete o.p; return o; }).catch(function(){ o.fail=true; delete o.p; return o; });
    return o.p; }
  function wanted(){ var out=[]; try{ project.tracks.forEach(function(t){ (t.clips||[]).forEach(function(c){ var tm=c.trackMatte; if(!tm||!tm.enabled||!tm.sourceTrackId||c.off) return;
      if(currentTime<c.start||currentTime>=c.start+c.duration) return;
      var st=project.tracks.find(function(x){ return x.id===tm.sourceTrackId; }); if(!st) return;
      var mc=(st.clips||[]).find(function(k){ return !k.off&&currentTime>=k.start&&currentTime<k.start+k.duration; }); if(!mc||mc.kind==="text") return;
      var a=project.assets[mc.assetId]; if(a&&a.type==="video") out.push({a:a,mc:mc}); }); }); }catch(e){ window.__swl&&window.__swl(e); } return out; }
  async function sync(){ var list=wanted(); if(!list.length) return; var playing=false; try{ playing=!!isPlaying; }catch(e){}
    for(var i=0;i<list.length;i++){ var it=list[i], o=await load(it.a); if(!o||!o.el) continue; var v=o.el, dur=v.duration; if(!isFinite(dur)||dur<=0) continue;
      var want=Math.max(0,Math.min(dur-.04,(it.mc.inPoint||0)+(currentTime-it.mc.start)*(it.mc.speed||1)));
      if(playing){ if(v.paused){ try{ if(Math.abs(v.currentTime-want)>.3) v.currentTime=want; var pr=v.play(); if(pr&&pr.catch) pr.catch(function(){}); }catch(e){} } else if(Math.abs(v.currentTime-want)>.4){ try{ v.currentTime=want; }catch(e){} } }
      else { if(!v.paused){ try{ v.pause(); }catch(e){} } if(Math.abs(v.currentTime-want)>.04){ try{ v.currentTime=want; await amiyoSeeked(v); }catch(e){} } } } }
  window.__amiyoMatteVideoEl=function(id){ var o=vids[id]; return o&&o.el||null; };
  var prp=window.renderPreviewFrame;
  window.renderPreviewFrame=async function(){ try{ await sync(); }catch(e){ window.__swl&&window.__swl(e); } return prp.apply(this,arguments); };
})();

