/* ==================== Script 1178 id="amiyo-w02-button-names" ==================== */
/* W02: every button gets an accessible name. Humanises id/data/class when nothing else exists; watches new nodes cheaply. */
(function(){
 if(window.__amiyoW02) return; window.__amiyoW02=1;
 var KNOWN={amTourNext:'Next tour step',expWhereDir:'Choose export folder',x1Go:'Run'};
 function human(id){ return String(id||'').replace(/^[a-z]{1,3}(?=[A-Z])/,'').replace(/([a-z0-9])([A-Z])/g,'$1 $2').replace(/[-_]+/g,' ').trim().toLowerCase().replace(/^./,function(c){return c.toUpperCase();}); }
 function name(b){
  try{
   if(b.getAttribute('aria-label')||b.getAttribute('aria-labelledby')||b.title) return;
   if((b.textContent||'').trim()) return;
   var img=b.querySelector('img[alt]'); if(img&&img.alt) return;
   var n=KNOWN[b.id]||b.getAttribute('data-label')||b.getAttribute('data-act')||b.getAttribute('data-w')&&('Option '+b.getAttribute('data-w'))||human(b.id)||human((b.className||'').toString().split(/\s+/)[0]);
   if(n&&n.length>1) b.setAttribute('aria-label',n);
  }catch(e){}
 }
 function scan(root){
  try{ if(root.nodeType!==1) return;
   if(root.tagName==='BUTTON'||root.getAttribute('role')==='button') name(root);
   var l=root.querySelectorAll('button,[role=button]'); for(var i=0;i<l.length;i++) name(l[i]);
  }catch(e){}
 }
 var q=[],t=0;
 function flush(){ t=0; var a=q; q=[]; for(var i=0;i<a.length;i++) scan(a[i]); }
 function start(){
  scan(document.documentElement);
  try{ new MutationObserver(function(ms){
    for(var i=0;i<ms.length;i++){ var a=ms[i].addedNodes; for(var j=0;j<a.length;j++) if(a[j].nodeType===1) q.push(a[j]); }
    if(q.length&&!t) t=setTimeout(flush,300);
  }).observe(document.documentElement,{childList:true,subtree:true}); }catch(e){}
 }
 if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',start); else start();
})();

