/* ==================== Script 1179 id="amiyo-w03-landmarks" ==================== */
/* W03: skip link, one hidden <h1>, labelled landmarks. */
(function(){
 function go(){
  try{
   var m=document.querySelector('main,[role=main]'); if(!m) return;
   if(!m.id) m.id='amiyoMain';
   if(!m.hasAttribute('tabindex')) m.setAttribute('tabindex','-1');
   if(!m.getAttribute('aria-label')) m.setAttribute('aria-label','Editor workspace');
   if(!document.querySelector('.amiyo-skip')){
     var a=document.createElement('a'); a.className='amiyo-skip'; a.href='#'+m.id; a.textContent='Skip to editor';
     a.addEventListener('click',function(e){ e.preventDefault(); try{ m.focus({preventScroll:true}); }catch(x){} });
     document.body.insertBefore(a,document.body.firstChild);
   }
   if(!document.querySelector('h1')){
     var h=document.createElement('h1'); h.className='amiyo-h1'; h.id='amiyoH1'; h.textContent='Amiyo Studio video editor';
     document.body.insertBefore(h,document.body.firstChild);
   }
   var seen={};
   document.querySelectorAll('nav,aside,header').forEach(function(e){
     if(e.getAttribute('aria-label')||e.getAttribute('aria-labelledby')) return;
     var t=e.tagName.toLowerCase(), base=t==='nav'?'Navigation':t==='aside'?'Side panel':'Section header';
     if(e.id) base=base+' '+e.id.replace(/([a-z])([A-Z])/g,'$1 $2').toLowerCase();
     else { seen[t]=(seen[t]||0)+1; base+=' '+seen[t]; }
     e.setAttribute('aria-label',base);
   });
  }catch(e){}
 }
 if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',function(){setTimeout(go,50)}); else setTimeout(go,50);
})();

