/* ==================== Script 1182 id="amiyo-w10-quota" ==================== */
/* W10: storage watchdog. Warns before the browser runs out of space (projects/media would stop saving), once per level, and adds usage to the diagnostics report. */
(function(){
 if(window.AMIYO_QUOTA) return;
 var last=0,lvl=0,info={usage:0,quota:0,pct:0,persisted:null};
 function mb(n){ return (n/1048576).toFixed(n>1073741824?0:1); }
 function say(m,ms){ try{ if(window.toast) window.toast(m,ms||7000); }catch(e){} }
 async function check(){
  try{
   if(!navigator.storage||!navigator.storage.estimate) return info;
   var e=await navigator.storage.estimate();
   info.usage=e.usage||0; info.quota=e.quota||0; info.pct=info.quota?Math.round(info.usage/info.quota*100):0;
   try{ info.persisted=navigator.storage.persisted?await navigator.storage.persisted():null; }catch(x){}
   var L=info.pct>=95?3:info.pct>=85?2:info.pct>=70?1:0;
   if(L>lvl){
     say(L===3?'Storage almost full ('+info.pct+'%, '+mb(info.usage)+' MB). Export your project and delete unused media now.'
        :L===2?'Storage '+info.pct+'% full. Export a backup and clear old media soon.'
        :'Storage is '+info.pct+'% full ('+mb(info.usage)+' MB used).');
     try{ window.AMIYO_DIAG&&AMIYO_DIAG.add('storage','usage '+info.pct+'% ('+mb(info.usage)+' of '+mb(info.quota)+' MB)'); }catch(x){}
   }
   lvl=L;
  }catch(e){}
  last=Date.now(); return info;
 }
 window.AMIYO_QUOTA={check:check,info:info};
 try{ var r=window.AMIYO_DIAG&&AMIYO_DIAG.report; if(r) AMIYO_DIAG.report=function(){ var t=r.apply(this,arguments); return t+'\n\nstorage: '+mb(info.usage)+' MB of '+mb(info.quota)+' MB ('+info.pct+'%) persisted='+info.persisted; }; }catch(e){}
 function tick(){ if(document.hidden) return; if(Date.now()-last>120000) check(); }
 setInterval(tick,30000);
 document.addEventListener('visibilitychange',function(){ if(!document.hidden&&Date.now()-last>60000) check(); });
 window.addEventListener('load',function(){ setTimeout(check,4000); });
 window.addEventListener('amiyo:saved',function(){ if(Date.now()-last>30000) check(); });
})();

