/* ==================== Script 1191 id="amiyo-ai20-s01-intent-guard" ==================== */
/* AI 20 · Step 1 — Intent guard for the Ask AI box.
   Fixes commands that were misread ("delete gaps" deleted the clip, "normalize audio" set speed 1x, "flip horizontal" changed the
   aspect ratio, "freeze frame" only paused) and adds the common editing words that used to answer "I don't know". Each intent
   runs the editor's own button, so undo, locks and checks behave exactly as when you tap it yourself. */
(function(){
  "use strict";
  function vis(b){ return !!(b.offsetParent||b.getClientRects().length); }
  function norm(s){ return String(s||"").replace(/\s+/g," ").trim().toLowerCase(); }
  /* find an editor control by id or by its label; hidden menu items are fine to click */
  function ctl(spec){
    var list=document.querySelectorAll("button,[role=button],[role=menuitem]"), best=null, i, b, tx;
    for(i=0;i<list.length;i++){
      b=list[i]; if(b.disabled) continue;
      if(typeof spec==="string"){ if(b.id===spec){ best=b; break; } continue; }
      tx=norm(b.textContent).replace(/^[^a-z0-9]+/,"");
      if(spec.test(tx)&&!b.closest("#aiCmdSheet")){ if(!best||(vis(b)&&!vis(best))) best=b; }
    }
    return best;
  }
  var FAIL=/^(?:move |select |reverse works|no |nothing|couldn|could not|can.?t|cannot|there is no|there are no|frame is|not |unlock|this track is locked|failed|pick |something went wrong|clip is silent|⚠)/i;
  function toastEl(){ return document.getElementById("toast"); }
  /* press an editor control, then report what the editor itself said: a refusal becomes a real error, not a fake success */
  function press(spec,label,o){
    o=o||{};
    var f=null; try{ f=window.getClip&&window.getClip(); }catch(e){}
    if(o.need!==false&&!(f&&f.clip)) throw new Error("There is no clip at the playhead. Move the playhead onto a clip first.");
    /* picture work needs a frame on screen: if the playhead is outside the selected clip, step it into the middle of that clip */
    if(o.mid&&f&&f.clip&&typeof window.setCurrentTime==="function"){
      var ct=playheadNow(), a=f.clip.start, b=a+f.clip.duration;
      if(ct==null||ct<=a+.05||ct>=b-.05){ try{ window.setCurrentTime(a+f.clip.duration/2); }catch(e){} }
    }
    var b=ctl(spec); if(!b) throw new Error("That control is not available right now.");
    var te=toastEl(); if(te) te.textContent="";
    var before=sig();
    b.click();
    var said=te?String(te.textContent||"").trim():"";
    if(said&&FAIL.test(said)) throw new Error(said);
    if(!said&&sig()===before&&o.expect!==false) throw new Error("Nothing changed. The editor did not report anything, so the clip may have no sound or picture to work on.");
    return said&&said.length<70?said:label;
  }
  /* Sound tools run in the background and write their result into #amSndOut: report that result as a toast when it lands */
  function pressSound(re,label){
    var f=null; try{ f=window.getClip&&window.getClip(); }catch(e){}
    if(!(f&&f.clip)) throw new Error("There is no clip at the playhead. Move the playhead onto a clip first.");
    if(!f.clip.assetId) throw new Error("This clip has no sound of its own. Select a video or audio clip.");
    var b=ctl(re); if(!b) throw new Error("That sound tool is not available right now.");
    var out=document.getElementById("amSndOut"); if(out) out.textContent="Working\u2026";
    b.click();
    var n=0, iv=setInterval(function(){
      n++; var t=out?String(out.textContent||"").trim():"";
      if((t&&!/^working/i.test(t))||n>60){ clearInterval(iv); try{ window.toast(n>60?label+": still working, check Sound tools":(t||label)); }catch(e){} }
    },250);
    return label+"\u2026";
  }
  function playheadNow(){ try{ var v=document.getElementById("timeReadout"); if(!v) return null; var m=String(v.textContent).match(/(\d+):(\d+)(?:[.:](\d+))?/); return m?(+m[1])*60+(+m[2])+(m[3]?+("0."+m[3]):0):null; }catch(e){ return null; } }
  function sig(){ try{ return JSON.stringify(window.project,function(k,v){ return (k==="history"||k==="_h")?undefined:(typeof v==="string"&&v.length>120?v.length:v); }).length; }catch(e){ return Math.random(); } }
  function hasClip(){ try{ var f=window.getClip&&window.getClip(); return !!(f&&f.clip); }catch(e){ return false; } }
  function clipCount(){ try{ var n=0; (window.project.tracks||[]).forEach(function(t){ n+=(t.clips||[]).length; }); return n; }catch(e){ return 0; } }
  var NUM=/(?:^|\s)(?:to\s+)?(\d+(?:\.\d+)?)\s*(?:s|sec|seconds?)?\b/;
  var INTENTS=[
    /* sound */
    [/\b(?:normali[sz]e|even out|level out|balance|match)\b.*\b(?:audio|volume|loudness|sound|clip)\b|\b(?:audio|volume|loudness|sound)\b.*\b(?:normali[sz]e|even out)\b|^normali[sz]e$/,
      function(){ return pressSound(/^normalize clip$/,"Normalizing the clip’s sound"); }],
    [/\b(?:denoise|de-noise|remove noise|reduce noise|noise reduction|clean (?:up )?(?:the )?(?:audio|sound|voice))\b/,
      function(t){ if(/audio|sound|voice|hum/.test(t)){ return press("amAlMenuBtn","Audio Lab is open: tap Auto-clean to remove hum and noise",{need:false,expect:false}); } return press("denoiseBtn","Denoise toggled for the clip"); }],
    /* timeline housekeeping */
    [/\b(?:close|delete|remove|fill|squash|get rid of)\s+(?:all\s+)?(?:the\s+)?(?:empty\s+)?(?:gaps?|spaces?|holes?)\b|^ripple\b/,
      function(){ return press("qGaps","Closed the gaps on the track"); }],
    [/\b(?:add|drop|put|set|place|make)\s+(?:a\s+)?marker\b|^marker\b/,
      function(){ return press(/^add marker/,"Marker added at the playhead",{need:false}); }],
    [/\b(?:trim|cut|remove)\s+(?:the\s+)?(?:start|beginning|front|head|before(?:\s+(?:the\s+)?playhead)?)\b/,
      function(){ return press("qTrimStart","Trimmed the start to the playhead"); }],
    [/\b(?:trim|cut|remove)\s+(?:the\s+)?(?:end|tail|rest|after(?:\s+(?:the\s+)?playhead)?)\b/,
      function(){ return press("qTrimEnd","Trimmed the end to the playhead"); }],
    [/^select\s+(?:all|everything)\b/,
      function(){ return press(/^select all/,"Selected every clip",{need:false}); }],
    [/^(?:loop|repeat)(?:\s+(?:playback|it|this))?$/,
      function(){ return press("loopBtn","Loop toggled",{need:false,expect:false}); }],
    /* picture */
    [/\bfreeze[- ]?frame\b|\bhold (?:the )?frame\b|^freeze here$/,
      function(){ return press(/^freeze frame/,"Choose how long to hold the frame",{mid:true,expect:false}); }],
    [/\breverse\b|\bplay (?:it )?backwards?\b|\bbackwards\b/,
      function(){ return press(/^reverse clip/,"Reversing the clip"); }],
    [/\brotate\b/,
      function(){ return press(/^rotate 90/,"Rotated 90° clockwise"); }],
    [/\b(?:flip|mirror)\b/,
      function(t){
        var f=window.getClip&&window.getClip(); if(!f||!f.clip) throw new Error("There is no clip at the playhead. Move the playhead onto a clip first.");
        var v=/vertical|upside|up.?down/.test(t), key=v?"flipV":"flipH";
        window.transact(v?"Flip vertical":"Flip horizontal",function(){ f.clip[key]=!f.clip[key]; });
        return v?"Flipped upside down":"Mirrored left to right";
      }],
    [/\b(?:fix|correct|repair)\b.*\b(?:colou?rs?|white balance|cast|tint)\b|\bauto[- ]?(?:fix|colou?r|white balance)\b/,
      function(){ return press("autoFixBtn","Fixed the colour cast",{mid:true}); }],
    [/\bauto[- ]?levels?\b|\b(?:fix|balance)\b.*\b(?:exposure|brightness|contrast|lighting)\b/,
      function(){ return press("autoLevelsBtn","Balanced brightness and contrast",{mid:true}); }],
    [/\benhance\b|\bmake (?:it|this|the video|the clip) (?:look )?(?:better|nicer|prettier)\b|\bimprove (?:the )?(?:picture|look|video|clip)\b/,
      function(){ return press("enhanceBtn","Enhanced the picture",{mid:true}); }]
  ];
  /* Called first by the Ask AI interpreter. Return a message to say the request was handled, or null to let the old rules try. */
  window.amiyoIntentPre=function(raw){
    var t=norm(raw).replace(/[.!?]+$/,"").replace(/^(?:please|can you|could you|hey|ai)\s+/,"").replace(/\s+(?:please|here|now)$/,"").trim();
    if(!t) return null;
    for(var i=0;i<INTENTS.length;i++){ if(INTENTS[i][0].test(t)) return INTENTS[i][1](t); }
    /* safety: "remove <something we do not know>" must never fall through to "delete the selected clip" */
    var d=t.match(/^(?:delete|remove|erase|trash|get rid of)\s+(.+)$/);
    if(d&&!/^(?:the |this |that |these |those |it\b|clip|selected|selection|video|audio|photo|image|picture|text|title|caption|layer|track|sticker|everything|all\b|silence|silent|pauses?|dead air|quiet|noise|hum|marker|beat)/.test(d[1])&&!/\b(?:silence|pauses?|dead air|quiet|noise|hum|marker|beat)\b/.test(d[1])){
      var e=new Error("I don't know \u201c"+raw+"\u201d yet, so I did not delete anything."); e.unknown=true; throw e;
    }
    return null;
  };
  try{ window.AMIYO_EDITOR_BUILD="ai20-s01-intent-guard"; }catch(e){}
})();

;
/* ==================== Script 1192 id="amiyo-ai20-s02-looks" ==================== */
/* AI 20 · Step 2 — Looks by words: black and white, brighter, warmer, more contrast, blur, reset. Works with no AI model connected. */
(function(){
  "use strict";
  var A=window.amiyoAI20=window.amiyoAI20||{};
  A.norm=function(s){ return String(s||"").replace(/\s+/g," ").trim().toLowerCase().replace(/[.!?]+$/,"").replace(/^(?:please|can you|could you|hey|ai)\s+/,"").replace(/\s+(?:please|now)$/,"").trim(); };
  A.hook=function(h){ var prev=window.amiyoIntentPre; window.amiyoIntentPre=function(raw){ var r=h(raw,A.norm(raw)); return r!==undefined?r:(prev?prev(raw):null); }; };
  A.need=function(){ var f=null; try{ f=window.getClip&&window.getClip(); }catch(e){} if(!f||!f.clip) throw new Error("There is no clip at the playhead. Move the playhead onto a clip first."); return f; };
  A.fxVal=function(c,name,def){ var x=(c.effects||[]).find(function(e){ return e.name===name; }); return x?+x.value:def; };
  A.setFx=function(c,name,v,def){
    if(/^lum/.test(name)&&window.applyColorFx){ window.applyColorFx(c,name,v,def); return; }
    c.effects=c.effects||[]; var x=c.effects.find(function(e){ return e.name===name; });
    if(Math.abs(v-def)<.0005){ c.effects=c.effects.filter(function(e){ return e.name!==name; }); return; }
    if(x){ x.value=v; x.enabled=true; } else c.effects.push({id:"fx_"+Math.random().toString(36).slice(2,9),name:name,enabled:true,value:v});
  };
  var clamp=function(v,a,b){ return Math.max(a,Math.min(b,v)); };
  function look(label,msg,fn){ var f=A.need(); if(f.track.kind!=="video"&&f.clip.kind!=="image"&&f.track.kind!=="text") {} window.transact(label,function(){ fn(f.clip); }); return msg; }
  window.amiyoLook=function(t){
    if(/\b(?:black (?:and|&|n) white|b ?& ?w|b and w|grey?scale|monochrome|no colou?r)\b/.test(t)) return look("Black and white","Black and white",function(c){ A.setFx(c,"lumSaturation",0,1); });
    if(/\b(?:desaturate|less (?:colou?r|saturat\w*)|muted|washed out|dull)\b/.test(t)) return look("Less colour","Colours toned down",function(c){ A.setFx(c,"lumSaturation",clamp(A.fxVal(c,"lumSaturation",1)*.7,0,2),1); });
    if(/\b(?:saturate|more (?:colou?r|saturat\w*)|vivid|vibrant|pop)\b/.test(t)) return look("More colour","More colour",function(c){ A.setFx(c,"lumSaturation",clamp(A.fxVal(c,"lumSaturation",1)*1.3,0,2),1); });
    if(/\b(?:brighten|brighter|lighter|too dark|lighten)\b/.test(t)) return look("Brighter","Brighter",function(c){ A.setFx(c,"lumBrightness",clamp(A.fxVal(c,"lumBrightness",1)*1.15,.4,2),1); });
    if(/\b(?:darken|darker|too bright|dim)\b/.test(t)) return look("Darker","Darker",function(c){ A.setFx(c,"lumBrightness",clamp(A.fxVal(c,"lumBrightness",1)/1.15,.4,2),1); });
    if(/\b(?:more|add|higher) contrast\b|\bpunchier\b/.test(t)) return look("More contrast","More contrast",function(c){ A.setFx(c,"lumContrast",clamp(A.fxVal(c,"lumContrast",1)+.15,.5,2),1); });
    if(/\b(?:less|lower|reduce) contrast\b|\bflatter\b/.test(t)) return look("Less contrast","Less contrast",function(c){ A.setFx(c,"lumContrast",clamp(A.fxVal(c,"lumContrast",1)-.15,.5,2),1); });
    if(/\b(?:warm|warmer|golden|sunny)\b/.test(t)) return look("Warmer","Warmer colours",function(c){ A.setFx(c,"lumTemp",clamp(A.fxVal(c,"lumTemp",0)+20,-100,100),0); });
    if(/\b(?:cool|cooler|colder|icy|bluer)\b/.test(t)) return look("Cooler","Cooler colours",function(c){ A.setFx(c,"lumTemp",clamp(A.fxVal(c,"lumTemp",0)-20,-100,100),0); });
    if(/\bsharpen\b|\bsharper\b|\bcrisper\b/.test(t)) return look("Sharpen","Sharper",function(c){ A.setFx(c,"sharpen",clamp(A.fxVal(c,"sharpen",0)+.5,0,2),0); });
    if(/\bblur\b/.test(t)){ var m=t.match(/(\d+)/), v=m?clamp(+m[1],1,60):(/\b(?:a lot|heavy|strong|very)\b/.test(t)?24:/\b(?:slight|little|light|soft)\b/.test(t)?3:8); return look("Blur","Blur "+v,function(c){ A.setFx(c,"blur",v,0); }); }
    if(/\b(?:reset|clear|remove|undo)\b.*\b(?:look|looks|colou?rs?|filters?|effects?|grade|grading)\b/.test(t)){ return look("Reset look","Look reset",function(c){ c.effects=[]; }); }
    return undefined;
  };
  A.hook(function(raw,t){
    if(/^(?:undo|redo)\b/.test(t)) return undefined;
    if(/\b(?:cinematic|film look|movie look|filmic)\b/.test(t)){ return look("Cinematic look","Cinematic look: more contrast, a little vignette",function(c){ A.setFx(c,"contrast",1.12,1); A.setFx(c,"vignette",.3,0); A.setFx(c,"lumSaturation",1.1,1); }); }
    var r=window.amiyoLook(t); return r;
  });
  try{ window.AMIYO_EDITOR_BUILD="ai20-s02-looks"; }catch(e){}
})();

;
/* ==================== Script 1193 id="amiyo-ai20-s03-request-history" ==================== */
/* AI 20 · Step 3 — Request history and "undo that". Every Ask AI request is logged with how many undo steps it made, so
   "undo that" reverts the whole last request (even one that chained several changes) and "history" lists what was done. */
(function(){
  "use strict";
  var A=window.amiyoAI20=window.amiyoAI20||{}, LOG=A.log=[];
  function hidx(){ try{ return window.project.history.index; }catch(e){ return 0; } }
  window.amiyoRunWrap=function(raw,inner){
    if(A.depth) return inner(raw);
    var t=A.norm?A.norm(raw):String(raw).toLowerCase();
    var meta=/^(?:undo (?:that|it|my last|the last|last)|history|what did you do|what have you done|show (?:my )?history)\b/.test(t);
    var b=hidx(), rec={text:String(raw).trim(),at:Date.now(),before:b,after:b,ok:false,undone:false};
    try{ var r=inner(raw); rec.after=hidx(); rec.ok=true; rec.msg=String(r); if(!meta&&(rec.after>rec.before||/…$/.test(rec.msg))) LOG.push(rec); if(LOG.length>30) LOG.shift(); return r; }
    catch(e){ rec.after=hidx(); if(rec.after>rec.before&&!meta){ rec.msg="partly done"; LOG.push(rec); } throw e; }
  };
  A.hook(function(raw,t){
    if(/^undo (?:that|it|my last|the last|last)\b/.test(t)){
      for(var i=LOG.length-1;i>=0;i--){ var r=LOG[i]; if(r.undone) continue;
        var n=r.after-r.before; if(n<=0){ r.undone=true; continue; }
        if(hidx()!==r.after) throw new Error("Other edits were made after that request, so I did not undo it. Use ↶ to step back one change at a time.");
        for(var k=0;k<n;k++) window.undo(); r.undone=true;
        return "Undid “"+r.text+"” ("+n+" change"+(n===1?"":"s")+")";
      }
      throw new Error("There is no earlier request to undo.");
    }
    if(/^(?:history|what did you do|what have you done|show (?:my )?history)\b/.test(t)){
      var live=LOG.filter(function(x){ return true; }).slice(-6).reverse();
      if(!live.length) return "No requests yet this session.";
      return "Recent requests:\n"+live.map(function(x,i){ return (i+1)+". "+x.text+" — "+(x.undone?"undone":(x.msg||"done")); }).join("\n");
    }
    return undefined;
  });
  try{ window.AMIYO_EDITOR_BUILD="ai20-s03-request-history"; }catch(e){}
})();

