/* ==================== Script 1194 id="amiyo-ai20-s04-scope" ==================== */
/* AI 20 · Step 4 — "all clips" scope. Say "mute all clips", "make every video clip black and white", "fade in everything 1 second":
   the request is run on each matching clip in turn. Delete is never applied to everything at once. */
(function(){
  "use strict";
  var A=window.amiyoAI20=window.amiyoAI20||{};
  var SCOPE=/\s*\b(?:on |for |to |across )?(?:all|every|each)(?: of)?(?: the| my)?(?: (video|audio|text|title|caption|photo|image))?(?: clips?| videos?| tracks?| layers?| titles?| captions?| photos?| images?)?\b|\s*\b(?:everything|the whole (?:timeline|project)|the entire (?:timeline|project))\b/;
  var PERCLIP=/\b(?:mute|unmute|speed|slow|faster|slower|fade|volume|louder|quieter|black (?:and|&) white|b ?& ?w|grey?scale|monochrome|bright|dark|warm|cool|contrast|blur|sharpen|saturat|vivid|colou?r|cinematic|reset|flip|mirror|rotate|reverse|denoise|enhance|fix|auto levels|normali[sz]e|desaturate|muted)\w*/;
  function kinds(word){ return word==="video"||word==="photo"||word==="image"?["video"]:word==="audio"?["audio"]:/text|title/.test(word||"")?["text"]:word==="caption"?["caption"]:["video","audio"]; }
  function pick(c,track){
    var el=document.querySelector('.clip[data-clip="'+c.id+'"]'); if(!el) return false;
    el.click(); var f=window.getClip&&window.getClip(); return !!(f&&f.clip&&f.clip.id===c.id);
  }
  A.hook(function(raw,t){
    var m=t.match(SCOPE); if(!m) return undefined;
    var cmd=t.replace(SCOPE," ").replace(/\s+/g," ").trim();
    if(/^(?:delete|remove|erase|trash)\b/.test(cmd)&&!/silence|pause|gap|noise/.test(cmd)) throw new Error("I won’t delete everything in one go. Select the clips and press Delete, or ask for one clip at a time.");
    if(!PERCLIP.test(cmd)) return undefined;
    var ks=kinds(m[1]), list=[];
    (window.project.tracks||[]).forEach(function(tr){ if(tr.locked||ks.indexOf(tr.kind)<0) return; (tr.clips||[]).forEach(function(c){ list.push({c:c,tr:tr}); }); });
    if(!list.length) throw new Error("There are no matching clips on the timeline.");
    var keep=null; try{ var g=window.getClip(); keep=g&&g.clip&&g.clip.id; }catch(e){}
    var done=0, skipped=0, last="", errs={};
    A.depth=(A.depth||0)+1;
    try{
      list.forEach(function(x){
        if(!pick(x.c,x.tr)){ skipped++; return; }
        try{ last=String(window.amiyoAskAI.runOne(cmd)); done++; }catch(e){ skipped++; errs[(e&&e.message)||"error"]=1; }
      });
    } finally { A.depth--; }
    if(keep){ var k=document.querySelector('.clip[data-clip="'+keep+'"]'); if(k) k.click(); }
    if(!done) throw new Error("Could not apply “"+cmd+"” to any clip"+(Object.keys(errs).length?": "+Object.keys(errs)[0]:". Zoom out so the clips are visible on the timeline."));
    return last+" — on "+done+" clip"+(done===1?"":"s")+(skipped?" ("+skipped+" skipped"+(Object.keys(errs).length?": "+Object.keys(errs)[0]:", not visible on the timeline")+")":"")+". Each is its own undo step.";
  });
  try{ window.AMIYO_EDITOR_BUILD="ai20-s04-scope"; }catch(e){}
})();

