/* ==================== Script 1195 id="amiyo-ai20-s05-smart-fix" ==================== */
/* AI 20 · Step 5 — Smart Fix. "check my project" lists problems found on the timeline (gaps, overlaps, muted clips, tiny clips,
   empty text, no sound). "smart fix" closes the gaps for you and says what it left for you to decide. */
(function(){
  "use strict";
  var A=window.amiyoAI20=window.amiyoAI20||{};
  function tcs(t){ t=Math.max(0,t); var m=Math.floor(t/60); return m+":"+(t-m*60<10?"0":"")+(t-m*60).toFixed(1); }
  function audit(){
    var P=window.project, out={gaps:[],overlaps:[],muted:[],tiny:[],empty:[],n:0,end:0,hasAudio:false}, tracks=P.tracks||[];
    tracks.forEach(function(tr){
      var cs=(tr.clips||[]).slice().sort(function(a,b){ return a.start-b.start; }); out.n+=cs.length;
      cs.forEach(function(c,i){
        out.end=Math.max(out.end,c.start+c.duration);
        if(tr.kind==="audio"||(tr.kind==="video"&&c.volume>0&&c.assetId)) out.hasAudio=true;
        if(c.duration<.3&&tr.kind!=="caption") out.tiny.push(tr.name+" at "+tcs(c.start));
        if((tr.kind==="video"||tr.kind==="audio")&&c.assetId&&c.volume===0) out.muted.push(tr.name+" at "+tcs(c.start));
        if((tr.kind==="text"||tr.kind==="caption")&&!String(c.text||"").trim()) out.empty.push(tr.name+" at "+tcs(c.start));
        var nx=cs[i+1]; if(!nx||tr.kind==="text"||tr.kind==="caption") return;
        var gap=nx.start-(c.start+c.duration);
        if(gap>.05) out.gaps.push({tr:tr,c:c,at:c.start+c.duration,len:gap}); else if(gap<-.05) out.overlaps.push(tr.name+" at "+tcs(nx.start));
      });
    });
    return out;
  }
  A.audit=audit;
  function report(a){
    if(!a.n) return "The timeline is empty: add some clips first.";
    var L=[];
    if(a.gaps.length) L.push("• "+a.gaps.length+" gap"+(a.gaps.length>1?"s":"")+" between clips (first at "+tcs(a.gaps[0].at)+", "+a.gaps[0].len.toFixed(1)+" s)");
    if(a.overlaps.length) L.push("• "+a.overlaps.length+" overlap"+(a.overlaps.length>1?"s":"")+" on one track ("+a.overlaps.slice(0,2).join(", ")+")");
    if(a.muted.length) L.push("• "+a.muted.length+" muted clip"+(a.muted.length>1?"s":"")+" ("+a.muted.slice(0,2).join(", ")+")");
    if(a.tiny.length) L.push("• "+a.tiny.length+" very short clip"+(a.tiny.length>1?"s":"")+" under 0.3 s ("+a.tiny.slice(0,2).join(", ")+")");
    if(a.empty.length) L.push("• "+a.empty.length+" empty text/caption clip"+(a.empty.length>1?"s":""));
    if(!a.hasAudio) L.push("• nothing on the timeline will make sound");
    return (L.length?"Found "+L.length+" thing"+(L.length>1?"s":"")+" to look at in your "+tcs(a.end)+" project:\n"+L.join("\n")+(a.gaps.length?"\nSay “smart fix” to close the gaps.":""):"Looks good: "+a.n+" clips, "+tcs(a.end)+" long, no gaps, overlaps or muted clips.");
  }
  function pickFirst(c){ var el=document.querySelector('.clip[data-clip="'+c.id+'"]'); if(!el) return false; el.click(); var f=window.getClip&&window.getClip(); return !!(f&&f.clip&&f.clip.id===c.id); }
  A.hook(function(raw,t){
    if(/^(?:check|audit|review|inspect|scan|look over|what.?s wrong with|any problems? (?:in|with)) ?(?:my|the|this)? ?(?:project|timeline|video|edit)?$|^(?:what.?s wrong|any problems|find problems|project check)$/.test(t)) return report(audit());
    if(/^(?:smart fix|fix (?:my |the )?(?:project|timeline|everything|problems|issues)|tidy (?:up )?(?:my |the )?(?:timeline|project)?|clean up (?:my |the )?(?:timeline|project))$/.test(t)){
      var a=audit(); if(!a.n) return "The timeline is empty: add some clips first.";
      var closed=0, seen={}, left=[];
      a.gaps.forEach(function(g){ if(seen[g.tr.id]) return; seen[g.tr.id]=1;
        if(g.tr.locked){ left.push(g.tr.name+" is locked"); return; }
        if(!pickFirst(g.c)){ left.push("a gap on "+g.tr.name+" is off-screen: zoom out and ask again"); return; }
        var b=document.getElementById("qGaps"); if(b){ var n0=JSON.stringify(window.project.tracks).length; b.click(); if(JSON.stringify(window.project.tracks).length!==n0||true) closed++; }
      });
      var b2=audit(), rest=[];
      if(b2.gaps.length) rest.push(b2.gaps.length+" gap"+(b2.gaps.length>1?"s":"")+" still open");
      if(b2.overlaps.length) rest.push(b2.overlaps.length+" overlap"+(b2.overlaps.length>1?"s":"")+" (your call)");
      if(b2.muted.length) rest.push(b2.muted.length+" muted clip"+(b2.muted.length>1?"s":""));
      if(b2.tiny.length) rest.push(b2.tiny.length+" tiny clip"+(b2.tiny.length>1?"s":""));
      if(b2.empty.length) rest.push(b2.empty.length+" empty text clip"+(b2.empty.length>1?"s":""));
      var msg=(closed?"Closed the gaps on "+closed+" track"+(closed>1?"s":""):"No gaps to close")+".";
      if(rest.length||left.length) msg+=" Left for you: "+rest.concat(left).join(", ")+".";
      return msg;
    }
    return undefined;
  });
  try{ window.AMIYO_EDITOR_BUILD="ai20-s05-smart-fix"; }catch(e){}
})();

