/* ==================== Script 1196 id="amiyo-ai20-s06-captions" ==================== */
/* AI 20 · Step 6 — Captions by words, on this device. "clean up captions" / "remove filler words" tidies the caption text (um, uh, repeated
   words, spacing, capital letters), "captions from: <text>" lays your own words out as timed captions from the playhead, "caps" /
   "lowercase" change the case, and "translate captions" opens the caption tools. Timing is never changed by cleanup. */
(function(){
  "use strict";
  var A=window.amiyoAI20=window.amiyoAI20||{};
  var FILL=/(?:^|[\s,;])(?:um+|uh+|uhm+|erm?|hmm+|mm+|ah+)(?=[\s,.!?;]|$)[,.]?/gi, PHR=/\b(?:you know|i mean)\s*,\s*/gi;
  function tidy(s,opt){
    var x=String(s||"");
    if(opt.filler){ x=x.replace(FILL," ").replace(PHR,""); }
    x=x.replace(/\b(\w+)(\s+\1\b)+/gi,"$1");                       /* "the the" -> "the" */
    x=x.replace(/\s+/g," ").replace(/\s+([,.!?;:])/g,"$1").replace(/([,.!?;:])\1+/g,"$1").replace(/^[\s,;.]+/,"").trim();
    x=x.replace(/\bi\b(?=[\s',.!?]|$)/g,"I");
    if(x) x=x.charAt(0).toUpperCase()+x.slice(1);
    return x;
  }
  function caps(){ return (window.project.tracks||[]).filter(function(t){ return t.kind==="caption"; }); }
  function change(label,fn){ window.transact(label,fn); }
  function runClean(filler){
    var n=0, tot=0, gone=0;
    var tr=caps(); tot=tr.reduce(function(a,t){ return a+t.clips.length; },0);
    if(!tot) throw new Error("There are no captions yet. Say “captions from: your words here” to add some.");
    change(filler?"Captions: remove filler words":"Captions: clean up",function(){
      tr.forEach(function(t){
        t.clips=t.clips.filter(function(c){ var o=c.text||"", v=tidy(o,{filler:filler}); if(!v){ gone++; return false; } if(v!==o){ c.text=v; if(c.name===o) c.name=v; n++; } return true; });
      });
    });
    if(!n&&!gone) return "Captions already look clean ("+tot+" lines checked).";
    return "Cleaned "+n+" of "+tot+" caption line"+(tot===1?"":"s")+(gone?" and removed "+gone+" that were only filler words":"")+".";
  }
  function build(text){
    var words=text.replace(/\s+/g," ").trim(); if(!words) throw new Error("Tell me the words, for example: captions from: Welcome to my channel.");
    var parts=words.split(/(?<=[.!?…])\s+/), chunks=[];
    parts.forEach(function(p){ var w=p.split(" "); for(var i=0;i<w.length;i+=8) chunks.push(w.slice(i,i+8).join(" ")); });
    var ex=null; caps().forEach(function(t){ if(!ex&&t.clips.length) ex=t.clips[t.clips.length-1]; });
    var at=0; try{ var tr0=document.getElementById("timeReadout"); var m=tr0&&String(tr0.textContent).match(/(\d+):(\d+)(?:[.:](\d+))?/); if(m) at=(+m[1])*60+(+m[2])+(m[3]?+("0."+m[3]):0); }catch(e){}
    var tr=window.getTrack("caption"), made=0;
    change("Captions from text",function(){
      chunks.forEach(function(ch){
        var n=ch.split(" ").length, d=Math.max(1.2,Math.round(n/2.7*100)/100);
        tr.clips.push({id:"cap_"+Math.random().toString(36).slice(2,10),kind:"caption",name:ch,start:Math.round(at*100)/100,duration:d,text:ch,x:.5,y:(ex&&ex.y)||.86,opacity:1,
          textStyle:ex&&ex.textStyle?JSON.parse(JSON.stringify(ex.textStyle)):{fontFamily:"system-ui",fontSize:44,weight:800,color:"#ffffff",align:"center",shadow:true}});
        at+=d; made++;
      });
      tr.clips.sort(function(a,b){ return a.start-b.start; });
    });
    return made+" caption"+(made===1?"":"s")+" added from the playhead ("+at.toFixed(1)+" s end). Adjust timing on the timeline.";
  }
  A.hook(function(raw,t){
    var q=String(raw).match(/^\s*(?:please\s+)?(?:add |make |create |write )?(?:the )?(?:captions?|subtitles?)\s+(?:from|for|saying|with|of)\b\s*:?\s*([\s\S]+)$/i);
    if(q&&!/^(?:this|the|my|a|an)\s+(?:video|clip|music|audio)\b/i.test(q[1].trim())) return build(q[1].replace(/^[“"']|[”"']$/g,""));
    if(/\b(?:remove|cut|delete|strip|clean(?: up)?|drop)\b.*\b(?:filler|fillers|ums?|uhs?|um and uh)\b/.test(t)) return runClean(true);
    if(/^(?:clean up|clean|tidy(?: up)?|fix|polish|proofread)\b.*\bcaptions?\b|^captions? (?:clean ?up|cleanup|tidy)\b/.test(t)) return runClean(false);
    var cs=t.match(/^(?:make |turn )?(?:the |my )?captions? (?:into |to |in )?(upper ?case|all caps|capitals|lower ?case)$|^(upper ?case|all caps|lower ?case) (?:the |my )?captions?$/);
    if(cs){ var up=/upper|caps|capitals/.test(cs[1]||cs[2]); var tr=caps(), k=0; if(!tr.some(function(x){ return x.clips.length; })) throw new Error("There are no captions yet.");
      change(up?"Captions: UPPERCASE":"Captions: lowercase",function(){ tr.forEach(function(x){ x.clips.forEach(function(c){ var v=up?String(c.text||"").toUpperCase():String(c.text||"").toLowerCase(); if(v!==c.text){ c.text=v; k++; } }); }); });
      return (up?"Uppercased ":"Lowercased ")+k+" caption line"+(k===1?"":"s")+"."; }
    if(/\b(?:translate|translation)\b.*\bcaptions?\b|\bcaption tools\b|\bsubtitle tools\b|\btranslate (?:the )?subtitles?\b/.test(t)){
      if(!window.amiyoCaptionAI) throw new Error("The caption tools are not ready."); window.amiyoCaptionAI.open(); return "Opened the caption tools: pick a language there.";
    }
    return undefined;
  });
  try{ window.AMIYO_EDITOR_BUILD="ai20-s06-captions"; }catch(e){}
})();

