/* ==================== Script 1197 id="amiyo-ai20-s07-silence" ==================== */
/* AI 20 · Step 7 — Smart silence by words. "how much silence is in this clip" measures it without cutting anything,
   "remove silence from all clips" cuts each clip in turn (gentle / balanced / tight, as you say), and "trim silence at the ends"
   uses the Audio Lab end trimmer. Uses the editor's own silence engine, so every cut is undoable. */
(function(){
  "use strict";
  var A=window.amiyoAI20=window.amiyoAI20||{}, busy=false;
  function sleep(ms){ return new Promise(function(r){ setTimeout(r,ms); }); }
  function toast(m){ try{ window.toast(m); }catch(e){} }
  function pick(id){ var el=document.querySelector('.clip[data-clip="'+id+'"]'); if(!el) return false; el.click(); var f=window.getClip&&window.getClip(); return !!(f&&f.clip&&f.clip.id===id); }
  function readDialog(){
    return (async function(){
      var t0=Date.now();
      window.amiyoCut.silences();
      while(Date.now()-t0<60000){
        await sleep(250);
        var d=document.querySelector(".cs-dlg"); if(!d) return {err:"The silence tool closed."};
        var s=d.querySelector(".cs-status"), txt=s?s.textContent:"";
        if(/no sound track/i.test(txt)) return {err:"This clip has no sound."};
        if(/Could not read/i.test(txt)) return {err:"Could not read this clip’s audio."};
        var info=d.innerText.match(/(\d+) silences? found[^\n]*|No (?:pauses|silences?)[^\n]*/i);
        if(info){ var c=document.getElementById("csCancel"); var txt2=info[0]; return {text:txt2,close:function(){ if(c) c.click(); }}; }
      }
      return {err:"Timed out while listening to the clip."};
    })();
  }
  function level(t){ return /tight|aggressive|fast|jump/.test(t)?"tight":/gentle|light|careful|soft|natural/.test(t)?"gentle":"balanced"; }
  A.hook(function(raw,t){
    if(/\b(?:how much|any|is there|find|measure|count|report)\b.*\b(?:silence|silent|pauses?|dead air)\b/.test(t)&&!/\b(?:remove|cut|delete)\b/.test(t)){
      if(!window.amiyoCut||!window.amiyoCut.silences) throw new Error("The silence tool is not available in this build.");
      A.need(); if(busy) return "Still working on the last silence request…";
      busy=true;
      readDialog().then(function(r){ busy=false; if(r.err){ toast(r.err); return; } r.close(); toast(r.text.replace(/\s+/g," ").slice(0,140)+" (nothing was cut)"); },function(){ busy=false; });
      return "Listening to the clip…";
    }
    var m=/\b(?:remove|cut|delete|tighten|trim)\b.*\b(?:silence|silent parts?|pauses?|dead air)\b.*\b(?:all|every|each)\b|\b(?:all|every|each)\b.*\b(?:silence|pauses?|dead air)\b|\btighten (?:all|everything)\b/.test(t);
    if(m){
      if(!window.amiyoSmartCut) throw new Error("Smart Cut is not ready.");
      if(busy) return "Still working on the last silence request…";
      var ids=[]; (window.project.tracks||[]).forEach(function(tr){ if(tr.locked||(tr.kind!=="video"&&tr.kind!=="audio")) return; (tr.clips||[]).forEach(function(c){ if(c.assetId) ids.push(c.id); }); });
      if(!ids.length) throw new Error("There are no clips with sound on the timeline.");
      var key=level(t); busy=true; var done=0, skipped=0;
      (async function(){
        for(var i=0;i<ids.length;i++){
          if(!pick(ids[i])){ skipped++; continue; }
          var before=window.project.history.index;
          try{ await window.amiyoSmartCut.run(key,true); }catch(e){}
          await sleep(300);
          if(window.project.history.index>before) done++; else skipped++;
        }
        busy=false; toast("Silence removed from "+done+" of "+ids.length+" clip"+(ids.length===1?"":"s")+(skipped?" ("+skipped+" had no pauses or were off-screen)":"")+". One undo per clip.");
      })();
      return "Cutting silence ("+key+") from "+ids.length+" clip"+(ids.length===1?"":"s")+" one by one…";
    }
    if(/\b(?:trim|cut|remove)\b.*\bsilence\b.*\b(?:ends?|start and end|beginning and end|edges)\b|\bsilence at the (?:ends?|start|beginning|end)\b/.test(t)){
      A.need(); var b=document.getElementById("altrim"); if(!b) throw new Error("The end trimmer is not available right now.");
      var before=window.project.history.index, te=document.getElementById("toast"); if(te) te.textContent="";
      b.click(); var said=te?te.textContent.trim():"";
      if(said) return said; if(window.project.history.index>before) return "Trimmed the silence at the ends";
      return "Asked the end trimmer to run: watch for its message.";
    }
    return undefined;
  });
  try{ window.AMIYO_EDITOR_BUILD="ai20-s07-silence"; }catch(e){}
})();

;
/* ==================== Script 1198 id="amiyo-ai20-s08-summary-chapters" ==================== */
/* AI 20 · Step 8 — Project summary and chapters, on this device. "summarize my project" describes what is on the timeline;
   "make chapters" puts a marker at the start of each section (named from the title text that starts there, else the file name,
   never closer than 10 s apart as YouTube requires) and prints the list ready to paste; "list chapters" shows the current ones. */
(function(){
  "use strict";
  var A=window.amiyoAI20=window.amiyoAI20||{};
  function tc(t){ t=Math.max(0,Math.round(t)); var h=Math.floor(t/3600), m=Math.floor((t%3600)/60), s=t%60; return (h?h+":"+(m<10?"0":""):"")+m+":"+(s<10?"0":"")+s; }
  function clean(n){ return String(n||"").replace(/\.[a-z0-9]{2,4}$/i,"").replace(/[_\-]+/g," ").replace(/\s+/g," ").trim(); }
  function mainTrack(){ var best=null; (window.project.tracks||[]).forEach(function(t){ if(t.kind==="video"&&t.clips.length&&(!best||t.clips.length>best.clips.length)) best=t; }); return best; }
  function texts(){ var o=[]; (window.project.tracks||[]).forEach(function(t){ if(t.kind==="text") t.clips.forEach(function(c){ if(String(c.text||"").trim()) o.push(c); }); }); return o.sort(function(a,b){ return a.start-b.start; }); }
  function chapters(){ return (window.project.markers||[]).slice().sort(function(a,b){ return a.time-b.time; }); }
  function summary(){
    var P=window.project, a=A.audit?A.audit():{n:0,end:0}; if(!a.n) return "The timeline is empty: nothing to summarize yet.";
    var cnt={}; (P.tracks||[]).forEach(function(t){ if(t.clips.length) cnt[t.kind]=(cnt[t.kind]||0)+t.clips.length; });
    var parts=Object.keys(cnt).map(function(k){ return cnt[k]+" "+k+" clip"+(cnt[k]>1?"s":""); });
    var st=P.settings||{}, L=["Your project is "+tc(a.end)+" long with "+parts.join(", ")+"."];
    if(st.width&&st.height) L.push("Frame: "+st.width+"×"+st.height+(st.width<st.height?" (vertical)":st.width===st.height?" (square)":" (landscape)")+".");
    var tx=texts().slice(0,3).map(function(c){ return "“"+String(c.text).trim().slice(0,40)+"”"; }); if(tx.length) L.push("Titles: "+tx.join(", ")+".");
    var cap=(P.tracks||[]).filter(function(t){ return t.kind==="caption"; }).reduce(function(n,t){ return n+t.clips.length; },0); L.push(cap?cap+" caption lines.":"No captions yet.");
    L.push(a.hasAudio?"There is sound.":"Nothing will make sound.");
    var mk=chapters().length; if(mk) L.push(mk+" marker"+(mk>1?"s":"")+" set.");
    var issues=(a.gaps||[]).length+(a.overlaps||[]).length+(a.muted||[]).length; if(issues) L.push(issues+" thing"+(issues>1?"s":"")+" to look at: say “check my project”.");
    return L.join(" ");
  }
  function makeChapters(){
    var mt=mainTrack(); if(!mt) throw new Error("Add a video to the timeline first.");
    var T=texts(), cs=mt.clips.slice().sort(function(a,b){ return a.start-b.start; }), cand=[];
    cs.forEach(function(c,i){
      var title=null; for(var k=0;k<T.length;k++){ if(T[k].start>=c.start-.05&&T[k].start<c.start+c.duration){ title=String(T[k].text).trim().split(/\n/)[0].slice(0,48); break; } }
      cand.push({t:i===0?0:c.start,label:title||(i===0?"Intro":clean(c.name)||"Part "+(i+1))});
    });
    var out=[], skipped=0; cand.forEach(function(x){ var l=out[out.length-1]; if(l&&x.t-l.t<9.9){ skipped++; return; } out.push(x); });
    if(out.length<2) throw new Error("Not enough separate sections for chapters: YouTube needs at least 3 chapters, each 10 s or longer"+(skipped?" ("+skipped+" were too close together)":"")+".");
    var have=chapters(), added=0;
    window.transact("Make chapters",function(){
      window.project.markers=window.project.markers||[];
      out.forEach(function(x){ var ex=window.project.markers.find(function(m){ return Math.abs(m.time-x.t)<1; }); if(ex){ if(ex.label!==x.label&&/^(?:Part \d+|Intro|Marker)$/.test(ex.label||"Marker")){ ex.label=x.label; added++; } return; } window.project.markers.push({id:"marker_"+Math.random().toString(36).slice(2,9),time:x.t,label:x.label,color:"#ff8040"}); added++; });
    });
    var list=out.map(function(x){ return tc(x.t)+" "+x.label; }).join("\n");
    return "Chapters ("+added+" marker"+(added===1?"":"s")+(out.length<3?"; YouTube needs 3 or more":"")+"):\n"+list+(skipped?"\n("+skipped+" short section"+(skipped>1?"s were":" was")+" merged)":"");
  }
  A.hook(function(raw,t){
    if(/^(?:summari[sz]e|describe|explain|sum up|overview of|give me an overview of)\b.*\b(?:project|timeline|video|edit)\b|^(?:project )?(?:summary|overview)$|^what.?s (?:in|on) (?:my|the) (?:project|timeline)$/.test(t)) return summary();
    if(/^(?:make|add|create|generate|auto|build|set)\b.*\bchapters?\b/.test(t)) return makeChapters();
    if(/^(?:list|show|what are|print)\b.*\bchapters?\b|^chapters?$/.test(t)){
      var c=chapters(); if(!c.length) return "No chapters yet. Say “make chapters” to create them."; return c.map(function(m){ return tc(m.time)+" "+(m.label||"Marker"); }).join("\n");
    }
    if(/^copy\b.*\bchapters?\b/.test(t)){ if(typeof window.amiyoCopyChapters!=="function") throw new Error("Copy chapters is not available."); window.amiyoCopyChapters(); return "Asked the editor to copy the chapter list."; }
    return undefined;
  });
  try{ window.AMIYO_EDITOR_BUILD="ai20-s08-summary-chapters"; }catch(e){}
})();

