/* ==================== Script 1199 id="amiyo-ai20-s09-titles" ==================== */
/* AI 20 · Step 9 — Titles by words. "lower third Anna Lee, Host" puts a name strap on the lower part of the picture, "intro title My Trip" and
   "end card" place a title at the start / a thank-you at the end, "suggest titles" proposes ideas from what is in your project,
   and "write titles with AI" opens AI Writer. All offline except the last. Each addition is one undo step. */
(function(){
  "use strict";
  var A=window.amiyoAI20=window.amiyoAI20||{};
  function playhead(){ try{ var v=document.getElementById("timeReadout"); var m=v&&String(v.textContent).match(/(\d+):(\d+)(?:[.:](\d+))?/); return m?(+m[1])*60+(+m[2])+(m[3]?+("0."+m[3]):0):0; }catch(e){ return 0; } }
  function unq(s){ return String(s||"").replace(/^[\s:,\-–]+/,"").replace(/^[“"'‘]|[”"'’]$/g,"").trim(); }
  function add(label,items){
    var tr=window.getTrack("text");
    window.transact(label,function(){ items.forEach(function(x){
      tr.clips.push({id:"clip_"+Math.random().toString(36).slice(2,10),kind:"text",name:x.text.split("\n")[0],start:Math.round(Math.max(0,x.start)*100)/100,duration:x.dur,text:x.text,
        textStyle:{fontFamily:"system-ui",fontSize:x.fs,weight:x.w||800,color:"#ffffff",align:x.align||"center",shadow:true},x:x.x==null?.5:x.x,y:x.y,opacity:1,rotation:0,scale:1,keyframes:[],fadeIn:.4,fadeOut:.4});
    }); });
  }
  function ideas(){
    var base=[], P=window.project;
    (P.tracks||[]).forEach(function(t){ t.clips.forEach(function(c){
      if(t.kind==="text"&&String(c.text||"").trim()) base.push(String(c.text).trim().split("\n")[0]);
      else if((t.kind==="video"||t.kind==="audio")&&c.name&&!/^clip_/.test(c.name)) base.push(c.name.replace(/\.[a-z0-9]{2,4}$/i,"").replace(/[_\-]+/g," ").trim());
    }); });
    var topic=(base.find(function(x){ return x&&x.length>2&&x.length<40&&!/^(?:title|video \d|audio \d|clip)/i.test(x); })||"").replace(/\b\w/g,function(c){ return c.toUpperCase(); });
    if(!topic) return null;
    return [topic, "The Story of "+topic, "Inside "+topic, topic+": What You Need to Know", "I Tried "+topic+" So You Don’t Have To", "Everything About "+topic+" in One Video"];
  }
  A.hook(function(raw,t){
    var r=String(raw).trim(), m;
    if((m=r.match(/^(?:please\s+)?(?:add |put |make |create )?(?:a )?lower[- ]?third\b\s*:?\s*([\s\S]*)$/i))){
      var parts=unq(m[1]).split(/\s*(?:,|\||\s[-–]\s)\s*/); var name=unq(parts[0]); if(!name) throw new Error("Whose name? For example: lower third Anna Lee, Host");
      var sub=unq(parts.slice(1).join(", ")), at=playhead();
      add("Lower third",[{text:name,start:at,dur:4,fs:42,y:sub?.80:.84,x:.2,align:"left"}].concat(sub?[{text:sub,start:at,dur:4,fs:28,w:500,y:.88,x:.2,align:"left"}]:[]));
      return "Lower third added at "+at.toFixed(1)+" s for 4 s"+(sub?" with a second line":"")+".";
    }
    if((m=r.match(/^(?:please\s+)?(?:add |put |make |create )?(?:an? )?(?:intro|opening|title card)(?: title| card)?\b\s*:?\s*([\s\S]*)$/i))&&!/^(?:music|sound|animation|clip|video)\b/i.test(unq(m[1]))){
      var tx=unq(m[1]); if(!tx){ var d=ideas(); tx=d?d[0]:"My Video"; }
      add("Intro title",[{text:tx,start:0,dur:3.5,fs:72,y:.5}]); return "Intro title “"+tx+"” added at the start for 3.5 s.";
    }
    if(/^(?:please\s+)?(?:add |put |make |create )?(?:an? )?(?:outro|end card|ending card|closing card|end screen|end title|thanks? for watching)\b/.test(t)){
      var a=A.audit?A.audit():{end:0}; if(!a.end) throw new Error("Add some clips first, then I can put the end card after them.");
      var cm=r.match(/["“]([^"”]+)["”]/); var txt=cm?cm[1]:"Thanks for watching!"; var st=Math.max(0,a.end-4);
      add("End card",[{text:txt,start:st,dur:Math.min(4,a.end),fs:64,y:.5}]); return "End card added for the last "+Math.min(4,a.end).toFixed(1)+" s.";
    }
    if(/^(?:suggest|give me|show me|think of|come up with|brainstorm)\b.*\b(?:titles?|names?|headlines?)\b/.test(t)){
      var s=ideas(); if(!s) return "I have nothing to base titles on yet. Add a title or a named clip, or say “write titles with AI”.";
      return "Title ideas:\n"+s.map(function(x,i){ return (i+1)+". "+x; }).join("\n")+"\nSay: intro title <your pick>.";
    }
    if(/\b(?:write|generate|make|give)\b.*\b(?:titles?|hooks?|headlines?)\b.*\b(?:ai|with ai)\b|\bai (?:titles?|writer)\b|\bopen (?:the )?(?:ai )?writer\b/.test(t)){
      if(!window.amiyoWriter) throw new Error("AI Writer is not ready."); window.amiyoWriter.open(); return "Opened AI Writer: it needs an AI provider (tap ⚙ Providers).";
    }
    return undefined;
  });
  try{ window.AMIYO_EDITOR_BUILD="ai20-s09-titles"; }catch(e){}
})();

