/* ==================== Script 1200 id="amiyo-ai20-s10-loudness" ==================== */
/* AI 20 · Step 10 — Loudness and ducking by words. "match loudness" evens the selected clips, "duck the music" lowers music under speech,
   "crossfade the audio joins" smooths cuts, and "music volume 20%" / "voice volume 100%" set a whole kind of sound at once.
   Uses the editor's own sound tools and reports what they report. */
(function(){
  "use strict";
  var A=window.amiyoAI20=window.amiyoAI20||{};
  var FAIL=/^(?:move |select |no |nothing|couldn|could not|can.?t|cannot|there is no|there are no|not |failed|something went wrong|⚠|clip is silent|add )/i;
  function ctl(re){ var l=document.querySelectorAll("button,[role=button],[role=menuitem]"); for(var i=0;i<l.length;i++){ var b=l[i]; if(b.disabled) continue; var tx=String(b.textContent||"").replace(/\s+/g," ").trim().toLowerCase().replace(/^[^a-z0-9]+/,""); if(re.test(tx)) return b; } return null; }
  function sig(){ try{ return JSON.stringify(window.project,function(k,v){ return k==="history"?undefined:(typeof v==="string"&&v.length>120?v.length:v); }).length; }catch(e){ return Math.random(); } }
  function press(re,label,what){
    var b=ctl(re); if(!b) throw new Error(what+" is not available right now.");
    var te=document.getElementById("toast"); if(te) te.textContent=""; var s0=sig(); b.click();
    var said=te?String(te.textContent||"").trim():""; if(said&&FAIL.test(said)) throw new Error(said);
    if(!said&&sig()===s0) return /^Opened/.test(label)?label:label+" started: watch for its message.";
    return said&&said.length<90?said:label;
  }
  function pct(t){ var m=t.match(/(\d{1,3})\s*(?:%|percent)/)||t.match(/\bto (\d{1,3})\b/)||t.match(/\b(\d{1,3})\b/); return m?Math.max(0,Math.min(100,+m[1])):null; }
  A.hook(function(raw,t){
    if(/\b(?:match|even out|equali[sz]e|balance|normali[sz]e)\b.*\b(?:loudness|volumes?|levels?)\b.*\b(?:clips?|all|everything|across)\b|\bmatch (?:the )?loudness\b|\bloudness (?:for|to|target)\b|\bset loudness\b/.test(t))
      return press(/^match loudness/,"Opened Match loudness: it measures the selected clips, then tap its button to level them","Match Loudness");
    if(/\b(?:duck|lower|dip|reduce|turn down)\b.*\b(?:music|background|bgm|soundtrack)\b.*\b(?:talk\w*|speech|voice|speak\w*|narration|dialogue|voiceover)\b|\bauto[- ]?duck\b|\bduck (?:the )?(?:music|background)\b/.test(t))
      return press(/^duck music/,"Ducking the music under speech","Duck music");
    if(/\bcrossfade\b.*\b(?:audio|sound|joins?|cuts?)\b|\b(?:smooth|soften)\b.*\b(?:audio|sound)\b.*\b(?:cuts?|joins?|edits?)\b/.test(t))
      return press(/^crossfade joins/,"Crossfading the audio joins","Crossfade joins");
    var m=t.match(/\b(music|background|bgm|soundtrack|voice|voiceover|narration|speech|dialogue|video)\b.*\b(?:volume|level|louder|quieter|softer)\b|\b(?:volume|level)\b.*\b(?:of|for) (?:the )?(music|background|bgm|soundtrack|voice|voiceover|narration|video)\b/);
    if(m){
      var who=m[1]||m[2], v=pct(t); if(v==null){ v=/\b(?:louder|up|higher|more)\b/.test(t)?null:/\b(?:quieter|softer|lower|down|less)\b/.test(t)?null:null; }
      var music=/music|background|bgm|soundtrack/.test(who), video=who==="video";
      var kinds=video?["video"]:["audio"], list=[];
      (window.project.tracks||[]).forEach(function(tr){ if(tr.locked||kinds.indexOf(tr.kind)<0) return; tr.clips.forEach(function(c){ if(c.assetId) list.push(c); }); });
      if(!list.length) throw new Error("There are no "+(video?"video":"audio")+" clips to change.");
      var delta=0; if(v==null){ delta=/\b(?:louder|up|higher|more)\b/.test(t)?.2:-.2; }
      window.transact((music?"Music":video?"Video":"Voice")+" volume",function(){ list.forEach(function(c){ var cur=c.volume==null?1:+c.volume; c.volume=Math.round(Math.max(0,Math.min(1,v!=null?v/100:cur+delta))*100)/100; }); });
      return (music?"Music":video?"Video sound":"Voice")+" set to "+(v!=null?v+"%":"about "+Math.round(list[0].volume*100)+"%")+" on "+list.length+" clip"+(list.length===1?"":"s")+(!video&&list.length?" (every audio-track clip: the editor does not label music vs voice)":"")+".";
    }
    return undefined;
  });
  try{ window.AMIYO_EDITOR_BUILD="ai20-s10-loudness"; }catch(e){}
})();

