/* ==================== Script 1201 id="amiyo-ai20-s11-platforms" ==================== */
/* AI 20 · Step 11 — Reframe for a platform by words. "make it for TikTok / Reels / Shorts / Stories" sets 9:16, "Instagram post" 1:1,
   "Instagram portrait" 4:5, "YouTube" 16:9, and "make all versions" is not faked: it tells you to export once per shape. Uses the editor's own aspect commands. */
(function(){
  "use strict";
  var A=window.amiyoAI20=window.amiyoAI20||{};
  function set(w,h,asp,label){
    window.transact("Frame: "+asp,function(){ var s=window.project.settings; s.width=w; s.height=h; s.aspect=asp; });
    try{ if(typeof window.renderAll==="function") window.renderAll(); }catch(e){}
    return "Project is now "+label+" "+asp+" ("+w+"×"+h+"). Clips keep their size: check the framing in the preview.";
  }
  A.hook(function(raw,t){
    if(/\bmake all (?:the )?(?:versions|sizes|formats)\b/.test(t)) return "I can’t make every size in one go. Pick one (for example “make it for TikTok”), export, then pick the next.";
    if(A.inPlat||/^(?:crop to square|landscape|vertical|square|make it vertical|portrait)$/.test(t)) return undefined;
    if(!/\b(?:make|set|resize|reframe|format|convert|switch|change|turn|optimi[sz]e|prepare|crop)\b.*\b(?:for|to|as|into|fit)\b|\b(?:for|as) (?:a |an )?(?:tiktok|reels?|shorts?|stories|story|instagram|youtube|facebook|linkedin|snapchat|twitter|x post)\b|^(?:tiktok|reels?|youtube shorts?|instagram (?:post|portrait|story)|youtube|story)$/.test(t)) return undefined;
    A.inPlat=true; try{ return plat(t); } finally { A.inPlat=false; }
  });
  function plat(t){
    if(/\b(?:tiktok|tik tok|reels?|shorts?|stor(?:y|ies)|snapchat|vertical video|9 ?: ?16)\b/.test(t)) return window.amiyoAskAI.runOne("make it vertical")+" (9:16, good for TikTok, Reels, Shorts and Stories)";
    if(/\b(?:instagram|facebook|linkedin)\b.*\b(?:portrait|4 ?: ?5)\b|\b4 ?: ?5\b/.test(t)) return set(864,1080,"4:5","portrait");
    if(/\b(?:instagram|facebook|linkedin|twitter|x)\b.*\b(?:post|feed)\b|\bsquare\b|\b1 ?: ?1\b/.test(t)) return window.amiyoAskAI.runOne("crop to square");
    if(/\b(?:youtube|landscape|widescreen|wide|tv|desktop|16 ?: ?9)\b/.test(t)) return window.amiyoAskAI.runOne("landscape");
    return undefined;
  }
  try{ window.AMIYO_EDITOR_BUILD="ai20-s11-platforms"; }catch(e){}
})();

