/* ==================== Script 1202 id="amiyo-ai20-s12-colour-match" ==================== */
/* AI 20 · Step 12 — Colour match by words. "match the colours to the first clip" grades each other clip to look like a reference clip
   (the first video clip, or "clip 2"), using the editor's own Color Match so one tap of undo reverses it. */
(function(){
  "use strict";
  var A=window.amiyoAI20=window.amiyoAI20||{};
  function sleep(ms){ return new Promise(function(r){ setTimeout(r,ms); }); }
  function toast(m){ try{ window.toast(m); }catch(e){} }
  function vids(){ var o=[]; (window.project.tracks||[]).forEach(function(t){ if(t.kind==="video") t.clips.slice().sort(function(a,b){ return a.start-b.start; }).forEach(function(c){ if(c.assetId&&c.kind!=="adjustment") o.push(c); }); }); return o; }
  function pick(id){ var el=document.querySelector('.clip[data-clip="'+id+'"]'); if(!el) return false; el.click(); var f=window.getClip&&window.getClip(); return !!(f&&f.clip&&f.clip.id===id); }
  A.hook(function(raw,t){
    if(!/\b(?:match|same|consistent|even out|unify|grade)\b.*\b(?:colou?rs?|look|grade|grading)\b|\bcolou?r match\b/.test(t)) return undefined;
    var v=vids(); if(v.length<2) throw new Error("Colour match needs at least two video clips on the timeline.");
    var n=t.match(/\b(?:clip|shot|video)\s*(\d+)\b/), ref=n?v[Math.min(v.length,Math.max(1,+n[1]))-1]:v[0];
    var targets=v.filter(function(c){ return c.id!==ref.id; });
    
    (async function(){
      var done=0, fail=0;
      var nb=[].slice.call(document.querySelectorAll("#nav button,#nav .navbtn")).find(function(b){ return String(b.textContent).trim()==="Color"; }); if(nb) nb.click(); await sleep(250);
      for(var i=0;i<targets.length;i++){
        if(!pick(targets[i].id)){ fail++; continue; }
        try{ if(typeof window.renderLeftPanel==="function") window.renderLeftPanel(); }catch(e){}
        await sleep(200);
        var sel=document.getElementById("colorMatchRef"), btn=document.getElementById("colorMatchBtn");
        if(!sel||!btn||btn.disabled){ fail++; continue; }
        sel.value=ref.id; if(sel.value!==ref.id){ fail++; continue; }
        var st=document.getElementById("colorMatchStatus"); if(st) st.textContent="";
        btn.click();
        for(var k=0;k<40;k++){ await sleep(250); var tx=st?st.textContent:""; if(tx&&!/sampling/i.test(tx)) break; }
        if(st&&/couldn/i.test(st.textContent)) fail++; else done++;
      }
      toast("Colour matched "+done+" clip"+(done===1?"":"s")+" to "+(n?"clip "+n[1]:"the first clip")+(fail?" ("+fail+" could not be matched: select it and use Color Match in its panel)":"")+". One undo per clip.");
    })();
    return "Matching "+targets.length+" clip"+(targets.length===1?"":"s")+" to "+(n?"clip "+n[1]:"the first clip")+"…";
  });
  try{ window.AMIYO_EDITOR_BUILD="ai20-s12-colour-match"; }catch(e){}
})();

