/* ==================== Script 1203 id="amiyo-ai20-s13-short" ==================== */
/* AI 20 · Step 13 — "Make a 30 second short" by words. Runs the AI Highlights finder for the clip at the playhead (15, 30 or 60 s),
   takes the best moment it finds and builds the short from it. Needs a clip at least 1.2 times as long as the short. Works on this device. */
(function(){
  "use strict";
  var A=window.amiyoAI20=window.amiyoAI20||{}, busy=false;
  function sleep(ms){ return new Promise(function(r){ setTimeout(r,ms); }); }
  function toast(m){ try{ window.toast(m); }catch(e){} }
  A.hook(function(raw,t){
    var m=t.match(/\b(?:make|create|cut|build|turn (?:this|it) into|give me|find)\b.*?\b(?:a |an |the )?(\d+)\s*(?:s|sec|secs|second|seconds)\b.*\b(?:short|clip|highlight|teaser|trailer|reel|version|cut|summary)\b|\b(?:make|create|build|cut)\b.*\b(?:short|teaser|trailer|highlight reel)\b/);
    if(!m) return undefined;
    if(!window.amiyoHighlights) throw new Error("AI Highlights is not ready.");
    var want=m[1]?+m[1]:30, len=want<=22?15:want<=45?30:60;
    if(busy) return "Still building the last short…";
    busy=true;
    (async function(){
      try{
        var h0=window.project.history.index, tr0=window.project.tracks.length;
        window.amiyoHighlights.open(); await sleep(300);
        var lb=document.querySelector('#hlSheet [data-len="'+len+'"]'); if(lb) lb.click();
        var go=document.getElementById("hlGo"); if(!go){ toast("Highlights could not open."); return; }
        go.click();
        var ok=false, out="";
        for(var i=0;i<240;i++){ await sleep(500); var mk=document.getElementById("hlMake"), o=document.getElementById("hlOut"); out=o?o.textContent:""; if(mk&&!mk.disabled&&document.querySelector("#hlList input,#hlList [data-i],#hlList button")){ ok=true; break; } if(/need at least|only \d+ s|no sound|could not|nothing/i.test(out)&&!/listening|working/i.test(out)){ break; } }
        if(!ok){ toast(out&&out.length<140?out:"No highlight found. The clip may be too short for a "+len+" s short."); return; }
        document.getElementById("hlMake").click(); await sleep(1200);
        var nt=window.project.tracks.slice(tr0), tot=0, n=0; nt.forEach(function(t){ t.clips.forEach(function(c){ tot+=c.duration; n++; }); }); var st=nt.length&&nt[0].clips.length?Math.min.apply(null,nt[0].clips.map(function(c){ return c.start; })):0;
        toast(window.project.history.index>h0?"Short built: "+Math.round(tot)+" s in "+n+" piece"+(n===1?"":"s")+", on a new track after your timeline (starts at "+Math.round(st)+" s). One undo removes it.":"Highlights found moments, but nothing was added: pick one in the Highlights sheet.");
      } catch(e){ toast("Short failed: "+((e&&e.message)||e)); } finally { busy=false; }
    })();
    return "Finding the best "+len+" s moment and building the short…";
  });
  try{ window.AMIYO_EDITOR_BUILD="ai20-s13-short"; }catch(e){}
})();

