/* ==================== Script 1204 id="amiyo-ai20-s14-beats" ==================== */
/* AI 20 · Step 14 — Beats by words. "find the beat" opens the beat finder for the music, "clear beat markers" removes them,
   "cut to the beat every 2 seconds" sets a fixed pace and opens Music Sync, "cut on the beat right away" cuts now. */
(function(){
  "use strict";
  var A=window.amiyoAI20=window.amiyoAI20||{};
  A.hook(function(raw,t){
    if(/\b(?:clear|remove|delete|reset)\b.*\bbeats?\b.*\b(?:markers?|marks?)?\b|\bclear beats\b/.test(t)){
      if(!window.amiyoBeats) throw new Error("The beat tool is not ready."); window.amiyoBeats.clear(); return "Asked the editor to clear the beat markers.";
    }
    if(/\b(?:find|detect|show|add|mark|analy[sz]e)\b.*\b(?:beats?|tempo|bpm|rhythm)\b/.test(t)&&!/\bcut\b/.test(t)){
      if(!window.amiyoBeats) throw new Error("The beat tool is not ready."); window.amiyoBeats.open(); return "Opened the beat finder: it listens to the selected clip and puts markers on the beats.";
    }
    var m=t.match(/\bcut\b.*\b(?:to|on) the (?:beat|music|rhythm)\b.*\bevery (\d+(?:\.\d+)?)\s*(?:s|sec|secs|seconds?)\b|\bevery (\d+(?:\.\d+)?)\s*(?:s|sec|secs|seconds?)\b.*\b(?:beat|music|cuts?)\b/);
    if(m){
      var sec=+(m[1]||m[2]); if(!window.amiyoMusicSync) throw new Error("Music Sync is not ready.");
      if(sec<.5||sec>6) throw new Error("Pick a pace between 0.5 and 6 seconds.");
      window.amiyoMusicSync.setTarget(sec); if(/right away|now|apply/.test(t)){ window.amiyoMusicSync.run("now"); return "Cutting on the beat about every "+sec+" s."; }
      window.amiyoMusicSync.open(); return "Pace set to about "+sec+" s between cuts. Opened Music Sync: tap Cut to apply.";
    }
    return undefined;
  });
  try{ window.AMIYO_EDITOR_BUILD="ai20-s14-beats"; }catch(e){}
})();

