/* ==================== Script 1206 id="amiyo-ai20-s02-clean-all" ==================== */
/* AI-20 Step 2: Clean all silences. Selects every clip that has sound, opens the existing Remove silences preview with Gentle / Balanced / Tight already set, and lets you check the saved time before anything is cut. */
(function(){
  "use strict";
  if(!window.amiyoSmart||window.amiyoSmart.cleanAll) return;
  var PRE={gentle:{min:.8,pad:.18,off:-3,label:"Gentle"},balanced:{min:.5,pad:.1,off:0,label:"Balanced"},tight:{min:.3,pad:.06,off:3,label:"Tight"}}, busy=false;
  function say(m){ try{ toast(m,3200); }catch(e){} }
  function wait(ms){ return new Promise(function(r){ setTimeout(r,ms); }); }
  function setVal(id,v){ var e=document.getElementById(id); if(!e) return; e.value=String(v); e.dispatchEvent(new Event("input",{bubbles:true})); }
  function eligible(){
    var out=[]; (project.tracks||[]).forEach(function(tr){
      if(tr.locked||(tr.kind!=="video"&&tr.kind!=="audio")) return;
      (tr.clips||[]).forEach(function(c){
        var a=c.assetId&&getAsset(c.assetId); if(!a||a.type==="image"||c.freeze||(c.speedKeyframes||[]).length>=2) return;
        out.push(c);
      });
    }); return out;
  }
  async function cleanAll(key){
    if(busy) return; var P=PRE[key]||PRE.balanced;
    if(!window.amiyoCut||!window.amiyoCut.silences){ say("The silence tool is not available in this build."); return; }
    var list=eligible(); if(!list.length){ say("No clips with sound to clean. Add a video or audio clip first."); return; }
    try{ if(isPlaying) pause(); }catch(e){}
    busy=true;
    try{
      (project.tracks||[]).forEach(function(tr){ (tr.clips||[]).forEach(function(c){ c.selected=false; }); });
      list.forEach(function(c){ c.selected=true; }); selectedClipId=list[0].id;
      try{ renderTracks(); }catch(e){}
      var sh=document.getElementById("smartSheet"); if(sh) sh.style.display="none";
      window.amiyoCut.silences();
      var t0=Date.now(), ok=false;
      while(Date.now()-t0<180000){
        await wait(250); var dlg=document.querySelector(".cs-dlg"); if(!dlg) return;
        var s=dlg.querySelector(".cs-status"); if(s&&/Drag the level|Could not read/.test(s.textContent)){ ok=!/Could not read/.test(s.textContent); break; }
      }
      if(!ok){ say("Could not read the sound of these clips."); return; }
      var thr=+document.getElementById("csThr").value;
      setVal("csThr",Math.max(-70,Math.min(-15,thr+P.off))); setVal("csMin",P.min); setVal("csPad",P.pad);
      say(list.length+" clip"+(list.length>1?"s":"")+" checked at "+P.label+". Look at the saved time, then tap Remove silences.");
      /* wait here until the person decides, so the busy flag stays honest */
      while(document.querySelector(".cs-dlg")&&Date.now()-t0<600000) await wait(400);
    } finally {
      busy=false; (project.tracks||[]).forEach(function(tr){ (tr.clips||[]).forEach(function(c){ c.selected=false; }); });
      try{ renderTracks(); }catch(e){}
    }
  }
  window.amiyoSmart.cleanAll=cleanAll; window.amiyoSmart.eligible=eligible; window.amiyoSmart.presets=PRE;
  /* add buttons to the Smart panel */
  function addRow(){
    var sh=document.getElementById("smartSheet"); if(!sh||sh.querySelector("#smartClean")) return;
    var d=document.createElement("div"); d.id="smartClean"; d.style.cssText="display:flex;gap:6px;flex-wrap:wrap;align-items:center;margin:8px 0";
    d.innerHTML='<span style="width:100%;font-weight:700">✂️ Clean all silences</span>'; 
    Object.keys(PRE).forEach(function(k){ var b=document.createElement("button"); b.type="button"; b.textContent=PRE[k].label; b.onclick=function(){ cleanAll(k); }; d.appendChild(b); });
    var l=sh.querySelector("#smartList"); l.parentNode.insertBefore(d,l);
  }
  var o=window.amiyoSmart.open; window.amiyoSmart.open=function(){ o(); addRow(); };
  var b=document.getElementById("smartBtn"); if(b) b.onclick=window.amiyoSmart.open;
})();

