/* ==================== Script 1207 id="amiyo-ai20-s03-best-moments" ==================== */
/* AI-20 Step 3: Best moments. Listens to the clip (selected, else the longest with sound), scores every second by loudness and how fast the sound changes, and lists the top moments. Tap Go to, or Add markers. It never cuts anything. */
(function(){
  "use strict";
  if(!window.amiyoSmart||window.amiyoSmart.bestMoments) return;
  var busy=false;
  function fmt(t){ return window.amiyoSmart._fmt(t); }
  function pick(){
    var best=null, sel=null;
    (project.tracks||[]).forEach(function(tr){ (tr.clips||[]).forEach(function(c){
      var a=c.assetId&&getAsset(c.assetId); if(!a||a.type==="image") return;
      if(c.id===selectedClipId||c.selected) sel=sel||c;
      if(!best||c.duration>best.duration) best=c;
    }); });
    return sel||best;
  }
  /* pure scoring: db[] = loudness per window, returns top moments [{t,len,score}] in source seconds */
  function score(db,win,len,n){
    var per=Math.max(1,Math.round(1/win)), secs=Math.floor(db.length/per), E=[], i, j;
    for(i=0;i<secs;i++){ var m=-120; for(j=0;j<per;j++) if(db[i*per+j]>m) m=db[i*per+j]; E.push(m); }
    var avg=E.reduce(function(a,b){ return a+b; },0)/Math.max(1,E.length), S=[];
    for(i=0;i<secs;i++){ var jump=i?Math.max(0,E[i]-E[i-1]):0; S.push((E[i]-avg)+jump*0.8); }
    var L=Math.max(1,Math.round(len)), W=[];
    for(i=0;i+L<=secs;i++){ var s=0; for(j=0;j<L;j++) s+=S[i+j]; W.push({t:i,len:L,score:s/L}); }
    W.sort(function(a,b){ return b.score-a.score; });
    var out=[]; W.forEach(function(w){ if(out.length>=n) return; if(out.every(function(o){ return Math.abs(o.t-w.t)>=L+1; })) out.push(w); });
    return out.sort(function(a,b){ return a.t-b.t; });
  }
  async function find(c,n,len){
    var a=getAsset(c.assetId); if(a.size&&a.size>500*1048576) throw new Error("This file is too large to analyze in the browser (over 500 MB).");
    var url=await ensureUrl(a); if(!url) throw new Error("Could not open the media file.");
    var buf=await (await fetch(url)).arrayBuffer();
    var AC=window.OfflineAudioContext||window.webkitOfflineAudioContext; if(!AC) throw new Error("This browser cannot read audio here.");
    var ab=await new Promise(function(res,rej){ var p=new AC(1,1,8000).decodeAudioData(buf,res,rej); if(p&&p.catch) p.catch(rej); });
    var d=ab.getChannelData(0), per=Math.round(ab.sampleRate*0.1), N=Math.floor(d.length/per), db=new Float32Array(N), i, j;
    for(i=0;i<N;i++){ var s=0; for(j=0;j<per;j++){ var v=d[i*per+j]; s+=v*v; } db[i]=20*Math.log10(Math.sqrt(s/per)+1e-7); }
    var inP=c.inPoint||0, sp=c.speed||1, from=Math.floor(inP/0.1), to=Math.min(N,Math.floor((inP+c.duration*sp)/0.1));
    var top=score(db.subarray(from,to),0.1,len,n);
    return top.map(function(m){ return {at:c.start+m.t/sp,len:m.len/sp,score:m.score}; });
  }
  async function run(){
    if(busy) return; var out=document.getElementById("smartMoments"); if(!out) return;
    var c=pick(); if(!c){ out.textContent="Add a video or audio clip first."; return; }
    busy=true; out.textContent="Listening…";
    try{
      var r=await find(c,5,4); out.innerHTML="";
      if(!r.length){ out.textContent="No clear best moments. The clip may be too short or too even."; return; }
      var head=document.createElement("div"); head.textContent="Top "+r.length+" moments (loud, lively parts):"; head.style.margin="4px 0"; out.appendChild(head);
      r.forEach(function(m,i){
        var row=document.createElement("div"); row.className="sr"; var s=document.createElement("span"); s.textContent=(i+1)+". "+fmt(m.at)+" for "+Math.round(m.len)+"s"; row.appendChild(s);
        var g=document.createElement("button"); g.type="button"; g.textContent="Go to"; g.onclick=function(){ try{ setCurrentTime(m.at); }catch(e){} }; row.appendChild(g); out.appendChild(row);
      });
      var mk=document.createElement("button"); mk.type="button"; mk.textContent="Add markers for all"; mk.style.marginTop="6px";
      mk.onclick=function(){ try{ transact("Best moment markers",function(){ r.forEach(function(m,i){ project.markers.push({id:mkid("marker"),time:m.at,label:"Best moment "+(i+1),color:"#ffd54f"}); }); }); mk.textContent="Markers added"; mk.disabled=true; try{ renderTracks(); }catch(e){} }catch(e){ mk.textContent="Could not add markers"; } };
      out.appendChild(mk);
    }catch(e){ out.textContent=(e&&e.message)||"Could not read this clip's sound."; }
    finally{ busy=false; }
  }
  window.amiyoSmart.bestMoments=run; window.amiyoSmart._score=score;
  function addRow(){
    var sh=document.getElementById("smartSheet"); if(!sh||sh.querySelector("#smartBest")) return;
    var d=document.createElement("div"); d.id="smartBest"; d.style.margin="8px 0";
    d.innerHTML='<button type="button" id="smartBestBtn">⭐ Find best moments</button><div id="smartMoments" aria-live="polite" style="margin-top:6px"></div>';
    var l=sh.querySelector("#smartList"); l.parentNode.insertBefore(d,l); d.querySelector("#smartBestBtn").onclick=run;
  }
  var o=window.amiyoSmart.open; window.amiyoSmart.open=function(){ o(); addRow(); };
  var b=document.getElementById("smartBtn"); if(b) b.onclick=window.amiyoSmart.open;
})();

