/* ==================== Script 1208 id="amiyo-ai20-s04-scenes" ==================== */
/* AI-20 Step 4: Scene finder. Looks at small snapshots of the selected video clip (else the longest video), finds where the picture changes a lot, and lists the cuts. Add markers (safe) or Split at scenes (second tap confirms; each cut can be undone). */
(function(){
  "use strict";
  if(!window.amiyoSmart||window.amiyoSmart.findScenes) return;
  var busy=false, last=null;
  function pick(){
    var best=null, sel=null;
    (project.tracks||[]).forEach(function(tr){ if(tr.kind!=="video") return; (tr.clips||[]).forEach(function(c){
      var a=c.assetId&&getAsset(c.assetId); if(!a||a.type!=="video") return;
      if(c.id===selectedClipId||c.selected) sel=sel||{c:c,tr:tr};
      if(!best||c.duration>best.c.duration) best={c:c,tr:tr};
    }); });
    return sel||best;
  }
  /* pure: diffs[i] = change between sample i-1 and i; returns indexes of cuts */
  function detect(diffs,minGap){
    var s=diffs.slice(1).sort(function(a,b){ return a-b; }), med=s.length?s[Math.floor(s.length/2)]:0, out=[], lastI=-1e9;
    for(var i=1;i<diffs.length;i++){
      var d=diffs[i]; if(d<22||d<med*3.5+8) continue;
      if(i>0&&i<diffs.length-1&&diffs[i+1]>d) continue;           /* keep only the peak */
      if(i-lastI<minGap) continue; out.push(i); lastI=i;
    } return out;
  }
  function seekV(v,t){ return new Promise(function(res){ var done=false, to=setTimeout(function(){ fin(false); },4000); function fin(ok){ if(done) return; done=true; clearTimeout(to); v.removeEventListener("seeked",f); res(ok); } function f(){ fin(true); } v.addEventListener("seeked",f); try{ v.currentTime=t; }catch(e){ fin(false); } }); }
  async function scan(it,prog){
    var c=it.c, a=getAsset(c.assetId), url=await ensureUrl(a); if(!url) throw new Error("Could not open the media file.");
    var v=document.createElement("video"); v.muted=true; v.preload="auto"; v.playsInline=true; v.src=url;
    await new Promise(function(res,rej){ var to=setTimeout(function(){ rej(new Error("The video took too long to open.")); },10000); v.onloadeddata=function(){ clearTimeout(to); res(); }; v.onerror=function(){ clearTimeout(to); rej(new Error("This video could not be read.")); }; v.load(); });
    var sp=c.speed||1, inP=c.inPoint||0, span=c.duration*sp, step=Math.max(0.5,span/300), n=Math.max(2,Math.floor(span/step)), W=32, H=18;
    var cv=document.createElement("canvas"); cv.width=W; cv.height=H; var g=cv.getContext("2d",{willReadFrequently:true}), prev=null, diffs=[0], times=[inP];
    try{
      for(var i=0;i<n;i++){
        var t=inP+i*step; if(!await seekV(v,t)) continue;
        g.drawImage(v,0,0,W,H); var px=g.getImageData(0,0,W,H).data, L=new Float32Array(W*H*3);
        for(var k=0;k<W*H;k++){ L[k*3]=px[k*4]; L[k*3+1]=px[k*4+1]; L[k*3+2]=px[k*4+2]; } /* colour, not just brightness */
        if(prev){ var s=0; for(k=0;k<L.length;k++) s+=Math.abs(L[k]-prev[k]); diffs.push(s/L.length); times.push(t); }
        prev=L; if(i%10===0) prog(Math.round(i/n*100));
      }
    } finally { try{ v.removeAttribute("src"); v.load(); }catch(e){} }
    var cuts=detect(diffs,2).map(function(i){ return it.c.start+(times[i]-inP)/sp; });
    return cuts.filter(function(t){ return t>c.start+0.2&&t<c.start+c.duration-0.2; });
  }
  function clipAt(trId,t){ var tr=(project.tracks||[]).find(function(x){ return x.id===trId; }); return tr&&(tr.clips||[]).find(function(c){ return t>c.start+0.05&&t<c.start+c.duration-0.05; }); }
  async function run(){
    if(busy) return; var out=document.getElementById("smartScenes"); if(!out) return;
    var it=pick(); if(!it){ out.textContent="Add a video clip first."; return; }
    if(it.c.freeze||(it.c.speedKeyframes||[]).length>=2){ out.textContent="Scenes need a clip without speed ramps."; return; }
    busy=true; last=null; out.textContent="Looking at the picture… 0%";
    try{
      var cuts=await scan(it,function(p){ out.textContent="Looking at the picture… "+p+"%"; });
      out.innerHTML=""; last={it:it,cuts:cuts};
      if(!cuts.length){ out.textContent="No scene changes found. The picture is steady all the way."; return; }
      var h=document.createElement("div"); h.textContent=cuts.length+" scene change"+(cuts.length>1?"s":"")+" found:"; out.appendChild(h);
      cuts.slice(0,30).forEach(function(t,i){ var row=document.createElement("div"); row.className="sr"; var s=document.createElement("span"); s.textContent=(i+1)+". at "+window.amiyoSmart._fmt(t); row.appendChild(s); var b=document.createElement("button"); b.type="button"; b.textContent="Go to"; b.onclick=function(){ try{ setCurrentTime(t); }catch(e){} }; row.appendChild(b); out.appendChild(row); });
      var mk=document.createElement("button"); mk.type="button"; mk.textContent="Add markers"; mk.onclick=function(){ try{ transact("Scene markers",function(){ cuts.forEach(function(t,i){ project.markers.push({id:mkid("marker"),time:t,label:"Scene "+(i+2),color:"#69f0ae"}); }); }); mk.textContent="Markers added"; mk.disabled=true; try{ renderTracks(); }catch(e){} }catch(e){ mk.textContent="Could not add markers"; } };
      var sp=document.createElement("button"); sp.type="button"; sp.textContent="Split at scenes"; var armed=false; sp.style.marginLeft="8px";
      sp.onclick=function(){
        if(!armed){ armed=true; sp.textContent="Tap again to cut "+cuts.length+" times"; setTimeout(function(){ armed=false; sp.textContent="Split at scenes"; },4000); return; }
        armed=false; var n=0; cuts.forEach(function(t){ try{ var c=clipAt(it.tr.id,t); if(c){ splitClipAt(it.tr.id,c.id,t); n++; } }catch(e){} });
        sp.textContent=n+" cut"+(n===1?"":"s")+" made. Undo steps back one at a time."; sp.disabled=true;
      };
      var r=document.createElement("div"); r.style.marginTop="6px"; r.appendChild(mk); r.appendChild(sp); out.appendChild(r);
    }catch(e){ out.textContent=(e&&e.message)||"Could not scan this clip."; }
    finally{ busy=false; }
  }
  window.amiyoSmart.findScenes=run; window.amiyoSmart._detect=detect;
  function addRow(){
    var sh=document.getElementById("smartSheet"); if(!sh||sh.querySelector("#smartScn")) return;
    var d=document.createElement("div"); d.id="smartScn"; d.style.margin="8px 0";
    d.innerHTML='<button type="button" id="smartScnBtn">🎬 Find scenes</button><div id="smartScenes" aria-live="polite" style="margin-top:6px"></div>';
    var l=sh.querySelector("#smartList"); l.parentNode.insertBefore(d,l); d.querySelector("#smartScnBtn").onclick=run;
  }
  var o=window.amiyoSmart.open; window.amiyoSmart.open=function(){ o(); addRow(); };
  var b=document.getElementById("smartBtn"); if(b) b.onclick=window.amiyoSmart.open;
})();

;
/* ==================== Script 1209 id="amiyo-ai20-s05-follow-reframe" ==================== */
/* AI-20 Step 5: Follow-the-subject reframe. Sets the project to 9:16 or 1:1, then writes pan keyframes on the selected video clip so the frame follows the busiest, most-moving part of the picture. Smoothed so it does not shake. Refuses if the clip already has keyframes. */
(function(){
  "use strict";
  if(!window.amiyoSmart||window.amiyoSmart.followReframe) return;
  var busy=false;
  function pick(){
    var best=null, sel=null;
    (project.tracks||[]).forEach(function(tr){ if(tr.kind!=="video"||tr.locked) return; (tr.clips||[]).forEach(function(c){
      var a=c.assetId&&getAsset(c.assetId); if(!a||a.type!=="video"||c.kind==="adjustment") return;
      if(c.id===selectedClipId||c.selected) sel=sel||{c:c,tr:tr};
      if(!best||c.duration>best.c.duration) best={c:c,tr:tr};
    }); });
    return sel||best;
  }
  /* pure: where is the action? L,P = luma now / before (P may be null). returns {x,y} in 0..1 */
  function focus(L,P,w,h){
    var mean=0,i; for(i=0;i<L.length;i++) mean+=L[i]; mean/=L.length;
    var ws=0,wx=0,wy=0;
    for(var y=0;y<h;y++) for(var x=0;x<w;x++){ i=y*w+x; var wt=Math.abs(L[i]-mean)+(P?2*Math.abs(L[i]-P[i]):0); ws+=wt; wx+=wt*x; wy+=wt*y; }
    return ws>0.001?{x:(wx/ws+0.5)/w,y:(wy/ws+0.5)/h}:{x:0.5,y:0.5};
  }
  /* pure: smooth a path, ignore tiny moves so the picture does not jitter */
  function smooth(v,a,dead){ var o=[],p=v[0]; v.forEach(function(x,i){ if(i===0){ o.push(x); return; } if(Math.abs(x-p)<dead) x=p; p=p+(x-p)*a; o.push(p); }); return o; }
  function seekV(v,t){ return new Promise(function(res){ var done=false, to=setTimeout(function(){ fin(false); },4000); function fin(ok){ if(done) return; done=true; clearTimeout(to); v.removeEventListener("seeked",f); res(ok); } function f(){ fin(true); } v.addEventListener("seeked",f); try{ v.currentTime=t; }catch(e){ fin(false); } }); }
  async function trace(c,prog){
    var a=getAsset(c.assetId), url=await ensureUrl(a); if(!url) throw new Error("Could not open the media file.");
    var v=document.createElement("video"); v.muted=true; v.preload="auto"; v.playsInline=true; v.src=url;
    await new Promise(function(res,rej){ var to=setTimeout(function(){ rej(new Error("The video took too long to open.")); },10000); v.onloadeddata=function(){ clearTimeout(to); res(); }; v.onerror=function(){ clearTimeout(to); rej(new Error("This video could not be read.")); }; v.load(); });
    var iw=v.videoWidth, ih=v.videoHeight; if(!iw||!ih) throw new Error("Video not ready to analyze.");
    var sp=c.speed||1, inP=c.inPoint||0, span=c.duration*sp, step=Math.max(1,span/40), n=Math.max(2,Math.floor(span/step)+1), W=48, H=Math.max(8,Math.round(48*ih/iw));
    var cv=document.createElement("canvas"); cv.width=W; cv.height=H; var g=cv.getContext("2d",{willReadFrequently:true}), P=null, pts=[];
    try{
      for(var i=0;i<n;i++){
        var t=Math.min(inP+i*step,inP+span-0.05); if(!await seekV(v,t)) continue;
        g.drawImage(v,0,0,W,H); var px=g.getImageData(0,0,W,H).data, L=new Float32Array(W*H);
        for(var k=0;k<W*H;k++) L[k]=0.299*px[k*4]+0.587*px[k*4+1]+0.114*px[k*4+2];
        var f=focus(L,P,W,H); pts.push({t:(t-inP)/sp,x:f.x,y:f.y}); P=L; prog(Math.round(i/n*100));
      }
    } finally { try{ v.removeAttribute("src"); v.load(); }catch(e){} }
    if(pts.length<2) throw new Error("Could not read enough of the picture.");
    return {pts:pts,iw:iw,ih:ih};
  }
  async function run(ratio){
    if(busy) return; var out=document.getElementById("smartReframeOut"); if(!out) return;
    var it=pick(); if(!it){ out.textContent="Add a video clip first."; return; }
    var c=it.c; if((c.keyframes||[]).length){ out.textContent="This clip already has keyframes. Delete them first so they are not mixed up."; return; }
    if(c.freeze||(c.speedKeyframes||[]).length>=2){ out.textContent="Needs a clip without speed ramps."; return; }
    busy=true; out.textContent="Following the action… 0%";
    try{
      var r=await trace(c,function(p){ out.textContent="Following the action… "+p+"%"; });
      if(typeof setSequenceAspect==="function") setSequenceAspect(ratio);
      var Wd=project.settings.width||1280, Hd=project.settings.height||720, ks=c.scale||1, dh=Hd*ks, dw=dh*(r.iw/r.ih);
      var xs=smooth(r.pts.map(function(p){ return p.x; }),0.5,0.02), ys=smooth(r.pts.map(function(p){ return p.y; }),0.5,0.02);
      var cl=function(v){ return Math.max(0,Math.min(1,v)); };
      transact("Follow-subject reframe",function(){
        c.fit="cover";
        c.keyframes=r.pts.map(function(p,i){ return {t:p.t,x:cl(0.5+(0.5-xs[i])*(dw/Wd)),y:cl(0.5+(0.5-ys[i])*(dh/Hd)),scale:c.scale||1,opacity:c.opacity==null?1:c.opacity,easing:"linear"}; });
      });
      out.textContent="Done: "+r.pts.length+" keyframes now follow the action at "+ratio+". Press play to check; undo puts it back.";
    }catch(e){ out.textContent=(e&&e.message)||"Could not reframe this clip."; }
    finally{ busy=false; }
  }
  window.amiyoSmart.followReframe=run; window.amiyoSmart._focus=focus; window.amiyoSmart._smooth=smooth;
  function addRow(){
    var sh=document.getElementById("smartSheet"); if(!sh||sh.querySelector("#smartRf")) return;
    var d=document.createElement("div"); d.id="smartRf"; d.style.margin="8px 0";
    d.innerHTML='<div style="font-weight:700;margin-bottom:4px">📱 Reframe and follow the action</div><button type="button" data-r="9:16">9:16</button> <button type="button" data-r="1:1">1:1</button> <button type="button" data-r="4:5">4:5</button><div id="smartReframeOut" aria-live="polite" style="margin-top:6px"></div>';
    var l=sh.querySelector("#smartList"); l.parentNode.insertBefore(d,l);
    d.querySelectorAll("button").forEach(function(b){ b.onclick=function(){ run(b.dataset.r); }; });
  }
  var o=window.amiyoSmart.open; window.amiyoSmart.open=function(){ o(); addRow(); };
  var b=document.getElementById("smartBtn"); if(b) b.onclick=window.amiyoSmart.open;
})();

