/* ==================== Script 1210 id="amiyo-ai20-s06-pacing" ==================== */
/* AI-20 Step 6: Pacing and beat check. Reads the first video track's cuts: shot lengths, shots that run long, and (if beat markers exist from the Beat detection tool) how many cuts land on a beat and how far off the others are. Reads only; changes nothing. */
(function(){
  "use strict";
  if(!window.amiyoSmart||window.amiyoSmart.pacing) return;
  function r1(n){ return Math.round(n*10)/10; }
  /* pure: clips=[{start,duration,name}] sorted; beats=[seconds] */
  function analyse(clips,beats){
    var n=clips.length; if(!n) return null;
    var lens=clips.map(function(c){ return c.duration; }), s=lens.slice().sort(function(a,b){ return a-b; });
    var med=s[Math.floor(n/2)], avg=lens.reduce(function(a,b){ return a+b; },0)/n;
    var longCut=Math.max(8,med*2.5), flags=[];
    clips.forEach(function(c){
      if(n>1&&c.duration>longCut) flags.push({at:c.start,msg:"“"+c.name+"” runs "+r1(c.duration)+"s. Consider a cut or cutaway."});
      else if(c.duration<0.5) flags.push({at:c.start,msg:"“"+c.name+"” is only "+r1(c.duration)+"s. It may flash by."});
    });
    var cuts=clips.slice(1).filter(function(c,i){ return Math.abs(c.start-(clips[i].start+clips[i].duration))<0.15; }).map(function(c){ return c.start; });
    var beat=null;
    if(beats&&beats.length&&cuts.length){
      var on=0, off=[];
      cuts.forEach(function(t){
        var best=null; beats.forEach(function(b){ if(best===null||Math.abs(b-t)<Math.abs(best-t)) best=b; });
        var d=t-best; if(Math.abs(d)<=0.08) on++; else off.push({at:t,off:d});
      });
      beat={on:on,total:cuts.length,off:off};
    }
    return {count:n,avg:avg,med:med,longest:Math.max.apply(null,lens),flags:flags,cuts:cuts.length,beat:beat};
  }
  function collect(){
    var tr=(project.tracks||[]).find(function(t){ return t.kind==="video"&&(t.clips||[]).some(function(c){ return c.kind!=="adjustment"; }); });
    if(!tr) return null;
    var nm=function(c){ try{ var a=c.assetId&&getAsset(c.assetId); return (a&&a.name)||c.name||c.text||"Clip"; }catch(e){ return "Clip"; } };
    var clips=(tr.clips||[]).filter(function(c){ return c.kind!=="adjustment"; }).slice().sort(function(a,b){ return a.start-b.start; }).map(function(c){ return {start:c.start,duration:c.duration,name:nm(c)}; });
    var beats=(project.markers||[]).filter(function(m){ return m.beat&&isFinite(m.time); }).map(function(m){ return m.time; });
    return {clips:clips,beats:beats};
  }
  function run(){
    var out=document.getElementById("smartPaceOut"); if(!out) return; out.innerHTML="";
    var d=collect(); if(!d){ out.textContent="Add video clips to the timeline first."; return; }
    var a=analyse(d.clips,d.beats); var fmt=window.amiyoSmart._fmt;
    var add=function(t){ var p=document.createElement("div"); p.textContent=t; p.style.margin="2px 0"; out.appendChild(p); };
    var row=function(msg,at){ var r=document.createElement("div"); r.className="sr"; var s=document.createElement("span"); s.textContent=msg; r.appendChild(s); var b=document.createElement("button"); b.type="button"; b.textContent="Go to "+fmt(at); b.onclick=function(){ try{ setCurrentTime(at); }catch(e){} }; r.appendChild(b); out.appendChild(r); };
    add(a.count+" shot"+(a.count>1?"s":"")+", average "+r1(a.avg)+"s, middle "+r1(a.med)+"s, longest "+r1(a.longest)+"s.");
    if(a.avg>6) add("Pace is slow. Shots of 2 to 4 seconds feel faster for short videos."); else if(a.avg<1.2&&a.count>4) add("Pace is very fast. Let key shots breathe a little longer.");
    a.flags.slice(0,10).forEach(function(f){ row(f.msg,f.at); });
    if(a.beat){
      add(a.beat.on+" of "+a.beat.total+" cuts land on a beat.");
      a.beat.off.slice(0,10).forEach(function(o){ row("Cut is "+r1(Math.abs(o.off))+"s "+(o.off>0?"late":"early")+" for the beat.",o.at); });
      if(a.beat.off.length>10) add("…and "+(a.beat.off.length-10)+" more off-beat cuts.");
    } else add("For beat matching, first add beat markers with the Beat detection tool, then check again.");
    if(!a.flags.length&&(!a.beat||!a.beat.off.length)) add("Nothing stands out. Pacing looks even.");
  }
  window.amiyoSmart.pacing=run; window.amiyoSmart._analyse=analyse;
  function addRow(){
    var sh=document.getElementById("smartSheet"); if(!sh||sh.querySelector("#smartPace")) return;
    var d=document.createElement("div"); d.id="smartPace"; d.style.margin="8px 0";
    d.innerHTML='<button type="button" id="smartPaceBtn">⏱️ Check pacing and beats</button><div id="smartPaceOut" aria-live="polite" style="margin-top:6px"></div>';
    var l=sh.querySelector("#smartList"); l.parentNode.insertBefore(d,l); d.querySelector("#smartPaceBtn").onclick=run;
  }
  var o=window.amiyoSmart.open; window.amiyoSmart.open=function(){ o(); addRow(); };
  var b=document.getElementById("smartBtn"); if(b) b.onclick=window.amiyoSmart.open;
})();

