/* ==================== Script 1211 id="amiyo-ai20-s07-narration-audio" ==================== */
/* AI-20 Step 7: Narration to real audio. Typed narration lines are preview-only. This sends each line to the same text-to-speech service the AI dubbing tool uses, imports the audio, and places each clip at its line's start on a new audio track so it is in the export. One undo step. Needs the voice service address saved in AI dubbing > Real voiceover settings. */
(function(){
  "use strict";
  if(!window.amiyoSmart||window.amiyoSmart.narrationToAudio) return;
  var busy=false, ac=null, KEY="amiyo.dub.tts.v1";
  function cfg(){ try{ return Object.assign({url:"",key:"",model:"tts-1",voice:"alloy"},JSON.parse(localStorage.getItem(KEY)||"{}")); }catch(e){ return {url:"",key:"",model:"tts-1",voice:"alloy"}; } }
  async function tts(text,c,signal){
    var r=await fetch(c.url,{method:"POST",headers:Object.assign({"Content-Type":"application/json"},c.key?{Authorization:"Bearer "+c.key}:{}),body:JSON.stringify({model:c.model,input:text,voice:c.voice,response_format:"mp3"}),signal:signal});
    if(!r.ok) throw new Error("the voice service answered "+r.status);
    var b=await r.blob(); if(b.size<800||(b.type&&b.type.indexOf("audio")!==0&&b.type.indexOf("octet")<0)) throw new Error("the voice service did not return audio");
    return b;
  }
  function ext(b){ var t=b.type||""; return t.indexOf("wav")>=0?"wav":t.indexOf("ogg")>=0?"ogg":t.indexOf("webm")>=0?"webm":"mp3"; }
  async function run(){
    var out=document.getElementById("smartNarrOut"), btn=document.getElementById("smartNarrBtn"); if(!out) return;
    if(busy){ if(ac) ac.abort(); return; }
    var lines=(project.narrations||[]).filter(function(n){ return n&&String(n.text||"").trim(); }).slice().sort(function(a,b){ return a.start-b.start; });
    if(!lines.length){ out.textContent="There are no typed narration lines. Add some in the Audio tab > Narration first."; return; }
    if(lines.length>30){ out.textContent="That is "+lines.length+" lines. Please keep it to 30 at a time."; return; }
    var c=cfg(); if(!c.url){ out.textContent="Save your text-to-speech address first: AI dubbing > Real voiceover settings. Then come back here."; return; }
    try{ if(isPlaying) pause(); }catch(e){}
    busy=true; ac=new AbortController(); if(btn) btn.textContent="Cancel"; var made=[], tag=Date.now().toString(36);
    try{
      for(var i=0;i<lines.length;i++){
        out.textContent="Making voice "+(i+1)+" of "+lines.length+"…";
        var blob=await tts(String(lines[i].text).trim(),c,ac.signal), name="narr_"+tag+"_"+(i+1)+"."+ext(blob);
        await window.importFiles([new File([blob],name,{type:blob.type||"audio/mpeg"})]);
        var a=null; Object.keys(project.assets).forEach(function(k){ if(project.assets[k].name===name) a=project.assets[k]; });
        if(!a) throw new Error("a voice file could not be added to the media library");
        a.tags=(a.tags||[]).concat(["voice-over","narration"]); made.push(a);
      }
      transact("Narration to real audio",function(){
        var tr={id:mkid("track"),kind:"audio",name:"Narration (real voice)",clips:[],muted:false,hidden:false};
        made.forEach(function(a,i){ var d=a.duration>0?a.duration:3, cl=makeClipFor(a,lines[i].start,d); cl.name="Narration "+(i+1); tr.clips.push(cl); });
        project.tracks.push(tr); project.narrationMuted=true;
      });
      try{ renderAll(); }catch(e){}
      out.textContent="Done: "+made.length+" real voice clip"+(made.length>1?"s":"")+" added on a new audio track. The typed preview voice is now muted so you do not hear it twice. Undo reverses it.";
    }catch(e){ out.textContent=(e&&e.name==="AbortError")?"Cancelled. Nothing was added to the timeline.":"Could not finish: "+((e&&e.message)||"error")+". Nothing was added to the timeline."; }
    finally{ busy=false; ac=null; if(btn) btn.textContent="🗣️ Make narration real audio"; }
  }
  window.amiyoSmart.narrationToAudio=run; window.amiyoSmart._tts=tts;
  function addRow(){
    var sh=document.getElementById("smartSheet"); if(!sh||sh.querySelector("#smartNarr")) return;
    var d=document.createElement("div"); d.id="smartNarr"; d.style.margin="8px 0";
    d.innerHTML='<button type="button" id="smartNarrBtn">🗣️ Make narration real audio</button><div id="smartNarrOut" aria-live="polite" style="margin-top:6px">Turns your typed narration lines into a real voice that is included in the export.</div>';
    var l=sh.querySelector("#smartList"); l.parentNode.insertBefore(d,l); d.querySelector("#smartNarrBtn").onclick=run;
  }
  var o=window.amiyoSmart.open; window.amiyoSmart.open=function(){ o(); addRow(); };
  var b=document.getElementById("smartBtn"); if(b) b.onclick=window.amiyoSmart.open;
})();

