/* ==================== Script 1212 id="amiyo-ai20-s08-duck-speech" ==================== */
/* AI-20 Step 8: Duck music under real speech. The old Auto-Duck needs clips tagged Dialogue. This one listens to every other clip, finds where someone is actually talking, and writes volume points on the selected music clip so it dips under the voice and comes back after. One undo. Refuses if the music clip already has volume points. */
(function(){
  "use strict";
  if(!window.amiyoSmart||window.amiyoSmart.duckUnderSpeech) return;
  var busy=false;
  /* pure: db per window -> speech spans [a,b] in seconds. floor adapts to the clip. */
  function spans(db,win){
    if(!db.length) return [];
    var s=Array.prototype.slice.call(db).sort(function(a,b){ return a-b; }), noise=s[Math.floor(s.length*0.2)], thr=Math.max(-48,noise+12), out=[], a=-1, i;
    for(i=0;i<db.length;i++){ if(db[i]>thr){ if(a<0) a=i; } else if(a>=0){ out.push([a*win,i*win]); a=-1; } }
    if(a>=0) out.push([a*win,db.length*win]);
    var m=[]; out.forEach(function(x){ var l=m[m.length-1]; if(l&&x[0]-l[1]<0.45) l[1]=x[1]; else m.push([x[0],x[1]]); });
    return m.filter(function(x){ return x[1]-x[0]>=0.3; });
  }
  /* pure: write points. spansTl = [[start,end]] on the timeline */
  function points(c,spansTl,base,ducked,pad){
    var pts=[{t:0,v:base},{t:c.duration,v:base}], cl=function(x){ return Math.max(0,Math.min(c.duration,x)); };
    spansTl.forEach(function(sp){ var ls=sp[0]-c.start, le=sp[1]-c.start; if(le<0||ls>c.duration) return;
      pts.push({t:cl(ls-pad),v:base},{t:cl(ls),v:ducked},{t:cl(le),v:ducked},{t:cl(le+pad),v:base}); });
    pts.sort(function(a,b){ return a.t-b.t; });
    var m=[]; pts.forEach(function(p){ var l=m[m.length-1]; if(l&&Math.abs(l.t-p.t)<0.01) l.v=Math.min(l.v,p.v); else m.push(p); });
    return m;
  }
  async function speechOf(c){
    var a=getAsset(c.assetId); if(!a||a.type==="image") return [];
    if(a.size&&a.size>300*1048576) throw new Error("A file is too large to analyze here (over 300 MB).");
    var url=await ensureUrl(a); if(!url) throw new Error("Could not open a media file.");
    var buf=await (await fetch(url)).arrayBuffer(), AC=window.OfflineAudioContext||window.webkitOfflineAudioContext; if(!AC) throw new Error("This browser cannot read audio here.");
    var ab; try{ ab=await new Promise(function(res,rej){ var p=new AC(1,1,8000).decodeAudioData(buf,res,rej); if(p&&p.catch) p.catch(rej); }); }catch(e){ return []; }
    var d=ab.getChannelData(0), per=Math.round(ab.sampleRate*0.05), N=Math.floor(d.length/per), db=new Float32Array(N), i, j;
    for(i=0;i<N;i++){ var s=0; for(j=0;j<per;j++){ var v=d[i*per+j]; s+=v*v; } db[i]=20*Math.log10(Math.sqrt(s/per)+1e-7); }
    var sp=c.speed||1, inP=c.inPoint||0, out=[];
    spans(db,0.05).forEach(function(x){ var a1=Math.max(x[0],inP), b1=Math.min(x[1],inP+c.duration*sp); if(b1>a1) out.push([c.start+(a1-inP)/sp,c.start+(b1-inP)/sp]); });
    return out;
  }
  async function run(){
    var out=document.getElementById("smartDuckOut"); if(!out||busy) return;
    var music=null, sel=null; (project.tracks||[]).forEach(function(t){ if(t.kind!=="audio") return; (t.clips||[]).forEach(function(c){ if(!c.assetId) return; if(c.id===selectedClipId||c.selected) sel=sel||{c:c,t:t}; }); });
    music=sel; if(!music){ out.textContent="Select the music clip on an audio track first."; return; }
    var mc=music.c; if((mc.volumeKeyframes||[]).length>2){ out.textContent="This music clip already has volume points. Clear them first so they are not mixed up."; return; }
    busy=true; out.textContent="Listening for speech…";
    try{
      var all=[], n=0;
      for(var ti=0;ti<project.tracks.length;ti++){ var t=project.tracks[ti]; if(t===music.t||t.muted||t.hidden||(t.kind!=="audio"&&t.kind!=="video")) continue;
        for(var ci=0;ci<(t.clips||[]).length;ci++){ var c=t.clips[ci]; if(c===mc||!c.assetId||c.off||/music|ambience/.test(c.soundCategory||"")||c.volume===0) continue;
          if(c.start>=mc.start+mc.duration||c.start+c.duration<=mc.start) continue;
          out.textContent="Listening for speech… "+(++n); var s=await speechOf(c); all=all.concat(s); } }
      if(!all.length){ out.textContent="No speech found over this music clip."; return; }
      var base=Math.max(0,Math.min(1,mc.volume==null?1:mc.volume)), pts=points(mc,all,base,base*0.28,0.35);
      transact("Duck music under speech",function(){ mc.volumeKeyframes=pts; });
      try{ renderAll(); }catch(e){}
      out.textContent="Done: the music dips under "+all.length+" stretch"+(all.length>1?"es":"")+" of speech and comes back after. Undo reverses it.";
    }catch(e){ out.textContent="Could not finish: "+((e&&e.message)||"error"); }
    finally{ busy=false; }
  }
  window.amiyoSmart.duckUnderSpeech=run; window.amiyoSmart._spans=spans; window.amiyoSmart._points=points;
  function addRow(){
    var sh=document.getElementById("smartSheet"); if(!sh||sh.querySelector("#smartDuck")) return;
    var d=document.createElement("div"); d.id="smartDuck"; d.style.margin="8px 0";
    d.innerHTML='<button type="button" id="smartDuckBtn">🎚️ Duck selected music under speech</button><div id="smartDuckOut" aria-live="polite" style="margin-top:6px"></div>';
    var l=sh.querySelector("#smartList"); l.parentNode.insertBefore(d,l); d.querySelector("#smartDuckBtn").onclick=run;
  }
  var o=window.amiyoSmart.open; window.amiyoSmart.open=function(){ o(); addRow(); };
  var b=document.getElementById("smartBtn"); if(b) b.onclick=window.amiyoSmart.open;
})();

