    if(!String(q||"").trim()){ box.textContent="Type a word or a phrase. Put it in quotes to find the exact phrase."; return; }
    if(!res.length){ var idx=load(), n=Object.keys(idx).length; box.textContent="Nothing found for “"+q+"”."+(n?"":" No clip has been listened to yet. Tap Listen to clips first, or make captions."); return; }
    var h=document.createElement("div"); h.textContent=res.length+" place"+(res.length>1?"s":"")+" found:"; box.appendChild(h);
