    o.innerHTML='<input id="smartSpQ" type="search" placeholder="Search what is said" aria-label="Search what is said" style="width:100%;box-sizing:border-box;min-height:40px;border-radius:10px;border:1px solid #3a4852;background:#0f1418;color:#eee;padding:0 10px;font:14px system-ui"><div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:6px"><button type="button" id="smartSpGo">Search</button><button type="button" id="smartSpListen">🎧 Listen to clips</button><button type="button" id="smartSpClear">Forget index</button></div><label style="display:block;margin-top:6px;font-size:12px;color:#f3996c">Spoken language <select id="smartSpLang" aria-label="Spoken language" style="min-height:36px;margin-left:6px;border-radius:8px;border:1px solid #3a4852;background:#0f1418;color:#eee;padding:0 6px;font:13px system-ui"></select> <span style="opacity:.8">(not English uses a bigger model, about 75 MB once)</span></label><div id="smartSpStat" aria-live="polite" style="margin-top:6px;font-size:12px;color:#f3996c"></div><div id="smartSpRes" aria-live="polite" style="margin-top:6px"></div>';
    var q=$("smartSpQ"), res=$("smartSpRes"), stat=$("smartSpStat");
    function status(extra){ var n=Object.keys(load()).length; stat.textContent=(extra?extra+" ":"")+(n?("Speech index: "+n+" clip"+(n>1?"s":"")+" remembered on this device."):"Speech index is empty. Captions are searched already."); }
    status();
