/* ==================== Script 1216 id="amiyo-ai20-s12-cleanup" ==================== */
/* AI-20 Step 12: Clean-up of unused media and duplicate clips. One review that finds (1) media files that no clip uses, (2) the same file imported twice (same type, size and length), and (3) clips stacked exactly on top of each other on one track (a double paste). Each group has its own button and asks before it changes anything. Every change is one undo step. Media that is used on the timeline is never removed. */
(function(){
  "use strict";
  var A=window.amiyoSmart; if(!A||A.cleanup||!A._sec) return;
  function $(i){ return document.getElementById(i); }
  function mb(n){ return n>=1048576?(n/1048576).toFixed(1)+" MB":Math.max(1,Math.round((n||0)/1024))+" KB"; }
  function nm(a){ return (a&&a.name)||"Media"; }
  /* pure: P={assets:{id:asset}, tracks:[{kind,clips:[]}]} */
  function analyse(P){
    var A_=P.assets||{}, used={}, count={}, out={unused:[],dupGroups:[],stacked:[],bytes:0,dupBytes:0};
    (P.tracks||[]).forEach(function(t){ (t.clips||[]).forEach(function(c){ if(c.assetId){ used[c.assetId]=1; count[c.assetId]=(count[c.assetId]||0)+1; } }); });
    Object.keys(A_).forEach(function(id){ if(!used[id]){ out.unused.push(id); out.bytes+=A_[id].size||0; } });
    var g={}; Object.keys(A_).forEach(function(id){
      var a=A_[id]; if(!a) return; var key=a.type+"|"+((a.size>0)?a.size:("n:"+nm(a)))+"|"+(Math.round((a.duration||0)*10)/10); (g[key]=g[key]||[]).push(id);
    });
    Object.keys(g).forEach(function(k){ if(g[k].length>1){
      var ids=g[k].slice().sort(function(x,y){ return (count[y]||0)-(count[x]||0); }); out.dupGroups.push(ids);
      ids.slice(1).forEach(function(id){ out.dupBytes+=A_[id].size||0; });
    } });
    (P.tracks||[]).forEach(function(t,ti){
      var seen=[]; (t.clips||[]).slice().sort(function(a,b){ return a.start-b.start; }).forEach(function(c){
        if(!c.assetId) return;
        var dup=seen.some(function(s){ return s.assetId===c.assetId&&Math.abs(s.start-c.start)<0.02&&Math.abs(s.duration-c.duration)<0.02&&Math.abs((s.inPoint||0)-(c.inPoint||0))<0.02; });
        if(dup) out.stacked.push({track:t,clip:c,ti:ti}); else seen.push(c);
      });
    });
    return out;
  }
  function confirm(msg,okLabel){
    if(window.amiyoOk) return Promise.resolve(window.amiyoOk(msg,{okLabel:okLabel,danger:true}));
    return Promise.resolve(window.confirm(msg));
  }
  function refresh(){ try{ if(typeof renderAll==="function") renderAll(); }catch(e){} try{ if(typeof scheduleAutosave==="function") scheduleAutosave(); }catch(e){} }
  var R=null;
  function show(msg){ var o=$("smartTidyOut"); if(o){ var d=document.createElement("div"); d.style.marginTop="6px"; d.textContent=msg; o.appendChild(d); } }
  async function doUnused(btn){
    var r=analyse({assets:project.assets,tracks:project.tracks}); if(!r.unused.length){ btn.textContent="Nothing to remove"; return; }
    if(!(await confirm("Remove "+r.unused.length+" unused file"+(r.unused.length>1?"s":"")+" ("+mb(r.bytes)+") from this project? Media used on the timeline is kept. You can undo this.","Remove"))) return;
    transact("Remove unused media",function(){ r.unused.forEach(function(id){ delete project.assets[id]; }); });
    refresh(); paint(r.unused.length+" unused file"+(r.unused.length>1?"s":"")+" removed. Undo brings them back.");
  }
  async function doMerge(btn){
    var r=analyse({assets:project.assets,tracks:project.tracks}); if(!r.dupGroups.length){ btn.textContent="Nothing to merge"; return; }
    var extra=r.dupGroups.reduce(function(s,g){ return s+g.length-1; },0);
    if(!(await confirm("Merge duplicates? "+extra+" extra cop"+(extra>1?"ies":"y")+" will be removed. Clips that use a copy are moved to the one that is kept. You can undo this.","Merge"))) return;
    transact("Merge duplicate media",function(){
      r.dupGroups.forEach(function(g){
        var keep=project.assets[g[0]]; if(!keep) return;
        g.slice(1).forEach(function(id){
          var o=project.assets[id]; if(!o) return;
          project.tracks.forEach(function(t){ (t.clips||[]).forEach(function(c){ if(c.assetId===id) c.assetId=g[0]; }); });
          (o.tags||[]).forEach(function(tg){ keep.tags=keep.tags||[]; if(keep.tags.indexOf(tg)<0) keep.tags.push(tg); });
          if(o.favorite) keep.favorite=true; delete project.assets[id];
        });
      });
    });
    refresh(); paint(extra+" duplicate cop"+(extra>1?"ies":"y")+" merged. Undo brings them back.");
  }
  async function doStacked(btn){
    var r=analyse({assets:project.assets,tracks:project.tracks}); if(!r.stacked.length){ btn.textContent="Nothing to remove"; return; }
    if(!(await confirm("Remove "+r.stacked.length+" clip"+(r.stacked.length>1?"s":"")+" that sit exactly on top of another? The first one of each pair stays. You can undo this.","Remove"))) return;
    transact("Remove duplicate clips",function(){
      r.stacked.forEach(function(x){ var t=project.tracks.find(function(q){ return q===x.track||q.id===x.track.id; }); if(t) t.clips=(t.clips||[]).filter(function(c){ return c!==x.clip&&c.id!==x.clip.id; }); });
    });
    refresh(); try{ if(typeof renderTracks==="function") renderTracks(); }catch(e){} paint(r.stacked.length+" stacked clip"+(r.stacked.length>1?"s":"")+" removed. Undo brings them back.");
  }
  function group(o,title,lines,btnLabel,fn){
    var d=document.createElement("div"); d.className="sr"; d.style.flexWrap="wrap";
    var s=document.createElement("span"); s.style.flex="1"; s.style.minWidth="150px"; var b=document.createElement("b"); b.textContent=title; s.appendChild(b);
    lines.slice(0,6).forEach(function(l){ s.appendChild(document.createElement("br")); s.appendChild(document.createTextNode("• "+l)); });
    if(lines.length>6){ s.appendChild(document.createElement("br")); s.appendChild(document.createTextNode("… and "+(lines.length-6)+" more")); }
    d.appendChild(s); var bt=document.createElement("button"); bt.type="button"; bt.textContent=btnLabel; bt.onclick=function(){ fn(bt); }; d.appendChild(bt); o.appendChild(d);
  }
  function paint(msg){
    var o=$("smartTidyOut"); if(!o) return; o.innerHTML="";
    var n=0; try{ n=Object.keys(project.assets||{}).length; }catch(e){}
    var r=analyse({assets:project.assets,tracks:project.tracks}); R=r;
    var total=r.unused.length+r.dupGroups.length+r.stacked.length;
    if(msg){ var m=document.createElement("div"); m.style.color="#8fe0a0"; m.textContent=msg; o.appendChild(m); }
    var h=document.createElement("div"); h.textContent=total?("Found things to tidy ("+n+" media file"+(n===1?"":"s")+" in the project):"):("Nothing to clean up. "+n+" media file"+(n===1?"":"s")+", none unused, no duplicates."); o.appendChild(h);
    var A_=project.assets;
    if(r.unused.length) group(o,r.unused.length+" unused file"+(r.unused.length>1?"s":"")+" ("+mb(r.bytes)+")",r.unused.map(function(id){ return nm(A_[id])+" ("+mb(A_[id].size)+")"; }),"Remove unused",doUnused);
    if(r.dupGroups.length) group(o,r.dupGroups.length+" file"+(r.dupGroups.length>1?"s":"")+" imported more than once (about "+mb(r.dupBytes)+" extra)",r.dupGroups.map(function(g){ return nm(A_[g[0]])+" × "+g.length; }),"Merge copies",doMerge);
    if(r.stacked.length) group(o,r.stacked.length+" clip"+(r.stacked.length>1?"s":"")+" stacked exactly on top of another",r.stacked.map(function(x){ return nm(A_[x.clip.assetId])+" on track "+(x.ti+1)+" at "+A._fmt(x.clip.start); }),"Remove duplicates",doStacked);
  }
  function run(){ paint(); }
  A.cleanup=run; A._cleanAnalyse=analyse;
  A._sec("smartTidy","🧹 Clean up media and duplicates",run);
  try{ window.AMIYO_EDITOR_BUILD="ai20-smart-s12-cleanup"; }catch(e){}
})();

