  function off(c){ return (c.x!=null&&(c.x<-0.05||c.x>1.05))||(c.y!=null&&(c.y<-0.05||c.y>1.05)); }
  function over(P,c){ var a=c.assetId&&P.assets&&P.assets[c.assetId]; if(!a||!(a.duration>0)||a.type==="image") return 0; return (c.inPoint||0)+c.duration*(c.speed||1)-a.duration; }
