/* ==================== Script 1219 id="amiyo-ai20-s15-caption-quality" ==================== */
/* AI-20 Step 15: Caption quality check. Looks at every caption line for: reading speed above 20 characters per second, a line longer than 42 characters, more than 2 lines, a caption shorter than 1 s or longer than 7 s, and captions that overlap. Each problem has a Go to button. Two safe fixes: "Wrap long lines" (breaks at word ends into at most 2 lines of 42 characters) and "Give fast captions more time" (extends the caption up to the next one, never past it). Each fix is one undo step. */
(function(){
  "use strict";
  var A=window.amiyoSmart; if(!A||!A._sec||A.captionCheck) return;
  var MAXCPS=20, GOALCPS=17, MAXLINE=42, MAXLINES=2, MINDUR=1, MAXDUR=7;
  function $(i){ return document.getElementById(i); }
  function r1(n){ return Math.round(n*10)/10; }
  function caps(P){ var r=[]; (P.tracks||[]).forEach(function(t){ if(t.kind!=="caption") return; (t.clips||[]).forEach(function(c){ if(String(c.text||"").trim()) r.push({c:c,t:t}); }); }); return r.sort(function(a,b){ return a.c.start-b.c.start; }); }
  function plain(s){ return String(s||"").replace(/\s+/g," ").trim(); }
  /* pure: split text into at most `maxLines` lines of `max` characters, breaking at spaces. null if it cannot fit. */
  function wrap(text,max,maxLines){
    var words=plain(text).split(" "), lines=[], cur="";
    words.forEach(function(w){ var t=cur?cur+" "+w:w; if(t.length>max&&cur){ lines.push(cur); cur=w; } else cur=t; }); if(cur) lines.push(cur);
    if(lines.length>maxLines||lines.some(function(l){ return l.length>max; })) return null; return lines.join("\n");
  }
  /* pure: balanced two-line wrap when one line is too long */
  function analyse(P){
    var L=caps(P), out=[];
    L.forEach(function(x,i){
      var c=x.c, raw=String(c.text||""), lines=raw.split(/\n/).map(function(s){ return s.trim(); }).filter(Boolean), chars=plain(raw).length, d=c.duration||0.01, cps=chars/d, nx=L[i+1];
      if(cps>MAXCPS) out.push({type:"speed",c:c,lv:"warn",msg:"Too fast to read: "+Math.round(cps)+" characters per second ("+Math.round(chars)+" characters in "+r1(d)+" s). Aim for "+GOALCPS+" or less.",at:c.start});
      if(lines.some(function(l){ return l.length>MAXLINE; })) out.push({type:"long",c:c,lv:"warn",msg:"A line is longer than "+MAXLINE+" characters ("+Math.max.apply(null,lines.map(function(l){ return l.length; }))+").",at:c.start});
      if(lines.length>MAXLINES) out.push({type:"lines",c:c,lv:"warn",msg:"This caption has "+lines.length+" lines. Two is easiest to read.",at:c.start});
      if(d<MINDUR&&chars>12) out.push({type:"short",c:c,lv:"info",msg:"On screen for only "+r1(d)+" s.",at:c.start});
      if(d>MAXDUR) out.push({type:"longdur",c:c,lv:"info",msg:"On screen for "+r1(d)+" s. Consider splitting it.",at:c.start});
      if(nx&&c.start+d-nx.c.start>0.05) out.push({type:"overlap",c:c,lv:"warn",msg:"Overlaps the next caption by "+r1(c.start+d-nx.c.start)+" s.",at:nx.c.start});
    });
    return out;
  }
  function wrapPlan(P){ var r=[]; caps(P).forEach(function(x){ var raw=String(x.c.text||""), lines=raw.split(/\n/).map(function(s){ return s.trim(); }).filter(Boolean); if(lines.some(function(l){ return l.length>MAXLINE; })||lines.length>MAXLINES){ var w=wrap(raw,MAXLINE,MAXLINES); if(w&&w!==raw) r.push({c:x.c,text:w}); } }); return r; }
  function extendPlan(P){
    var L=caps(P), r=[]; L.forEach(function(x,i){
      var c=x.c, chars=plain(c.text).length, d=c.duration; if(chars/d<=MAXCPS) return;
      var need=chars/GOALCPS, nx=L[i+1], room=nx?(nx.c.start-c.start-0.05):need, nd=Math.min(need,room);
      if(nd>d+0.05) r.push({c:c,duration:nd,fixes:chars/nd<=MAXCPS});
    }); return r;
  }
  function refresh(){ try{ if(typeof renderAll==="function") renderAll(); }catch(e){} try{ if(typeof scheduleAutosave==="function") scheduleAutosave(); }catch(e){} }
  var note="";
  function doWrap(){ var pl=wrapPlan(project); if(!pl.length) return; transact("Wrap long captions",function(){ wrapPlan(project).forEach(function(p){ p.c.text=p.text; }); }); refresh(); note=pl.length+" caption"+(pl.length>1?"s":"")+" wrapped into short lines. Undo brings them back."; paint(); }
  function doExtend(){ var pl=extendPlan(project); if(!pl.length) return; transact("Give fast captions more time",function(){ extendPlan(project).forEach(function(p){ p.c.duration=p.duration; }); }); refresh(); note=pl.length+" caption"+(pl.length>1?"s":"")+" given more time. Undo brings them back."; paint(); }
  function paint(){
    var o=$("smartCapQOut"); if(!o) return; o.innerHTML="";
    var L=caps(project), iss=analyse(project);
    if(note){ var m=document.createElement("div"); m.style.color="#8fe0a0"; m.textContent=note; o.appendChild(m); note=""; }
    var h=document.createElement("div");
    if(!L.length){ h.textContent="No captions yet. Make captions in the Captions tab first, then check them here."; o.appendChild(h); return; }
    h.textContent=L.length+" caption"+(L.length>1?"s":"")+" checked. "+(iss.length?(iss.length+" thing"+(iss.length>1?"s":"")+" to look at:"):"All of them are easy to read."); o.appendChild(h);
    var wp=wrapPlan(project).length, ep=extendPlan(project).length;
    if(wp||ep){ var row=document.createElement("div"); row.style.cssText="display:flex;gap:8px;flex-wrap:wrap;margin:6px 0";
      if(wp){ var b=document.createElement("button"); b.type="button"; b.textContent="Wrap long lines ("+wp+")"; b.onclick=doWrap; row.appendChild(b); }
      if(ep){ var e=document.createElement("button"); e.type="button"; e.textContent="Give fast captions more time ("+ep+")"; e.onclick=doExtend; row.appendChild(e); }
      o.appendChild(row); }
    iss.slice(0,30).forEach(function(x){ var r=document.createElement("div"); r.className="sr"; var s=document.createElement("span"); s.className=x.lv; s.style.flex="1"; s.textContent="“"+plain(x.c.text).slice(0,40)+"” — "+x.msg; r.appendChild(s); var g=document.createElement("button"); g.type="button"; g.textContent="Go to "+A._fmt(x.at); g.onclick=function(){ try{ setCurrentTime(x.at); }catch(e){} }; r.appendChild(g); o.appendChild(r); });
  }
  A.captionCheck=paint; A._capAnalyse=analyse; A._capWrap=wrap; A._capExtendPlan=extendPlan;
  A._sec("smartCapQ","💬 Caption quality check",paint);
  try{ window.AMIYO_EDITOR_BUILD="ai20-smart-s15-caption-quality"; }catch(e){}
})();

