/* Adds the caption language to SRT/VTT download names: "My Video.srt" -> "My Video.en.srt". Export plan step 12: files that are not captions (marker SRT, chapter VTT) set data-no-lang and keep their own name. */
(function(){try{
  var ISO={english:"en",hindi:"hi",spanish:"es",french:"fr",german:"de",portuguese:"pt",italian:"it",russian:"ru",arabic:"ar",urdu:"ur",bengali:"bn",tamil:"ta",telugu:"te",marathi:"mr",gujarati:"gu",kannada:"kn",malayalam:"ml",punjabi:"pa",nepali:"ne",turkish:"tr",chinese:"zh",japanese:"ja",korean:"ko",indonesian:"id",malay:"ms",tagalog:"tl",vietnamese:"vi",thai:"th",dutch:"nl",polish:"pl",ukrainian:"uk",greek:"el",hebrew:"he",swedish:"sv",swahili:"sw"};
  function code(){var k="english";try{k=localStorage.getItem("amiyo.caption.lang")||"english";}catch(e){}
    return ISO[k]||String(k).toLowerCase().replace(/[^a-z]/g,"").slice(0,3)||"en";}
  var orig=HTMLAnchorElement.prototype.click;
  HTMLAnchorElement.prototype.click=function(){
    try{var d=this.download;
      if(d&&!this.getAttribute("data-no-lang")&&/\.(srt|vtt)$/i.test(d)&&!/\.[a-z]{2,3}(-[A-Za-z]{2,4})?\.(srt|vtt)$/i.test(d)){
        this.download=d.replace(/\.(srt|vtt)$/i,function(m,x){return "."+code()+"."+x.toLowerCase();});
      }}catch(e){}
    return orig.apply(this,arguments);
  };
}catch(e){}})();

