/* ==================== Script 1228 id="gutter-fix-2-js" ==================== */
(function(){
  var SEL='.pr2-gut.on,.pp-gutter.on,.pp-gutter.pp-drag,.am-grip.drag';
  function reset(){document.documentElement.classList.remove('am-resizing');
    document.querySelectorAll(SEL).forEach(function(g){g.classList.remove('on','pp-drag','drag')});}
  /* a lost/cancelled touch must never leave a divider in its dragging (orange) state */
  ['pointerup','pointercancel','lostpointercapture','touchend','touchcancel','mouseup','blur','visibilitychange'].forEach(function(t){
    addEventListener(t,function(){setTimeout(reset,80)},true)});
  /* safety net: pointer moving with no button/finger down means no drag is in progress */
  document.addEventListener('pointermove',function(e){
    if(e.buttons===0&&e.pointerType==='mouse'&&document.querySelector(SEL))reset();
  },true);
})();

