/* ==================== Script 1243 id="am-brand-clip" ==================== */
/* The collapsed top bar clips the "Amiyo Studio PRO" text next to the logo, which left a thin white sliver. Hide that text while it does not fit. */
(function(){"use strict";
 function fix(){ var br=document.querySelector("header.topbar .brand"); if(!br) return;
  var kids=[].filter.call(br.children,function(c){ return !c.classList.contains("logo"); });
  var clipped=br.scrollWidth>br.clientWidth+2;
  kids.forEach(function(c){
   if(clipped){ if(c.style.getPropertyValue("display")!=="none") c.style.setProperty("display","none","important"); c.__bh=1; }
   else if(c.__bh){ c.style.removeProperty("display"); c.__bh=0; } });
  if(!clipped) return; }
 function run(){ try{ fix(); }catch(e){} }
 setInterval(function(){ if(!document.hidden) run(); },1500);
 window.addEventListener("resize",function(){ setTimeout(run,80); });
 setTimeout(run,300); setTimeout(run,1200);
})();

