/* ==================== Script 1247 id="amiyo-xt-s01-contents" ==================== */
/* Export contents, step 1 of 10: "In this video" card in the Export dialog.
   Lists exactly what the file will hold from the timeline - picture clips, text, captions, stickers/graphics, effects, transitions, music and sound clips,
   sound of video clips - and what will be LEFT OUT and why (hidden track, muted track, clip switched off, zero volume, sound off in settings,
   outside the chosen range). Only reads the project. */
(function(){
"use strict";
var XT=window.amiyoXT=window.amiyoXT||{};
function $(i){ return document.getElementById(i); }
function esc(x){ return String(x==null?"":x).replace(/[&<>"]/g,function(c){ return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]; }); }
function asset(c){ try{ return (project.assets||{})[c.assetId]; }catch(e){ return null; } }
function nm(c){ var a=asset(c); return String(c.name||(a&&a.name)||c.text||c.kind||"clip").slice(0,28); }
function fx(c){ return (c.effects||[]).filter(function(e){ return e&&e.enabled!==false; }).length+((c.look&&c.look!=="none")?1:0)+(c.filter?1:0)+((c.lut&&c.lut.enabled&&c.lut.table)?1:0); }
XT.contents=function(){
  var P=window.project, R=window.__amiyoExportRange||window.__amiyoXRange||null, mute=!!window.__amiyoXMute;
  var r={pic:0,text:0,cap:0,gfx:0,adj:0,fx:0,tr:0,music:[],vsound:0,out:[],tracks:0};
  if(!P||!P.tracks) return r;
  var anySolo=P.tracks.some(function(t){ return t.kind==="audio"&&t.solo; });
  P.tracks.forEach(function(t){
    var cl=(t.clips||[]).filter(function(c){ return c.duration>0; }); if(!cl.length) return; r.tracks++;
    var label=t.name||t.kind;
    if(t.kind==="audio"){
      var off=t.muted?"track “"+label+"” is muted":(anySolo&&!t.solo)?"another track is solo":t.hidden?"track “"+label+"” is hidden":mute?"sound is off in the export settings":"";
      cl.forEach(function(c){
        var why=off||(c.off?"clip is switched off":((c.volume===0&&!(c.volumeKeyframes&&c.volumeKeyframes.length))?"its volume is 0":""));
        if(R&&(c.start>=R.t1||c.start+c.duration<=R.t0)) why=why||"outside the exported part";
        if(why) r.out.push(nm(c)+" — "+why); else r.music.push(nm(c));
      }); return;
    }
    if(t.hidden){ r.out.push("Track “"+label+"” ("+cl.length+" clip"+(cl.length>1?"s":"")+") — track is hidden"); return; }
    cl.forEach(function(c){
      if(c.off){ r.out.push(nm(c)+" — clip is switched off"); return; }
      if(R&&(c.start>=R.t1||c.start+c.duration<=R.t0)) return;
      var k=c.kind||t.kind;
      if(k==="text") r.text++; else if(k==="caption"||t.kind==="caption") r.cap++; else if(k==="graphic") r.gfx++; else if(k==="adjustment") r.adj++;
      else if(t.kind==="video"){ r.pic++; var a=asset(c); if(a&&a.type==="video"&&(c.volume==null||c.volume>0)&&!mute) r.vsound++; }
      r.fx+=fx(c); if(c.transitionIn||c.transitionOut) r.tr++;
    });
  });
  return r;
};
function line(ok,t){ return '<div style="display:flex;gap:6px;color:'+(ok?"var(--muted)":"#ffcf70")+'"><span aria-hidden="true">'+(ok?"✓":"⚠")+'</span><span>'+t+'</span></div>'; }
function paint(){
  var b=$("xt1Card"); if(!b) return; var c; try{ c=XT.contents(); }catch(e){ window.__swl&&window.__swl(e); return; }
  var h=[];
  h.push(line(c.pic>0,c.pic+" picture clip"+(c.pic===1?"":"s")+(c.vsound?" · "+c.vsound+" with their own sound":"")));
  if(c.text||c.cap) h.push(line(true,(c.text?c.text+" text":"")+(c.text&&c.cap?" + ":"")+(c.cap?c.cap+" caption":"")+" clip"+((c.text+c.cap)===1?"":"s")+" drawn on the picture"));
  if(c.gfx||c.adj) h.push(line(true,(c.gfx?c.gfx+" sticker/graphic":"")+(c.gfx&&c.adj?" + ":"")+(c.adj?c.adj+" adjustment layer":"")+((c.gfx+c.adj)>1?"s":"")));
  if(c.fx||c.tr) h.push(line(true,(c.fx?c.fx+" effect"+(c.fx>1?"s":""):"")+(c.fx&&c.tr?" · ":"")+(c.tr?c.tr+" clip"+(c.tr>1?"s":"")+" with transitions":"")));
  h.push(line(true,c.music.length?c.music.length+" music / sound clip"+(c.music.length>1?"s":"")+" mixed in: "+esc(c.music.slice(0,4).join(", "))+(c.music.length>4?"…":""):"No separate music or sound clips"));
  c.out.slice(0,6).forEach(function(x){ h.push(line(false,"Left out: "+esc(x))); });
  if(c.out.length>6) h.push(line(false,"…and "+(c.out.length-6)+" more left out"));
  b.querySelector("#xt1List").innerHTML=h.join("");
  b.querySelector("h4").textContent="In this video"+(c.out.length?" · "+c.out.length+" left out":" · everything on the timeline");
}
function inject(){
  var body=$("modalBody"); if(!body||$("xt1Card")) return;
  var anchor=$("x12Check")||$("expSummary"); var go=$("expGo"); var at=anchor?anchor.nextSibling:(go&&go.parentNode);
  var par=anchor?anchor.parentNode:(go&&go.parentNode&&go.parentNode.parentNode); if(!par) return;
  var box=document.createElement("div"); box.id="xt1Card"; box.className="x80-card"; box.setAttribute("role","status");
  box.style.cssText="margin-top:10px;padding:8px 10px;border:1px solid var(--line,#2a2a2a);border-radius:10px";
  box.innerHTML='<h4 style="margin:0 0 4px;font-size:12px">In this video</h4><div id="xt1List" style="font-size:12px;line-height:1.5;display:flex;flex-direction:column;gap:3px"></div>';
  par.insertBefore(box,at||null); paint();
  var t=0; function later(){ clearTimeout(t); t=setTimeout(paint,150); }
  body.addEventListener("click",later); body.addEventListener("input",later); body.addEventListener("change",later);
}
var prev=window.openModal;
window.openModal=function(title){ var r=prev.apply(this,arguments); if(title==="Export video"){ try{ inject(); }catch(e){ window.__swl&&window.__swl(e); } } return r; };
window.AMIYO_XT_STEP=1;
})();

