/* ==================== Script 1251 id="amiyo-xt-s04-retry" ==================== */
/* Export contents, step 4 of 10: if the check (step 3) finds the sound missing from the file, the export is run once more by itself with the OTHER method
   (fast export <-> standard live-recording export), using the same size, range and name settings. The first file stays saved; the second one is checked too.
   It only retries once, and only for missing / silent sound. If the second file is also wrong you are told in words what to do. */
(function(){
"use strict";
var XT=window.amiyoXT=window.amiyoXT||{};
function say(m,ms){ try{ window.toast(m,ms||6000); }catch(e){} }
function lost(m,ms){ if(XT.offerWav) XT.offerWav(m); else say(m,ms); }
var KEY="amiyo_fast_export";
function setFast(v){ try{ localStorage.setItem(KEY,v?"on":"off"); }catch(e){} }
function getFast(){ try{ return localStorage.getItem(KEY); }catch(e){ return null; } }
XT.job=null; XT.engine="";
var fe=window.amiyoFastExport;
if(typeof fe==="function") window.amiyoFastExport=async function(){
  XT.job={opts:window.__amiyoExportOpts,range:window.__amiyoExportRange,name:window.__amiyoExportName,inc:Object.assign({},XT.inc||{})};
  var r=await fe.apply(this,arguments); XT.engine=r?"fast":"standard"; return r;
};
var be=window.__amiyoBaseExport;
if(typeof be==="function") window.__amiyoBaseExport=function(legacy){ if(legacy===true) XT.engine="standard"; return be.apply(this,arguments); };
function badSound(R){ return R&&!R.ok&&(R.audio==="none"||R.audio==="silent"||R.items.some(function(i){ return !i.heard&&!i.video; })); }
async function retry(R){
  var job=XT.job; if(!job||!job.opts){ say("⚠ The sound is missing from the file. Try Export again, or use the Audio button to save the sound separately.",9000); return; }
  if(window.__amiyoExporting) return;
  var was=XT.engine, wasFast=getFast();
  say("The sound is missing, so exporting again with the "+(was==="fast"?"standard":"fast")+" method…",7000);
  window.__amiyoExportOpts=job.opts; window.__amiyoExportRange=job.range; window.__amiyoExportName=job.name||R.name.replace(/\.[^.]+$/,"");
  window.__amiyoCancel=false; window.__amiyoUserStop=false; window.__amiyoFastSlowUntil=0; XT.retrying=true;
  try{
    if(was==="fast"){ await window.__amiyoBaseExport(true); }
    else {
      setFast(true); window.__amiyoFastForce=true;
      var started=await window.amiyoFastExport();
      if(!started){ XT.retrying=false; lost("⚠ The sound is missing and the fast export is not available for this edit ("+(window.__amiyoFastWhy||"not supported")+"). Use the Audio button to save the sound as its own file.",11000); }
    }
  }catch(e){ XT.retrying=false; window.__swl&&window.__swl(e); }
  finally{ window.__amiyoFastForce=false; if(wasFast!=="on") setTimeout(function(){ if(!window.__amiyoExporting) setFast(wasFast==="off"?false:true); else { var iv=setInterval(function(){ if(!window.__amiyoExporting){ clearInterval(iv); setFast(wasFast==="off"?false:true); } },500); } },300); }
}
document.addEventListener("amiyo-xt-report",function(ev){
  var R=ev.detail; if(!R) return;
  if(XT.retrying){ XT.retrying=false; XT.retried=true; if(badSound(R)) lost("⚠ Both export methods lost the sound. Use the Audio button to save the sound as its own file, then check that no audio clip uses an unusual effect.",12000); else if(R.ok) say("✓ Fixed: the second export has the sound.",6000); return; }
  XT.retried=false;
  if(badSound(R)) setTimeout(function(){ retry(R); },2500);
});
window.AMIYO_XT_STEP=4;
})();

