/* ==================== Script 1253 id="amiyo-xt-s06-method" ==================== */
/* Export contents, step 6 of 10: the Export dialog says which method will be used and why.
   Fast export cannot be used when a clip with sound has its speed changed, plays backwards, uses an audio effect (voice, equalizer, room, clean-up),
   or its sound track uses ducking or panning - then the standard live-recording export runs (as long as the video). This was invisible before.
   The note is a prediction read from the project; nothing is changed. */
(function(){
"use strict";
var XT=window.amiyoXT=window.amiyoXT||{};
function $(i){ return document.getElementById(i); }
XT.predict=function(){
  var on=true; try{ on=localStorage.getItem("amiyo_fast_export")!=="off"; }catch(e){}
  if(!on) return {fast:false,why:"fast export is switched off in this dialog"};
  if(typeof VideoEncoder==="undefined") return {fast:false,why:"this browser has no fast encoder"};
  var why="", P=window.project, mute=!!window.__amiyoXMute, n=0;
  if(!mute) P.tracks.forEach(function(t){
    if((t.kind!=="audio"&&t.kind!=="video")||t.hidden||(t.kind==="audio"&&t.muted)) return;
    (t.clips||[]).forEach(function(c){
      if(c.off||!(c.duration>0)) return; var a=(P.assets||{})[c.assetId]; if(!a) return;
      if(t.kind==="video"&&(a.type!=="video"||c.volume===0)) return;
      var r="";
      if(Math.abs((c.speed||1)-1)>.001) r="a clip with sound has its speed changed"; else if(c.reverse) r="a clip with sound plays backwards";
      else if(c.eqFx||c.roomFx||c.deessFx||c.cleanFx||c.voiceFx) r="a clip uses an audio effect"; else if(t.kind==="audio"&&t.duck) r="a sound track uses ducking";
      if(r){ n++; why=why||r; }
    });
  });
  return why?{fast:false,why:why+(n>1?" (and "+(n-1)+" more)":"")}:{fast:true,why:""};
};
function paint(){
  var b=$("xt6Note"); if(!b) return; var p=XT.predict();
  b.innerHTML=p.fast?'<b>Method:</b> fast export — the sound is mixed separately and checked afterwards.':'<b>Method:</b> standard — recorded live, so it takes as long as the video ('+esc(p.why)+'). Keep this screen on. The sound is checked afterwards, and if it is missing the export runs again by itself.';
}
function esc(x){ return String(x).replace(/[&<>"]/g,function(c){ return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]; }); }
function inject(){
  if($("xt6Note")) return; var card=$("xt1Card"); if(!card) return;
  var d=document.createElement("div"); d.id="xt6Note"; d.style.cssText="font-size:11px;color:var(--muted);margin-top:6px;line-height:1.45";
  card.appendChild(d); paint();
  var body=$("modalBody"), t=0; function later(){ clearTimeout(t); t=setTimeout(paint,150); }
  body.addEventListener("click",later); body.addEventListener("input",later); body.addEventListener("change",later);
}
var prev=window.openModal;
window.openModal=function(title){ var r=prev.apply(this,arguments); if(title==="Export video"){ try{ setTimeout(inject,0); inject(); }catch(e){ window.__swl&&window.__swl(e); } } return r; };
window.AMIYO_XT_STEP=6;
})();

