  if(R.pic&&R.pic.items&&R.pic.items.length) R.pic.items.forEach(function(i){ L.push("Picture "+(i.skip?"– not compared ("+(i.err||"unreadable")+")":(i.ok?"✓":"✗"))+" "+i.n+" at "+tc(i.t)); });
