   +'<div style="display:flex;gap:6px;flex-wrap:wrap"><button class="toolbtn" id="dvTapeIn" type="button">In</button><button class="toolbtn" id="dvTapeOut" type="button">Out</button><button class="toolbtn" id="dvTapeClr" type="button">Clear</button><span id="dvTapeR" style="margin-left:auto;font-size:12px;align-self:center;opacity:.8"></span></div>'
   +'<div style="display:flex;gap:6px"><button class="toolbtn" id="dvTapeIns" type="button" style="flex:1">Insert at playhead</button><button class="toolbtn" id="dvTapeApp" type="button" style="flex:1">Append to end</button></div></div>';
  openModal("Source Tape",h);
