  bar.innerHTML=T.list.map(function(e,i){ return '<i style="position:absolute;top:0;bottom:0;left:'+(e.from/T.total*100)+'%;width:calc('+(e.dur/T.total*100)+'% - 1px);background:'+(i%2?"#c25a1e":"#ff7a3d")+';opacity:.75"></i>'; }).join("");
  function paint(){ var nm=$("dvTapeName"), rg=$("dvTapeR"); if(!nm||!rg||!S.a) return; var r=range(); nm.textContent=(S.a.name||"clip")+" · "+tc(S.t)+" / "+tc(S.a.duration||0); rg.textContent=(S.i==null&&S.o==null)||!r?"whole clip "+tc(r?r.d:0):"In "+tc(r.i)+" → Out "+tc(r.o)+" ("+tc(r.d)+")"; }
  function show(){ var u=null; try{u=S.a.type==="video"?assetUrl(S.a.id):null}catch(e){} if(u&&v.getAttribute("data-u")!==u){ v.setAttribute("data-u",u); v.src=u; } v.style.display=u?"":"none"; try{ if(u) v.currentTime=S.t; }catch(e){} paint(); }
