/* ==================== Script 1261 id="amiyo-dv-s03-edit-ops" ==================== */
/* DaVinci-style step 3: the Cut-page edit buttons. Pick something in Source Tape (or leave it on the first clip), then:
   Smart Insert  = puts it at the nearest cut to the playhead and pushes everything after it along.
   Overwrite     = lays it at the playhead and covers whatever was there (nothing moves).
   Ripple Overwrite = replaces the clip under the playhead with it and closes or opens the gap for you.
   Place on Top  = puts it on a free video track above, without touching the clips below.
   Keys: F9 Smart Insert · F10 Overwrite · Shift+F10 Ripple Overwrite. Each one is a single undo step. */
(function(){"use strict";
if(window.AMIYO_DV_S03||!window.AMIYO_DV_S02) return;
var S2=window.AMIYO_DV_S02, S=S2.state;
function $(i){return document.getElementById(i)}
function say(m){ try{toast(m)}catch(e){} }
function ensureSrc(){ if(S.a&&project.assets[S.a.id]) return true; var T=S2.tape(); if(!T.list.length){ say("Import media first, then open Source Tape"); return false; } S.a=T.list[0].a; S.t=0; S.i=null; S.o=null; return true; }
function rng(){ var a=S.a, d=Math.max(.1,a.duration||(a.type==="image"?5:1)); var i=S.i==null?0:S.i, o=S.o==null?d:S.o; if(o<=i) o=Math.min(d,i+.5); return {i:i,o:o,d:o-i}; }
function srcTrack(){ if(!ensureSrc()) return null; var t=S2.trackFor(S.a); if(!t){ say("No track for this media"); return null; } if(t.locked){ say("Track is locked"); return null; } return t; }
function cut(tr,T){ /* split any clip that straddles T, return nothing */
  tr.clips.slice().forEach(function(c){ var end=c.start+c.duration; if(c.start<T-.001&&end>T+.001){ var el=T-c.start,ratio=el/c.duration,sd=(c.outPoint==null?c.duration:c.outPoint)-(c.inPoint||0); var R=JSON.parse(JSON.stringify(c)); R.id=uid("clip"); R.start=T; R.duration=end-T; R.inPoint=(c.inPoint||0)+sd*ratio; c.duration=el; c.outPoint=R.inPoint; tr.clips.push(R); } });
}
function clear(tr,a,b){ /* remove the span [a,b) from a track without moving anything */
  cut(tr,a); cut(tr,b); tr.clips=tr.clips.filter(function(c){ return !(c.start>=a-.001&&c.start+c.duration<=b+.001); });
}
function edges(tr){ var e=[0]; tr.clips.forEach(function(c){ e.push(c.start,c.start+c.duration); }); return e; }
function done(label,c,tr,T){ selectedClipId=c.id; selectedTrackId=tr.id; tr.clips.sort(function(x,y){return x.start-y.start}); try{ setCurrentTime(T); }catch(e){} }
function smartInsert(){
  var tr=srcTrack(); if(!tr) return false; var r=rng(), P=currentTime, T=0, best=1e9;
  edges(tr).forEach(function(x){ var d=Math.abs(x-P); if(d<best){ best=d; T=x; } });
  window.transact("Smart Insert",function(){ S2.rippleOpen(tr,T,r.d); var c=S2.mkClip(S.a,r,T); tr.clips.push(c); done("",c,tr,T); });
  say("Smart Insert at "+T.toFixed(2)+"s"); return true;
}
function overwrite(){
  var tr=srcTrack(); if(!tr) return false; var r=rng(), T=currentTime;
  window.transact("Overwrite",function(){ clear(tr,T,T+r.d); var c=S2.mkClip(S.a,r,T); tr.clips.push(c); done("",c,tr,T); });
  say("Overwrote "+r.d.toFixed(2)+"s"); return true;
}
function rippleOverwrite(){
  var tr=srcTrack(); if(!tr) return false; var r=rng(), T=currentTime;
  var hit=tr.clips.filter(function(c){ return T>=c.start-.001&&T<c.start+c.duration-.001; })[0];
  if(!hit){ say("Put the playhead on the clip to replace"); return false; }
  window.transact("Ripple Overwrite",function(){ var s=hit.start, old=hit.duration, delta=r.d-old;
    tr.clips=tr.clips.filter(function(c){ return c!==hit; });
    tr.clips.forEach(function(c){ if(c.start>=s+old-.001) c.start+=delta; });
    var c=S2.mkClip(S.a,r,s); tr.clips.push(c); done("",c,tr,s); });
  say("Replaced the clip, track rippled"); return true;
}
function placeOnTop(){
  if(!ensureSrc()) return false; var kind=S.a.type==="audio"?"audio":"video", r=rng(), T=currentTime, placed=false;
  window.transact("Place on Top",function(){
    var lanes=project.tracks.filter(function(t){ return t.kind===kind&&!t.locked; });
    var base=S2.trackFor(S.a); var tr=null;
    for(var i=lanes.length-1;i>=0;i--){ var t=lanes[i]; if(t===base&&lanes.length>1) { /* prefer a track above the base */ }
      if(!t.clips.some(function(c){ return c.start<T+r.d-.001&&c.start+c.duration>T+.001; }) && (lanes.length===1||t!==lanes[0])){ tr=t; break; } }
    if(!tr){ var n=project.tracks.filter(function(t){return t.kind===kind}).length+1; tr={id:uid("track"),kind:kind,name:(kind==="audio"?"Audio ":"Video ")+n,clips:[],muted:false,hidden:false,locked:false,solo:false}; project.tracks.push(tr); }
    var c=S2.mkClip(S.a,r,T); tr.clips.push(c); done("",c,tr,T); placed=tr.name; });
  say("Placed on "+placed); return true;
}
/* add the buttons under the Source Tape window */
var prev=window.openModal;
window.openModal=function(title){ var out=prev.apply(this,arguments);
  if(title==="Source Tape"){ setTimeout(function(){ var host=$("dvTape"); if(!host||$("dvTapeOps")) return;
    var d=document.createElement("div"); d.id="dvTapeOps"; d.style.cssText="display:grid;grid-template-columns:1fr 1fr;gap:6px";
    [["Smart Insert (F9)",smartInsert],["Overwrite (F10)",overwrite],["Ripple Overwrite (⇧F10)",rippleOverwrite],["Place on Top",placeOnTop]].forEach(function(p){ var b=document.createElement("button"); b.type="button"; b.className="toolbtn"; b.textContent=p[0]; b.onclick=function(){ if(p[1]()) $("modalBackdrop").style.display="none"; }; d.appendChild(b); });
    host.appendChild(d); },0); }
  return out; };
window.addEventListener("keydown",function(e){ var t=e.target,g=t&&t.tagName; if(g==="INPUT"||g==="TEXTAREA"||g==="SELECT"||(t&&t.isContentEditable)) return;
  if(e.ctrlKey||e.metaKey||e.altKey) return;
  if(e.key==="F9"&&!e.shiftKey){ e.preventDefault(); e.stopPropagation(); smartInsert(); }
  else if(e.key==="F10"){ e.preventDefault(); e.stopPropagation(); e.shiftKey?rippleOverwrite():overwrite(); } },true);
if(window.pr2Register){ pr2Register("Smart Insert","F9",smartInsert); pr2Register("Overwrite","F10",overwrite); pr2Register("Ripple Overwrite","Shift+F10",rippleOverwrite); pr2Register("Place on Top","—",placeOnTop); }
window.AMIYO_DV_S03={smartInsert:smartInsert,overwrite:overwrite,rippleOverwrite:rippleOverwrite,placeOnTop:placeOnTop};
window.AMIYO_DV.steps.S03="Edit buttons";
try{window.AMIYO_EDITOR_BUILD="dv-step03-edit-buttons"}catch(e){}
})();

