  wrap=document.createElement("div"); wrap.id="dvOverview"; wrap.style.cssText="position:relative;height:36px;margin:0;background:#0b0a08;border-top:1px solid var(--line,#2a2620);border-bottom:1px solid var(--line,#2a2620);touch-action:none;cursor:pointer;display:"+(on?"block":"none");
  wrap.setAttribute("role","slider"); wrap.setAttribute("aria-label","Project overview — drag to move the timeline view"); wrap.tabIndex=0;
  cv=document.createElement("canvas"); cv.style.cssText="position:absolute;inset:0;width:100%;height:100%;display:block"; wrap.appendChild(cv);
  sc.parentNode.insertBefore(wrap,sc);
