  var __pq=0; sc.addEventListener("scroll",function(){ if(__pq) return; __pq=requestAnimationFrame(function(){ __pq=0; paint(); }); },{passive:true});
  try{ new ResizeObserver(function(){ paint(true); }).observe(wrap); }catch(e){}
