  var W=wrap.clientWidth, H=wrap.clientHeight; if(W<10||H<10) return;
  var s=g.dur+"|"+currentTime.toFixed(2)+"|"+g.t0.toFixed(2)+"|"+g.t1.toFixed(2)+"|"+W+"|"+project.tracks.map(function(t){ return t.id+":"+t.clips.map(function(c){ return (c.start|0)+","+((c.duration*10)|0); }).join(";"); }).join("/");
  if(!force&&s===sig) return; sig=s;
  var d=window.devicePixelRatio||1; if(cv.width!==Math.round(W*d)||cv.height!==Math.round(H*d)){ cv.width=Math.round(W*d); cv.height=Math.round(H*d); }
  var x=cv.getContext("2d"); x.setTransform(d,0,0,d,0,0); x.clearRect(0,0,W,H);
  var tr=project.tracks.filter(function(t){ return t.clips.length; }), n=Math.max(1,tr.length), rh=Math.max(2,(H-6)/n);
  tr.forEach(function(t,i){ x.fillStyle=COLORS[t.kind]||"#8a93a3"; t.clips.forEach(function(c){ var a=c.start/g.dur*W, w=Math.max(1.5,c.duration/g.dur*W); x.globalAlpha=t.hidden||t.muted?.35:.9; x.fillRect(a,3+i*rh,w-1,Math.max(1,rh-1.5)); }); });
  x.globalAlpha=1;
  var a=g.t0/g.dur*W, b=g.t1/g.dur*W; x.fillStyle="rgba(255,255,255,.10)"; x.fillRect(a,0,Math.max(3,b-a),H); x.strokeStyle="#ffffff"; x.lineWidth=1.5; x.strokeRect(a+.75,.75,Math.max(3,b-a)-1.5,H-1.5);
