window.addEventListener("keydown",function(e){ var t=e.target,g=t&&t.tagName; if(g==="INPUT"||g==="TEXTAREA"||g==="SELECT"||(t&&t.isContentEditable)) return; if(e.altKey&&!e.ctrlKey&&!e.metaKey&&!e.shiftKey&&e.code==="KeyO"){ e.preventDefault(); e.stopPropagation(); toggle(); } },true);
