/* ==================== Script 1267 id="amiyo-pe-s01" ==================== */
/* Pro Editing step 1: shared helpers + EXTEND EDIT. Press E (or Pr Tools > Extend edit to playhead): the nearest edge of each selected clip is pulled (or pushed back) to the playhead, without overlapping neighbours or running past the source media. One undo step. */
(function(){"use strict";
var P=window.AMIYO_PE=window.AMIYO_PE||{};
P.sel=function(){var r=[];try{selectedClips().forEach(function(f){r.push(f)})}catch(e){}return r};
P.say=function(m){try{toast(m)}catch(e){}};
P.edit=function(label,fn){var before=deepClone(serializableProject());var r=fn();try{pushHistory(label,before)}catch(e){}try{renderAll()}catch(e){}return r};
P.fps=function(){try{return +project.settings.fps||30}catch(e){return 30}};
P.reg=function(name,keys,fn,test){try{pr2Register(name,keys,fn)}catch(e){} if(test){try{pr2Key(test,fn)}catch(e){}}};
function srcRate(c){var d=c.duration||1;return ((c.outPoint==null?d:c.outPoint)-(c.inPoint||0))/d}
function assetMax(c){try{var a=getAsset(c.assetId);return a&&a.duration?a.duration:Infinity}catch(e){return Infinity}}
function extend(){
 var s=P.sel().filter(function(f){return !f.track.locked}); if(!s.length){P.say("Select a clip first");return 0}
 var t=currentTime,n=0;
 P.edit("Extend edit",function(){s.forEach(function(f){var c=f.clip,tr=f.track,end=c.start+c.duration,r=srcRate(c);
  var toEnd=Math.abs(t-end)<=Math.abs(t-c.start);
  if(toEnd){var lim=Infinity;tr.clips.forEach(function(o){if(o!==c&&o.start>=end-1e-4)lim=Math.min(lim,o.start)});
   var ne=Math.min(t,lim); if(ne<=c.start+.05) return;
   var nd=ne-c.start,no=(c.inPoint||0)+r*nd; if(no>assetMax(c)){no=assetMax(c);nd=(no-(c.inPoint||0))/r}
   if(Math.abs(nd-c.duration)<1e-4) return; c.duration=nd;c.outPoint=no;n++;
  }else{var lo=0;tr.clips.forEach(function(o){if(o!==c&&o.start+o.duration<=c.start+1e-4)lo=Math.max(lo,o.start+o.duration)});
   var ns=Math.max(t,lo); if(ns>=end-.05) return;
   var delta=c.start-ns,ni=(c.inPoint||0)-r*delta; if(ni<0){delta=(c.inPoint||0)/r;ni=0;ns=c.start-delta}
   if(Math.abs(delta)<1e-4) return; c.start=ns;c.duration=end-ns;c.inPoint=ni;n++;}
 });});
 P.say(n?"Extended "+n+" edit"+(n>1?"s":""):"Nothing to extend here"); return n}
P.extend=extend;
P.reg("Extend edit to playhead","E",extend,function(e){return !e.ctrlKey&&!e.metaKey&&!e.altKey&&!e.shiftKey&&e.code==="KeyE"});
window.AMIYO_PE_S01={extend:extend};
try{window.AMIYO_EDITOR_BUILD="pe-step01-extend-edit"}catch(e){}
})();

