/* ==================== Script 1269 id="amiyo-pe-s03" ==================== */
/* Pro Editing step 3: SPACE CLIPS EVENLY. Select 2+ clips on a track, then Pr Tools > Space clips evenly (Alt+Shift+E) and type the gap in seconds (0 = butt them together). The first clip stays put, the rest are laid out in time order, and anything after them on that track moves along so nothing overlaps. One undo step. */
(function(){"use strict";
if(window.AMIYO_PE_S03) return; var P=window.AMIYO_PE;
function space(gap){
 var s=P.sel().filter(function(f){return !f.track.locked}); if(s.length<2){P.say("Select two or more clips first");return 0}
 if(gap==null){var v=prompt("Gap between clips in seconds (0 = no gap):","0.5"); if(v==null) return 0; gap=parseFloat(v)} if(!isFinite(gap)||gap<0){P.say("Type a gap like 0.5");return 0}
 var done=0; P.edit("Space clips evenly",function(){
  var by={}; s.forEach(function(f){(by[f.track.id]=by[f.track.id]||{t:f.track,l:[]}).l.push(f.clip)});
  Object.keys(by).forEach(function(k){var t=by[k].t,l=by[k].l.sort(function(a,b){return a.start-b.start}); if(l.length<2) return;
   var ids={}; l.forEach(function(c){ids[c.id]=1}); var oldEnd=l[l.length-1].start+l[l.length-1].duration, x=l[0].start+l[0].duration+gap;
   for(var i=1;i<l.length;i++){l[i].start=x; x+=l[i].duration+gap}
   var newEnd=l[l.length-1].start+l[l.length-1].duration, d=newEnd-oldEnd;
   t.clips.forEach(function(o){ if(!ids[o.id]&&o.start>=oldEnd-1e-4) o.start=Math.max(0,o.start+d) });
   t.clips.sort(function(a,b){return a.start-b.start}); done+=l.length; });
 });
 P.say("Spaced "+done+" clips, gap "+gap+" s"); return done}
P.space=space; P.reg("Space clips evenly","Alt+Shift+E",function(){space()},function(e){return e.altKey&&e.shiftKey&&!e.ctrlKey&&!e.metaKey&&e.code==="KeyE"});
window.AMIYO_PE_S03={space:space};
try{window.AMIYO_EDITOR_BUILD="pe-step03-space-evenly"}catch(e){}
})();

