  "<div>Media in bin <b>"+as.length+"</b> · used <b>"+(as.length-un.length)+"</b> · unused <b>"+un.length+"</b></div>"+
  (un.length?"<ul style='margin:8px 0 0;padding-left:18px;max-height:160px;overflow:auto'>"+un.map(function(a){return "<li>"+String(a.name||a.id).replace(/</g,"&lt;")+"</li>"}).join("")+"</ul>":"<div style='margin-top:8px;color:#8fd19e'>Every media file is used.</div>");
