/* ==================== Script 1283 id="amiyo-pe-s17" ==================== */
/* Pro Editing step 17: REPEAT SELECTION. Select one or more clips, then Pr Tools > Repeat selection (Alt+Shift+Y) and type how many extra copies. The whole selected block is copied again and again right after itself, and everything later on those tracks slides along. Good for loops and repeating patterns. One undo step. */
(function(){"use strict";
if(window.AMIYO_PE_S17) return; var P=window.AMIYO_PE;
function nid(){try{return uid("clip")}catch(e){return "clip_"+Math.random().toString(36).slice(2,9)}}
function repeat(n){
 var s=P.sel().filter(function(f){return !f.track.locked}); if(!s.length){P.say("Select clips first");return 0}
 if(n==null){var v=prompt("How many extra copies?","3"); if(v==null) return 0; n=parseInt(v,10)} if(!(n>=1)||n>50){P.say("Type 1 to 50");return 0}
 var a=Infinity,b=0; s.forEach(function(f){a=Math.min(a,f.clip.start);b=Math.max(b,f.clip.start+f.clip.duration)}); var len=b-a,made=0;
 P.edit("Repeat selection x"+n,function(){ var ids={},tr={}; s.forEach(function(f){ids[f.clip.id]=1;tr[f.track.id]=f.track});
  Object.keys(tr).forEach(function(k){ tr[k].clips.forEach(function(o){ if(!ids[o.id]&&o.start>=b-1e-4) o.start+=len*n }) });
  for(var i=1;i<=n;i++) s.forEach(function(f){ var r=deepClone(f.clip); r.id=nid(); r.selected=false; r.start=f.clip.start+len*i; f.track.clips.push(r); made++ });
  Object.keys(tr).forEach(function(k){ tr[k].clips.sort(function(p,q){return p.start-q.start}) }) });
 P.say("Added "+made+" cop"+(made===1?"y":"ies")); return made}
P.repeat=repeat; P.reg("Repeat selection","Alt+Shift+Y",function(){repeat()},function(e){return e.altKey&&e.shiftKey&&!e.ctrlKey&&!e.metaKey&&e.code==="KeyY"});
window.AMIYO_PE_S17={repeat:repeat};
try{window.AMIYO_EDITOR_BUILD="pe-step17-repeat"}catch(e){}
})();

