/* ==================== Script 1331 id="amiyo-prx-s01" ==================== */
/* Premiere Pro pack, step 1: AUDIT FIX. The automatic audit of all 66 Pr tools found one crash: Pr Tools > Project report (and "Remove unused media" inside it) treated the media bin as a list, but it is a map, so it stopped with "as.filter is not a function". Fixed in place. Also adds the shared AMIYO_PRX helper used by the next steps. */
(function(){"use strict";
var X=window.AMIYO_PRX=window.AMIYO_PRX||{};
X.say=function(m){try{toast(m)}catch(e){}};
X.sel=function(){try{return selectedClips()}catch(e){return []}};
X.assets=function(){var a=project.assets||{};return Object.keys(a).map(function(k){return a[k]})};
X.edit=function(label,fn){var before=deepClone(serializableProject());var r=fn();if(r===false)return false;try{pushHistory(label,before)}catch(e){}try{scheduleAutosave()}catch(e){}try{renderAll()}catch(e){}return true};
X.reg=function(name,keys,fn){try{pr2Register(name,keys,fn)}catch(e){}};
window.AMIYO_PRX_S01={ok:true};
try{window.AMIYO_EDITOR_BUILD="prx-step01-report-fix"}catch(e){}
})();

