/* ==================== Script 1332 id="amiyo-prx-s02" ==================== */
/* Premiere Pro pack, step 2: REMIX (fit music to length). Pick a music clip (or select it), choose a target (video length, playhead or your own seconds) and tap Fit. Too long: it is trimmed with a fade out. Too short: it loops with tiny joins and a fade out on the last piece. Never overlaps other clips; one undo step. Open from Pr Tools: Remix. */
(function(){"use strict";
var X=window.AMIYO_PRX, kit=window.amiyoKit; if(!X||!kit) return;
var target="video", custom=30;
function pick(){var s=X.sel().filter(function(f){return f.track.kind==="audio"}); if(s.length) return s[0]; var best=null;
 project.tracks.forEach(function(t){ if(t.kind!=="audio"||t.locked) return; (t.clips||[]).forEach(function(c){ if(!best||c.duration>best.clip.duration) best={track:t,clip:c}})}); return best}
function videoEnd(){var e=0; project.tracks.forEach(function(t){ if(t.kind!=="video"&&t.kind!=="image") return; (t.clips||[]).forEach(function(c){e=Math.max(e,c.start+c.duration)})}); return e}
function targetLen(f){ return target==="video"?videoEnd()-f.clip.start : target==="playhead"?currentTime-f.clip.start : custom }
function fit(f,T){
 var c=f.clip,tr=f.track; if(tr.locked){X.say("That track is locked");return false}
 T=+T; if(!(T>=0.5)){X.say("Target length must be at least 0.5 s");return false}
 var d=c.duration, inP=c.inPoint||0, rate=((c.outPoint==null?d:c.outPoint)-inP)/d;
 if(Math.abs(T-d)<0.02){X.say("Music is already that length");return false}
 var others=tr.clips.filter(function(o){return o!==c});
 if(T>d && others.some(function(o){return o.start<c.start+T-1e-4 && o.start+o.duration>c.start+d+1e-4})){X.say("Not enough free room on that track");return false}
 var pieces=1;
 var ok=X.edit("Remix music",function(){
  if(T<d){ c.duration=T; c.outPoint=inP+rate*T; c.fadeOut=Math.min(2,T/2); if((c.fadeIn||0)>T/2) c.fadeIn=T/2; return true}
  var n=Math.ceil(T/d-1e-6); c.fadeOut=n>1?0.03:Math.min(2,d/2);
  for(var k=1;k<n;k++){ var cp=deepClone(c); cp.id=uid("clip"); cp.start=c.start+k*d; var dd=Math.min(d,T-k*d); cp.duration=dd; cp.inPoint=inP; cp.outPoint=inP+rate*dd; cp.fadeIn=0.03; cp.fadeOut=(k===n-1)?Math.min(2,dd/2):0.03; tr.clips.push(cp)}
  tr.clips.sort(function(a,b){return a.start-b.start}); pieces=n; return true});
 if(ok) X.say("Music is now "+T.toFixed(1)+" s"+(pieces>1?" ("+pieces+" pieces)":""));
 return ok}
function run(){var f=pick(); if(!f){X.say("Add a music clip on an audio track first");return false} var T=targetLen(f); if(!(T>0)){X.say("Target is before the music starts");return false} return fit(f,T)}
var sh=kit.sheet("prxRemix","\uD83C\uDFB5 Remix: fit music to length",function(){
 var f=pick(), h='<div class="note">'+(f?"Music clip: "+kit.esc(f.clip.name||"audio")+" ("+f.clip.duration.toFixed(1)+" s). Video length is "+videoEnd().toFixed(1)+" s.":"No music clip found. Add one on an audio track.")+'</div><h5>Make it as long as</h5><div class="g">';
 [["video","Video length"],["playhead","Playhead"],["custom","My seconds"]].forEach(function(t){h+='<button type="button" data-k="t:'+t[0]+'" style="'+(target===t[0]?"border-color:#ffb454;color:#ffb454":"")+'">'+t[1]+'</button>'});
 return h+'</div>'+(target==="custom"?'<label>Seconds<input id="prxRemixSec" type="number" min="1" step="0.5" value="'+custom+'"></label>':"")+'<button type="button" data-k="go" style="border-color:#ffb454">Fit music now</button>'},
 function(k,b,api){ if(k.indexOf("t:")===0){target=k.slice(2);api.paint()} else if(k==="go"){ var e=document.getElementById("prxRemixSec"); if(e&&e.value) custom=parseFloat(e.value)||custom; if(run()!==false) api.close()}});
window.AMIYO_PRX_S02={open:sh.open,fit:fit,run:run,pick:pick,setTarget:function(t,s){target=t;if(s)custom=s}};
kit.menu("\uD83C\uDFB5 Remix music",sh.open,"Remix: fit music to length","AMIYO_PRX_S02.open()");
try{window.AMIYO_EDITOR_BUILD="prx-step02-remix"}catch(e){}
})();

