/* ==================== Script 1333 id="amiyo-prx-s03" ==================== */
/* Premiere Pro pack, step 3: EXPORT FCPXML. Pr Tools > Export FCPXML writes your edit as an .fcpxml 1.9 file that DaVinci Resolve and Final Cut Pro open (clips, audio, titles, markers, volume, opacity, on/off). Media is linked by file name, so relink after opening. Speed changes, effects and captions are not carried; the message tells you how many were left out. */
(function(){"use strict";
var X=window.AMIYO_PRX, kit=window.amiyoKit; if(!X||!kit) return;
X.download=X.download||function(name,txt,mime){var b=new Blob([txt],{type:mime||"application/octet-stream"}),u=URL.createObjectURL(b),a=document.createElement("a");a.href=u;a.download=name;document.body.appendChild(a);a.click();setTimeout(function(){a.remove();URL.revokeObjectURL(u)},4000)};
function esc(s){return String(s==null?"":s).replace(/[&<>"']/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&apos;"}[c]})}
function build(){
 var fps=+project.settings.fps||30, fd=Math.abs(fps-29.97)<.02?[1001,30000]:Math.abs(fps-23.976)<.02?[1001,24000]:Math.abs(fps-59.94)<.02?[1001,60000]:[1,Math.round(fps)];
 function T(sec){var n=Math.max(0,Math.round(sec*(fd[1]/fd[0]))); return n?(n*fd[0])+"/"+fd[1]+"s":"0s"}
 var W=project.settings.width||1280,H=project.settings.height||720, rid=1, res=[], ids={}, skipped=0, clips=0, titles=0, total=0;
 res.push('<format id="r1" frameDuration="'+fd[0]+'/'+fd[1]+'s" width="'+W+'" height="'+H+'"/>');
 function assetRef(c){var a=getAsset(c.assetId); if(!a) return null; if(!ids[a.id]){ids[a.id]="r"+(++rid); var vid=a.type==="audio"?0:1, aud=a.type==="image"?0:1, dur=Math.max(a.duration||0,(c.outPoint||c.duration||1));
   res.push('<asset id="'+ids[a.id]+'" name="'+esc(a.name||a.id)+'" start="0s" duration="'+T(dur)+'" hasVideo="'+vid+'" hasAudio="'+aud+'"'+(vid?' format="r1"':'')+' src="file:///'+esc(encodeURI(a.name||a.id))+'"/>')} return ids[a.id]}
 var effId=null; project.tracks.forEach(function(t){(t.clips||[]).forEach(function(c){total=Math.max(total,c.start+c.duration)})});
 var vTracks=project.tracks.filter(function(t){return t.kind==="video"||t.kind==="image"}), aTracks=project.tracks.filter(function(t){return t.kind==="audio"}), xTracks=project.tracks.filter(function(t){return t.kind==="text"});
 var body=[];
 function lane(t){var i; if(t.kind==="audio"){i=aTracks.indexOf(t);return -(i+1)} if(t.kind==="text") return vTracks.length+xTracks.indexOf(t)+1; return vTracks.indexOf(t)+1}
 project.tracks.forEach(function(t){
  (t.clips||[]).forEach(function(c){
   var en=(t.muted||t.hidden||c.disabled||c.enabled===false)?' enabled="0"':'', L=lane(t), ln=L?' lane="'+L+'"':'';
   if(t.kind==="caption"){skipped++;return}
   if(t.kind==="text"||c.kind==="text"){ if(!effId){effId="r"+(++rid); res.push('<effect id="'+effId+'" name="Basic Title" uid=".../Titles.localized/Bumper:Opener.localized/Basic Title.moti"/>')}
     var sid="ts"+(titles+1); titles++; var col=(c.textStyle&&c.textStyle.color)||"#ffffff", n=parseInt(col.replace("#","").slice(0,6),16)||16777215;
     body.push('<title ref="'+effId+'"'+ln+' offset="'+T(c.start)+'" name="'+esc(c.name||c.text||"Title")+'" duration="'+T(c.duration)+'"'+en+'><text><text-style ref="'+sid+'">'+esc(c.text||c.name||"")+'</text-style></text><text-style-def id="'+sid+'"><text-style font="Helvetica" fontSize="'+((c.textStyle&&c.textStyle.fontSize)||64)+'" fontColor="'+((n>>16&255)/255).toFixed(3)+' '+((n>>8&255)/255).toFixed(3)+' '+((n&255)/255).toFixed(3)+' 1"/></text-style-def></title>'); clips++; return}
   if(!c.assetId){skipped++;return}
   var r=assetRef(c); if(!r){skipped++;return}
   var inner=""; if(c.volume!=null&&Math.abs(c.volume-1)>.001) inner+='<adjust-volume amount="'+(c.volume>0?(20*Math.log10(c.volume)).toFixed(2):"-96")+'dB"/>';
   if(t.kind!=="audio"&&c.opacity!=null&&c.opacity<.999) inner+='<adjust-blend amount="'+(+c.opacity).toFixed(3)+'"/>';
   if(c.speed&&Math.abs(c.speed-1)>.001) skipped++;
   body.push('<asset-clip ref="'+r+'"'+ln+' offset="'+T(c.start)+'" name="'+esc(c.name||(getAsset(c.assetId)||{}).name||"Clip")+'" start="'+T(c.inPoint||0)+'" duration="'+T(c.duration)+'"'+en+(t.kind==="audio"?' audioRole="dialogue"':'')+(inner?'>'+inner+'</asset-clip>':'/>')); clips++});
 });
 var marks=(project.markers||[]).map(function(m){return '<marker start="'+T(m.time||0)+'" duration="'+fd[0]+'/'+fd[1]+'s" value="'+esc(m.label||"Marker")+'"/>'});
 var nm=esc((project.metadata&&project.metadata.name)||"Amiyo project");
 var xml='<?xml version="1.0" encoding="UTF-8"?>\n<!DOCTYPE fcpxml>\n<fcpxml version="1.9">\n<resources>\n'+res.join("\n")+'\n</resources>\n<library>\n<event name="'+nm+'">\n<project name="'+nm+'">\n<sequence format="r1" duration="'+T(total)+'" tcStart="0s" tcFormat="NDF" audioLayout="stereo" audioRate="48k">\n<spine>\n<gap name="Gap" offset="0s" start="0s" duration="'+T(total)+'">\n'+body.join("\n")+(marks.length?"\n"+marks.join("\n"):"")+'\n</gap>\n</spine>\n</sequence>\n</project>\n</event>\n</library>\n</fcpxml>\n';
 return {xml:xml,clips:clips,titles:titles,markers:marks.length,skipped:skipped,assets:Object.keys(ids).length};
}
function run(){ if(!project.tracks.some(function(t){return (t.clips||[]).length})){X.say("The timeline is empty");return false}
 var r=build(), name=String((project.metadata&&project.metadata.name)||"Amiyo project").replace(/[^\w\- ]+/g,"").trim()||"Amiyo project";
 X.download(name+".fcpxml",r.xml,"application/xml"); X.say("FCPXML saved: "+r.clips+" clips, "+r.markers+" markers"+(r.skipped?" ("+r.skipped+" items not carried)":"")+". Relink media in DaVinci/Final Cut."); return r}
window.AMIYO_PRX_S03={build:build,run:run};
kit.menu("\uD83C\uDFAC Export FCPXML",run,"Export FCPXML (DaVinci / Final Cut)","AMIYO_PRX_S03.run()");
try{window.AMIYO_EDITOR_BUILD="prx-step03-fcpxml"}catch(e){}
})();

