/* ==================== Script 1335 id="amiyo-prx-s05" ==================== */
/* Premiere Pro pack, step 5: BARS & TONE and COUNTING LEADER generators. Pr Tools > Bars & Tone adds 5 s of colour bars with a 1 kHz tone at the playhead. Pr Tools > Counting leader adds an 8..2 countdown with a beep each second. Made inside the editor, no files needed; one undo step. */
(function(){"use strict";
var X=window.AMIYO_PRX, kit=window.amiyoKit; if(!X||!kit) return;
function wav(sec,beeps){var sr=24000,n=Math.round(sec*sr),b=new ArrayBuffer(44+n*2),v=new DataView(b);
 function S(o,s){for(var i=0;i<s.length;i++)v.setUint8(o+i,s.charCodeAt(i))}
 S(0,"RIFF");v.setUint32(4,36+n*2,true);S(8,"WAVEfmt ");v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,1,true);v.setUint32(24,sr,true);v.setUint32(28,sr*2,true);v.setUint16(32,2,true);v.setUint16(34,16,true);S(36,"data");v.setUint32(40,n*2,true);
 for(var i=0;i<n;i++){var t=i/sr,on=beeps?(t%1)<0.1:true,a=on?0.125*Math.sin(2*Math.PI*1000*t):0;v.setInt16(44+i*2,Math.round(a*32767),true)}
 var u=new Uint8Array(b),s="";for(var j=0;j<u.length;j+=8192)s+=String.fromCharCode.apply(null,u.subarray(j,j+8192));return "data:audio/wav;base64,"+btoa(s)}
function svg(inner){return "data:image/svg+xml;base64,"+btoa(unescape(encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="1280" height="720" viewBox="0 0 1280 720">'+inner+'</svg>')))}
function bars(){var c=["#c0c0c0","#c0c000","#c04000","#00c000","#c000c0","#c00000","#c04000"],h="";
 c.forEach(function(x,i){h+='<rect x="'+Math.round(i*1280/7)+'" y="0" width="187" height="480" fill="'+x+'"/>'});
 var d=["#c04000","#101010","#c000c0","#101010","#c04000","#101010","#c0c0c0"];d.forEach(function(x,i){h+='<rect x="'+Math.round(i*1280/7)+'" y="480" width="187" height="60" fill="'+x+'"/>'});
 h+='<rect y="540" width="1280" height="180" fill="#101010"/><text x="640" y="650" fill="#fff" font-family="monospace" font-size="44" text-anchor="middle">1 kHz  -18 dBFS</text>';return svg(h)}
function num(n){return svg('<rect width="1280" height="720" fill="#111"/><circle cx="640" cy="360" r="250" fill="none" stroke="#888" stroke-width="6"/><path d="M640 60V660M340 360H940" stroke="#555" stroke-width="3"/><text x="640" y="470" fill="#fff" font-family="sans-serif" font-weight="700" font-size="340" text-anchor="middle">'+n+'</text>')}
function addAsset(id,name,type,mime,dur,data,w,h){project.assets[id]={id:id,name:name,type:type,mime:mime,duration:dur,fileData:data,width:w,height:h};return project.assets[id]}
function place(items){ var vt=getTrack("video"),at=getTrack("audio"),start=currentTime,tot=0;
 items.forEach(function(it){tot=Math.max(tot,it.at+it.dur)});
 [vt,at].forEach(function(t){start=Math.max(start,nearestGap(t.clips,start,tot))});
 [vt,at].forEach(function(t){ if(t.locked) start=-1 }); if(start<0){X.say("A target track is locked");return false}
 return X.edit("Add leader",function(){ items.forEach(function(it){ var t=it.a.type==="audio"?at:vt, c=makeClipFor(it.a,start+it.at,it.dur); c.name=it.name; t.clips.push(c); t.clips.sort(function(x,y){return x.start-y.start}); selectedClipId=c.id }) }) }
function addBars(){var u=Date.now().toString(36),a=addAsset("bars_"+u,"Color Bars.svg","image","image/svg+xml",5,bars(),1280,720),t=addAsset("tone_"+u,"Tone 1kHz.wav","audio","audio/wav",5,wav(5,false));
 var ok=place([{a:a,at:0,dur:5,name:"Color Bars"},{a:t,at:0,dur:5,name:"Tone 1 kHz"}]); if(ok!==false) X.say("Bars & Tone added (5 s)"); return ok}
function addLeader(){var u=Date.now().toString(36),items=[],i;
 for(i=0;i<7;i++){var n=8-i;items.push({a:addAsset("ld"+n+"_"+u,"Leader "+n+".svg","image","image/svg+xml",1,num(n),1280,720),at:i,dur:1,name:"Leader "+n})}
 items.push({a:addAsset("ldt_"+u,"Leader beeps.wav","audio","audio/wav",7,wav(7,true)),at:0,dur:7,name:"Leader beeps"});
 var ok=place(items); if(ok!==false) X.say("Counting leader added (8 to 2)"); return ok}
window.AMIYO_PRX_S05={bars:addBars,leader:addLeader,wav:wav};
kit.menu("\uD83D\uDCCA Bars & Tone",addBars,"Bars and Tone","AMIYO_PRX_S05.bars()");
kit.menu("\u23F1 Counting leader",addLeader,"Counting leader","AMIYO_PRX_S05.leader()");
try{window.AMIYO_EDITOR_BUILD="prx-step05-leaders"}catch(e){}
})();

