/* ==================== Script 1336 id="amiyo-w35-s01" ==================== */
/* W35 step 1: Phone timeline room. On phones the timeline showed only about 1.5 tracks once a clip was selected, and the round Audio Lab / Flow buttons sat on top of the
   track names. The timeline now gets about 40% of the screen height (the preview shrinks to make room), and the two round buttons move to the right end of the ruler
   as small 26 px buttons. Desktop is unchanged. Tap the new "Tl size" button in the status bar to cycle Small / Medium / Large. */
(function(){
  "use strict";
  if(window.__w35s01) return; window.__w35s01=true;
  var SIZES=[["Small",32],["Medium",40],["Large",52]], idx=1;
  try{ var sv=parseInt(localStorage.getItem("w35.tlsize"),10); if(sv>=0&&sv<3) idx=sv; }catch(e){}
  var st=document.createElement("style"); st.id="w35s01css";
  document.head.appendChild(st);
  function phone(){ return window.innerWidth<=700; }
  function css(){
    var vh=SIZES[idx][1];
    st.textContent="@media (max-width:700px){.center>.timeline{flex:0 0 clamp(228px,"+vh+"vh,560px)!important;height:clamp(228px,"+vh+"vh,560px)!important;min-height:228px!important;max-height:560px!important}"+
      ".center>.preview-wrap{min-height:120px!important}"+
      "#w35TlSize{height:26px!important;min-height:26px!important;max-height:26px!important;line-height:1!important}#alb,#amFlDock{width:26px!important;height:26px!important;min-width:26px!important;min-height:26px!important;max-height:26px!important;font-size:13px!important;line-height:1!important;padding:0!important;opacity:.88!important;border-radius:13px!important}}";
  }
  function place(){
    if(!phone()) return;
    var rl=document.getElementById("ruler"), a=document.getElementById("alb"), f=document.getElementById("amFlDock"); if(!rl) return;
    var top=Math.round(rl.getBoundingClientRect().top)-1, W=window.innerWidth;
    if(f){ f.style.setProperty("top",top+"px","important"); f.style.setProperty("left",(W-30)+"px","important"); f.style.setProperty("bottom","auto","important"); }
  }
  function sizeBtn(){
    var bar=document.querySelector(".statusbar,#statusbar,.status-bar")||document.getElementById("statusLine");
    var b=document.getElementById("w35TlSize"); if(!phone()){ if(b) b.style.display="none"; return; }
    if(!b){
      b=document.createElement("button"); b.id="w35TlSize"; b.type="button"; b.setAttribute("aria-label","Timeline size");
      b.style.cssText="position:fixed;z-index:60;min-height:26px;height:26px;padding:0 9px;border-radius:13px;border:1px solid #302c26;background:#211f1b;color:#f1ece2;font:600 11px system-ui;opacity:.9";
      b.addEventListener("click",function(){ idx=(idx+1)%3; try{ localStorage.setItem("w35.tlsize",String(idx)); }catch(e){} css(); b.textContent="Tl size: "+SIZES[idx][0]; setTimeout(place,60); try{ window.dispatchEvent(new Event("resize")); }catch(e){} try{ toast("Timeline size: "+SIZES[idx][0]); }catch(e){} });
      document.body.appendChild(b);
    }
    b.style.display="block"; b.textContent="Tl size: "+SIZES[idx][0];
    var rl=document.getElementById("ruler"); if(rl){ b.style.top=(Math.round(rl.getBoundingClientRect().top)-1)+"px"; b.style.left=(window.innerWidth-62-b.offsetWidth-6)+"px"; }
  }
  function tick(){ css(); place(); sizeBtn(); }
  window.addEventListener("resize",function(){ setTimeout(tick,50); }); window.addEventListener("orientationchange",function(){ setTimeout(tick,300); });
  var ra=window.renderAll; if(typeof ra==="function"&&!ra.__w35){ window.renderAll=function(){ var r=ra.apply(this,arguments); try{ requestAnimationFrame(tick); }catch(e){} return r; }; window.renderAll.__w35=true; }
  css(); setTimeout(tick,200); setTimeout(tick,1500); setInterval(function(){ if(phone()&&!document.hidden) place(); },2000);
  window.AMIYO_W35_SIZES=SIZES; try{ window.AMIYO_EDITOR_BUILD="w35-step01-phone-timeline"; }catch(e){}
})();

