/* ==================== Script 1337 id="amiyo-w35-s02" ==================== */
/* W35 step 2: Pro FX engine + Chromatic Aberration. A new effect stack (clip.fxPost) that draws on top of the finished picture, in the preview AND in the export
   (export renders every frame through the same preview). Each effect has sliders. Open it: Tools > Pro FX (or the "Pro FX" chip). Steps 3-7 add Strobe, Echo, Glitch,
   Mosaic and Lens flare to this same window. Chromatic Aberration splits red/green/blue sideways like a cheap lens (amount in pixels, angle, radial option). */
(function(){
  "use strict";
  if(window.W35FX) return;
  var kit=window.amiyoKit; if(!kit) return;
  var REG={}, ORDER=[], scratch=null, tmp=null;
  function mk(w,h){ var c=document.createElement("canvas"); c.width=w; c.height=h; return c; }
  function snap(W,H){ if(!scratch||scratch.width!==W||scratch.height!==H) scratch=mk(W,H); var x=scratch.getContext("2d"); x.setTransform(1,0,0,1,0,0); x.globalCompositeOperation="copy"; x.globalAlpha=1; x.drawImage(viewCanvas,0,0); x.globalCompositeOperation="source-over"; return scratch; }
  function tcv(W,H){ if(!tmp||tmp.width!==W||tmp.height!==H) tmp=mk(W,H); return tmp; }
  function register(d){ if(!REG[d.id]) ORDER.push(d.id); REG[d.id]=d; }
  function defaults(d){ var p={}; d.params.forEach(function(q){ p[q.k]=q.def; }); return p; }
  function stackOf(c){ return Array.isArray(c.fxPost)?c.fxPost:[]; }
  /* ---------- drawing hook ---------- */
  function applyAll(){
    try{
      var cl=[]; var v=window.activeClipAt&&activeClipAt(currentTime,"video"); if(v&&v.clip) cl.push(v.clip);
      var im=window.activeClipAt&&activeClipAt(currentTime,"image"); if(im&&im.clip&&cl.indexOf(im.clip)<0) cl.push(im.clip);
      for(var i=0;i<cl.length;i++){
        var st=stackOf(cl[i]); if(!st.length) continue;
        var local=currentTime-(cl[i].start||0), W=viewCanvas.width, H=viewCanvas.height, c=viewCanvas.getContext("2d");
        for(var j=0;j<st.length;j++){
          var e=st[j]; if(!e||e.enabled===false) continue; var d=REG[e.type]; if(!d) continue;
          c.save(); c.setTransform(1,0,0,1,0,0); c.filter="none"; c.globalAlpha=1; c.globalCompositeOperation="source-over";
          try{ d.draw(c,W,H,Object.assign(defaults(d),e.p||{}),local,cl[i],{snap:snap,tmp:tcv,mk:mk}); }catch(err){ try{ window.__swl&&window.__swl(err); }catch(e2){} }
          c.restore();
        }
      }
    }catch(err){}
  }
  var orf=window.renderPreviewFrame;
  if(typeof orf==="function"&&!orf.__w35fx){
    window.renderPreviewFrame=async function(){ var r=await orf.apply(this,arguments); applyAll(); return r; };
    window.renderPreviewFrame.__w35fx=true;
  }
  /* ---------- selection helpers ---------- */
  function targets(){ var L=kit.sel().map(function(x){ return x.clip; }); if(!L.length){ try{ var f=getClip(); if(f) L=[f.clip]; }catch(e){} } return L.filter(function(c){ return c; }); }
  function add(type){
    var T=targets(); if(!T.length){ kit.say("Select a clip first"); return false; } var d=REG[type]; if(!d) return false;
    kit.edit("Add "+d.label,function(){ T.forEach(function(c){ c.fxPost=stackOf(c).slice(); c.fxPost.push({id:"fp"+Math.random().toString(36).slice(2,9),type:type,enabled:true,p:defaults(d)}); }); });
    redraw(); return true;
  }
  function find(id){ var o=kit.all(); for(var i=0;i<o.length;i++){ var s=stackOf(o[i].clip); for(var j=0;j<s.length;j++) if(s[j].id===id) return {clip:o[i].clip,e:s[j],i:j}; } return null; }
  function remove(id){ var f=find(id); if(!f) return; kit.edit("Remove effect",function(){ f.clip.fxPost.splice(f.i,1); }); redraw(); }
  function toggle(id){ var f=find(id); if(!f) return; kit.edit("Effect on/off",function(){ f.e.enabled=f.e.enabled===false; }); redraw(); }
  function preview(){ try{ renderPreviewFrame(); }catch(e){} }
  /* ---------- sheet ---------- */
  var pend=null;
  function html(){
    var T=targets(), h="";
    h+='<div class="note">'+(T.length?T.length+" clip"+(T.length>1?"s":"")+" selected. Tap an effect to add it; sliders change it live.":"Select a clip on the timeline first.")+'</div><h5>Add effect</h5><div class="g">';
    ORDER.forEach(function(k){ h+='<button type="button" data-k="add:'+k+'">'+kit.esc(REG[k].icon+" "+REG[k].label)+'</button>'; });
    h+='</div>';
    if(T.length){
      var st=stackOf(T[0]);
      h+='<h5>On the first selected clip ('+st.length+')</h5>';
      if(!st.length) h+='<div class="note">No Pro FX on this clip yet.</div>';
      st.forEach(function(e){
        var d=REG[e.type]; if(!d) return;
        h+='<div style="border:1px solid #302c26;border-radius:11px;padding:8px;display:flex;flex-direction:column;gap:6px"><div style="display:flex;gap:6px;align-items:center"><b style="flex:1;font-size:13px">'+kit.esc(d.icon+" "+d.label)+'</b>'+
           '<button type="button" data-k="tg:'+e.id+'" style="min-height:36px">'+(e.enabled===false?"Off":"On")+'</button><button type="button" data-k="rm:'+e.id+'" style="min-height:36px">Remove</button></div>';
        d.params.forEach(function(q){
          var v=(e.p&&e.p[q.k]!=null)?e.p[q.k]:q.def;
          if(q.type==="select"){ h+='<label>'+kit.esc(q.label)+'<select data-fx="'+e.id+'" data-p="'+q.k+'">'+q.opts.map(function(o){ return '<option value="'+o[0]+'"'+(String(o[0])===String(v)?" selected":"")+'>'+kit.esc(o[1])+'</option>'; }).join("")+'</select></label>'; }
          else h+='<label>'+kit.esc(q.label)+': <span data-val="'+e.id+q.k+'">'+v+'</span><input type="range" data-fx="'+e.id+'" data-p="'+q.k+'" min="'+q.min+'" max="'+q.max+'" step="'+q.step+'" value="'+v+'"></label>';
        });
        h+='</div>';
      });
    }
    return h;
  }
  var sh=kit.sheet("w35FxSheet","\u2728 Pro FX",html,function(k,b,api){
    var a=k.split(":"); if(a[0]==="add") add(a[1]); else if(a[0]==="rm") remove(a[1]); else if(a[0]==="tg") toggle(a[1]);
  });
  function redraw(){ if(sh.el.style.display==="flex") sh.paint(); preview(); }
  function slide(ev){
    var t=ev.target; if(!t||!t.getAttribute||!t.getAttribute("data-fx")) return; var f=find(t.getAttribute("data-fx")); if(!f) return;
    if(!pend) pend=deepClone(serializableProject());
    var k=t.getAttribute("data-p"), v=t.tagName==="SELECT"?t.value:parseFloat(t.value); f.e.p=f.e.p||{}; f.e.p[k]=v;
    var lab=sh.el.querySelector('[data-val="'+f.e.id+k+'"]'); if(lab) lab.textContent=v; preview();
    if(ev.type==="change"){ try{ pushHistory("Adjust "+(REG[f.e.type]||{label:"effect"}).label,pend); }catch(e){} pend=null; try{ scheduleAutosave(); }catch(e){} }
  }
  sh.el.addEventListener("input",slide); sh.el.addEventListener("change",slide);
  window.W35FX={register:register,open:function(){ sh.open(); },list:function(){ return ORDER.slice(); },reg:REG,add:add,stack:stackOf,apply:applyAll,defaults:defaults};
  kit.menu("\u2728 Pro FX",function(){ sh.open(); },"Pro FX","W35FX.open()");
  /* ---------- Chromatic Aberration ---------- */
  register({id:"chroma",label:"Chromatic aberration",icon:"\uD83C\uDF08",
    params:[{k:"amount",label:"Amount (px)",min:0,max:40,step:1,def:6},{k:"angle",label:"Angle (degrees)",min:0,max:360,step:5,def:0},{k:"mode",label:"Style",type:"select",def:"line",opts:[["line","Straight line"],["radial","Radial (stronger at the edges)"]]}],
    draw:function(c,W,H,p,t,clip,u){
      var S=u.snap(W,H), T=u.tmp(W,H), x=T.getContext("2d"), a=p.angle*Math.PI/180, cols=["#ff0000","#00ff00","#ff5500"], sgn=[1,0,-1];
      c.globalCompositeOperation="source-over"; c.fillStyle="#000"; c.fillRect(0,0,W,H);
      for(var i=0;i<3;i++){
        x.setTransform(1,0,0,1,0,0); x.globalCompositeOperation="source-over"; x.clearRect(0,0,W,H);
        if(p.mode==="radial"){
          var s=1+sgn[i]*p.amount/Math.max(W,H)*0.9; x.translate(W/2,H/2); x.scale(s,s); x.translate(-W/2,-H/2); x.drawImage(S,0,0);
          x.setTransform(1,0,0,1,0,0);
        } else { x.drawImage(S,Math.cos(a)*p.amount*sgn[i],Math.sin(a)*p.amount*sgn[i]); }
        x.globalCompositeOperation="multiply"; x.fillStyle=cols[i]; x.fillRect(0,0,W,H);
        x.globalCompositeOperation="destination-in"; x.setTransform(1,0,0,1,0,0);
        if(p.mode==="radial"){ var s2=1+sgn[i]*p.amount/Math.max(W,H)*0.9; x.translate(W/2,H/2); x.scale(s2,s2); x.translate(-W/2,-H/2); x.drawImage(S,0,0); x.setTransform(1,0,0,1,0,0); }
        else x.drawImage(S,Math.cos(a)*p.amount*sgn[i],Math.sin(a)*p.amount*sgn[i]);
        c.globalCompositeOperation="lighter"; c.drawImage(T,0,0);
      }
      c.globalCompositeOperation="source-over";
    }});
  try{ window.AMIYO_EDITOR_BUILD="w35-step02-profx-chroma"; }catch(e){}
})();

;
/* ==================== Script 1338 id="amiyo-w35-s03" ==================== */
/* W35 step 3: Strobe. Flashes the picture white or black at a steady rate (flashes per second), with strength and flash length sliders. Added to Tools > Pro FX. */
(function(){
  "use strict";
  if(!window.W35FX||window.W35FX.reg.strobe) return;
  W35FX.register({id:"strobe",label:"Strobe",icon:"\u26A1",
    params:[{k:"rate",label:"Flashes per second",min:1,max:20,step:1,def:4},{k:"strength",label:"Strength (%)",min:5,max:100,step:5,def:80},{k:"length",label:"Flash length (%)",min:5,max:90,step:5,def:25},{k:"color",label:"Flash colour",type:"select",def:"white",opts:[["white","White"],["black","Black"]]}],
    draw:function(c,W,H,p,t){
      var ph=(t*p.rate)%1; if(ph>=p.length/100) return;
      var fade=1-ph/(p.length/100)*0.5; c.globalAlpha=Math.min(1,p.strength/100*fade); c.fillStyle=p.color==="black"?"#000":"#fff"; c.fillRect(0,0,W,H);
    }});
  try{ window.AMIYO_EDITOR_BUILD="w35-step03-strobe"; }catch(e){}
})();

;
/* ==================== Script 1339 id="amiyo-w35-s04" ==================== */
/* W35 step 4: Echo (ghost trails). Lays several fading ghost copies of the picture behind the motion, in a chosen direction. Sliders: copies, spacing, angle, fade, zoom per copy. In Tools > Pro FX. */
(function(){
  "use strict";
  if(!window.W35FX||window.W35FX.reg.echo) return;
  W35FX.register({id:"echo",label:"Echo",icon:"\uD83D\uDC65",
    params:[{k:"copies",label:"Ghost copies",min:1,max:8,step:1,def:3},{k:"spacing",label:"Spacing (px)",min:2,max:120,step:2,def:24},{k:"angle",label:"Direction (degrees)",min:0,max:360,step:5,def:0},{k:"fade",label:"Fade (%)",min:10,max:95,step:5,def:60},{k:"zoom",label:"Zoom per copy (%)",min:-10,max:10,step:1,def:0}],
    draw:function(c,W,H,p,t,clip,u){
      var S=u.snap(W,H), a=p.angle*Math.PI/180; c.globalCompositeOperation="screen";
      for(var i=p.copies;i>=1;i--){
        var al=Math.pow(p.fade/100,i)*0.9, s=1+p.zoom/100*i; c.globalAlpha=al;
        c.save(); c.translate(W/2+Math.cos(a)*p.spacing*i,H/2+Math.sin(a)*p.spacing*i); c.scale(s,s); c.drawImage(S,-W/2,-H/2); c.restore();
      }
      c.globalAlpha=1; c.globalCompositeOperation="source-over";
    }});
  try{ window.AMIYO_EDITOR_BUILD="w35-step04-echo"; }catch(e){}
})();

;
/* ==================== Script 1340 id="amiyo-w35-s05" ==================== */
/* W35 step 5: Glitch. Slides random horizontal strips sideways and splits red/green/blue, in short bursts (how often, how many strips, how far, colour split). Same look every time you play it, so exports match the preview. In Tools > Pro FX. */
(function(){
  "use strict";
  if(!window.W35FX||window.W35FX.reg.glitch) return;
  function rng(seed){ var s=(seed*9301+49297)%233280; return function(){ s=(s*9301+49297)%233280; return s/233280; }; }
  W35FX.register({id:"glitch",label:"Glitch",icon:"\uD83D\uDCFA",
    params:[{k:"often",label:"How often (% of time)",min:5,max:100,step:5,def:50},{k:"strips",label:"Strips",min:1,max:24,step:1,def:8},{k:"shift",label:"Shift distance (%)",min:1,max:30,step:1,def:8},{k:"split",label:"Colour split (px)",min:0,max:24,step:1,def:4},{k:"rate",label:"Changes per second",min:2,max:30,step:1,def:12}],
    draw:function(c,W,H,p,t,clip,u){
      var b=Math.floor(t*p.rate), r=rng(b+7); if(r()>p.often/100) return;
      var S=u.snap(W,H);
      for(var i=0;i<p.strips;i++){
        var y=Math.floor(r()*H), h=Math.max(2,Math.floor((0.01+r()*0.08)*H)), dx=Math.round((r()*2-1)*W*p.shift/100);
        c.drawImage(S,0,y,W,h,dx,y,W,h);
        if(dx>0) c.drawImage(S,W-dx,y,dx,h,0,y,dx,h); else if(dx<0) c.drawImage(S,0,y,-dx,h,W+dx,y,-dx,h);
      }
      if(p.split>0&&W35FX.reg.chroma) W35FX.reg.chroma.draw(c,W,H,{amount:p.split,angle:0,mode:"line"},t,clip,u);
    }});
  try{ window.AMIYO_EDITOR_BUILD="w35-step05-glitch"; }catch(e){}
})();

