/* ==================== Script 1341 id="amiyo-w35-s06" ==================== */
/* W35 step 6: Mosaic (pixelate). Blocks the picture into big squares, over the whole frame or only a box (to hide a face, number plate or screen). Sliders: block size, shape (whole / box / oval), box centre and size. In Tools > Pro FX. */
(function(){
  "use strict";
  if(!window.W35FX||window.W35FX.reg.mosaic) return;
  var small=null;
  W35FX.register({id:"mosaic",label:"Mosaic",icon:"\uD83E\uDDF1",
    params:[{k:"size",label:"Block size (px)",min:4,max:120,step:2,def:20},{k:"shape",label:"Where",type:"select",def:"box",opts:[["all","Whole picture"],["box","Box"],["oval","Oval"]]},{k:"cx",label:"Centre across (%)",min:0,max:100,step:1,def:50},{k:"cy",label:"Centre down (%)",min:0,max:100,step:1,def:50},{k:"w",label:"Width (%)",min:5,max:100,step:1,def:30},{k:"h",label:"Height (%)",min:5,max:100,step:1,def:30}],
    draw:function(c,W,H,p,t,clip,u){
      var S=u.snap(W,H), sw=Math.max(1,Math.round(W/p.size)), sh=Math.max(1,Math.round(H/p.size));
      if(!small) small=document.createElement("canvas"); small.width=sw; small.height=sh;
      var sx=small.getContext("2d"); sx.imageSmoothingEnabled=true; sx.clearRect(0,0,sw,sh); sx.drawImage(S,0,0,sw,sh);
      c.save();
      if(p.shape!=="all"){
        var bw=W*p.w/100, bh=H*p.h/100, bx=W*p.cx/100-bw/2, by=H*p.cy/100-bh/2; c.beginPath();
        if(p.shape==="oval") c.ellipse(bx+bw/2,by+bh/2,bw/2,bh/2,0,0,Math.PI*2); else c.rect(bx,by,bw,bh); c.clip();
      }
      c.imageSmoothingEnabled=false; c.drawImage(small,0,0,sw,sh,0,0,W,H); c.restore();
    }});
  try{ window.AMIYO_EDITOR_BUILD="w35-step06-mosaic"; }catch(e){}
})();

