/* ==================== Script 1342 id="amiyo-w35-s07" ==================== */
/* W35 step 7: Lens flare and light leak. Flare: a bright sun with a ring and ghost dots along a line through the centre. Leak: a warm film-light glow from an edge that slowly pulses. Sliders: position, size, strength, drift. In Tools > Pro FX. */
(function(){
  "use strict";
  if(!window.W35FX||window.W35FX.reg.flare) return;
  function glow(c,x,y,r,col,a){ var g=c.createRadialGradient(x,y,0,x,y,r); g.addColorStop(0,"rgba("+col+","+a+")"); g.addColorStop(1,"rgba("+col+",0)"); c.fillStyle=g; c.fillRect(x-r,y-r,r*2,r*2); }
  W35FX.register({id:"flare",label:"Lens flare / light leak",icon:"\u2600\uFE0F",
    params:[{k:"kind",label:"Look",type:"select",def:"flare",opts:[["flare","Lens flare"],["leak","Warm light leak"]]},{k:"x",label:"Position across (%)",min:0,max:100,step:1,def:75},{k:"y",label:"Position down (%)",min:0,max:100,step:1,def:25},{k:"size",label:"Size (%)",min:10,max:100,step:5,def:50},{k:"power",label:"Strength (%)",min:5,max:100,step:5,def:70},{k:"drift",label:"Drift speed",min:0,max:10,step:1,def:2}],
    draw:function(c,W,H,p,t){
      var m=Math.max(W,H), x=W*p.x/100+Math.sin(t*p.drift*0.6)*W*0.04*(p.drift>0?1:0), y=H*p.y/100+Math.cos(t*p.drift*0.5)*H*0.04*(p.drift>0?1:0), a=p.power/100, r=m*p.size/100;
      c.globalCompositeOperation="screen";
      if(p.kind==="leak"){
        var pulse=0.8+0.2*Math.sin(t*(0.8+p.drift*0.3)); glow(c,x,y,r*1.6,"255,120,40",a*0.8*pulse); glow(c,x,y,r*0.9,"255,200,90",a*0.6*pulse); glow(c,x+r*0.5,y+r*0.2,r*0.7,"255,60,90",a*0.35*pulse);
      } else {
        glow(c,x,y,r*0.9,"255,235,190",a); glow(c,x,y,r*0.18,"255,255,255",Math.min(1,a*1.2));
        c.strokeStyle="rgba(255,220,160,"+(a*0.35)+")"; c.lineWidth=Math.max(2,m*0.004); c.beginPath(); c.arc(x,y,r*0.42,0,Math.PI*2); c.stroke();
        var dx=W/2-x, dy=H/2-y, cols=["120,200,255","255,150,90","170,255,170","255,120,200"], f=[0.5,0.9,1.3,1.8];
        for(var i=0;i<4;i++){ glow(c,x+dx*f[i],y+dy*f[i],r*(0.08+i*0.035),cols[i],a*0.55); }
      }
      c.globalCompositeOperation="source-over";
    }});
  try{ window.AMIYO_EDITOR_BUILD="w35-step07-flare"; }catch(e){}
})();

