/* ==================== Script 1343 id="amiyo-w35-s08" ==================== */
/* W35 step 8: Match Color. Make one clip look like another. 1) Put the playhead on the clip whose look you like and tap "Grab look". 2) Select the clip to fix, put the playhead on it, tap "Match".
   It compares average colour and contrast of the two frames and adds a Match colour effect (in Pro FX, with a Strength slider) to the clip, in the preview AND the export. "Colour only" keeps your contrast. */
(function(){
  "use strict";
  if(!window.W35FX||window.W35FX.reg.match||!window.amiyoKit) return;
  var kit=window.amiyoKit, ref=null, keepContrast=false, cv=null;
  try{ ref=JSON.parse(localStorage.getItem("w35.matchref")||"null"); }catch(e){}
  function clamp(v,a,b){ return v<a?a:v>b?b:v; }
  function stats(){
    var W=96, H=Math.max(1,Math.round(96*viewCanvas.height/viewCanvas.width));
    if(!cv) cv=document.createElement("canvas"); cv.width=W; cv.height=H;
    var x=cv.getContext("2d",{willReadFrequently:true}); x.drawImage(viewCanvas,0,0,W,H);
    var d=x.getImageData(0,0,W,H).data, n=0, s=[0,0,0], q=[0,0,0], i, k;
    for(i=0;i<d.length;i+=4){ if(d[i]+d[i+1]+d[i+2]<12) continue; n++; for(k=0;k<3;k++){ s[k]+=d[i+k]; q[k]+=d[i+k]*d[i+k]; } }
    if(n<50) return null;
    var m=[],sd=[]; for(k=0;k<3;k++){ m[k]=s[k]/n; sd[k]=Math.sqrt(Math.max(0,q[k]/n-m[k]*m[k])); }
    return {m:m,sd:sd};
  }
  function lut(g,o,s){ var L=new Uint8ClampedArray(256); for(var v=0;v<256;v++){ var t=v*g+o; L[v]=v+(t-v)*s; } return L; }
  W35FX.register({id:"match",label:"Match colour",icon:"\uD83C\uDFAF",
    params:[{k:"strength",label:"Strength (%)",min:0,max:100,step:5,def:100}],
    draw:function(c,W,H,p){
      var s=p.strength/100; if(s<=0||p.rg==null) return;
      var im=c.getImageData(0,0,W,H), d=im.data, a=lut(p.rg,p.ro,s), b=lut(p.gg,p.go,s), e=lut(p.bg,p.bo,s);
      for(var i=0;i<d.length;i+=4){ d[i]=a[d[i]]; d[i+1]=b[d[i+1]]; d[i+2]=e[d[i+2]]; }
      c.putImageData(im,0,0);
    }});
  function sw(m){ return '<span style="display:inline-block;width:34px;height:34px;border-radius:8px;border:1px solid #302c26;background:rgb('+m.map(Math.round).join(",")+')"></span>'; }
  function html(){
    var h='<div class="note">Step 1: put the playhead on the clip with the look you like, then tap Grab look. Step 2: select the clip to fix, put the playhead on it, then tap Match.</div>';
    h+='<button type="button" data-k="grab">1. Grab look from playhead</button>';
    h+=ref?'<div style="display:flex;gap:8px;align-items:center">'+sw(ref.m)+'<span class="note">Saved look: average colour of the grabbed frame</span></div>':'<div class="note">No look grabbed yet.</div>';
    h+='<button type="button" data-k="ct">Mode: '+(keepContrast?"Colour only (keep my contrast)":"Colour + contrast")+' (tap to change)</button>';
    h+='<button type="button" data-k="match">2. Match selected clip to this look</button><button type="button" data-k="rm">Remove Match colour from selected clip</button>';
    return h;
  }
  var sh=kit.sheet("w35MatchSheet","\uD83C\uDFAF Match Color",html,function(k,b,api){
    if(k==="grab") grab(); else if(k==="ct"){ keepContrast=!keepContrast; api.paint(); } else if(k==="match") match(); else if(k==="rm") unmatch();
  });
  function grab(){
    var s=stats(); if(!s){ kit.say("Nothing to read here. Move the playhead onto a clip with picture."); return; }
    ref=s; try{ localStorage.setItem("w35.matchref",JSON.stringify(s)); }catch(e){} kit.say("Look grabbed"); sh.paint();
  }
  function target(){
    var T=kit.sel().map(function(x){ return x.clip; }); if(!T.length){ try{ var f=getClip(); if(f) T=[f.clip]; }catch(e){} }
    return T[0]||null;
  }
  function strip(c){ return (Array.isArray(c.fxPost)?c.fxPost:[]).filter(function(e){ return e.type!=="match"; }); }
  async function match(){
    if(!ref){ kit.say("Grab a look first"); return; }
    var c=target(); if(!c){ kit.say("Select the clip to fix first"); return; }
    if(currentTime<c.start||currentTime>c.start+c.duration){ kit.say("Move the playhead onto the selected clip"); return; }
    var old=Array.isArray(c.fxPost)?c.fxPost:[], saved=old.map(function(e){ return e.enabled; });
    old.forEach(function(e){ if(e.type==="match") e.enabled=false; });
    try{ await renderPreviewFrame(); }catch(e){}
    var s=stats(); old.forEach(function(e,i){ e.enabled=saved[i]; });
    if(!s){ kit.say("Nothing to read at the playhead"); return; }
    var p={strength:100};
    ["r","g","b"].forEach(function(n,i){
      var g=keepContrast?1:clamp(ref.sd[i]/Math.max(s.sd[i],4),0.6,1.6);
      p[n+"g"]=+g.toFixed(3); p[n+"o"]=+clamp(ref.m[i]-s.m[i]*g,-80,80).toFixed(1);
    });
    kit.edit("Match colour",function(){ var st=strip(c); st.push({id:"fp"+Math.random().toString(36).slice(2,9),type:"match",enabled:true,p:p}); c.fxPost=st; });
    try{ renderPreviewFrame(); }catch(e){} kit.say("Matched. Lower Strength in Pro FX if it is too much.");
  }
  function unmatch(){ var c=target(); if(!c) return; kit.edit("Remove match colour",function(){ c.fxPost=strip(c); }); try{ renderPreviewFrame(); }catch(e){} kit.say("Match colour removed"); }
  W35FX.matchColor={open:function(){ sh.open(); },grab:grab,match:match,remove:unmatch};
  kit.menu("\uD83C\uDFAF Match Color",function(){ sh.open(); },"Match Color","W35FX.matchColor.open()");
  try{ window.AMIYO_EDITOR_BUILD="w35-step08-match-color"; }catch(e){}
})();

;
/* ==================== Script 1344 id="amiyo-w35-s09" ==================== */
/* W35 step 9: Work Area. A bar on the timeline ruler with two handles (drag them) that marks the part you are working on. Same marks as the I and O keys, so Export In to Out and Render cached preview use it too.
   Sheet: Pr tools > Work Area. Buttons: set from the selected clip, set from the playhead, whole edit, clear. Play it once or loop it. Keys: Alt+L loops the work area, Alt+W opens the sheet. */
(function(){
  "use strict";
  var kit=window.amiyoKit; if(!kit||window.W35WA) return;
  var mode="off", bar=null, hl=null, hr=null, sig="";
  function $(id){ return document.getElementById(id); }
  function end(){ try{ return Math.max(0,window.amiyoContentEnd?window.amiyoContentEnd():getProjectDuration()); }catch(e){ return 0; } }
  function io(){ var r=window.amiyoGetIO?window.amiyoGetIO():{}; var e=end(); return {i:r.i==null?0:r.i,o:r.o==null?e:Math.min(r.o,e),set:r.i!=null||r.o!=null}; }
  function put(i,o){ i=Math.max(0,i); if(o-i<0.2) return; window.amiyoSetIO(+i.toFixed(2),+o.toFixed(2)); }
  function tc(s){ s=Math.max(0,s); var m=Math.floor(s/60); return m+":"+(s%60).toFixed(1).padStart(4,"0"); }
  /* ---- handles on the ruler ---- */
  function mkH(side){
    var h=document.createElement("div"); h.setAttribute("aria-label",side==="l"?"Work area start":"Work area end"); h.setAttribute("role","slider");
    h.style.cssText="position:absolute;top:0;width:22px;height:100%;z-index:6;touch-action:none;cursor:ew-resize;display:none";
    h.innerHTML='<div style="position:absolute;top:2px;bottom:2px;'+(side==="l"?"right":"left")+':0;width:8px;border-radius:'+(side==="l"?"6px 0 0 6px":"0 6px 6px 0")+';background:#ff7a3d"></div>';
    h.addEventListener("pointerdown",function(e){
      e.stopPropagation(); e.preventDefault(); try{ h.setPointerCapture(e.pointerId); }catch(x){}
      var rl=$("ruler"), pps=timeToPx(1)||1;
      function mv(ev){
        var r=rl.getBoundingClientRect(), t=Math.round((ev.clientX-r.left-labelW())/pps*10)/10, c=io();
        if(side==="l") put(Math.min(t,c.o-0.2),c.o); else put(c.i,Math.max(t,c.i+0.2));
        try{ if(!window.__w35WaDrag) window.__w35WaDrag=1; }catch(x){} place();
      }
      function up(){ h.removeEventListener("pointermove",mv); h.removeEventListener("pointerup",up); h.removeEventListener("pointercancel",up); window.__w35WaDrag=0; try{ scheduleAutosave(); }catch(x){} if(sh.el.style.display==="flex") sh.paint(); }
      h.addEventListener("pointermove",mv); h.addEventListener("pointerup",up); h.addEventListener("pointercancel",up);
    });
    return h;
  }
  function place(){
    var rl=$("ruler"); if(!rl) return;
    if(!bar){ bar=document.createElement("div"); bar.id="w35WaBar"; bar.style.cssText="position:absolute;left:0;top:0;height:0;width:0;pointer-events:none"; hl=mkH("l"); hr=mkH("r"); bar.appendChild(hl); bar.appendChild(hr); }
    if(bar.parentNode!==rl) rl.appendChild(bar);
    var c=io(), pps=timeToPx(1), L=labelW(), s=c.set+"|"+c.i+"|"+c.o+"|"+pps+"|"+L; if(s===sig) return; sig=s;
    if(!c.set){ hl.style.display=hr.style.display="none"; return; }
    hl.style.display=hr.style.display="block"; hl.style.pointerEvents=hr.style.pointerEvents="auto";
    hl.style.left=(L+c.i*pps-22)+"px"; hr.style.left=(L+c.o*pps)+"px";
  }
  /* ---- playback inside the work area ---- */
  function watch(){
    place();
    try{
      if(mode!=="off"&&isPlaying){ var c=io(); if(c.set&&currentTime>=c.o-0.02){ window.pause(); if(mode==="loop"){ setCurrentTime(c.i); window.play(); } else { mode="off"; setCurrentTime(c.o); upd(); } } }
    }catch(e){}
    requestAnimationFrame(watch);
  }
  function playWA(m){ var c=io(); if(!c.set){ kit.say("Set the work area first"); return; } mode=m; try{ window.pause(); }catch(e){} setCurrentTime(c.i); window.play(); upd(); }
  /* ---- sheet ---- */
  function html(){
    var c=io(), len=c.o-c.i, h='<div class="note">'+(c.set?"Work area: "+tc(c.i)+" to "+tc(c.o)+" ("+len.toFixed(1)+" s of "+end().toFixed(1)+" s). Drag the orange handles on the ruler to change it.":"No work area set. The whole edit is used. Set one below or with the I and O keys.")+'</div>';
    h+='<button type="button" data-k="clip">Set from selected clip</button><button type="button" data-k="in">Set start at playhead</button><button type="button" data-k="out">Set end at playhead</button>';
    h+='<button type="button" data-k="all">Whole edit</button><button type="button" data-k="clr">Clear work area</button>';
    h+='<button type="button" data-k="once">\u25B6 Play work area once</button><button type="button" data-k="loop">\u21BB Loop work area'+(mode==="loop"?" (on, tap to stop)":"")+'</button>';
    h+='<button type="button" data-k="exp">Export / render this work area\u2026</button>';
    return h;
  }
  var sh=kit.sheet("w35WaSheet","\uD83D\uDCCF Work Area",html,function(k,b,api){
    var c=io();
    if(k==="clip"){ var s=kit.sel(); if(!s.length){ try{ var f=getClip(); if(f) s=[f]; }catch(e){} } if(!s.length){ kit.say("Select a clip first"); return; } var a=1e9,z=0; s.forEach(function(x){ var cl=x.clip||x; a=Math.min(a,cl.start); z=Math.max(z,cl.start+cl.duration); }); put(a,z); }
    else if(k==="in"){ put(currentTime,c.set?Math.max(c.o,currentTime+0.2):end()); }
    else if(k==="out"){ put(c.set?Math.min(c.i,currentTime-0.2):0,currentTime); }
    else if(k==="all"){ put(0,end()); }
    else if(k==="clr"){ window.amiyoSetIO(null,null); mode="off"; }
    else if(k==="once"){ api.close(); playWA("once"); return; }
    else if(k==="loop"){ if(mode==="loop"){ mode="off"; try{ window.pause(); }catch(e){} } else { api.close(); playWA("loop"); return; } }
    else if(k==="exp"){ api.close(); if(window.amiyoRegion) window.amiyoRegion.open(); else kit.say("Use the export Range chips: In to Out"); return; }
    place(); api.paint();
  });
  function upd(){ if(sh.el.style.display==="flex") sh.paint(); }
  window.W35WA={open:function(){ sh.open(); },loop:function(){ playWA(mode==="loop"?"off":"loop"); },get:io,set:put};
  kit.menu("\uD83D\uDCCF Work Area",function(){ sh.open(); },"Work Area","W35WA.open()");
  document.addEventListener("keydown",function(e){
    if(!e.altKey||e.ctrlKey||e.metaKey) return; var t=e.target; if(t&&/INPUT|TEXTAREA|SELECT/.test(t.tagName||"")) return;
    if(e.code==="KeyL"){ e.preventDefault(); if(mode==="loop"){ mode="off"; try{ window.pause(); }catch(x){} upd(); } else playWA("loop"); }
    else if(e.code==="KeyW"){ e.preventDefault(); sh.open(); }
  });
  var ri=window.renderIORange; if(typeof ri==="function"&&!ri.__w35){ window.renderIORange=function(){ var r=ri.apply(this,arguments); sig=""; try{ place(); }catch(e){} return r; }; window.renderIORange.__w35=true; }
  requestAnimationFrame(watch);
  try{ window.AMIYO_EDITOR_BUILD="w35-step09-work-area"; }catch(e){}
})();

;
/* ==================== Script 1345 id="amiyo-w35-s10" ==================== */
/* W35 step 10: Smart auto-duck. Lowers music while someone speaks and brings it back in the pauses. It listens to the real loudness of the voice clips (not just the clip edges),
   so the music comes back between sentences. Pick the voice source, set how far to duck, how quiet counts as silence, and the fade speeds. It writes points on the music clip's Volume line
   (the same line as the old Auto-Duck, so preview, export and editing by hand all work). Open: Pr tools > Smart Duck. */
(function(){
  "use strict";
  var kit=window.amiyoKit; if(!kit||window.W35Duck) return;
  var S={src:"dialogue",db:14,thr:-42,hold:0.6,att:0.25,rel:0.6};
  try{ var sv=JSON.parse(localStorage.getItem("w35.duck")||"null"); if(sv) Object.keys(S).forEach(function(k){ if(sv[k]!=null) S[k]=sv[k]; }); }catch(e){}
  var SRC=[["dialogue","Clips tagged Dialogue"],["audio","All other audio clips"],["video","Video clips' own sound"],["all","All of the above"]];
  var SL=[["db","Duck amount (dB)",4,30,1],["thr","Voice threshold (dB)",-60,-20,1],["hold","Bridge pauses shorter than (s)",0.1,2,0.1],["att","Fade down (s)",0.05,1,0.05],["rel","Fade up (s)",0.1,2,0.1]];
  function clamp(v,a,b){ return v<a?a:v>b?b:v; }
  function musicTargets(){
    var T=kit.sel().map(function(x){ return x.clip; }).filter(function(c){ var t=trackOf(c); return t&&t.kind==="audio"; });
    if(!T.length){ try{ var f=getClip(); if(f&&f.track.kind==="audio") T=[f.clip]; }catch(e){} }
    if(!T.length){ project.tracks.forEach(function(t){ if(t.kind==="audio") t.clips.forEach(function(c){ if((c.soundCategory||"")==="music") T.push(c); }); }); }
    return T;
  }
  function trackOf(c){ for(var i=0;i<project.tracks.length;i++) if(project.tracks[i].clips.indexOf(c)>=0) return project.tracks[i]; return null; }
  function voiceClips(targets){
    var L=[], ids={}; targets.forEach(function(c){ ids[c.id]=1; });
    project.tracks.forEach(function(t){
      if(t.muted||t.hidden) return;
      t.clips.forEach(function(c){
        if(c.off||ids[c.id]||!c.assetId) return; var k=S.src, ok=false;
        if(t.kind==="audio") ok=k==="all"||k==="audio"||(k==="dialogue"&&(c.soundCategory||"")==="dialogue");
        else if(t.kind==="video") ok=k==="video"||k==="all";
        if(ok&&(c.soundCategory||"")!=="music") L.push(c);
      });
    });
    return L;
  }
  /* loudness (dB) of a voice clip every 50 ms of timeline time -> list of [t0,t1] where it is speaking */
  async function spans(c){
    var buf=await decodeClipBuffer(c); if(!buf) return null;
    var d=buf.getChannelData(0), sr=buf.sampleRate, sp=c.speed||1, hop=0.05, n=Math.max(1,Math.floor(c.duration/hop)), db=[], i;
    for(i=0;i<n;i++){
      var a=Math.floor(((c.inPoint||0)+i*hop*sp)*sr), b=Math.min(d.length,Math.floor(((c.inPoint||0)+(i+1)*hop*sp)*sr)); if(b<=a){ db.push(-90); continue; }
      var s=0; for(var j=a;j<b;j++) s+=d[j]*d[j]; var r=Math.sqrt(s/(b-a)); db.push(r>0?20*Math.log10(r):-90);
    }
    var so=db.slice().sort(function(x,y){ return x-y; }), floor=so[Math.floor(so.length*0.1)], thr=Math.max(S.thr,floor+8), out=[], cur=null;
    for(i=0;i<n;i++){
      if(db[i]>thr){ if(!cur) cur=[c.start+i*hop,c.start+(i+1)*hop]; else cur[1]=c.start+(i+1)*hop; } else if(cur){ out.push(cur); cur=null; }
    }
    if(cur) out.push(cur);
    return out;
  }
  function merge(L){
    L.sort(function(a,b){ return a[0]-b[0]; }); var gap=Math.max(S.hold,S.att+S.rel+0.05), o=[];
    L.forEach(function(x){ var l=o[o.length-1]; if(l&&x[0]-l[1]<gap) l[1]=Math.max(l[1],x[1]); else o.push([x[0],x[1]]); });
    return o.filter(function(x){ return x[1]-x[0]>=0.15; });
  }
  function curve(c,sp){
    var base=clamp(c.volume==null?1:c.volume,0,1), dk=base*Math.pow(10,-S.db/20), D=c.duration, pts=[{t:0,v:base}], used=0;
    sp.forEach(function(x){
      var s=x[0]-c.start, e=x[1]-c.start; if(e<=0||s>=D) return; used++;
      var a=clamp(s-S.att,0,D), b=clamp(s,0,D), z=clamp(e,0,D), r=clamp(e+S.rel,0,D);
      pts.push({t:a,v:base}); pts.push({t:b,v:dk}); pts.push({t:z,v:dk}); pts.push({t:r,v:base});
    });
    pts.push({t:D,v:base}); pts.sort(function(p,q){ return p.t-q.t; });
    var m=[]; pts.forEach(function(p){ var l=m[m.length-1]; if(l&&Math.abs(l.t-p.t)<0.01) l.v=Math.min(l.v,p.v); else m.push({t:+p.t.toFixed(3),v:+p.v.toFixed(4)}); });
    return {pts:m,used:used};
  }
  var busy=false;
  async function run(){
    if(busy) return; var T=musicTargets(); if(!T.length){ kit.say("Select the music clip first"); return; }
    var V=voiceClips(T); if(!V.length){ kit.say("No voice clips found for \""+SRC.filter(function(x){ return x[0]===S.src; })[0][1]+"\". Change the voice source."); return; }
    busy=true; kit.say("Listening to the voice\u2026"); var all=[], bad=0;
    try{ for(var i=0;i<V.length;i++){ var r=await spans(V[i]); if(r) all=all.concat(r); else bad++; } }catch(e){ busy=false; kit.say("Could not read the sound"); return; }
    busy=false; var sp=merge(all);
    if(!sp.length){ kit.say(bad===V.length?"Could not read the sound of those clips":"No speech found. Lower the voice threshold."); return; }
    var total=0, hit=0; sp.forEach(function(x){ total+=x[1]-x[0]; });
    kit.edit("Smart duck",function(){ T.forEach(function(c){ var r=curve(c,sp); if(r.used){ c.volumeKeyframes=r.pts; hit++; } }); if(!hit) return false; });
    kit.say(hit?"Ducked "+hit+" music clip"+(hit>1?"s":"")+" under "+sp.length+" voice part"+(sp.length>1?"s":"")+" ("+total.toFixed(1)+" s of speech)":"The voice does not overlap the music clip");
    if(sh.el.style.display==="flex") sh.paint();
  }
  function reset(){
    var T=musicTargets(); if(!T.length){ kit.say("Select the music clip first"); return; }
    kit.edit("Clear ducking",function(){ T.forEach(function(c){ var v=clamp(c.volume==null?1:c.volume,0,1); c.volumeKeyframes=[{t:0,v:v},{t:c.duration,v:v}]; }); });
    kit.say("Volume line reset");
  }
  function html(){
    var h='<div class="note">Select the music clip, choose where the voice is, then tap Duck. The music drops while the voice speaks and comes back in the pauses.</div><h5>Voice is in</h5><div class="g">';
    SRC.forEach(function(x){ h+='<button type="button" data-k="src:'+x[0]+'" style="'+(S.src===x[0]?"outline:2px solid #ff7a3d":"")+'">'+x[1]+'</button>'; });
    h+='</div>';
    SL.forEach(function(q){ h+='<label>'+q[1]+': <span data-dv="'+q[0]+'">'+S[q[0]]+'</span><input type="range" data-ds="'+q[0]+'" min="'+q[2]+'" max="'+q[3]+'" step="'+q[4]+'" value="'+S[q[0]]+'"></label>'; });
    h+='<button type="button" data-k="run"'+(busy?" disabled":"")+'>\uD83C\uDF99 Duck music under voice</button><button type="button" data-k="reset">Reset volume line on the music clip</button>';
    return h;
  }
  var sh=kit.sheet("w35DuckSheet","\uD83C\uDF99 Smart Duck",html,function(k,b,api){
    var a=k.split(":"); if(a[0]==="src"){ S.src=a[1]; save(); api.paint(); } else if(k==="run") run(); else if(k==="reset") reset();
  });
  function save(){ try{ localStorage.setItem("w35.duck",JSON.stringify(S)); }catch(e){} }
  sh.el.addEventListener("input",function(e){ var t=e.target, k=t&&t.getAttribute&&t.getAttribute("data-ds"); if(!k) return; S[k]=parseFloat(t.value); var l=sh.el.querySelector('[data-dv="'+k+'"]'); if(l) l.textContent=S[k]; save(); });
  window.W35Duck={open:function(){ sh.open(); },run:run,reset:reset,settings:S,_curve:curve,_merge:merge};
  kit.menu("\uD83C\uDF99 Smart Duck",function(){ sh.open(); },"Smart Duck","W35Duck.open()");
  try{ window.AMIYO_EDITOR_BUILD="w35-step10-smart-duck"; }catch(e){}
})();

;
/* ==================== Script 1346 id="amiyo-w35-s11" ==================== */
/* W35 step 11: Mirror and Kaleidoscope (Pro FX). Mirror: reflect one half of the picture onto the other (left to right, right to left, top to bottom, bottom to top) or all four corners from the top-left,
   with a slider for where the mirror line sits. Kaleidoscope: repeat one wedge of the picture around a centre point, 2 to 16 segments, with zoom, which part of the picture to use, a centre, and a slow spin.
   Both draw in the preview and the export. Add them in Tools > Pro FX. */
(function(){
  "use strict";
  if(!window.W35FX||window.W35FX.reg.mirror) return;
  W35FX.register({id:"mirror",label:"Mirror",icon:"\uD83E\uDE9E",
    params:[{k:"mode",label:"Direction",type:"select",def:"lr",opts:[["lr","Left side onto right"],["rl","Right side onto left"],["tb","Top onto bottom"],["bt","Bottom onto top"],["quad","Four ways (from top-left)"]]},
            {k:"cx",label:"Line across (%)",min:10,max:90,step:1,def:50},{k:"cy",label:"Line down (%)",min:10,max:90,step:1,def:50}],
    draw:function(c,W,H,p,t,clip,u){
      var S=u.snap(W,H), x=W*p.cx/100, y=H*p.cy/100;
      function part(sx,sy,rx,ry,rw,rh){ c.save(); c.beginPath(); c.rect(rx,ry,rw,rh); c.clip(); c.translate(sx<0?2*x:0,sy<0?2*y:0); c.scale(sx,sy); c.drawImage(S,0,0); c.restore(); }
      if(p.mode==="lr") part(-1,1,x,0,W-x,H);
      else if(p.mode==="rl") part(-1,1,0,0,x,H);
      else if(p.mode==="tb") part(1,-1,0,y,W,H-y);
      else if(p.mode==="bt") part(1,-1,0,0,W,y);
      else { part(-1,1,x,0,W-x,y); part(1,-1,0,y,x,H-y); part(-1,-1,x,y,W-x,H-y); }
    }});
  W35FX.register({id:"kaleido",label:"Kaleidoscope",icon:"\uD83D\uDD2E",
    params:[{k:"segs",label:"Segments",min:2,max:16,step:1,def:6},{k:"zoom",label:"Zoom (%)",min:40,max:300,step:5,def:100},{k:"src",label:"Part of picture to use (degrees)",min:0,max:360,step:5,def:0},
            {k:"spin",label:"Spin (degrees per second)",min:-90,max:90,step:5,def:10},{k:"cx",label:"Centre across (%)",min:0,max:100,step:1,def:50},{k:"cy",label:"Centre down (%)",min:0,max:100,step:1,def:50}],
    draw:function(c,W,H,p,t,clip,u){
      var S=u.snap(W,H), n=Math.round(p.segs), w=Math.PI*2/n, cx=W*p.cx/100, cy=H*p.cy/100, R=Math.sqrt(W*W+H*H), rot=t*p.spin*Math.PI/180, z=p.zoom/100, sa=p.src*Math.PI/180;
      for(var i=0;i<n;i++){
        c.save(); c.translate(cx,cy);
        if(i%2===0) c.rotate(i*w+rot); else { c.rotate((i+1)*w+rot); c.scale(1,-1); }
        c.beginPath(); c.moveTo(0,0); c.arc(0,0,R,-0.003,w+0.003); c.closePath(); c.clip();
        c.rotate(-sa); c.scale(z,z); c.translate(-W/2,-H/2); c.drawImage(S,0,0); c.restore();
      }
    }});
  try{ window.AMIYO_EDITOR_BUILD="w35-step11-mirror-kaleido"; }catch(e){}
})();

;
/* ==================== Script 1347 id="amiyo-w35-s12" ==================== */
/* W35 step 12: Vignette controls (Pro FX). The old Vignette filter has one slider. This one has full control: strength, size (how far the clear middle reaches), softness of the edge, shape (follows the frame or a true circle),
   where the middle is, and the colour (black, white, warm, cool or blue night). Draws in the preview and the export. Add it in Tools > Pro FX. */
(function(){
  "use strict";
  if(!window.W35FX||window.W35FX.reg.vignette2) return;
  var COL={black:"0,0,0",white:"255,255,255",warm:"60,22,4",cool:"4,24,60",night:"8,12,48"};
  W35FX.register({id:"vignette2",label:"Vignette (full control)",icon:"\u26AB",
    params:[{k:"strength",label:"Strength (%)",min:0,max:100,step:1,def:60},{k:"size",label:"Size of the clear middle (%)",min:10,max:150,step:1,def:70},{k:"soft",label:"Edge softness (%)",min:0,max:100,step:1,def:60},
            {k:"shape",label:"Shape",type:"select",def:"frame",opts:[["frame","Follows the frame"],["round","Round circle"]]},
            {k:"cx",label:"Middle across (%)",min:0,max:100,step:1,def:50},{k:"cy",label:"Middle down (%)",min:0,max:100,step:1,def:50},
            {k:"color",label:"Colour",type:"select",def:"black",opts:[["black","Black"],["white","White (fade out)"],["warm","Warm brown"],["cool","Cool blue"],["night","Night blue"]]}],
    draw:function(c,W,H,p){
      var a=p.strength/100; if(a<=0) return;
      var round=p.shape==="round", R=(round?Math.sqrt(W*W+H*H)/2:W*0.7071)*p.size/100, rat=round?1:H/W, inner=R*(1-p.soft/100*0.98), col=COL[p.color]||COL.black;
      var g=c.createRadialGradient(0,0,Math.max(0,inner),0,0,Math.max(inner+1,R));
      g.addColorStop(0,"rgba("+col+",0)"); g.addColorStop(1,"rgba("+col+","+a+")");
      c.save(); c.translate(W*p.cx/100,H*p.cy/100); c.scale(1,rat); c.fillStyle=g; c.fillRect(-W*3,-W*3,W*6,W*6); c.restore();
    }});
  try{ window.AMIYO_EDITOR_BUILD="w35-step12-vignette"; }catch(e){}
})();

