/* ==================== Script 1348 id="amiyo-w35-s13" ==================== */
/* W35 step 13: Cinema bars (Pro FX). Black bars that crop the picture to a film shape: 2.39:1 scope, 2.35, 2:1, 1.85, square, 4:3 or your own ratio. Bars of any colour, a shift to reframe the shot up/down (or left/right),
   and a slide in / slide out time so the bars open at the start of the clip and close at the end. Draws in the preview and the export. Add it in Tools > Pro FX. */
(function(){
  "use strict";
  if(!window.W35FX||window.W35FX.reg.bars) return;
  var COL={black:"#000",white:"#fff",grey:"#1c1c1c"};
  function ease(x){ x=x<0?0:x>1?1:x; return x*x*(3-2*x); }
  W35FX.register({id:"bars",label:"Cinema bars",icon:"\uD83C\uDFAC",
    params:[{k:"ratio",label:"Shape",type:"select",def:"2.39",opts:[["2.39","Scope 2.39:1"],["2.35","Classic 2.35:1"],["2","Univisium 2:1"],["1.85","Flat 1.85:1"],["1.33","Old TV 4:3"],["1","Square 1:1"],["custom","Custom (slider below)"]]},
            {k:"custom",label:"Custom ratio",min:0.5,max:4,step:0.01,def:2.2},
            {k:"shift",label:"Shift picture (%)",min:-100,max:100,step:5,def:0},
            {k:"color",label:"Bar colour",type:"select",def:"black",opts:[["black","Black"],["grey","Dark grey"],["white","White"]]},
            {k:"inT",label:"Slide in (s)",min:0,max:3,step:0.1,def:0},{k:"outT",label:"Slide out (s)",min:0,max:3,step:0.1,def:0}],
    draw:function(c,W,H,p,t,clip){
      var r=p.ratio==="custom"?p.custom:parseFloat(p.ratio), fa=W/H, k=1, D=clip&&clip.duration||0;
      if(p.inT>0) k=Math.min(k,ease(t/p.inT));
      if(p.outT>0&&D>0) k=Math.min(k,ease((D-t)/p.outT));
      if(k<=0) return;
      c.fillStyle=COL[p.color]||COL.black; var sh=p.shift/100;
      if(r>fa){ /* top and bottom bars */
        var bh=(H-W/r)/2, a=bh*(1+sh)*k, b=bh*(1-sh)*k; if(a>0) c.fillRect(0,0,W,a); if(b>0) c.fillRect(0,H-b,W,b);
      } else if(r<fa){ /* side bars */
        var bw=(W-H*r)/2, l=bw*(1+sh)*k, q=bw*(1-sh)*k; if(l>0) c.fillRect(0,0,l,H); if(q>0) c.fillRect(W-q,0,q,H);
      }
    }});
  try{ window.AMIYO_EDITOR_BUILD="w35-step13-cinema-bars"; }catch(e){}
})();

