/* ==================== Script 1349 id="amiyo-w35-s14" ==================== */
/* W35 step 14: Camera shake (Pro FX) + shared helpers used by steps 15 to 20. Shake moves, tilts and zooms the picture with smooth random wobble: amount, tilt, speed, roughness and a seed (same look every play,
   so the export matches the preview). "Zoom to hide edges" keeps the borders from showing. Add it in Tools > Pro FX. */
(function(){
  "use strict";
  if(!window.W35FX||window.W35FX.reg.shake) return; var kit=window.amiyoKit;
  function rid(){ return "fp"+Math.random().toString(36).slice(2,9); }
  var U=W35FX.utils={
    targets:function(){ var L=kit.sel().map(function(x){ return x.clip; }); if(!L.length){ try{ var f=getClip(); if(f) L=[f.clip]; }catch(e){} } return L.filter(function(c){ return c; }); },
    entry:function(type,over){ var d=W35FX.reg[type]; if(!d) return null; return {id:rid(),type:type,enabled:true,p:Object.assign(W35FX.defaults(d),over||{})}; },
    /* entries: array, or function(clip) returning an array. Adds to the stack, or replaces it. One undo step. */
    put:function(clips,entries,replace,label){
      if(!clips.length){ kit.say("Select a clip first"); return false; }
      kit.edit(label,function(){ clips.forEach(function(c){
        var base=replace?[]:(Array.isArray(c.fxPost)?c.fxPost.slice():[]), L=typeof entries==="function"?entries(c):entries;
        (L||[]).forEach(function(e){ if(e&&W35FX.reg[e.type]) base.push({id:rid(),type:e.type,enabled:e.enabled!==false,p:Object.assign({},e.p)}); });
        c.fxPost=base; }); });
      try{ renderPreviewFrame(); }catch(e){} return true;
    },
    clips:function(){ var o=[]; project.tracks.forEach(function(t){ t.clips.forEach(function(c){ o.push({t:t,c:c}); }); }); return o; },
    name:function(c){ var a=null; try{ a=getAsset(c.assetId); }catch(e){} return (a&&a.name)||c.name||c.label||("clip "+String(c.id||"").slice(-4)); },
    esc:function(s){ return kit.esc?kit.esc(s):String(s).replace(/[&<>"]/g,function(m){ return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[m]; }); }
  };
  W35FX.register({id:"shake",label:"Camera shake",icon:"\uD83D\uDCF3",
    params:[{k:"amount",label:"Movement (px)",min:0,max:80,step:1,def:12},{k:"rot",label:"Tilt (degrees)",min:0,max:6,step:0.1,def:0.8},{k:"speed",label:"Speed (wobbles per second)",min:0.5,max:12,step:0.5,def:4},
            {k:"rough",label:"Roughness (1 smooth to 4 jittery)",min:1,max:4,step:1,def:2},{k:"seed",label:"Seed (change for a different shake)",min:1,max:99,step:1,def:7},
            {k:"fill",label:"Edges",type:"select",def:"zoom",opts:[["zoom","Zoom in to hide edges"],["none","Leave edges"]]}],
    draw:function(c,W,H,p,t,clip,u){
      var S=u.snap(W,H);
      function n(ch){ var v=0,a=1,f=1,tot=0; for(var o=0;o<p.rough;o++){ v+=a*Math.sin(Math.PI*2*t*p.speed*f+p.seed*37.7+ch*91.3+o*17.1); tot+=a; a*=0.55; f*=2.13; } return v/tot; }
      var dx=n(1)*p.amount, dy=n(2)*p.amount, r=n(3)*p.rot*Math.PI/180, z=1;
      if(p.fill==="zoom") z=1+(2*p.amount+p.rot*Math.PI/180*Math.max(W,H))/Math.min(W,H);
      c.save(); c.translate(W/2+dx,H/2+dy); c.rotate(r); c.scale(z,z); c.drawImage(S,-W/2,-H/2); c.restore();
    }});
  try{ window.AMIYO_EDITOR_BUILD="w35-step14-camera-shake"; }catch(e){}
})();

;
/* ==================== Script 1350 id="amiyo-w35-s15" ==================== */
/* W35 step 15: Punch-in zoom presets (Pro FX + sheet). Quick zoom effects: Punch (snap in), Big punch, Punch and release, Slow push-in, Pull-out, Beat pulse (zooms on every beat of a BPM).
   Open Pr tools > Punch-in. Put the playhead where the punch should land, select the clip(s), tap a preset. It becomes a Punch zoom effect in Pro FX where you can fine-tune every number. */
(function(){
  "use strict";
  if(!window.W35FX||window.W35FX.reg.punch||!W35FX.utils) return; var kit=window.amiyoKit, U=W35FX.utils;
  function cl(x){ return x<0?0:x>1?1:x; }
  function eo(x){ x=cl(x); return 1-Math.pow(1-x,3); }
  W35FX.register({id:"punch",label:"Punch zoom",icon:"\uD83D\uDD0D",
    params:[{k:"kind",label:"Type",type:"select",def:"punch",opts:[["punch","Punch in (snap)"],["push","Slow push-in"],["pull","Slow pull-out"],["pulse","Beat pulse"]]},
            {k:"amount",label:"Zoom amount (%)",min:2,max:100,step:1,def:20},{k:"start",label:"Starts at (s into clip)",min:0,max:60,step:0.1,def:0},{k:"dur",label:"Snap time (s)",min:0.05,max:5,step:0.05,def:0.2},
            {k:"hold",label:"Hold then release (s, 0 = stay)",min:0,max:20,step:0.1,def:0},{k:"bpm",label:"Beats per minute",min:40,max:200,step:1,def:120},
            {k:"cx",label:"Zoom centre across (%)",min:0,max:100,step:1,def:50},{k:"cy",label:"Zoom centre down (%)",min:0,max:100,step:1,def:50}],
    draw:function(c,W,H,p,t,clip,u){
      var a=p.amount/100, D=(clip&&clip.duration)||10, s=1, k;
      if(p.kind==="punch"){ if(t>=p.start){ k=eo((t-p.start)/p.dur); if(p.hold>0){ var o=t-p.start-p.hold; if(o>0) k*=1-eo(o/p.dur); } s=1+a*k; } }
      else if(p.kind==="push"){ k=cl((t-p.start)/Math.max(0.1,D-p.start)); s=1+a*k; }
      else if(p.kind==="pull"){ k=cl((t-p.start)/Math.max(0.1,D-p.start)); s=1+a*(1-k); }
      else { var ph=(t*p.bpm/60)%1; s=1+a*Math.pow(1-ph,3); }
      if(s<1.0005) return; var S=u.snap(W,H), x=W*p.cx/100, y=H*p.cy/100;
      c.save(); c.translate(x,y); c.scale(s,s); c.translate(-x,-y); c.drawImage(S,0,0); c.restore();
    }});
  var PRE=[["Punch in",{kind:"punch",amount:20,dur:0.2,hold:0}],["Big punch",{kind:"punch",amount:40,dur:0.15,hold:0}],["Punch and release",{kind:"punch",amount:25,dur:0.2,hold:0.8}],
           ["Slow push-in",{kind:"push",amount:15,dur:0.2}],["Slow pull-out",{kind:"pull",amount:15,dur:0.2}],["Beat pulse (120 BPM)",{kind:"pulse",amount:6,bpm:120}]];
  function html(){
    var h='<div class="note">Put the playhead where the punch should land, select the clip, then tap a preset. Fine-tune it later in Tools > Pro FX.</div>';
    PRE.forEach(function(x,i){ h+='<button type="button" data-k="p:'+i+'">'+x[0]+'</button>'; }); return h;
  }
  var sh=kit.sheet("w35PunchSheet","\uD83D\uDD0D Punch-in zoom",html,function(k,b,api){
    var i=parseInt(k.split(":")[1],10), P=PRE[i]; if(!P) return; var T=U.targets();
    if(U.put(T,function(c){ var o=Object.assign({},P[1]); o.start=Math.max(0,Math.min(c.duration,+(currentTime-c.start).toFixed(1))); return [U.entry("punch",o)]; },false,"Add "+P[0])){ kit.say(P[0]+" added"); api.close(); }
  });
  window.W35Punch={open:function(){ sh.open(); },presets:PRE};
  kit.menu("\uD83D\uDD0D Punch-in zoom",function(){ sh.open(); },"Punch-in zoom","W35Punch.open()");
  try{ window.AMIYO_EDITOR_BUILD="w35-step15-punch-in"; }catch(e){}
})();

;
/* ==================== Script 1351 id="amiyo-w35-s16" ==================== */
/* W35 step 16: Duotone and colorize (Pro FX). Duotone maps the dark parts of the picture to one colour and the light parts to another (ready palettes, or pick two hues). Colorize tints the whole picture with one colour
   while keeping its light and dark. Sliders: strength, contrast, saturation. Draws in the preview and the export. Add it in Tools > Pro FX. */
(function(){
  "use strict";
  if(!window.W35FX||window.W35FX.reg.duotone) return;
  var PAL={midnight:["Midnight and gold",[10,10,40],[255,190,120]],sunset:["Sunset",[40,10,60],[255,160,90]],teal:["Teal and orange",[8,40,50],[255,170,90]],blue:["Mono blue",[5,10,30],[160,200,255]],
           sepia:["Sepia",[30,16,6],[240,214,170]],neon:["Neon pink and cyan",[60,0,90],[0,255,230]],term:["Terminal green",[0,12,4],[120,255,150]],bw:["Black and white",[0,0,0],[255,255,255]]};
  function hsl(h,s,l){ var a=s*Math.min(l,1-l); function f(n){ var k=(n+h/30)%12; return Math.round(255*(l-a*Math.max(-1,Math.min(k-3,9-k,1)))); } return [f(0),f(8),f(4)]; }
  var cache={};
  function lut(p){
    var d,l,key=[p.pal,p.sh,p.lh,p.sat,p.mode,p.contrast].join("|"); if(cache[key]) return cache[key];
    if(p.pal==="custom"){ d=hsl(p.sh,p.sat/100,0.12); l=hsl(p.lh,p.sat/100,0.78); } else { var q=PAL[p.pal]||PAL.midnight; d=q[1]; l=q[2]; }
    var R=new Float32Array(256),G=new Float32Array(256),B=new Float32Array(256), mid=[(d[0]+l[0])/2,(d[1]+l[1])/2,(d[2]+l[2])/2];
    if(p.mode==="colorize"){ var tint=p.pal==="custom"?hsl(p.lh,p.sat/100,0.5):l; mid=tint; }
    for(var i=0;i<256;i++){
      var x=Math.max(0,Math.min(1,((i-128)*p.contrast/100+128)/255)), r,g,b;
      if(p.mode==="colorize"){ if(x<0.5){ var y=x*2; r=mid[0]*y; g=mid[1]*y; b=mid[2]*y; } else { var z=(x-0.5)*2; r=mid[0]+(255-mid[0])*z; g=mid[1]+(255-mid[1])*z; b=mid[2]+(255-mid[2])*z; } }
      else { r=d[0]+(l[0]-d[0])*x; g=d[1]+(l[1]-d[1])*x; b=d[2]+(l[2]-d[2])*x; }
      R[i]=r; G[i]=g; B[i]=b;
    }
    var o={R:R,G:G,B:B}; cache={}; cache[key]=o; return o;
  }
  var PO=Object.keys(PAL).map(function(k){ return [k,PAL[k][0]]; }); PO.push(["custom","Custom (use the hue sliders)"]);
  W35FX.register({id:"duotone",label:"Duotone / colorize",icon:"\uD83C\uDFA8",
    params:[{k:"mode",label:"Look",type:"select",def:"duotone",opts:[["duotone","Duotone (two colours)"],["colorize","Colorize (one tint)"]]},{k:"pal",label:"Palette",type:"select",def:"midnight",opts:PO},
            {k:"sh",label:"Custom: dark hue",min:0,max:360,step:5,def:230},{k:"lh",label:"Custom: light hue (also the tint)",min:0,max:360,step:5,def:40},{k:"sat",label:"Custom: saturation (%)",min:0,max:100,step:5,def:70},
            {k:"contrast",label:"Contrast (%)",min:50,max:200,step:5,def:100},{k:"strength",label:"Strength (%)",min:0,max:100,step:5,def:100}],
    draw:function(c,W,H,p){
      var s=p.strength/100; if(s<=0) return; var L=lut(p), im=c.getImageData(0,0,W,H), d=im.data, i, y, r, g, b;
      for(i=0;i<d.length;i+=4){ r=d[i]; g=d[i+1]; b=d[i+2]; y=(r*0.299+g*0.587+b*0.114)|0; d[i]=r+(L.R[y]-r)*s; d[i+1]=g+(L.G[y]-g)*s; d[i+2]=b+(L.B[y]-b)*s; }
      c.putImageData(im,0,0);
    }});
  try{ window.AMIYO_EDITOR_BUILD="w35-step16-duotone"; }catch(e){}
})();

