/* ==================== Script 1352 id="amiyo-w35-s17" ==================== */
/* W35 step 17: Bloom (Pro FX). A soft glow around the bright parts of the picture. Sliders: threshold (how bright counts), strength, size of the glow, and a glow tint (none, warm, cool, pink).
   Works on a shrunk copy of the picture so it stays quick. Draws in the preview and the export. Add it in Tools > Pro FX. */
(function(){
  "use strict";
  if(!window.W35FX||window.W35FX.reg.bloom) return;
  var pool={}, TINT={none:[1,1,1],warm:[1,0.82,0.55],cool:[0.65,0.85,1],pink:[1,0.55,0.85]};
  function cv(k,w,h){ var c=pool[k]; if(!c) c=pool[k]=document.createElement("canvas"); if(c.width!==w||c.height!==h){ c.width=w; c.height=h; } return c; }
  function shrink(S,W,H,tw,th,slot){
    var cur=S, cw=W, ch=H, i=0, n, x;
    while(cw>tw*2){ var nw=Math.max(tw,Math.ceil(cw/2)), nh=Math.max(th,Math.ceil(ch/2)); n=cv(slot+i,nw,nh); x=n.getContext("2d"); x.clearRect(0,0,nw,nh); x.imageSmoothingEnabled=true; x.drawImage(cur,0,0,cw,ch,0,0,nw,nh); cur=n; cw=nw; ch=nh; i++; }
    if(cw!==tw||ch!==th){ n=cv(slot+"f",tw,th); x=n.getContext("2d"); x.clearRect(0,0,tw,th); x.imageSmoothingEnabled=true; x.drawImage(cur,0,0,cw,ch,0,0,tw,th); cur=n; }
    return cur;
  }
  W35FX.register({id:"bloom",label:"Bloom (glow)",icon:"\u2728",
    params:[{k:"thr",label:"Threshold (how bright counts, %)",min:20,max:95,step:1,def:68},{k:"strength",label:"Strength (%)",min:0,max:100,step:1,def:60},{k:"radius",label:"Glow size (1 tight to 4 wide)",min:1,max:4,step:1,def:2},
            {k:"tint",label:"Glow tint",type:"select",def:"none",opts:[["none","None (picture colours)"],["warm","Warm"],["cool","Cool"],["pink","Pink"]]}],
    draw:function(c,W,H,p,t,clip,u){
      if(p.strength<=0) return;
      var S=u.snap(W,H), tw=Math.max(8,Math.round(W/(8*p.radius))), th=Math.max(4,Math.round(tw*H/W));
      var A=shrink(S,W,H,tw,th,"a"), ax=A.getContext("2d"), im=ax.getImageData(0,0,tw,th), d=im.data, thr=p.thr/100*255, tn=TINT[p.tint]||TINT.none, i, m, f;
      for(i=0;i<d.length;i+=4){ m=Math.max(d[i],d[i+1],d[i+2]); f=m<=thr?0:(m-thr)/(255-thr+1e-6); d[i]*=f*tn[0]; d[i+1]*=f*tn[1]; d[i+2]*=f*tn[2]; }
      ax.putImageData(im,0,0);
      var B=shrink(A,tw,th,Math.max(4,Math.round(tw/4)),Math.max(3,Math.round(th/4)),"b");
      c.save(); c.imageSmoothingEnabled=true; try{ c.imageSmoothingQuality="high"; }catch(e){}
      c.globalCompositeOperation="screen"; c.globalAlpha=Math.min(1,p.strength/100*1.2); c.drawImage(B,0,0,W,H); c.globalAlpha=Math.min(1,p.strength/100*0.8); c.drawImage(A,0,0,W,H); c.restore();
    }});
  try{ window.AMIYO_EDITOR_BUILD="w35-step17-bloom"; }catch(e){}
})();

