/* ==================== Script 1353 id="amiyo-w35-s18" ==================== */
/* W35 step 18: Effect-stack presets. Save the Pro FX stack of one clip as a named preset and apply it to many clips at once (add to what they have, or replace). Six ready looks are included
   (VHS tape, Cinema look, Dream glow, Night blue, Retro film, Music-video punch). Open: Pr tools > FX Presets. Your own presets are kept in this browser. */
(function(){
  "use strict";
  if(!window.W35FX||window.W35FX.presets||!W35FX.utils) return; var kit=window.amiyoKit, U=W35FX.utils, KEY="w35.fxpresets";
  var BUILT=[
    ["VHS tape",[["chroma",{amount:4}],["glitch",{often:25,strips:5,shift:4,split:3}],["vignette2",{strength:45}]]],
    ["Cinema look",[["bars",{ratio:"2.39"}],["vignette2",{strength:55,size:80}],["bloom",{thr:75,strength:35}]]],
    ["Dream glow",[["bloom",{thr:55,strength:80,radius:3}],["vignette2",{strength:35,color:"warm"}]]],
    ["Night blue",[["duotone",{pal:"midnight",strength:70}],["vignette2",{strength:60,color:"night"}]]],
    ["Retro film",[["duotone",{pal:"sepia",strength:60}],["vignette2",{strength:65}],["shake",{amount:3,rot:0.2,speed:3}]]],
    ["Music-video punch",[["punch",{kind:"pulse",amount:6,bpm:120}],["chroma",{amount:3}],["bloom",{strength:40}]]]
  ].map(function(b){ return {name:b[0],built:true,stack:b[1].map(function(e){ return {type:e[0],enabled:true,p:e[1]}; })}; });
  function mine(){ try{ var a=JSON.parse(localStorage.getItem(KEY)||"[]"); return Array.isArray(a)?a:[]; }catch(e){ return []; } }
  function store(a){ try{ localStorage.setItem(KEY,JSON.stringify(a)); }catch(e){ kit.say("Could not save the preset in this browser"); } }
  function all(){ return mine().concat(BUILT); }
  function stackOf(c){ return (Array.isArray(c.fxPost)?c.fxPost:[]).map(function(e){ return {type:e.type,enabled:e.enabled!==false,p:Object.assign({},e.p)}; }); }
  function html(){
    var T=U.targets(), h='<div class="note">'+(T.length?T.length+" clip"+(T.length>1?"s":"")+" selected.":"Select one or more clips first.")+' Add keeps what the clips already have; Replace swaps their Pro FX for the preset.</div>';
    h+='<button type="button" data-k="save">Save selected clip\'s Pro FX as a preset\u2026</button>';
    var L=all(); L.forEach(function(p,i){
      var names=p.stack.map(function(e){ var d=W35FX.reg[e.type]; return d?d.label:e.type; }).join(", ");
      h+='<div style="border:1px solid #302c26;border-radius:11px;padding:8px;display:flex;flex-direction:column;gap:6px"><b style="font-size:13px">'+U.esc(p.name)+(p.built?"":" (yours)")+'</b><span class="note">'+U.esc(names||"empty")+'</span>'+
         '<div style="display:flex;gap:6px"><button type="button" data-k="add:'+i+'" style="flex:1;min-height:40px">Add</button><button type="button" data-k="rep:'+i+'" style="flex:1;min-height:40px">Replace</button>'+(p.built?"":'<button type="button" data-k="del:'+i+'" style="min-height:40px">Delete</button>')+'</div></div>';
    });
    return h;
  }
  var sh=kit.sheet("w35PresetSheet","\uD83C\uDF9B FX Presets",html,function(k,b,api){
    var a=k.split(":"), L=all();
    if(a[0]==="save"){
      var T=U.targets(); if(!T.length||!stackOf(T[0]).length){ kit.say("Select a clip that has Pro FX first"); return; }
      var n=(window.prompt("Name for this preset","My look")||"").trim(); if(!n) return;
      var m=mine().filter(function(p){ return p.name!==n; }); m.unshift({name:n,stack:stackOf(T[0])}); store(m); kit.say("Preset saved"); api.paint(); return;
    }
    var p=L[parseInt(a[1],10)]; if(!p) return;
    if(a[0]==="del"){ var mm=mine(); mm.splice(parseInt(a[1],10),1); store(mm); api.paint(); return; }
    var T2=U.targets(); if(U.put(T2,p.stack,a[0]==="rep","Preset: "+p.name)){ kit.say(p.name+" applied to "+T2.length+" clip"+(T2.length>1?"s":"")); api.paint(); }
  });
  window.W35FX.presets={open:function(){ sh.open(); },builtin:BUILT,mine:mine};
  kit.menu("\uD83C\uDF9B FX Presets",function(){ sh.open(); },"FX Presets","W35FX.presets.open()");
  try{ window.AMIYO_EDITOR_BUILD="w35-step18-fx-presets"; }catch(e){}
})();

