/* ==================== Script 1354 id="amiyo-w35-s19" ==================== */
/* W35 step 19: Copy, paste and reset effects, plus an effects report. Copy the Pro FX of one clip, paste onto other clips (add or replace), reset to defaults, clear, or switch all on/off.
   The report lists every clip that has Pro FX with its settings and a load rating (light / medium / heavy) so you know what will play slowly or export slowly. Open: Pr tools > FX Copy and Report. */
(function(){
  "use strict";
  if(!window.W35FX||window.W35FX.report||!W35FX.utils) return; var kit=window.amiyoKit, U=W35FX.utils, KEY="w35.fxclip", clip=null;
  try{ clip=JSON.parse(localStorage.getItem(KEY)||"null"); }catch(e){}
  var COST={bloom:4,kaleido:3,echo:3,glitch:2,chroma:2,match:2,duotone:2,mosaic:1,mirror:1,shake:1,punch:1,vignette2:1,flare:1,strobe:0.5,bars:0.5};
  function stackOf(c){ return Array.isArray(c.fxPost)?c.fxPost:[]; }
  function load(c){ var s=0; stackOf(c).forEach(function(e){ if(e.enabled!==false) s+=COST[e.type]||1; }); return s; }
  function rating(s){ return s>=8?"heavy":s>=4?"medium":"light"; }
  function summary(e){
    var d=W35FX.reg[e.type]; if(!d) return e.type+" (unknown)";
    var bits=d.params.slice(0,3).map(function(q){ var v=e.p&&e.p[q.k]!=null?e.p[q.k]:q.def; if(q.type==="select"){ var o=q.opts.filter(function(x){ return String(x[0])===String(v); })[0]; v=o?o[1]:v; } return q.label.split(" (")[0]+" "+v; });
    return d.label+(e.enabled===false?" [off]":"")+": "+bits.join(", ");
  }
  function lines(){
    var out=[], clips=0, fx=0, off=0, heavy=0;
    U.clips().forEach(function(x){ var st=stackOf(x.c); if(!st.length) return; clips++; fx+=st.length; st.forEach(function(e){ if(e.enabled===false) off++; }); var s=load(x.c); if(s>=8) heavy++;
      out.push({head:(x.t.name||x.t.id||"track")+" \u00B7 "+U.name(x.c)+" \u00B7 "+x.c.start.toFixed(1)+" s to "+(x.c.start+x.c.duration).toFixed(1)+" s \u00B7 "+rating(s),items:st.map(summary)}); });
    return {out:out,clips:clips,fx:fx,off:off,heavy:heavy};
  }
  function text(){ var r=lines(), t="Pro FX report\n"+r.clips+" clips, "+r.fx+" effects ("+r.off+" off), "+r.heavy+" heavy clips\n"; r.out.forEach(function(l){ t+="\n"+l.head+"\n"; l.items.forEach(function(i){ t+="  - "+i+"\n"; }); }); return t; }
  function html(){
    var T=U.targets(), r=lines(), h='<div class="note">'+(T.length?T.length+" clip"+(T.length>1?"s":"")+" selected.":"Select clips first.")+(clip?" Clipboard: "+clip.length+" effect"+(clip.length>1?"s":"")+".":" Clipboard is empty.")+'</div>';
    h+='<button type="button" data-k="copy">Copy Pro FX from selected clip</button><button type="button" data-k="padd">Paste (add to selected clips)</button><button type="button" data-k="prep">Paste (replace on selected clips)</button>';
    h+='<button type="button" data-k="defs">Reset all settings to defaults (selected)</button><button type="button" data-k="on">Switch all on (selected)</button><button type="button" data-k="offall">Switch all off (selected)</button><button type="button" data-k="clear">Remove all Pro FX (selected)</button>';
    h+='<h5>Effects report</h5><div class="note">'+r.clips+" clip"+(r.clips===1?"":"s")+" with Pro FX, "+r.fx+" effect"+(r.fx===1?"":"s")+" ("+r.off+" off), "+r.heavy+" heavy.</div>";
    r.out.forEach(function(l){ h+='<div style="border:1px solid #302c26;border-radius:11px;padding:8px;font-size:12px;line-height:1.5"><b>'+U.esc(l.head)+'</b><br>'+l.items.map(U.esc).join("<br>")+'</div>'; });
    h+='<button type="button" data-k="rep">Copy this report as text</button>'; return h;
  }
  var sh=kit.sheet("w35FxReportSheet","\uD83D\uDCCB FX Copy and Report",html,function(k,b,api){
    var T=U.targets();
    if(k==="copy"){ if(!T.length||!stackOf(T[0]).length){ kit.say("Select a clip that has Pro FX"); return; } clip=stackOf(T[0]).map(function(e){ return {type:e.type,enabled:e.enabled!==false,p:Object.assign({},e.p)}; }); try{ localStorage.setItem(KEY,JSON.stringify(clip)); }catch(e){} kit.say("Copied "+clip.length+" effect"+(clip.length>1?"s":"")); }
    else if(k==="padd"||k==="prep"){ if(!clip||!clip.length){ kit.say("Nothing copied yet"); return; } U.put(T,clip,k==="prep","Paste Pro FX"); }
    else if(!T.length){ kit.say("Select a clip first"); return; }
    else if(k==="defs"){ kit.edit("Reset Pro FX settings",function(){ T.forEach(function(c){ c.fxPost=stackOf(c).filter(function(e){ return e.type!=="match"; }).map(function(e){ var d=W35FX.reg[e.type]; return d?{id:e.id,type:e.type,enabled:e.enabled!==false,p:W35FX.defaults(d)}:e; }); }); }); try{ renderPreviewFrame(); }catch(e){} kit.say("Settings reset"); }
    else if(k==="on"||k==="offall"){ kit.edit("Pro FX on/off",function(){ T.forEach(function(c){ stackOf(c).forEach(function(e){ e.enabled=k==="on"; }); }); }); try{ renderPreviewFrame(); }catch(e){} }
    else if(k==="clear"){ kit.edit("Remove all Pro FX",function(){ T.forEach(function(c){ c.fxPost=[]; }); }); try{ renderPreviewFrame(); }catch(e){} kit.say("Pro FX removed"); }
    else if(k==="rep"){ try{ navigator.clipboard.writeText(text()); kit.say("Report copied"); }catch(e){ kit.say("Could not copy. Select the text instead."); } return; }
    api.paint();
  });
  window.W35FX.report={open:function(){ sh.open(); },text:text,lines:lines,load:load,rating:rating};
  kit.menu("\uD83D\uDCCB FX Copy and Report",function(){ sh.open(); },"FX Copy and Report","W35FX.report.open()");
  try{ window.AMIYO_EDITOR_BUILD="w35-step19-fx-copy-report"; }catch(e){}
})();

