/* ==================== Script 1364 id="amiyo-export6-s09-range-parts-fixes" ==================== */
/* Export plan 2026-11, step 9 of 20 (Range and parts): three faults fixed.
   (1) A long edit (over 15 min) opens with 10-minute parts already chosen, but the "Will make" line, the size estimate and the "each file up to" figure still said "one file" until a part button was tapped, so the line showed one huge file while the export made several. The line is now refreshed as soon as the dialog opens.
   (2) A negative custom time such as -5 was quietly turned into 0:00; the range line now says so.
   (3) With only an In point (or only an Out point) set, the dialog said "Exports the whole edit" without a word; a hint now says the point is not used yet and which button uses it. */
(function(){ "use strict";
  function $(i){ return document.getElementById(i); }
  function io(){ try{ return window.amiyoGetIO?window.amiyoGetIO():{i:null,o:null}; }catch(e){ return {i:null,o:null}; } }
  function tc(s){ s=Math.max(0,+s||0); var m=Math.floor(s/60), x=s-m*60; return m+":"+(x<10?"0":"")+x.toFixed(x%1?1:0); }
  function selected(box){ if(!box) return null; return [].slice.call(box.querySelectorAll(".chip")).filter(function(c){ return /solid/.test(c.style.outline||""); })[0]||null; }
  function hint(){
    var info=$("expRangeInfo"); if(!info) return; var h=$("expIOHint");
    if(!h){ h=document.createElement("div"); h.id="expIOHint"; h.setAttribute("aria-live","polite"); h.style.cssText="font-size:11px;color:var(--warn,#f0c36a);margin:-4px 0 8px"; info.parentNode.insertBefore(h,info.nextSibling); }
    var g=io(), one=(g.i!=null)!==(g.o!=null), using=!!window.__amiyoXRange;
    h.textContent=(one&&!using)?("Only an "+(g.i!=null?"In point at "+tc(g.i):"Out point at "+tc(g.o))+" is set, so it is not used yet. Choose In → Out to export from there."):"";
  }
  function wire(){
    var box=$("expRange"); if(!box||box.dataset.s9) return; box.dataset.s9="1";
    box.addEventListener("click",function(){ setTimeout(hint,60); });
    var cu=$("expRangeCustom");
    if(cu) cu.addEventListener("change",function(){
      var a=String($("expRFrom").value||"").trim(), b=String($("expRTo").value||"").trim();
      if(/^-/.test(a)||/^-/.test(b)){ var i=$("expRangeInfo"); if(i&&window.__amiyoXRange) i.textContent+=" A time below 0 counts as 0:00."; }
    });
    hint();
  }
  function fixLine(){
    var parts=$("expParts"), on=selected(parts);
    if(on&&Number(on.dataset.s)>0){ try{ on.click(); }catch(e){ window.__swl&&window.__swl(e); } }   /* synthetic click: refreshes the line and the estimate, keeps a chosen preset */
    else if(window.amiyoRefreshExpSummary){ try{ window.amiyoRefreshExpSummary(); }catch(e){ window.__swl&&window.__swl(e); } }
  }
  var prev=window.openModal;
  window.openModal=function(title){
    var r=prev.apply(this,arguments);
    if(title==="Export video"){ setTimeout(function(){ try{ wire(); fixLine(); hint(); }catch(e){ window.__swl&&window.__swl(e); } },0); setTimeout(function(){ try{ wire(); hint(); }catch(e){ window.__swl&&window.__swl(e); } },400); }
    return r;
  };
  window.AMIYO_EXPORT6_STEP=9;
})();

