/* ==================== Script 1370 id="amiyo-export6-s18-mobile-js" ==================== */
(function(){
  if(window.__x18mob) return; window.__x18mob=true;
  function $(i){ return document.getElementById(i); }
  function warn(e){ try{ window.__swl&&window.__swl(e); }catch(_){} }
  /* 1. Floating buttons (Audio Lab, dock, timeline size) used to sit on top of the dialog and the progress screen. */
  function shown(el){ if(!el) return false; try{ var cs=getComputedStyle(el); if(cs.display==="none"||cs.visibility==="hidden") return false; var r=el.getBoundingClientRect(); return r.width>0&&r.height>0; }catch(e){ return false; } }
  var watched=null, wobs=null;
  function sync(){
    try{
      var ex=$("amExp");
      if(ex&&ex!==watched&&window.MutationObserver){ watched=ex; window.__x18w=ex; if(wobs) wobs.disconnect(); wobs=new MutationObserver(sync); wobs.observe(ex,{attributes:true,attributeFilter:["style","class","hidden"]}); }
      document.documentElement.classList.toggle("x18s-open",shown($("modalBackdrop"))||shown(ex));
    }catch(e){ warn(e); }
  }
  window.__x18sync=sync;
  try{
    var mb=$("modalBackdrop");
    if(mb&&window.MutationObserver) new MutationObserver(sync).observe(mb,{attributes:true,attributeFilter:["style","class","hidden"]});
    if(window.MutationObserver) new MutationObserver(sync).observe(document.body,{childList:true});
    document.addEventListener("visibilitychange",sync); setInterval(function(){ if(!document.hidden) sync(); },400); sync();
  }catch(e){ warn(e); }

  /* 2. Long or heavy exports on a phone: say so in plain words and offer safe settings. */
  function isPhone(){ try{ return (matchMedia("(pointer:coarse)").matches&&Math.min(innerWidth,innerHeight)<=820)||innerWidth<=760; }catch(e){ return innerWidth<=760; } }
  function pressed(box){ if(!box) return null; return [].slice.call(box.querySelectorAll(".chip")).filter(function(c){ return c.getAttribute("aria-pressed")==="true"||/solid/.test(c.style.outline||""); })[0]||null; }
  function human(sec){ sec=Math.round(sec); var m=Math.floor(sec/60); return m>=1?(m+" min"):(sec+" s"); }
  function advise(){
    try{
      var go=$("expGo"), old=$("x18Phone");
      if(!go){ if(old) old.remove(); return; }
      var end=0; try{ end=window.amiyoContentEnd(); }catch(e){}
      var sc=pressed($("expSizes")), pc=pressed($("expParts"));
      var W=project.settings.width, H=project.settings.height, short=Math.min(W,H);
      if(sc&&Number(sc.dataset.h)>0) short=Number(sc.dataset.h);
      var sm=($("expSummary")&&$("expSummary").textContent||"").match(/(\d{3,4})\s*[×x]\s*(\d{3,4})/);
      if(sm) short=Math.min(Number(sm[1]),Number(sm[2]));
      var ps=pc?Number(pc.dataset.s)||0:0, per=ps>0?Math.min(ps,end):end, perMin=per/60;
      var mem=Number(navigator.deviceMemory)||0;
      var heavy=isPhone()&&end>0&&((short>=1080&&perMin>5)||perMin>15||short>=2160||(mem>0&&mem<=4&&short>=1080&&perMin>2));
      if(!heavy){ if(old) old.remove(); return; }
      var why=short+"p, "+human(per)+(ps>0?" per file":" in one file");
      var sig=why+"|"+mem+"|"+(short>720)+"|"+(end>660&&ps!==600);
      if(old&&old.dataset.sig===sig) return;
      if(old) old.remove();
      var box=document.createElement("div"); box.id="x18Phone"; box.dataset.sig=sig; box.setAttribute("role","note");
      var tips=[]; if(short>720) tips.push("720p"); if(end>660&&ps!==600) tips.push("10-minute files"); if(!tips.length) tips.push("keep this screen on and the app in front");
      box.innerHTML="<b>Heavy export for a phone</b> ("+why+"). A phone can run out of memory and close the page, and then the export is lost. Safer: "+tips.join(" and ")+".";
      var b=document.createElement("button"); b.type="button"; b.className="chip"; b.id="x18Safe"; b.textContent="Use phone-safe settings";
      b.addEventListener("click",function(){
        try{
          var s=$("expSizes"); if(s&&short>720){ var c7=s.querySelector('.chip[data-h="720"]'); if(c7) c7.click(); }
          var p=$("expParts"); if(p&&end>660){ var c6=p.querySelector('.chip[data-s="600"]'); if(c6) c6.click(); }
        }catch(e){ warn(e); }
        setTimeout(advise,120);
      });
      box.appendChild(b);
      var anchor=$("expSummary")||go.parentNode; anchor.parentNode.insertBefore(box,anchor);
    }catch(e){ warn(e); }
  }
  window.amiyoPhoneExportAdvice=advise;
  var body=$("modalBody");
  if(body) body.addEventListener("click",function(){ setTimeout(advise,150); },true);
  var prev=window.openModal;
  window.openModal=function(title){
    var r=prev.apply(this,arguments);
    if(title==="Export video"){ [0,400,1200].forEach(function(t){ setTimeout(advise,t); }); }
    sync();
    return r;
  };
  window.AMIYO_EXPORT6_STEP=18;
})();

