/* ==================== Script 1372 id="amiyo-export6-s19-errors-js" ==================== */
(function(){
  if(window.__x19err) return; window.__x19err=true;
  function $(i){ return document.getElementById(i); }
  function warn(e){ try{ window.__swl&&window.__swl(e); }catch(_){} }
  function esc(x){ return String(x).replace(/[&<>"]/g,function(c){ return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]; }); }
  /* ---- 1. raw browser error -> plain words (storage, memory, unreadable file) ---- */
  function kind(raw){
    var m=String((raw&&(raw.name?raw.name+" "+(raw.message||""):raw.message))||raw||"");
    if(/quota|no space|not enough (free )?(space|storage)|out of (storage|space)|disk full|ENOSPC|DEVICE_SPACE/i.test(m)) return "storage";
    if(/memory|alloc|RangeError|out of resources?/i.test(m)) return "memory";
    if(/NotReadable|could not be read|permission problems|NotFoundError|ENOENT|file.*(moved|deleted|changed on disk)/i.test(m)) return "file";
    return "";
  }
  window.amiyoPlainError=function(raw){
    var k=kind(raw), m=String((raw&&raw.message)||raw||"");
    if(k==="storage") return "the device is out of storage space";
    if(k==="memory") return "the device ran out of memory";
    if(k==="file") return "a media file could not be read - the phone may have moved or deleted it";
    return m||"a frame could not be drawn";
  };
  window.amiyoPlainAdvice=function(raw){
    var k=kind(raw);
    if(k==="storage") return "Free some space (delete old videos or downloads), then export again.";
    if(k==="memory") return "Close other tabs and apps, pick Draft or 720p, or split into 10-minute parts.";
    if(k==="file") return "Import the file again (Media > Import), then export again.";
    return "Try a lower resolution and export again.";
  };
  window.amiyoFolderWhy=function(e,name){
    var nm="\u201C"+(name||"the folder")+"\u201D", n=String((e&&e.name)||""), m=String((e&&e.message)||e||"");
    if(kind(e)==="storage") return "The drive for "+nm+" is full, so the file could not be saved there. It was downloaded instead. Free some space to use that folder again.";
    if(n==="NotFoundError") return "The folder "+nm+" was moved or deleted, so the file was downloaded instead. Tap Change folder\u2026 to pick it again.";
    if(n==="NotAllowedError"||n==="SecurityError"||/permission/i.test(m)) return "There is no permission to write to "+nm+", so the file was downloaded instead. Tap Change folder\u2026 and allow access.";
    return "Could not write to the folder, so the file was downloaded instead.";
  };

  /* ---- 2. low storage: tell before starting, not after ---- */
  var estCache={t:0,free:null};
  function getFree(){
    return new Promise(function(res){
      try{
        if(Date.now()-estCache.t<4000) return res(estCache.free);
        if(!(navigator.storage&&navigator.storage.estimate)) return res(null);
        navigator.storage.estimate().then(function(e){ estCache={t:Date.now(),free:(e&&e.quota)?Math.max(0,(e.quota||0)-(e.usage||0)):null}; res(estCache.free); },function(){ res(null); });
      }catch(e){ res(null); }
    });
  }
  function bytes(n,u){ n=parseFloat(n); u=String(u).toUpperCase(); return n*(u==="GB"?1073741824:u==="MB"?1048576:1024); }
  function nice(b){ return b>=1073741824?(b/1073741824).toFixed(1)+" GB":Math.max(1,Math.round(b/1048576))+" MB"; }
  function space(){
    var go=$("expGo"), old=$("x19Space");
    if(!go){ if(old) old.remove(); return; }
    var sum=($("expSummary")&&$("expSummary").textContent)||"";
    var m=sum.match(/up to\s*([\d.]+)\s*(KB|MB|GB)/i); if(!m){ if(old) old.remove(); return; }
    var files=1, fm=sum.match(/(\d+)\s*files/i); if(fm) files=Math.max(1,Number(fm[1]));
    var need=bytes(m[1],m[2])*files;
    getFree().then(function(free){
      try{
        var cur=$("x19Space");
        if(free==null||!$("expGo")||need*1.2<free){ if(cur) cur.remove(); return; }
        var txt="<b>Low storage.</b> This export may need up to "+nice(need)+" and the browser reports about "+nice(free)+" free. If saving fails, free some space (delete old videos or downloads) or pick a smaller size.";
        if(cur){ if(cur.innerHTML!==txt) cur.innerHTML=txt; return; }
        var box=document.createElement("div"); box.id="x19Space"; box.setAttribute("role","note"); box.innerHTML=txt;
        var anchor=$("x18Phone")||$("expSummary")||$("expGo").parentNode; anchor.parentNode.insertBefore(box,anchor);
      }catch(e){ warn(e); }
    });
  }
  window.amiyoExportSpaceCheck=space;
  var body=$("modalBody"); if(body) body.addEventListener("click",function(){ setTimeout(space,200); },true);

  /* ---- 3. leaving the app during an export: a note that stays ---- */
  var away=0, hiddenAt=0, wasExp=false;
  var fastAt=null;
  function fast(){ return fastAt!==null?fastAt:!!window.__amiyoFastBusy; }
  function awayText(){
    var s=Math.round((window.__x19away?window.__x19away():away)/1000);
    return "<b>You were away from the app for "+s+" s while this was exporting.</b> "+(fast()?"Fast export usually carries on, but check the finished video.":"The recording may have frozen or gone quiet during that time. If it did, export again and keep this screen in front.");
  }
  function paintAway(){
    try{
      if(away<2000) return;
      var card=document.querySelector("#amExp .amx-card"), n=$("x19Away");
      if(card){ if(!n){ n=document.createElement("div"); n.id="x19Away"; n.setAttribute("role","status"); card.appendChild(n); } n.innerHTML=awayText(); }
    }catch(e){ warn(e); }
  }
  document.addEventListener("visibilitychange",function(){
    try{
      var ex=!!window.__amiyoExporting;
      if(document.visibilityState==="hidden"){ if(ex&&!hiddenAt) hiddenAt=Date.now(); }
      else if(hiddenAt){ away+=Date.now()-hiddenAt; hiddenAt=0; if(ex){ fastAt=!!window.__amiyoFastBusy; paintAway(); } }
    }catch(e){ warn(e); }
  });
  setInterval(function(){
    try{
      var ex=!!window.__amiyoExporting;
      if(ex&&!wasExp){ away=0; fastAt=null; hiddenAt=document.visibilityState==="hidden"?Date.now():0; var n=$("x19Away"); if(n) n.remove(); }
      wasExp=ex;
    }catch(e){ warn(e); }
  },300);
  window.__x19away=function(){ return away+(hiddenAt?Date.now()-hiddenAt:0); };
  var prev=window.openModal;
  window.openModal=function(title){
    var r=prev.apply(this,arguments);
    try{
      if(title==="Export video"){ [200,700,1500].forEach(function(t){ setTimeout(space,t); }); }
      if(title==="Your video is ready"&&window.__x19away()>=2000){
        var b=$("modalBody"); if(b&&!b.querySelector(".x19-note")){ var d=document.createElement("div"); d.className="x19-note"; d.setAttribute("role","note"); d.innerHTML=awayText().replace(/^<b>You were away/,"<b>You were away"); b.appendChild(d); }
      }
    }catch(e){ warn(e); }
    return r;
  };
  window.AMIYO_EXPORT6_STEP=19;
})();

