    heights.forEach(function(h){ var e=o.est({h:h,ps:0,end:o.end,fps:o.fps,sound:o.sound,bps:o.bps||0,from:1}); rows.push({h:h,label:h?(h+"p"):"Project size",dims:e.dims,size:e.all,secs:e.secs,fits:!tb||e.all<=tb}); });
    var best=rows.filter(function(r){ return r.fits; })[0]||null, notes=[], last=rows[rows.length-1];
    if(tb&&!best&&last){ var ms=Math.floor(o.end*tb/last.size); notes.push("Even "+last.label+" would be about "+mb(last.size)+". To stay under "+mb(tb)+", keep the video to about "+dur(Math.max(1,ms))+" or less"+(o.fps>30?", or lower the frame rate to 30":"")+"."); }
    if(best&&rows[0]&&best!==rows[0]&&tb) notes.push("Full project size would be about "+mb(rows[0].size)+", over your "+mb(tb)+" limit.");
    if(o.fps>30){ var e30=o.est({h:0,ps:0,end:o.end,fps:30,sound:o.sound,bps:0,from:1}); if(rows[0]&&e30.all<rows[0].size*0.85) notes.push("Project is "+o.fps+" fps. At 30 fps the file would be about "+Math.round((1-e30.all/rows[0].size)*100)+"% smaller."); }
    var ref=best||rows[0]; 
    if(ref&&ref.secs>(o.phone?600:1800)) notes.push("This export runs in real time (about "+dur(ref.secs)+"). Keep the app open and the screen on"+(o.phone?", and plug the phone in":"")+".");
    var parts=o.end>900?"10 min":"";
    if(parts) notes.push("Long video: choose "+parts+" parts in the Export window. If one part fails you only redo that part.");
    if(o.free!=null&&ref&&ref.size>o.free*0.8) notes.push("Free space looks tight: about "+mb(Math.max(0,o.free))+" left on this device, and this file may need up to "+mb(ref.size)+".");
