    var end=0; try{ end=window.amiyoContentEnd?window.amiyoContentEnd():0; }catch(e){}
    var s=project.settings||{}, free=null; try{ if(navigator.storage&&navigator.storage.estimate){ var q=await navigator.storage.estimate(); if(q&&q.quota) free=q.quota-q.usage; } }catch(e){}
