          if(G.end<0.5){ box.textContent=""; return; } var R=analyse(G), cur=R.rows.filter(function(x){ return x.h===h; })[0]||R.rows[0], lines=[];
          /* export step 10: judge the file the window is really set up to make (preset, custom size, quality chip, manual bitrate, sound, parts), not the plain size row */
          var now=window.amiyoExportNow&&window.amiyoExportNow(); if(cur&&now&&now.perFile>0) cur=Object.assign({},cur,{size:now.perFile,fits:!R.target||now.perFile<=R.target});
          if(R.target&&cur){ lines.push(cur.fits?"✓ This size (about "+mb(cur.size)+") fits your "+mb(R.target)+" limit.":"✗ This size (about "+mb(cur.size)+") is over your "+mb(R.target)+" limit."+(R.best?" Try "+R.best.label+" (about "+mb(R.best.size)+").":" Try a shorter video.")); }
