    R.push(T("All 16 tool sections are in the sheet",function(){ var miss=secs.filter(function(s){ return !sh||!sh.querySelector("#"+s); }); return miss.length?"missing: "+miss.join(", "):true; }));
    R.push(T("No section is doubled",function(){ var d=[]; secs.forEach(function(s){ if(document.querySelectorAll("#"+s).length>1) d.push(s); }); return d.length?"doubled: "+d.join(", "):true; }));
