    R.push(T("Every Help entry explains edits and privacy",function(){ var bad=A._helpData.tools.filter(function(t){ return !(t.what&&t.edit&&t.priv); }); return bad.length?"incomplete: "+bad.map(function(t){ return t.id; }).join(", "):true; }));
    R.push(T("B-roll finds a gap and a long shot",function(){
      var P={assets:{v:{id:"v",type:"video",duration:30}},tracks:[{kind:"video",clips:[{start:0,duration:12,assetId:"v"},{start:16,duration:4,assetId:"v"}]},{kind:"caption",clips:[{start:13,duration:2,text:"fresh coffee beans roasting",kind:"caption"}]}]};
      var r=A._broll.analyse(P), g=r.slots.filter(function(s){ return s.kind==="gap"; }), l=r.slots.filter(function(s){ return s.kind==="long"; });
      if(g.length!==1||g[0].start!==12||g[0].end!==16) return "gap not found"; if(!l.length||l[0].start!==3) return "long shot not found"; if(g[0].words.indexOf("coffee")<0) return "caption words missing"; return true; }));
    R.push(T("B-roll offers only unused pictures and clips",function(){
      var P={assets:{a:{id:"a",type:"image"},b:{id:"b",type:"video"},c:{id:"c",type:"audio"},d:{id:"d",type:"image"}},tracks:[{kind:"video",clips:[{assetId:"d",start:0,duration:1}]}]};
      var s=A._broll.spare(P); return (s.length===2&&s.indexOf("a")>=0&&s.indexOf("b")>=0)||("got "+s.join(",")); }));
    R.push(T("Export advice picks the largest size that fits",function(){
      var E=window.AMIYO_EXPORT_ESTIMATE; if(!E) return "estimate missing";
      var base={est:E.estimate,end:60,fps:30,sound:true,shortSide:1080,free:null,phone:false};
      var none=A._exp.analyse(Object.assign({},base,{targetMB:0})), tight=A._exp.analyse(Object.assign({},base,{targetMB:1}));
      if(!none.rows[0].fits) return "no limit should fit"; if(tight.best) return "1 MB should not fit a minute"; if(!tight.notes.length) return "no advice when nothing fits";
      var mid=A._exp.analyse(Object.assign({},base,{targetMB:Math.ceil(none.rows[2].size/1048576)})); return (mid.best&&mid.best.size<=mid.target)||"best does not fit"; }));
    R.push(T("Clean-up finds unused media",function(){
      var r=A._cleanAnalyse({assets:{a:{id:"a",type:"image",size:5,name:"x"},b:{id:"b",type:"image",size:9,name:"y"}},tracks:[{kind:"video",clips:[{assetId:"a",start:0,duration:1}]}]}); return (r.unused.length===1&&r.unused[0]==="b")||"unused wrong"; }));
