  function esc(s){ return String(s==null?"":s).replace(/[&<>"]/g,function(c){ return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]; }); }
  function cap(s){ s=String(s||"").trim(); return s?s.charAt(0).toUpperCase()+s.slice(1):s; }
  function splitSteps(text){
    var A=window.amiyoAskAI, p=null;
    try{ if(A&&A.parse) p=A.parse(text); }catch(e){}
    if(!p||!p.length){ p=/["\u201c']/.test(text)?[text]:String(text).split(/\s*(?:,|;|\bthen\b|\band then\b|\band\b)\s*/i); }
    return p.map(function(x){ return String(x).trim(); }).filter(Boolean);
  }
