    var actions=Ag.parse(text);
    if(actions.some(function(a){ return a.action==="UNMAPPED"; })) throw new Error("I did not understand \u201c"+text+"\u201d.");
    var needs=actions.filter(function(a){ return a.requiresProvider; });
    if(needs.length&&needs.length===actions.length) throw new Error("This step needs a tool this build has no button for yet: "+needs.map(function(a){ return a.action.replace(/_/g," ").toLowerCase(); }).join(", ")+".");
    var p=Ag.execute(actions.filter(function(a){ return !a.requiresProvider; }),{confirmDestructive:false});
    try{ p&&p.catch&&p.catch(function(e){ window.__swl&&window.__swl(e); }); }catch(e){}
    var ag=(window.project.agentActions||[]).slice(-1)[0], res=ag&&ag.results?ag.results.slice():[];
