/* ==================== Script 1381 id="amiyo-dir-s02-goal-recipes" ==================== */
/* AI Director · Step 2 of 20 — goal recipes.
   Say what you want to end up with ("get ready for TikTok", "clean up my video", "polish my audio", "fix everything") and the
   editor writes the plan: a short list of its own on-device tools in a sensible order, shown on the plan card so you can untick
   any step before anything runs. Type "recipes" to pick one from a list. Before: "fix everything" only closed gaps, and goals
   like these were answered with "I don't know". */
(function(){
  "use strict";
  var D=window.amiyoDirector, A20=window.amiyoAI20;
  if(!D||D.s02||!A20||!A20.hook) return; D.s02=true;
  var R=[
    {id:"social",name:"Ready for TikTok / Reels / Shorts",desc:"Close gaps, cut pauses, make it vertical, even sound, captions",goal:"get ready for tiktok",
     re:/^(?:(?:get|make|prepare|prep)(?: (?:it|this|my video|my project))? ready for|prepare(?: my video| it| this)? for|prep(?: my video| it| this)? for|post(?: it| this| my video)? to|upload(?: it| this| my video)? to) (?:tiktok|reels?|shorts?|instagram)$/,
     steps:["close the gaps","remove silence","make it for tiktok","match loudness","add captions","check my project"]},
    {id:"youtube",name:"Ready for YouTube",desc:"Close gaps, cut pauses, landscape, even sound, title ideas, final check",goal:"get ready for youtube",
     re:/^(?:(?:get|make|prepare|prep)(?: (?:it|this|my video|my project))? ready for|prepare(?: my video| it| this)? for|prep(?: my video| it| this)? for|finish(?: my video| it| this)? for) (?:youtube|upload|publishing)$|^ready to (?:upload|publish|post)$/,
     steps:["close the gaps","remove silence","make it for youtube","match loudness","suggest titles","check my project"]},
    {id:"tidy",name:"Clean up my video",desc:"Close gaps, cut pauses, reduce noise, even the sound, check",goal:"clean up my video",
     re:/^(?:clean up|tidy up|tidy|tighten up|tighten)(?: (?:my|the|this))?(?: (?:video|project|timeline|edit|footage))?$/,
     steps:["close the gaps","remove silence","denoise audio","match loudness","check my project"]},
    {id:"audio",name:"Polish the audio",desc:"Reduce noise, normalise the clip, match loudness across clips",goal:"polish my audio",
     re:/^(?:polish|improve|perfect|enhance)(?: (?:my|the|all))?(?: (?:audio|sound))$/,
     steps:["denoise audio","normalize audio","match loudness"]},
    {id:"look",name:"Cinematic look",desc:"Colour fix, brightness balance, film look",goal:"cinematic treatment",
     re:/^(?:make it |give it |apply )?(?:a )?(?:full |complete )?cinematic (?:grade|treatment|edit|polish)$/,
     steps:["fix the colour","auto levels","cinematic look"]},
    {id:"beat",name:"Edit to the music",desc:"Find the beats, cut on them, make it vertical",goal:"edit to the beat",
     re:/^(?:make (?:a |an )?)?(?:beat|music)[- ]?(?:synced?|driven)? ?(?:reel|edit|video)$|^edit to the (?:music|beat)$/,
     steps:["find beats","cut to the beat","make it for tiktok"]},
    {id:"mc",name:"Add music and captions",desc:"Background music under the video, then captions from the speech",goal:"add music and captions",
     re:/^(?:add|put) (?:music|background music) and (?:captions?|subtitles?)$/,
     steps:["add background music","add captions"]},
    {id:"all",name:"Fix everything",desc:"Gaps, pauses, colour, brightness, sound, then a final check",goal:"fix everything",
     re:/^(?:fix everything|fix it all|improve everything|do everything|make it better|make (?:my )?(?:video|project) better|auto ?-?edit|edit (?:it )?for me|polish (?:my |the )?(?:video|project|edit))$/,
     steps:["close the gaps","remove silence","fix the colour","auto levels","normalize audio","check my project"]}
  ];
  function norm(s){ return String(s||"").toLowerCase().replace(/\s+/g," ").trim().replace(/[.!?]+$/,"").replace(/^(?:please|can you|could you|hey|ai)\s+/,"").replace(/\s+(?:please|now)$/,"").trim(); }
  function find(t){ for(var i=0;i<R.length;i++) if(R[i].re.test(t)) return R[i]; return null; }
  /* a goal inside a longer chain ("clean up my video and make it vertical") is expanded in place; repeated steps appear once */
  D.expand=function(parts){
    var out=[], seen={}, any=false;
    parts.forEach(function(p){
      var r=find(norm(p));
      var list=r?r.steps:[p]; if(r) any=true;
      list.forEach(function(x){ var k=norm(x); if(!seen[k]){ seen[k]=1; out.push(x); } });
    });
    return any?out:parts;
  };
  D.recipes=R;
  A20.hook(function(raw,t){
    if(window.__dirRunning) return undefined;
    if(/^(?:recipes|goal recipes|show recipes|show me recipes|what can you plan|plans)$/.test(t)){
      D.open("recipes",{picks:R,steps:[]}); return "Opened the goal recipes";
    }
    var r=find(norm(raw)); if(!r) return undefined;
    D.open(raw,{steps:r.steps,title:"Plan: "+r.name});
    return "Plan ready: "+r.name+" ("+r.steps.length+" steps). Check it and tap Run.";
  });
  try{ window.AMIYO_EDITOR_BUILD="dir-s02-goal-recipes"; }catch(e){}
})();

