/* ==================== Script 1389 id="amiyo-dir-s10-dry-run" ==================== */
/* AI Director · Step 10 of 20 — see the result before you run it.
   The plan card now shows a "Before you run" line that updates as you tick, untick, move or add steps: the timeline length now and
   after, and the export file size now and after, at the default export quality (about 0.07 bits per pixel per frame plus 128 kbit/s
   sound). Closing gaps uses the real gap time on the timeline. Cutting pauses and filler words uses typical values (8% and 5% of
   the spoken length), so those are marked "about". Vertical or landscape steps change the picture size. After the run the card
   shows the real new length next to the estimate. Nothing is changed by looking. Later steps add their own estimators with D.addEstimator. */
(function(){
  "use strict";
  var D=window.amiyoDirector;
  if(!D||D.s10||!D.facts||!D.repaint) return; D.s10=true;
  function $(i){ return document.getElementById(i); }
  function fmt(t){ t=Math.max(0,Math.round(t)); var m=Math.floor(t/60), s=t%60; return m+":"+(s<10?"0":"")+s; }
  function mb(b){ var m=b/1048576; return (m<10?m.toFixed(1):Math.round(m))+" MB"; }
  function gapTime(){
    var best=0; try{
      (window.project.tracks||[]).forEach(function(t){
        if(t.kind==="caption"||t.kind==="text"||t.name==="Music") return;
        var cl=(t.clips||[]).slice().sort(function(a,b){ return a.start-b.start; }), g=0;
        for(var i=1;i<cl.length;i++){ var d=cl[i].start-(cl[i-1].start+cl[i-1].duration); if(d>0.05) g+=d; }
        best=Math.max(best,g);
      });
    }catch(e){} return best;
  }
  var EST=[];
  /* fn(text, E) edits E: {dur, w, h, rough}; return nothing */
  D.addEstimator=function(fn){ EST.push(fn); };
  D.addEstimator(function(t,E,F){
    if(/\bclose (?:all )?(?:the )?gaps?\b|\bripple\b/.test(t)){ E.dur-=Math.min(E.dur,E.gaps); E.gaps=0; }
    else if(/\bremove silence|cut (?:long )?pauses/.test(t)){ if(F.sound){ E.dur*=0.92; E.rough=true; } }
    else if(/\bremove filler/.test(t)){ if(F.sound){ E.dur*=0.95; E.rough=true; } }
    else if(/\bfor tiktok|\bfor reels|\bfor shorts|\bvertical\b/.test(t)){ var p=E.w*E.h; if(p>0){ E.w=Math.round(Math.sqrt(p*9/16)); E.h=Math.round(E.w*16/9); } }
    else if(/\bfor youtube|\blandscape\b/.test(t)){ var q=E.w*E.h; if(q>0){ E.w=Math.round(Math.sqrt(q*16/9)); E.h=Math.round(E.w*9/16); } }
  });
  function size(dur,w,h,fps){ return dur*((w*h*(fps||30)*0.07)+128000)/8; }
  D.estimate=function(S){
    var F=D.facts(); if(!F.dur||!F.w||!F.h) return null;
    var fps=30; try{ fps=window.project.settings.fps||30; }catch(e){}
    var E={dur:F.dur,w:F.w,h:F.h,gaps:gapTime(),rough:false};
    var now={dur:F.dur,bytes:size(F.dur,F.w,F.h,fps)};
    S.steps.forEach(function(x){
      if(!x.on) return; var t=String(x.text).toLowerCase().replace(/\s+/g," ").trim();
      EST.forEach(function(fn){ try{ fn(t,E,F); }catch(e){ window.__swl&&window.__swl(e); } });
    });
    return {now:now,after:{dur:E.dur,bytes:size(E.dur,E.w,E.h,fps),w:E.w,h:E.h},rough:E.rough,resized:(E.w!==F.w||E.h!==F.h)};
  };
  var prev=D.afterPaint;
  D.afterPaint=function(S,ov){
    if(prev) prev(S,ov);
    if(S.picks||S.running) return;
    var bt=ov.querySelector(".dbtns"); if(!bt) return;
    var d=document.createElement("div"); d.className="dsub"; d.id="dirEst"; d.setAttribute("role","status");
    if(S.done){
      if(!S.est) return;
      var F=D.facts(); d.innerHTML="<b>Length now:</b> "+fmt(F.dur)+" (the estimate was "+(S.est.rough?"about ":"")+fmt(S.est.after.dur)+")";
    } else {
      var e=null; try{ e=D.estimate(S); }catch(x){ window.__swl&&window.__swl(x); }
      S.est=e;
      if(!e) return;
      var dl=e.after.dur-e.now.dur, dsz=e.after.bytes-e.now.bytes, ap=e.rough?"about ":"";
      d.innerHTML="<b>Before you run:</b> length "+fmt(e.now.dur)+" \u2192 "+ap+fmt(e.after.dur)+(Math.abs(dl)>=1?" ("+(dl<0?"\u2212":"+")+fmt(Math.abs(dl))+")":" (no change)")+
        "<br>File size at default quality: about "+mb(e.now.bytes)+" \u2192 about "+mb(e.after.bytes)+(e.resized?" ("+e.after.w+"\u00d7"+e.after.h+")":"")+(Math.abs(dsz)<1048576*0.05?"":"")+
        "<br><span style=\"color:#948a79\">A rough guide only. Nothing changes until you tap Run.</span>";
    }
    bt.parentNode.insertBefore(d,bt);
  };
  try{ window.AMIYO_EDITOR_BUILD="dir-s10-dry-run"; }catch(e){}
})();

