/* ==================== Script 1390 id="amiyo-dir-s11-progress-cancel" ==================== */
/* AI Director · Step 11 of 20 — see progress, and stop.
   Before: while a plan ran, the Cancel button was greyed out and the only feedback was the word "Working". Now a progress bar shows
   "Step 2 of 5" (and each row says what it is doing, such as "Clip 3 of 6"), and the button becomes "Stop". Stop lets the step that is
   running finish (it cannot be cut in half safely), then leaves the remaining steps as "Cancelled". What was already done stays,
   and "Undo all" takes it back. */
(function(){
  "use strict";
  var D=window.amiyoDirector;
  if(!D||D.s11||!D.repaint) return; D.s11=true;
  function $(i){ return document.getElementById(i); }
  D.stop=function(S){ return !!S.cancelled; };
  function css(){
    if($("dirProgCss")) return; var s=document.createElement("style"); s.id="dirProgCss";
    s.textContent="#dirPlan .dprog{margin:8px 0 0}#dirPlan .dprog .dpl{font-size:12px;color:#948a79;margin-bottom:4px}#dirPlan .dprog .dpb{height:8px;border-radius:4px;background:#26231e;overflow:hidden}#dirPlan .dprog .dpf{height:100%;background:var(--accent,#e8a24a);transition:width .25s}";
    document.head.appendChild(s);
  }
  var prev=D.afterPaint;
  D.afterPaint=function(S,ov){
    if(prev) prev(S,ov); css();
    if(!S.running) return;
    var on=S.steps.filter(function(x){ return x.on; }), total=on.length, done=on.filter(function(x){ return x.cls==="ok"||x.cls==="bad"||x.status==="Cancelled"; }).length;
    var cur=Math.min(total,done+1), txt=S.cancelled?"Stopping after this step\u2026":"Step "+cur+" of "+total;
    var bt=ov.querySelector(".dbtns"); if(!bt) return;
    var p=document.createElement("div"); p.className="dprog";
    p.innerHTML='<div class="dpl" role="status">'+txt+'</div><div class="dpb" role="progressbar" aria-valuemin="0" aria-valuemax="'+total+'" aria-valuenow="'+done+'" aria-label="Plan progress"><div class="dpf" style="width:'+(total?Math.round(done*100/total):0)+'%"></div></div>';
    bt.parentNode.insertBefore(p,bt);
    var c=$("dirCancel"); if(c){ c.disabled=!!S.cancelled; c.textContent=S.cancelled?"Stopping\u2026":"Stop"; }
    if(!ov.__dirStop){
      ov.__dirStop=true;
      /* capture phase: the plan card's own Cancel handler (which just closes the card) must not run while a plan is running */
      ov.addEventListener("click",function(e){
        var b=e.target&&e.target.closest&&e.target.closest("#dirCancel"), st=D.getState&&D.getState();
        if(!b||!st||!st.running) return;
        e.stopPropagation(); e.preventDefault(); st.cancelled=true; D.repaint();
      },true);
    }
  };
  try{ window.AMIYO_EDITOR_BUILD="dir-s11-progress-cancel"; }catch(e){}
})();

