/* ==================== Script 1391 id="amiyo-dir-s12-retry-skip" ==================== */
/* AI Director · Step 12 of 20 — fix a failed step without starting over.
   Before: a step that failed (red) or was stopped stayed that way; the only way forward was to build the plan again. Now, after a run,
   every failed step has "Retry" and "Skip", and every step you stopped has "Run now". Retry runs only that step and its change is
   added to the same "Undo all". Skip marks the step as skipped and updates the summary. If you edited the timeline after the plan
   finished, retry is refused (so Undo all stays safe) and the card says why. */
(function(){
  "use strict";
  var D=window.amiyoDirector;
  if(!D||D.s12||!D.exec||!D.getState||!D.repaint) return; D.s12=true;
  function $(i){ return document.getElementById(i); }
  function hidx(){ try{ return window.project.history.index; }catch(e){ return 0; } }
  function recount(S){
    var ok=0,bad=0,can=0; S.steps.forEach(function(x){ if(x.cls==="ok") ok++; else if(x.cls==="bad") bad++; else if(x.status==="Cancelled") can++; });
    return (S.cancelled?"Stopped by you. ":"")+ok+" step"+(ok===1?"":"s")+" done"+(bad?", "+bad+" could not run (shown in red).":".")+(can?" "+can+" not run.":"")+
      (S.changes?" "+S.changes+" change"+(S.changes===1?"":"s")+" made.":" Nothing in the timeline changed.");
  }
  async function retry(S,i){
    var x=S.steps[i]; if(S.running||!x) return;
    if(S.changes===0&&hidx()===S.before) S.after=S.before;
    if(hidx()!==S.after){ S.summary="Other edits were made after this plan, so I did not run it again. Use \u21b6 to step back, or make a new plan."; D.repaint(); return; }
    var A20=window.amiyoAI20, logN=A20&&A20.log?A20.log.length:0, rid="dirFix"+i;
    S.running=true; S.done=false; S.cancelled=false; S.targets=null; x.on=true; x.cls="run"; x.status="Working\u2026"; S.summary=""; D.repaint(); window.__dirRunning=true;
    try{
      var r=await D.exec(x,S); x.status=String(r==null?"Done":r).slice(0,90); x.cls="ok";
    }catch(e){ x.status=String((e&&e.message)||e).slice(0,140); x.cls="bad"; }
    finally{ window.__dirRunning=false; D.pending=null; }
    var after=hidx(); S.after=after; S.changes=Math.max(0,after-S.before);
    try{
      if(A20&&A20.log){
        A20.log.splice(logN); var g=S.group;
        if(g&&A20.log.indexOf(g)>-1){ g.after=after; g.undone=false; }
        else if(S.changes>0){ g=S.group={text:S.text,at:Date.now(),before:S.before,after:after,ok:true,undone:false,msg:"plan"}; A20.log.push(g); }
      }
    }catch(e){}
    S.running=false; S.done=true; S.summary=recount(S); D.repaint();
    var f=$(rid+"R")||$("dirUndo")||$("dirClose"); if(f) f.focus();
  }
  function skip(S,i){
    var x=S.steps[i]; if(!x) return; x.on=false; x.cls="skip"; x.status="Skipped by you"; S.summary=recount(S); D.repaint();
  }
  function css(){
    if($("dirFixCss")) return; var s=document.createElement("style"); s.id="dirFixCss";
    s.textContent="#dirPlan .drow.fx{flex-wrap:wrap}#dirPlan .dfix{display:flex;gap:6px;width:100%;justify-content:flex-end}#dirPlan .dfix button{min-height:44px;min-width:92px;border-radius:10px;border:1px solid var(--accent,#e8a24a);background:#211f1b;color:#f1ece2;font-size:14px;padding:0 12px}";
    document.head.appendChild(s);
  }
  var prev=D.afterPaint;
  D.afterPaint=function(S,ov){
    if(prev) prev(S,ov); css();
    if(!S.done||S.running||S.picks) return;
    Array.prototype.forEach.call(ov.querySelectorAll(".drow"),function(row,i){
      var x=S.steps[i]; if(!x) return;
      var failed=x.cls==="bad", stopped=x.status==="Cancelled"; if(!failed&&!stopped) return;
      row.classList.add("fx");
      var d=document.createElement("div"); d.className="dfix";
      var a=document.createElement("button"); a.type="button"; a.id="dirFix"+i+"R"; a.textContent=failed?"Retry":"Run now"; a.setAttribute("aria-label",(failed?"Retry":"Run")+" step "+(i+1));
      a.onclick=function(){ retry(S,i); }; d.appendChild(a);
      if(failed){ var b=document.createElement("button"); b.type="button"; b.textContent="Skip"; b.setAttribute("aria-label","Skip step "+(i+1)); b.onclick=function(){ skip(S,i); }; d.appendChild(b); }
      row.appendChild(d);
    });
  };
  D.retryStep=retry; D.skipStep=skip;
  try{ window.AMIYO_EDITOR_BUILD="dir-s12-retry-skip"; }catch(e){}
})();

;
/* ==================== Script 1392 id="amiyo-dir-s13-scope" ==================== */
/* AI Director · Step 13 of 20 — choose where a plan applies.
   The plan card gets "Apply clip steps to": Selected clip(s) (as before), This track (every clip on the track of the selected clip),
   or Whole project (every picture, video and sound clip). The card shows how many clips each choice covers. Steps that work on one
   clip (cut pauses, noise, normalise, captions, colour, levels, looks) run once for each clip that fits that step (audio steps skip
   picture-only clips, colour steps skip sound-only clips). Steps that already cover the whole timeline (close gaps, match loudness,
   music, picture shape, check) are not changed by this choice. Your own selection is put back when the plan finishes. */
(function(){
  "use strict";
  var D=window.amiyoDirector;
  if(!D||D.s13||!D.exec||!D.perClip||!D.repaint) return; D.s13=true;
  function $(i){ return document.getElementById(i); }
  function core(){ return window.AMIYO_STUDIO_CORE||{}; }
  function sel(){ try{ return (core().selectedClips&&core().selectedClips())||[]; }catch(e){ return []; } }
  function aType(c){ var a=c.assetId&&window.project.assets?window.project.assets[c.assetId]:null; return a&&a.type; }
  function skipTrack(t){ return t.kind==="caption"||t.kind==="text"||t.name==="Music"; }
  function selTrack(){ var s=sel(); return s.length?s[0].track:null; }
  function mediaClips(tracks){
    var o=[]; (tracks||[]).forEach(function(t){ (t.clips||[]).forEach(function(c){ var ty=aType(c); if(ty==="video"||ty==="audio"||ty==="image") o.push({clipId:c.id,trackId:t.id,type:ty}); }); }); return o;
  }
  function scopeAll(scope){
    var P=window.project, tr=P&&P.tracks||[];
    if(scope==="track"){ var t=selTrack(); return t?mediaClips([t]):[]; }
    if(scope==="project") return mediaClips(tr.filter(function(t){ return !skipTrack(t); }));
    return [];
  }
  D.scopeCounts=function(){ return {selected:sel().length,track:scopeAll("track").length,project:scopeAll("project").length}; };
  /* which clips suit this step */
  function fits(text,t){
    var x=String(text).toLowerCase();
    if(/level the clip volume|enhance the voice|soften harsh s sounds|denoise|reduce noise|normali[sz]e audio|\bduck\b|remove silence|cut (?:long )?pauses|remove filler|^add (?:auto )?captions?|^auto captions?|^transcribe/.test(x)) return t.type==="video"||t.type==="audio";
    if(/colou?r|auto levels|cinematic look|\benhance\b|\bsharpen|\bstabili[sz]e/.test(x)) return t.type==="video"||t.type==="image";
    return true;
  }
  var inner=D.exec;
  D.exec=async function(x,S){
    if(!S.scope||S.scope==="selected"||!D.perClip(x.text)) return inner(x,S);
    var all=scopeAll(S.scope), list=all.filter(function(t){ return fits(x.text,t); }), c=core();
    if(!list.length) throw new Error(all.length?"No clip in this scope suits this step (for example no sound for an audio step).":(S.scope==="track"?"Select a clip first, so I know which track.":"There are no clips on the timeline."));
    var orig=sel().map(function(g){ return {clipId:g.clip.id,trackId:g.track.id}; });
    S.each=true; S.targets=list;
    try{
      if(list.length===1&&c.selectClip) c.selectClip(list[0].clipId,list[0].trackId);
      return await inner(x,S);
    } finally {
      S.targets=null;
      try{ orig.forEach(function(t,i){ if(i===0) c.selectClip(t.clipId,t.trackId); else c.selectClip(t.clipId,t.trackId,{toggle:true}); }); }catch(e){ window.__swl&&window.__swl(e); }
    }
  };
  function css(){
    if($("dirScopeCss")) return; var s=document.createElement("style"); s.id="dirScopeCss";
    s.textContent="#dirPlan .dscope{border:1px solid var(--line,#302c26);border-radius:12px;margin:8px 0 0;padding:6px 10px}#dirPlan .dscope legend{font-size:12px;color:#948a79;padding:0 4px}#dirPlan .dscope label{display:flex;align-items:center;gap:10px;min-height:44px;font-size:14px}#dirPlan .dscope input{width:22px;height:22px;flex:none}#dirPlan .dscope .dn{font-size:12px;color:#948a79;margin-left:auto}#dirPlan .dscope p{margin:2px 0 4px;font-size:12px;color:#948a79;line-height:1.4}";
    document.head.appendChild(s);
  }
  var prev=D.afterPaint;
  D.afterPaint=function(S,ov){
    if(prev) prev(S,ov); css();
    if(S.picks||S.running||S.done) return;
    if(!S.scope) S.scope="selected";
    var any=S.steps.some(function(x){ return x.on&&D.perClip(x.text); });
    if(!any){ return; }
    var n=D.scopeCounts(), bt=ov.querySelector(".dbtns"); if(!bt) return;
    if(S.scope!=="selected"){ var e=$("dirEach"); if(e&&e.parentNode) e.parentNode.removeChild(e.parentNode.tagName==="LABEL"?e.parentNode:e); S.each=true; }
    var f=document.createElement("fieldset"); f.className="dscope";
    var opts=[["selected","Selected clip"+(n.selected===1?"":"s"),n.selected],["track","This track",n.track],["project","Whole project",n.project]];
    f.innerHTML='<legend>Apply clip steps to</legend>'+opts.map(function(o){
      var dis=o[0]!=="selected"&&!o[2]; return '<label><input type="radio" name="dirScope" value="'+o[0]+'"'+(S.scope===o[0]?" checked":"")+(dis?" disabled":"")+'><span>'+o[1]+'</span><span class="dn">'+o[2]+" clip"+(o[2]===1?"":"s")+'</span></label>';
    }).join("")+'<p>Close gaps, match loudness, music, picture shape and checks always cover the whole timeline.</p>';
    bt.parentNode.insertBefore(f,bt);
    Array.prototype.forEach.call(f.querySelectorAll("input"),function(r){
      r.onchange=function(){ S.scope=r.value; S.targets=null; if(r.value==="selected") S.each=undefined; D.repaint(); var b=ov.querySelector('input[name="dirScope"][value="'+r.value+'"]'); if(b) b.focus(); };
    });
  };
  try{ window.AMIYO_EDITOR_BUILD="dir-s13-scope"; }catch(e){}
})();

;
/* ==================== Script 1393 id="amiyo-dir-s14-speech-cleanup" ==================== */
/* AI Director · Step 14 of 20 — filler-word and pause cleanup.
   New recipe "Clean up speech": make captions, cut the filler words out of the video, cut the pauses, close the gaps, even the sound,
   final check. The new step "cut filler words from the video" (typed, spoken or in a plan) finds caption lines that are only um / uh / er /
   hmm and removes that time from the timeline with the editor's own Extract, closing the gaps. Each cut is an undo step and the plan's
   Undo all takes them all back. It needs captions first; it says so if there are none. It cuts whole lines only, so "um" inside a long
   sentence stays (the older "remove filler words" still tidies the caption text itself). The dry-run preview uses the real length of the
   filler lines when captions already exist. Example requests: "clean up my speech", "remove the ums and uhs from the video". */
(function(){
  "use strict";
  var D=window.amiyoDirector, A20=window.amiyoAI20;
  if(!D||D.s14||!D.recipes||!A20||!A20.hook) return; D.s14=true;
  var FILL=/^(?:[\s,.!?\u2026-]*(?:um+|uh+|uhm+|er+|erm|ah+|eh+|hmm+|mm+|hm+)[\s,.!?\u2026-]*)+$/i;
  var STEP="cut filler words from the video";
  function hidx(){ try{ return window.project.history.index; }catch(e){ return 0; } }
  function fillerLines(){
    var T=window.amiyoTranscript; if(!T||!T.lines) return null;
    return T.lines().filter(function(x){ return !x.locked&&x.text&&FILL.test(x.text); });
  }
  function cutFillers(){
    var T=window.amiyoTranscript;
    if(!T||!T.lines||!T.pick||!T.cut||!window.amiyoCut||!window.amiyoSetIO) throw new Error("The cut tools are not available in this build.");
    var all=T.lines(); if(!all.length) throw new Error("No captions yet. Make captions first, then I can find the filler words.");
    var f=all.filter(function(x){ return !x.locked&&x.text&&FILL.test(x.text); });
    if(!f.length) return "No lines that are only um or uh were found, so nothing was cut";
    var secs=f.reduce(function(n,x){ return n+(x.end-x.start); },0), h0=hidx();
    T.pick(f.map(function(x){ return x.id; })); T.cut();
    if(hidx()===h0) throw new Error("Nothing could be cut. The tracks may be locked.");
    return "Cut "+f.length+" filler line"+(f.length===1?"":"s")+" ("+secs.toFixed(1)+" s) and closed the gaps";
  }
  D.cutFillers=cutFillers;
  D.recipes.push({id:"speech",name:"Clean up speech (ums and pauses)",desc:"Captions, cut um/uh, cut pauses, close gaps, even sound, check",goal:"clean up my speech",
    re:/^(?:(?:clean up|tidy up|tidy|polish|fix|tighten)(?: (?:my|the|this))? (?:speech|talking|narration|voice ?over|voice|podcast|interview)|(?:remove|cut) (?:the )?(?:ums? and (?:pauses|uhs?)|ums?,? uhs? and pauses|filler words and (?:pauses|silence)))$/,
    steps:["add captions",STEP,"remove silence","close the gaps","match loudness","check my project"]});
  A20.hook(function(raw,t){
    if(/^(?:please )?(?:cut|remove|delete|strip|take out) (?:all )?(?:the )?(?:filler words?|fillers|ums?(?: and uhs?)?|ums?,? uhs?) from (?:the |my |this )?(?:video|clips?|timeline|speech|audio|recording)$/.test(t)) return cutFillers();
    return undefined;
  });
  var w0=D.why;
  if(w0) D.why=function(step,F){
    if(String(step).toLowerCase().trim()===STEP) return F.sound?null:"no clip with sound";
    return w0(step,F);
  };
  if(D.addEstimator) D.addEstimator(function(t,E,F){
    if(t!==STEP||!F.sound) return;
    var f=null; try{ f=fillerLines(); }catch(e){}
    if(f&&f.length){ E.dur-=Math.min(E.dur,f.reduce(function(n,x){ return n+(x.end-x.start); },0)); }
    else { E.dur*=0.97; E.rough=true; }
  });
  try{ window.AMIYO_EDITOR_BUILD="dir-s14-speech-cleanup"; }catch(e){}
})();

