/* ==================== Script 1394 id="amiyo-dir-s15-auto-broll" ==================== */
/* AI Director · Step 15 of 20 — automatic B-roll.
   "add b-roll" (typed, spoken, or the new "Add B-roll" recipe) lays your spare pictures and videos over the main video on a new
   "B-roll" track, silent, full-screen, 3 to 3.5 seconds each, about every 8 seconds, as ONE undo step. Spare means media in the
   Library that is not on the timeline yet. If captions exist, a clip whose file name shares a word with a caption line (for example
   beach.mp4 and "we walked on the beach") is placed at that line first, and the other clips snap to the nearest caption start. The
   same media is not used twice in a row, clips never overlap each other, and nothing on your existing tracks is touched. It does
   not run twice: delete the B-roll track to place it again. */
(function(){
  "use strict";
  var D=window.amiyoDirector, A20=window.amiyoAI20;
  if(!D||D.s15||!D.recipes||!A20||!A20.hook) return; D.s15=true;
  var STEP="add b-roll", LEN=3, GAP=8, FIRST=4, MAXN=12;
  function idg(p){ return p+"_"+Date.now().toString(36)+Math.random().toString(36).slice(2,7); }
  function words(name){
    return String(name||"").replace(/\.[a-z0-9]{2,4}$/i,"").toLowerCase().split(/[^a-z\u00c0-\u024f]+/).filter(function(w){ return w.length>=4&&!/^(?:video|clip|img|image|photo|final|copy|footage|movie|screen|recording|untitled)$/.test(w); });
  }
  function usedIds(P){ var u={}; (P.tracks||[]).forEach(function(t){ (t.clips||[]).forEach(function(c){ if(c.assetId) u[c.assetId]=1; }); }); return u; }
  function spare(P){
    var u=usedIds(P), o=[]; Object.keys(P.assets||{}).forEach(function(k){ var a=P.assets[k]; if(a&&(a.type==="video"||a.type==="image")&&!u[a.id||k]) o.push(a); }); return o;
  }
  function hasBroll(P){ return (P.tracks||[]).some(function(t){ return t.name==="B-roll"&&(t.clips||[]).length; }); }
  function mainEnd(P){
    var e=0; (P.tracks||[]).forEach(function(t){ if(t.kind==="caption"||t.kind==="text"||t.name==="Music"||t.name==="B-roll") return; (t.clips||[]).forEach(function(c){ var a=c.assetId&&P.assets&&P.assets[c.assetId]; if(a&&(a.type==="video"||a.type==="image")) e=Math.max(e,c.start+c.duration); }); }); return e;
  }
  function capLines(P){
    var o=[]; (P.tracks||[]).forEach(function(t){ if(t.kind!=="caption") return; (t.clips||[]).forEach(function(c){ var tx=String(c.text||c.caption||"").toLowerCase(); if(tx) o.push({start:c.start,end:c.start+c.duration,text:tx}); }); });
    return o.sort(function(a,b){ return a.start-b.start; });
  }
  /* pure: returns [{asset,start,dur,matched}] */
  function planPlacement(P){
    var end=mainEnd(P), cands=spare(P), caps=capLines(P), out=[], used={};
    if(end<6||!cands.length) return out;
    function dur(a){ return a.type==="image"?LEN:Math.max(1,Math.min(3.5,a.duration||LEN)); }
    function free(st,d){ for(var i=0;i<out.length;i++){ if(st<out[i].start+out[i].dur+1.5&&st+d>out[i].start-1.5) return false; } return st>=2&&st+d<=end-1; }
    caps.forEach(function(l){
      if(out.length>=MAXN) return;
      cands.forEach(function(a){
        if(used[a.id]||out.length>=MAXN) return;
        if(words(a.name).some(function(w){ return l.text.indexOf(w)>=0; })){ var d=dur(a); if(free(l.start,d)){ out.push({asset:a,start:l.start,dur:d,matched:true}); used[a.id]=1; } }
      });
    });
    var ci=0, last=out.length?out[out.length-1].asset.id:null;
    for(var t=FIRST;t<end-2&&out.length<MAXN;t+=GAP){
      var st=t; if(caps.length){ var best=null; caps.forEach(function(l){ if(Math.abs(l.start-t)<=2&&(best===null||Math.abs(l.start-t)<Math.abs(best-t))) best=l.start; }); if(best!==null) st=best; }
      var a=null, tries=0; while(tries++<cands.length){ var c=cands[ci++%cands.length]; if(c.id!==last||cands.length===1){ a=c; break; } }
      if(!a) continue; var d=dur(a); if(!free(st,d)) continue;
      out.push({asset:a,start:+st.toFixed(2),dur:d,matched:false}); last=a.id;
    }
    return out.sort(function(x,y){ return x.start-y.start; });
  }
  function addBroll(){
    var P=window.project; if(!P) throw new Error("No project is open.");
    if(hasBroll(P)) throw new Error("B-roll is already on the timeline. Delete the B-roll track first if you want to place it again.");
    if(mainEnd(P)<6) throw new Error("Put a main video on the timeline first (at least 6 seconds), so there is something to cover.");
    if(!spare(P).length) throw new Error("There are no spare pictures or videos. Import some extra clips into the Library (not on the timeline), then try again.");
    var plan=planPlacement(P); if(!plan.length) throw new Error("I could not find room for B-roll in this timeline.");
    var sel=null; try{ sel=window.getClip&&window.getClip(); }catch(e){}
    window.transact("Auto B-roll",function(){
      var tr=null; (P.tracks||[]).forEach(function(t){ if(t.name==="B-roll"&&t.kind==="video") tr=t; });
      if(!tr){ tr={id:idg("track"),kind:"video",name:"B-roll",clips:[],muted:false,hidden:false}; P.tracks.push(tr); }
      plan.forEach(function(p){
        tr.clips.push({id:idg("clip"),assetId:p.asset.id,start:p.start,duration:p.dur,inPoint:0,outPoint:p.dur,volume:0,opacity:1,speed:1,rotation:0,scale:1,x:.5,y:.5,trimL:0,trimR:0,fit:"cover",effects:[],keyframes:[],transitionIn:null,transitionOut:null});
      });
      tr.clips.sort(function(a,b){ return a.start-b.start; });
    });
    var m=plan.filter(function(p){ return p.matched; }).length;
    return "Placed "+plan.length+" B-roll clip"+(plan.length===1?"":"s")+" on a new B-roll track"+(m?" ("+m+" matched words in the speech)":"")+". One undo takes them away";
  }
  D.addBroll=addBroll; D.planBroll=planPlacement;
  D.recipes.push({id:"broll",name:"Add B-roll",desc:"Cover your video with spare pictures and clips, placed for you",goal:"add b-roll",
    re:/^(?:(?:add|place|put|insert|use) (?:some )?(?:auto(?:matic)? )?b[- ]?roll|auto b[- ]?roll|cover (?:it |this |my video )?with b[- ]?roll|add cutaways)(?: automatically| for me)?$/,
    steps:[STEP]});
  A20.hook(function(raw,t){
    if(window.__dirRunning&&t===STEP) return addBroll();
    return undefined;
  });
  var w0=D.why;
  if(w0) D.why=function(step,F){
    if(String(step).toLowerCase().trim()===STEP){
      var P=window.project; if(!P) return null;
      if(hasBroll(P)) return "B-roll already placed";
      if(mainEnd(P)<6) return "the video is too short";
      if(!spare(P).length) return "no spare pictures or videos in the Library";
      return null;
    }
    return w0(step,F);
  };
  try{ window.AMIYO_EDITOR_BUILD="dir-s15-auto-broll"; }catch(e){}
})();

