/* ==================== Script 1395 id="amiyo-dir-s16-highlight-reel" ==================== */
/* AI Director · Step 16 of 20 — highlight reel from spoken words.
   Say the words that matter and the editor keeps only those moments. Example: make a highlight reel of "price, launch, free" (add
   "under 30 seconds" to set a limit; the default limit is 60 s). It reads your captions, keeps every caption line that contains one
   of the words (with about half a second of room each side), joins moments that are close together, and cuts out everything else with
   the editor's own Extract so the gaps close. If there are more moments than the limit allows, the ones with more of your words win,
   and the reel stays in the original order. It needs captions first, so a plan can start with "add captions". Because it deletes
   video, a typed request opens the plan card first. The whole cut is ONE undo step, and the dry-run preview shows the real length of
   the reel once captions exist. It tells you which words were not found. */
(function(){
  "use strict";
  var D=window.amiyoDirector, A20=window.amiyoAI20;
  if(!D||D.s16||!D.facts||!A20||!A20.hook) return; D.s16=true;
  var RE=/^(?:please )?(?:make|build|create|cut|give me|do|produce)(?: me)?(?: an?| the)? (?:highlight ?reel|highlights?(?: video| reel| clip)?|best[- ]?of(?: reel| video)?)(?: (?:of|from|about|with|for|on|using|from the words|of the words)(?: the)?(?: words?)? (.+?))?(?: (?:in|under|within|of|max(?:imum)?|up to|no (?:longer|more) than) (\d+(?:\.\d+)?) ?(seconds?|secs?|s|minutes?|mins?|m))?$/;
  function parse(text){
    var m=RE.exec(String(text||"").toLowerCase().replace(/\s+/g," ").trim().replace(/[.!?]+$/,"")); if(!m) return null;
    var kws=String(m[1]||"").replace(/[\u201c\u201d"']/g,"").split(/\s*(?:,|;|\bor\b|\band\b)\s*/).map(function(k){ return k.trim(); }).filter(function(k){ return k.length>=3; });
    var lim=60; if(m[2]){ lim=parseFloat(m[2])*(/^m/.test(m[3])&&!/^s/.test(m[3])?60:1); }
    return {kws:kws.filter(function(k,i,a){ return a.indexOf(k)===i; }),limit:Math.max(5,lim)};
  }
  function capLines(){
    var T=window.amiyoTranscript; if(!T||!T.lines) return [];
    return T.lines().filter(function(x){ return x.text; }).map(function(x){ return {start:x.start,end:x.end,text:String(x.text).toLowerCase()}; });
  }
  /* pure: returns {keep:[{a,b}], cut:[{a,b}], found:{kw:n}, total} */
  function plan(lines,kws,limit,end){
    var found={}; kws.forEach(function(k){ found[k]=0; });
    var hits=[]; lines.forEach(function(l){ var sc=0; kws.forEach(function(k){ if(l.text.indexOf(k)>=0){ sc++; found[k]++; } }); if(sc) hits.push({a:Math.max(0,l.start-0.5),b:Math.min(end,l.end+0.5),sc:sc}); });
    function merge(list){ var o=[]; list.slice().sort(function(x,y){ return x.a-y.a; }).forEach(function(r){ var p=o[o.length-1]; if(p&&r.a<=p.b+1) p.b=Math.max(p.b,r.b); else o.push({a:r.a,b:r.b}); }); return o; }
    var keep=merge(hits), total=keep.reduce(function(n,r){ return n+r.b-r.a; },0);
    if(total>limit){
      var sorted=hits.slice().sort(function(x,y){ return y.sc-x.sc||(x.b-x.a)-(y.b-y.a); }), pick=[], t=0;
      for(var i=0;i<sorted.length;i++){ var d=sorted[i].b-sorted[i].a; if(t+d>limit&&pick.length) continue; pick.push(sorted[i]); t+=d; }
      keep=merge(pick); total=keep.reduce(function(n,r){ return n+r.b-r.a; },0);
    }
    var cut=[], pos=0; keep.forEach(function(r){ if(r.a-pos>0.1) cut.push({a:pos,b:r.a}); pos=Math.max(pos,r.b); }); if(end-pos>0.1&&keep.length) cut.push({a:pos,b:end});
    return {keep:keep,cut:cut,found:found,total:total};
  }
  function hidx(){ try{ return window.project.history.index; }catch(e){ return -1; } }
  function mergeSince(idx,label){
    var H=window.project.history; if(!H||H.index<=idx+1) return;
    var first=H.entries[idx+1], last=H.entries[H.index]; if(!first||!last) return; first.after=last.after; first.label=label;
    H.entries.splice(idx+2,H.index-idx-1); H.index=idx+1; try{ window.updateUndoRedo&&window.updateUndoRedo(); }catch(e){}
  }
  function build(text){
    var q=parse(text); if(!q) throw new Error("I did not understand that highlight request.");
    if(!q.kws.length) throw new Error("Tell me which words to look for, for example: make a highlight reel of \u201cprice, launch\u201d.");
    var lines=capLines(); if(!lines.length) throw new Error("No captions yet. Add captions first so I can find your words, then ask again.");
    if(!window.amiyoCut||!window.amiyoSetIO) throw new Error("The cut tools are not available in this build.");
    var end=D.facts().dur, p=plan(lines,q.kws,q.limit,end);
    if(!p.keep.length) throw new Error("None of these words were spoken: "+q.kws.join(", ")+". Nothing was cut.");
    var h0=hidx(), n=0;
    for(var i=p.cut.length-1;i>=0;i--){ window.amiyoSetIO(p.cut[i].a,p.cut[i].b); if(window.amiyoCut.extract()) n++; }
    if(hidx()===h0&&p.cut.length) throw new Error("Nothing could be cut. The tracks may be locked.");
    mergeSince(h0,"Highlight reel");
    var miss=q.kws.filter(function(k){ return !p.found[k]; });
    return "Kept "+p.keep.length+" moment"+(p.keep.length===1?"":"s")+" ("+Math.round(p.total)+" s of "+Math.round(end)+" s)"+(miss.length?"; not found: "+miss.join(", "):"");
  }
  D.highlightReel=build; D.planHighlights=plan; D.parseHighlight=parse;
  A20.hook(function(raw,t){
    if(!parse(raw)) return undefined;
    if(window.__dirRunning) return build(raw);
    var q=parse(raw);
    if(!q.kws.length) return "Tell me which words to look for, for example: make a highlight reel of \u201cprice, launch\u201d";
    D.open(raw,{steps:[raw],title:"Plan: Highlight reel"}); return "Plan ready: highlight reel for "+q.kws.join(", ")+". Check it and tap Run.";
  });
  var w0=D.why;
  if(w0) D.why=function(step,F){ if(parse(step)) return F.sound?null:"no clip with sound"; return w0(step,F); };
  if(D.addEstimator) D.addEstimator(function(t,E,F){
    var q=parse(t); if(!q||!q.kws.length) return;
    var lines=capLines(); if(!lines.length) return;
    var p=plan(lines,q.kws,q.limit,F.dur); if(p.keep.length){ E.dur=Math.min(E.dur,p.total); E.gaps=0; }
  });
  try{ window.AMIYO_EDITOR_BUILD="dir-s16-highlight-reel"; }catch(e){}
})();

