    "#dirHelp .xbox,#dirTest .xbox{width:100%;max-width:560px;max-height:90vh;overflow:auto;background:#14120f;color:#f1ece2;border:1px solid var(--line,#302c26);border-radius:16px 16px 0 0;padding:14px 14px calc(14px + env(safe-area-inset-bottom,0px));box-sizing:border-box;font-family:inherit}"+
    "#dirHelp h3,#dirTest h3{margin:0 0 4px;font-size:15px}#dirHelp h4{margin:14px 0 4px;font-size:13px;color:var(--accent,#e8a24a)}"+
    "#dirHelp p,#dirTest .xsub{font-size:13px;line-height:1.5;margin:0 0 6px;color:#d9d2c3}#dirTest .xsub{font-size:12px;color:#948a79}"+
    "#dirHelp ul{margin:0 0 4px;padding-left:18px}#dirHelp li{font-size:13px;line-height:1.5;margin-bottom:3px}#dirHelp code{background:#211f1b;border:1px solid #302c26;border-radius:6px;padding:0 5px;font-size:12px;color:#f6dca8;word-break:break-word}"+
    "#dirTest .xrow{display:flex;gap:10px;align-items:flex-start;padding:8px 10px;border:1px solid var(--line,#302c26);border-radius:12px;margin-bottom:6px;background:#0f0d0b}"+
    "#dirTest .xrow .xi{flex:none;width:22px;text-align:center;font-weight:700}#dirTest .xrow.p{border-color:#2f6f4a}#dirTest .xrow.p .xi{color:#5fd88a}#dirTest .xrow.f{border-color:#7a3340}#dirTest .xrow.f .xi{color:#ff91a0}#dirTest .xrow.n .xi{color:#948a79}"+
    "#dirTest .xrow b{display:block;font-size:14px;line-height:1.35}#dirTest .xrow span{display:block;font-size:12px;color:#948a79;line-height:1.4;margin-top:2px;word-break:break-word}"+
    "#dirTest .xsum{font-size:14px;font-weight:700;margin:8px 0}"+
    ".xbtns{display:flex;gap:8px;margin-top:10px;flex-wrap:wrap}.xbtns button{flex:1;min-height:48px;min-width:110px;border-radius:12px;border:1px solid var(--line,#302c26);background:#211f1b;color:#f1ece2;font-size:14px;padding:0 12px}.xbtns button.go{background:var(--accent,#e8a24a);color:#1a0c03;font-weight:700;border-color:transparent}";
